        private const string BattleMapStartupBuildMarker = "battle-map-startup-deferral-v1";

        public override void AfterStart()
        {
            ModLogger.Info("CoopMissionSpawnLogic AfterStart ENTER");
            base.AfterStart();
            Mission mission = Mission;
            if (mission == null) return;
            if (_hasLoggedStart) return;
            _hasLoggedStart = true;

            if (MissionMultiplayerCoopBattleMode.IsBattleMapSceneName(mission.SceneName))
            {
                TryInitializeServerMissionRuntimeState(
                    mission,
                    "CoopMissionSpawnLogic.AfterStart battle-map deferred",
                    forceReinitialize: false);
                AppendExactBattleAgentSpawnTraceLifecycleStep(
                    mission,
                    "afterstart",
                    "runtime-init-complete",
                    "CoopMissionSpawnLogic.AfterStart battle-map deferred");
                ExactCampaignRuntimeItemRegistry.EnsureLoadedFromState(
                    BattleSnapshotRuntimeState.GetState(),
                    "CoopMissionSpawnLogic.AfterStart battle-map deferred");
                AppendExactBattleAgentSpawnTraceLifecycleStep(
                    mission,
                    "afterstart",
                    "exact-item-registry-ready",
                    "CoopMissionSpawnLogic.AfterStart battle-map deferred");
                LogImportedEquipmentAvailabilityDiagnostics();
                AppendExactBattleAgentSpawnTraceLifecycleStep(
                    mission,
                    "afterstart",
                    "imported-equipment-diagnostics-ready",
                    "CoopMissionSpawnLogic.AfterStart battle-map deferred");
                LogHeroEquipmentResolutionAudit();
                AppendExactBattleAgentSpawnTraceLifecycleStep(
                    mission,
                    "afterstart",
                    "hero-equipment-audit-ready",
                    "CoopMissionSpawnLogic.AfterStart battle-map deferred",
                    "CompatibilityAuditDeferred=True");
                ModLogger.Info(
                    "CoopMissionSpawnLogic: deferred exact entry compatibility audit out of battle-map AfterStart hot path. " +
                    "Source=CoopMissionSpawnLogic.AfterStart battle-map deferred");
                ModLogger.Info("CoopMissionSpawnLogic: battle-map AfterStart using minimal deferred startup path. BuildMarker=" + BattleMapStartupBuildMarker);
                _timeUntilNextPeerLog = ServerLogIntervalSeconds;
                AppendExactBattleAgentSpawnTraceLifecycleStep(
                    mission,
                    "afterstart",
                    "deferred-exit",
                    "CoopMissionSpawnLogic.AfterStart battle-map deferred",
                    "BuildMarker=" + BattleMapStartupBuildMarker);
                ModLogger.Info("CoopMissionSpawnLogic AfterStart EXIT (battle-map deferred). BuildMarker=" + BattleMapStartupBuildMarker);
                return;
            }

            TryInitializeServerMissionRuntimeState(mission, "CoopMissionSpawnLogic.AfterStart", forceReinitialize: false);
            ExactCampaignRuntimeItemRegistry.EnsureLoadedFromState(
                BattleSnapshotRuntimeState.GetState(),
                "CoopMissionSpawnLogic.AfterStart");

            ModLogger.Info("CoopMissionSpawnLogic: server mission entered.");
            try
            {
                string mode = mission.Mode.ToString();
                ModLogger.Info("CoopMissionSpawnLogic: current mission mode = " + mode);
            }
            catch (Exception ex) { ModLogger.Info("CoopMissionSpawnLogic: mission mode log failed: " + ex.Message); }

            if (GameNetwork.IsSessionActive)
            {
                int peerCount = GameNetwork.NetworkPeerCount;
                ModLogger.Info("CoopMissionSpawnLogic: peer count (after start) = " + peerCount);
            }

            ModLogger.Info("CoopMissionSpawnLogic: server mission started. Campaign roster: " + CampaignRosterTroopIds.Count + " normalized troop IDs.");
            if (!string.IsNullOrEmpty(SelectedAllowedTroopId))
                ModLogger.Info("CoopMissionSpawnLogic: selected allowed troop id = " + SelectedAllowedTroopId);
            else
                ModLogger.Info("CoopMissionSpawnLogic: no allowed troop id available yet (roster empty).");
            LogAllowedCharacterResolution();
            LogImportedEquipmentAvailabilityDiagnostics();
            LogHeroEquipmentResolutionAudit();
            TryWriteExactEntryCompatibilityAuditSafely("CoopMissionSpawnLogic.AfterStart");
            CoopBattlePhaseRuntimeState.AdvanceToAtLeast(CoopBattlePhase.SideSelection, "CoopMissionSpawnLogic.AfterStart", mission);

            _timeUntilNextPeerLog = ServerLogIntervalSeconds;
            ModLogger.Info("CoopMissionSpawnLogic AfterStart EXIT.");
        }

        public override void OnMissionTick(float dt)
        {
            base.OnMissionTick(dt);
            if (!_hasLoggedStart) return;
            BattleAgentCapacityPolicy.Tick(Mission, "CoopMissionSpawnLogic.OnMissionTick");
            ExactSiegeMoraleDiagnostics.Tick(Mission, "CoopMissionSpawnLogic.OnMissionTick");
            TryRestoreExpiredMaterializedPossessionProtection(Mission, "CoopMissionSpawnLogic.OnMissionTick");
            _timeUntilNextPeerLog -= dt;
            if (_timeUntilNextPeerLog <= 0f)
            {
                _timeUntilNextPeerLog = ServerLogIntervalSeconds;
                try
                {
                    if (GameNetwork.IsSessionActive)
                        ModLogger.Info("CoopMissionSpawnLogic: peer count = " + GameNetwork.NetworkPeerCount);
                }
                catch (Exception ex) { ModLogger.Info("CoopMissionSpawnLogic: peer log failed: " + ex.Message); }
            }

            if (Mission.GetMissionBehavior<MissionMultiplayerCoopBattle>() != null ||
                Mission.GetMissionBehavior<MissionMultiplayerCoopSiegeAssaultWithDeployment>() != null)
                return;

            // Dedicated siege assault bootstrap must run outside Mission.OnTick because
            // native Mission.OnTick iterates MissionBehaviors by index and our exact
            // siege bootstrap can still mount late mission behaviors.
            if (ShouldDedicatedObserverOwnExactSiegeLifecycle(Mission))
                return;

            RunCoopBattleSpawnOwnerTick(Mission, "CoopMissionSpawnLogic.OnMissionTick fallback");
            RunCoopBattlePhaseOwnerTick(Mission, "CoopMissionSpawnLogic.OnMissionTick fallback");
        }

        public override void OnScoreHit(
            Agent affectedAgent,
            Agent affectorAgent,
            WeaponComponentData attackerWeapon,
            bool isBlocked,
            bool isSiegeEngineHit,
            in Blow blow,
            in AttackCollisionData collisionData,
            float damagedHp,
            float hitDistance,
            float shotDifficulty)
        {
            float authoritativeDamagedHp = damagedHp;
            TryApplyAuthoritativeExactPersonalRangedDamageBonusOnScoreHit(
                affectedAgent,
                affectorAgent,
                attackerWeapon,
                isBlocked,
                isSiegeEngineHit,
                blow,
                collisionData,
                ref authoritativeDamagedHp);
            TryLogMountedCombatDamageDiagnostics(
                affectedAgent,
                affectorAgent,
                attackerWeapon,
                isBlocked,
                isSiegeEngineHit,
                blow,
                collisionData,
                authoritativeDamagedHp,
                hitDistance,
                shotDifficulty);

            _materializedBattleResultRawOnScoreHitCount++;
            TryTrackMaterializedBattleResultScoreHit(
                affectedAgent,
                affectorAgent,
                attackerWeapon,
                isBlocked,
                isSiegeEngineHit,
                blow,
                collisionData,
                authoritativeDamagedHp,
                hitDistance,
                shotDifficulty);
            base.OnScoreHit(affectedAgent, affectorAgent, attackerWeapon, isBlocked, isSiegeEngineHit, blow, collisionData, authoritativeDamagedHp, hitDistance, shotDifficulty);
        }

        private static void TryLogMountedCombatDamageDiagnostics(
            Agent affectedAgent,
            Agent affectorAgent,
            WeaponComponentData attackerWeapon,
            bool isBlocked,
            bool isSiegeEngineHit,
            in Blow blow,
            in AttackCollisionData collisionData,
            float damagedHp,
            float hitDistance,
            float shotDifficulty)
        {
            if (!CoopDebugConfig.CombatModelDiagnostics ||
                !GameNetwork.IsServerOrRecorder ||
                affectedAgent == null ||
                affectorAgent == null ||
                _mountedCombatDamageDiagnosticLogCount >= MountedCombatDamageDiagnosticBudget)
            {
                return;
            }

            try
            {
                Mission mission = affectorAgent.Mission ?? affectedAgent.Mission;
                if (mission == null || !MissionMultiplayerCoopBattleMode.IsBattleMapSceneName(mission.SceneName))
                    return;

                CoopBattlePhase currentPhase = CoopBattlePhaseRuntimeState.GetPhase();
                if (currentPhase < CoopBattlePhase.BattleActive || currentPhase >= CoopBattlePhase.BattleEnded)
                    return;

                Agent normalizedAffectorAgent = NormalizeBattleResultCombatAffectorAgent(affectorAgent) ?? affectorAgent;
                bool attackerMounted =
                    affectorAgent.IsMount ||
                    normalizedAffectorAgent.HasMount ||
                    normalizedAffectorAgent.MountAgent != null;
                bool victimMounted =
                    affectedAgent.IsMount ||
                    affectedAgent.HasMount ||
                    affectedAgent.MountAgent != null;
                if (!attackerMounted && !victimMounted && !collisionData.IsHorseCharge)
                    return;

                Agent attackerEntryAgent = normalizedAffectorAgent.IsMount
                    ? normalizedAffectorAgent.RiderAgent
                    : normalizedAffectorAgent;
                Agent victimEntryAgent = affectedAgent.IsMount
                    ? affectedAgent.RiderAgent
                    : affectedAgent;
                TryResolveAuthoritativeTrackedEntryId(attackerEntryAgent, out string attackerEntryId);
                TryResolveAuthoritativeTrackedEntryId(victimEntryAgent, out string victimEntryId);
                string weaponItemId = ResolveCombatEventWeaponItemId(normalizedAffectorAgent, attackerWeapon);
                string skillId = attackerWeapon?.RelevantSkill?.StringId ?? "null";
                string logKey =
                    normalizedAffectorAgent.Index + "|" + affectedAgent.Index + "|" +
                    (weaponItemId ?? string.Empty) + "|" + skillId + "|" +
                    collisionData.VictimHitBodyPart + "|" + collisionData.IsHorseCharge + "|" +
                    Math.Round(damagedHp, 1).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) + "|" +
                    Math.Round((double)collisionData.AbsorbedByArmor, 1).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) + "|" +
                    Math.Round(collisionData.BaseMagnitude, 1).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture);
                if (!_mountedCombatDamageDiagnosticKeys.Add(logKey))
                    return;

                _mountedCombatDamageDiagnosticLogCount++;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: mounted combat damage sample. " +
                    "RawAffector=" + affectorAgent.Index +
                    " Attacker=" + normalizedAffectorAgent.Index +
                    " AttackerEntryId=" + (string.IsNullOrWhiteSpace(attackerEntryId) ? "unknown" : attackerEntryId) +
                    " AttackerMounted=" + attackerMounted +
                    " AttackerMount=" + (normalizedAffectorAgent.MountAgent?.Index ?? (affectorAgent.IsMount ? affectorAgent.Index : -1)) +
                    " Victim=" + affectedAgent.Index +
                    " VictimEntryId=" + (string.IsNullOrWhiteSpace(victimEntryId) ? "unknown" : victimEntryId) +
                    " VictimKind=" + (affectedAgent.IsMount ? "Mount" : "Human") +
                    " VictimMounted=" + victimMounted +
                    " VictimMount=" + (affectedAgent.IsMount ? affectedAgent.Index : affectedAgent.MountAgent?.Index ?? -1) +
                    " Weapon=" + (string.IsNullOrWhiteSpace(weaponItemId) ? "none" : weaponItemId) +
                    " Skill=" + skillId +
                    " WeaponClass=" + (attackerWeapon?.WeaponClass.ToString() ?? "None") +
                    " DamageType=" + ((DamageTypes)collisionData.DamageType) +
                    " BodyPart=" + collisionData.VictimHitBodyPart +
                    " BlowDamage=" + blow.InflictedDamage +
                    " DamagedHp=" + damagedHp.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " BlowBaseMagnitude=" + blow.BaseMagnitude.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " CollisionBaseMagnitude=" + collisionData.BaseMagnitude.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " BlowAbsorbedByArmor=" + blow.AbsorbedByArmor.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " CollisionAbsorbedByArmor=" + collisionData.AbsorbedByArmor.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " MovementSpeedModifier=" + collisionData.MovementSpeedDamageModifier.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " HorseCharge=" + collisionData.IsHorseCharge +
                    " Missile=" + collisionData.IsMissile +
                    " Blocked=" + isBlocked +
                    " SiegeEngineHit=" + isSiegeEngineHit +
                    " HitDistance=" + hitDistance.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " ShotDifficulty=" + shotDifficulty.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " VictimHealth=" + affectedAgent.Health.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                    " Mission=" + mission.SceneName + ".");
            }
            catch (Exception ex)
            {
                if (_hasLoggedMountedCombatDamageDiagnosticFailure)
                    return;

                _hasLoggedMountedCombatDamageDiagnosticFailure = true;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: mounted combat damage diagnostics failed. " +
                    ex.GetType().Name + ":" + ex.Message);
            }
        }

        public override void OnAgentShootMissile(
            Agent shooterAgent,
            EquipmentIndex weaponIndex,
            Vec3 position,
            Vec3 velocity,
            Mat3 orientation,
            bool hasRigidBody,
            int forcedMissileIndex)
        {
            base.OnAgentShootMissile(
                shooterAgent,
                weaponIndex,
                position,
                velocity,
                orientation,
                hasRigidBody,
                forcedMissileIndex);

            TryTraceServerProjectileLaunchDiagnostics(
                shooterAgent,
                weaponIndex,
                position,
                velocity,
                orientation,
                hasRigidBody,
                forcedMissileIndex);
            TryTraceRoleMatrixStreamWeaponPriorityProjectile(
                shooterAgent,
                weaponIndex,
                forcedMissileIndex,
                "OnAgentShootMissile");
        }

        private static void TryTraceServerProjectileLaunchDiagnostics(
            Agent shooterAgent,
            EquipmentIndex weaponIndex,
            Vec3 position,
            Vec3 velocity,
            Mat3 orientation,
            bool hasRigidBody,
            int forcedMissileIndex)
        {
            if (!ExperimentalFeatures.EnableExactCreateAgentCorridorDiagnostics ||
                !GameNetwork.IsServerOrRecorder ||
                shooterAgent == null ||
                shooterAgent.IsMount)
            {
                return;
            }

            try
            {
                MissionWeapon launchWeapon = ResolveAgentMissionWeapon(shooterAgent, weaponIndex);
                if (!IsThrownProjectileLaunchWeapon(launchWeapon))
                    return;

                if (!IsServerProjectileLaunchDiagnosticsTarget(shooterAgent, out string entryId, out RosterEntryState entryState, out string targetReason))
                    return;

                string key =
                    "server|" +
                    forcedMissileIndex + "|" +
                    shooterAgent.Index + "|" +
                    weaponIndex + "|" +
                    (launchWeapon.Item?.StringId ?? "null") + "|" +
                    FormatProjectileLaunchVec3(position) + "|" +
                    FormatProjectileLaunchFloat(SafeLength(velocity));
                if (_projectileLaunchDiagnosticKeys.Count >= ProjectileLaunchDiagnosticBudget ||
                    !_projectileLaunchDiagnosticKeys.Add(key))
                {
                    return;
                }

                string details = BuildServerProjectileLaunchDiagnosticDetails(
                    shooterAgent,
                    entryId,
                    entryState,
                    targetReason,
                    weaponIndex,
                    launchWeapon,
                    position,
                    velocity,
                    orientation,
                    hasRigidBody,
                    forcedMissileIndex);

                ModLogger.Info("CoopMissionSpawnLogic: projectile launch diagnostics. " + details);
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent("projectile-launch-server-on-agent-shoot", details);
            }
            catch (Exception ex)
            {
                ModLogger.Info("CoopMissionSpawnLogic: projectile launch diagnostics failed open: " + ex.Message);
            }
        }

        private static MissionWeapon ResolveAgentMissionWeapon(Agent agent, EquipmentIndex weaponIndex)
        {
            if (agent?.Equipment != null && weaponIndex != EquipmentIndex.None)
            {
                try
                {
                    return agent.Equipment[weaponIndex];
                }
                catch
                {
                }
            }

            return MissionWeapon.Invalid;
        }

        private static bool IsServerProjectileLaunchDiagnosticsTarget(
            Agent agent,
            out string entryId,
            out RosterEntryState entryState,
            out string reason)
        {
            entryId = null;
            entryState = null;
            reason = "not-controlled-hero";

            if (agent == null || agent.IsMount)
                return false;

            bool controlled = agent.MissionPeer != null || agent.Controller == AgentControllerType.Player;
            bool resolvedEntry =
                TryResolveAuthoritativeTrackedEntryId(agent, out entryId) ||
                TryResolveSelectableEntryId(agent, out entryId);
            if (resolvedEntry)
                entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);

            bool heroEntry = IsProjectileLaunchHeroEntry(entryState);
            if (!controlled && !heroEntry)
                return false;

            reason =
                (controlled ? "controlled" : "observed-hero-entry") +
                "|HeroEntry=" + heroEntry +
                "|EntryResolved=" + resolvedEntry;
            return true;
        }

        private static bool IsProjectileLaunchHeroEntry(RosterEntryState entryState)
        {
            return entryState != null &&
                   (entryState.IsHero ||
                    !string.IsNullOrWhiteSpace(entryState.HeroId) ||
                    string.Equals(entryState.OriginalCharacterId, "main_hero", StringComparison.OrdinalIgnoreCase));
        }

        private static bool IsThrownProjectileLaunchWeapon(MissionWeapon weapon)
        {
            try
            {
                if (weapon.IsEmpty)
                    return false;

                ItemObject item = weapon.Item;
                if (item?.ItemType == ItemObject.ItemTypeEnum.Thrown)
                    return true;

                WeaponComponentData usage = weapon.CurrentUsageItem ?? item?.PrimaryWeapon;
                if (usage == null)
                    return false;

                return usage.RelevantSkill == DefaultSkills.Throwing ||
                       usage.WeaponClass == WeaponClass.Javelin ||
                       usage.WeaponClass == WeaponClass.ThrowingAxe ||
                       usage.WeaponClass == WeaponClass.ThrowingKnife ||
                       usage.WeaponClass == WeaponClass.Stone ||
                       usage.WeaponClass == WeaponClass.SlingStone;
            }
            catch
            {
                return false;
            }
        }

        private static string BuildServerProjectileLaunchDiagnosticDetails(
            Agent shooterAgent,
            string entryId,
            RosterEntryState entryState,
            string targetReason,
            EquipmentIndex weaponIndex,
            MissionWeapon launchWeapon,
            Vec3 position,
            Vec3 velocity,
            Mat3 orientation,
            bool hasRigidBody,
            int forcedMissileIndex)
        {
            Vec3 agentPosition = shooterAgent?.Position ?? Vec3.Zero;
            Vec3 offset = position - agentPosition;
            Vec3 lookDirection = ResolveAgentLookDirection(shooterAgent);
            Vec3 normalizedDirection = NormalizeVec3(velocity);
            float speed = SafeLength(velocity);
            float offsetLookDot = DotSafe(offset, lookDirection);
            float directionLookDot = DotSafe(normalizedDirection, lookDirection);
            float offsetLength = SafeLength(offset);
            bool startsBehindLook = offsetLookDot < -0.10f;

            EquipmentIndex primaryWieldedIndex = EquipmentIndex.None;
            EquipmentIndex offhandWieldedIndex = EquipmentIndex.None;
            string missionWeapons = "(unavailable)";
            string spawnWeapons = "(unavailable)";
            string currentWeaponOffset = "(unavailable)";
            try
            {
                primaryWieldedIndex = shooterAgent.GetPrimaryWieldedItemIndex();
                offhandWieldedIndex = shooterAgent.GetOffhandWieldedItemIndex();
                missionWeapons = BuildMissionEquipmentSummary(
                    shooterAgent.Equipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);
                spawnWeapons = BuildExactEntryEquipmentSummary(
                    shooterAgent.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);
                currentWeaponOffset = FormatProjectileLaunchVec3(shooterAgent.GetCurWeaponOffset());
            }
            catch
            {
            }

            WeaponComponentData usage = null;
            try
            {
                usage = launchWeapon.CurrentUsageItem ?? launchWeapon.Item?.PrimaryWeapon;
            }
            catch
            {
            }

            return
                "Stage=server-on-agent-shoot" +
                " Scene=" + (Mission.Current?.SceneName ?? "null") +
                " ForcedMissileIndex=" + forcedMissileIndex +
                " AgentIndex=" + (shooterAgent?.Index ?? -1) +
                " EntryId=" + (entryId ?? "null") +
                " TargetReason=" + (targetReason ?? "unknown") +
                " EntryHero=" + (entryState?.IsHero ?? false) +
                " OriginalCharacterId=" + (entryState?.OriginalCharacterId ?? "null") +
                " HeroId=" + (entryState?.HeroId ?? "null") +
                " CharacterId=" + (shooterAgent?.Character?.StringId ?? "null") +
                " Controller=" + (shooterAgent?.Controller.ToString() ?? "null") +
                " HasMount=" + (shooterAgent?.HasMount ?? false) +
                " MountAgentIndex=" + (shooterAgent?.MountAgent?.Index ?? -1) +
                " WeaponIndex=" + weaponIndex +
                " PrimaryWieldedIndex=" + primaryWieldedIndex +
                " OffhandWieldedIndex=" + offhandWieldedIndex +
                " LaunchItem=" + (launchWeapon.Item?.StringId ?? "null") +
                " LaunchItemType=" + (launchWeapon.Item?.ItemType.ToString() ?? "null") +
                " LaunchUsage=" + (usage?.WeaponClass.ToString() ?? "null") +
                " LaunchRelevantSkill=" + (usage?.RelevantSkill?.StringId ?? "null") +
                " HasRigidBody=" + hasRigidBody +
                " AgentPosition=" + FormatProjectileLaunchVec3(agentPosition) +
                " AgentLook=" + FormatProjectileLaunchVec3(lookDirection) +
                " MissilePosition=" + FormatProjectileLaunchVec3(position) +
                " MissileDirection=" + FormatProjectileLaunchVec3(normalizedDirection) +
                " MissileSpeed=" + FormatProjectileLaunchFloat(speed) +
                " Offset=" + FormatProjectileLaunchVec3(offset) +
                " OffsetLength=" + FormatProjectileLaunchFloat(offsetLength) +
                " OffsetLookDot=" + FormatProjectileLaunchFloat(offsetLookDot) +
                " DirectionLookDot=" + FormatProjectileLaunchFloat(directionLookDot) +
                " StartsBehindLook=" + startsBehindLook +
                " OrientationF=" + FormatProjectileLaunchVec3(orientation.f) +
                " CurWeaponOffset=" + currentWeaponOffset +
                " MissionWeapons={" + missionWeapons + "}" +
                " SpawnWeapons={" + spawnWeapons + "}";
        }

        private static Vec3 ResolveAgentLookDirection(Agent agent)
        {
            if (agent == null)
                return Vec3.Forward;

            try
            {
                Vec3 look = agent.LookDirection;
                if (look.LengthSquared > 0.0001f)
                    return NormalizeVec3(look);
            }
            catch
            {
            }

            try
            {
                Vec3 frameForward = agent.Frame.rotation.f;
                if (frameForward.LengthSquared > 0.0001f)
                    return NormalizeVec3(frameForward);
            }
            catch
            {
            }

            return Vec3.Forward;
        }

        private static Vec3 NormalizeVec3(Vec3 value)
        {
            try
            {
                if (value.LengthSquared <= 0.0001f)
                    return Vec3.Zero;

                value.Normalize();
                return value;
            }
            catch
            {
                return Vec3.Zero;
            }
        }

        private static float DotSafe(Vec3 left, Vec3 right)
        {
            try
            {
                return Vec3.DotProduct(left, right);
            }
            catch
            {
                return 0f;
            }
        }

        private static float SafeLength(Vec3 value)
        {
            try
            {
                return value.Length;
            }
            catch
            {
                return 0f;
            }
        }

        private static string FormatProjectileLaunchVec3(Vec3 value)
        {
            return "(" +
                   FormatProjectileLaunchFloat(value.x) + "," +
                   FormatProjectileLaunchFloat(value.y) + "," +
                   FormatProjectileLaunchFloat(value.z) + ")";
        }

        private static string FormatProjectileLaunchFloat(float value)
        {
            return value.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture);
        }

        public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow blow)
        {
            _materializedBattleResultRawOnAgentRemovedCount++;
            PreserveExactDisplayNameForRemovedAgent(affectedAgent);
            TraceServerExactHeroRemovalContract(affectedAgent, affectorAgent, agentState, "CoopMissionSpawnLogic.OnAgentRemoved");
            TrySyncExactCampaignNativeOriginRemoval(Mission, affectedAgent, affectorAgent, agentState);
            TryTrackMaterializedBattleResultRemoval(affectedAgent, affectorAgent, agentState);
            TryLogMaterializedBattleResultRemovalDebug(affectedAgent, affectorAgent, agentState, blow);
            TryHandleRoleMatrixStreamAgentRemoved(affectedAgent?.Index ?? -1);
            ExactSiegeMoraleDiagnostics.RecordAgentRemoved(affectedAgent, agentState);
            DropMaterializedPossessionProtectionForRemovedAgent(
                affectedAgent,
                agentState,
                "CoopMissionSpawnLogic.OnAgentRemoved");
            if (GameNetwork.IsServer && affectedAgent != null)
            {
                CoopBattleAgentControlRuntimeState.TryMarkServerObservedAgentUnavailable(
                    affectedAgent.Index,
                    "CoopMissionSpawnLogic.OnAgentRemoved",
                    out _,
                    out _);
            }
            if (GameNetwork.IsClient && affectedAgent != null)
            {
                BattleMapSpawnHandoffPatch.ClearDeferredClientAgentPayloadsOnRemoval(
                    affectedAgent.Index,
                    "CoopMissionSpawnLogic.OnAgentRemoved");
            }
            if (affectedAgent != null)
            {
                foreach (MaterializedSiegeReinforcementWaveState waveState in
                         MaterializedSiegeReinforcementWaveStates.Values)
                {
                    waveState?.HeldAgentsByIndex.Remove(affectedAgent.Index);
                }
            }
            ClearMaterializedAgentIndexScopedRuntimeCaches(affectedAgent?.Index ?? -1, clearRemovedGuard: false);
            ExactCreateAgentCorridorDiagnostics.ClearServerAgentIndexState(
                affectedAgent?.Index ?? -1,
                "CoopMissionSpawnLogic.OnAgentRemoved");
            TryCompleteBattleIfResolved(Mission, "server behavior agent-removed", force: true);
            BattleAgentCapacityPolicy.OnAgentRemoved(affectedAgent);
            base.OnAgentRemoved(affectedAgent, affectorAgent, agentState, blow);
        }

