            _pendingCaptainSynchronizedBattleStartMission = null;
            _pendingCaptainSynchronizedBattleStartSource = string.Empty;
            _lastAppliedBattlePhaseAiHold = null;
            _lastAppliedFormationHoldPhase = null;
            _battleLifecycleStartupTraceKeys.Clear();
            _lastMaterializedArmyMission = null;
            ResetMaterializedCombatProfileRuntimeState();
            ResetMaterializedBattleResultRuntimeState();
            ResetExactBattleAgentSpawnTrace(mission, (_lastServerRuntimeInitializationSource ?? source ?? "unknown") + " init");
            _hasMaterializedBattlefieldArmies = false;
            _hasLoggedImportedEquipmentAvailabilityDiagnostics = false;
            _hasLoggedHeroEquipmentResolutionAudit = false;
            _hasLoggedMaterializedEquipmentCoverageSummary = false;
            _hasTriggeredAuthoritativeBattleCompletion = false;
            _authoritativeBattleWinnerSide = string.Empty;
            _authoritativeBattleCompletionReason = string.Empty;
            _lastLoggedBattleSnapshotAckBlockStateByPeer.Clear();
            _lastLoggedReconnectFinalizeBlockStateByPeer.Clear();
            _lastLoggedBattleCompletionAuditKey = string.Empty;
            _lastLoggedBattleStartReadinessAuditKey = string.Empty;
            _nextIncompleteBattleSnapshotRefreshUtc = DateTime.MinValue;
            _nextIncompleteBattleSnapshotLogUtc = DateTime.MinValue;
            _nextInitialMaterializedArmyPulseUtc = DateTime.MinValue;
            _nextMaterializedArmyReinforcementPulseUtc = DateTime.MinValue;
            _nextExactCampaignBattlefieldRuntimeSyncUtc = DateTime.MinValue;
            _nextBattleCompletionFallbackCheckUtc = DateTime.MinValue;
            _nextBattleCompletionLiveReconciliationUtc = DateTime.MinValue;
            _nextEntryStatusSnapshotBuildUtc = DateTime.MinValue;
            _nextBattleMapStartupDeferLogUtc = DateTime.MinValue;
            _nextExactSceneMaterializationDeferLogUtc = DateTime.MinValue;
            _exactScenePostPossessionMaterializationResumeUtc = DateTime.MinValue;
            _nextNativeBattleMapWarmupFallbackRefreshUtc = DateTime.MinValue;
            _lastNativeBattleMapWarmupFallbackLogKey = string.Empty;
            _battleLifecycleStartupTraceBudgetRemaining =
                ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics
                    ? BattleLifecycleStartupTraceBudgetPerMission
                    : 0;
            CoopBattleSelectionIntentState.Reset();
            CoopBattleSelectionRequestState.Reset();
            CoopBattleSpawnIntentState.Reset();
            CoopBattleSpawnRequestState.Reset();
            CoopBattleSpawnRuntimeState.Reset();
            CoopBattlePeerLifecycleRuntimeState.Reset();
            CoopBattleAgentControlRuntimeState.ResetServer(source + " init");
            CoopBattlePhaseRuntimeState.Clear(source + " init");
            CoopBattleResultBridgeFile.ClearResult(source + " init");
            CoopBattleSelectionBridgeFile.ClearAll(source + " init");
            CoopBattleSpawnBridgeFile.ClearPendingRequests(source + " init");
            _diagnosticAllowedAgent = null;
            ExactTransferContractRuntimeCache.Reset((_lastServerRuntimeInitializationSource ?? source ?? "unknown") + " server-runtime-init");

            RefreshAllowedTroopsFromRoster(source);
            BattleRuntimeState initializedRuntimeState = BattleSnapshotRuntimeState.GetState();
            if (MissionMultiplayerCoopBattleMode.IsBattleMapSceneName(mission.SceneName) &&
                initializedRuntimeState?.Sides != null &&
                initializedRuntimeState.Sides.Count > 0)
            {
                string teamInitSource = (_lastServerRuntimeInitializationSource ?? source ?? "unknown") + " runtime-init";
                MissionMultiplayerCoopBattle.TryApplyAuthoritativeBattleCultureOptionsFromRuntimeState(teamInitSource);
                MissionMultiplayerCoopBattle.EnsureOpposingTeamsReadyForMission(mission, teamInitSource);
            }
            CampaignMapPatchMissionInit.TryApplyCampaignAtmosphereToLiveScene(
                mission,
                (_lastServerRuntimeInitializationSource ?? source ?? "unknown") + " time-of-day");
            CampaignMapPatchMissionInit.TryRepairLiveMissionContract(
                mission,
                (_lastServerRuntimeInitializationSource ?? source ?? "unknown") + " live-contract-repair");
            ModLogger.Info(
                "CoopMissionSpawnLogic: server runtime initialized. " +
                "Mission=" + (mission.SceneName ?? "null") +
                " Source=" + (_lastServerRuntimeInitializationSource ?? "unknown") +
                " CampaignRosterTroops=" + CampaignRosterTroopIds.Count);
            BattleMapContractDiagnostics.LogMissionRuntimeContract(mission, source + " runtime-init");
            if (!string.IsNullOrEmpty(SelectedAllowedTroopId))
                ModLogger.Info("CoopMissionSpawnLogic: runtime selected allowed troop id = " + SelectedAllowedTroopId);
            else
                ModLogger.Info("CoopMissionSpawnLogic: runtime found no allowed troop id (roster empty).");
            LogAllowedCharacterResolution();
            return true;
        }

        // Keep mission behavior and dedicated observer on the same battle-lifecycle pipeline.
        // This shared tick owns authoritative coop runtime state and battlefield materialization.
        // The legacy vanilla player-spawn bridge is kept in a separate explicit tick below.
        private static void RunSharedServerBattleLifecycleTick(
            Mission mission,
            string source,
            bool applyPreMaterializationPeerNudges)
        {
            if (mission == null || !GameNetwork.IsServer)
                return;

            TryRestoreExpiredMaterializedPossessionProtection(mission, (source ?? "shared-tick") + " possession-protection");

            AppendExactBattleAgentSpawnTraceLifecycleStep(
                mission,
                "shared-tick",
                "enter",
                source,
                "ApplyPreMaterializationPeerNudges=" + applyPreMaterializationPeerNudges);

            if (ShouldDeferBattleMapStartupRuntime(mission, out string deferReason))
            {
                AppendExactBattleAgentSpawnTraceLifecycleStep(
                    mission,
                    "shared-tick",
                    "deferred-startup",
                    source,
                    "Reason=" + (deferReason ?? "unknown"));
                TryConsumeSelectionRequests(mission);
                TryApplySelectionIntentToPrimaryPeer(mission, source + " deferred-startup");
                if (applyPreMaterializationPeerNudges)
                    TryForceAuthoritativePeerTeams(mission, source + " deferred-startup");

                TryWriteEntryStatusSnapshot(mission, source + " deferred-startup");
                LogBattleMapStartupDeferralIfNeeded(mission, source, deferReason);
                return;
            }

            if (applyPreMaterializationPeerNudges)
            {
                AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "pre-peer-nudges", source);
                TryConsumeSelectionRequests(mission);
                TryApplySelectionIntentToPrimaryPeer(mission, source);
                TryForceAuthoritativePeerTeams(mission, source);
                TryForceFixedMissionCultures(mission, source);
            }
            else
            {
                AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "selection-intent-only", source);
                TryConsumeSelectionRequests(mission);
                TryApplySelectionIntentToPrimaryPeer(mission, source);
            }

            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "native-bootstrap-before", source);
            TryEnsureExactCampaignNativeArmyBootstrap(mission, source);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "native-bootstrap-after", source);
            if (RunRoleMatrixStreamTick(mission, source))
            {
                AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "role-matrix-stream", source);
                TryConsumeSpawnRequests(mission);
                TryApplySpawnIntentToPrimaryPeer(mission, source);
                TrySyncExactCampaignBattlefieldRuntimeState(mission, source);
                TryPromoteDeferredDeploymentSpawnRequests(mission, source + " role-matrix-stream");
                TryForceAuthoritativePeerTeams(mission, source);
                TryForceFixedMissionCultures(mission, source);
                TryForcePreferredHeroClassForPeer(mission, source);
                TryRefreshPendingSpawnRequests(mission, source);
                TryWriteEntryStatusSnapshot(mission, source + " role-matrix-stream");
                AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "role-matrix-stream-complete", source);
                return;
            }

            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "materialize-armies-before", source);
            TryEnsureBattlefieldArmiesMaterialized(mission, source);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "materialize-armies-after", source);
            TryConsumeSpawnRequests(mission);
            TryApplySpawnIntentToPrimaryPeer(mission, source);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "runtime-sync-before", source);
            TrySyncExactCampaignBattlefieldRuntimeState(mission, source);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "runtime-sync-after", source);
            TryPromoteDeferredDeploymentSpawnRequests(mission, source + " post-runtime-sync");
            TryForceAuthoritativePeerTeams(mission, source);
            TryForceFixedMissionCultures(mission, source);
            TryForcePreferredHeroClassForPeer(mission, source);
            if (EnableMaterializedArmyPossessionExperiment)
            {
                AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "materialized-possession-before", source);
                TryTakeControlOfMaterializedArmyAgents(mission, source);
                AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "materialized-possession-after", source);
            }
            TryRefreshPendingSpawnRequests(mission, source);
            TryAlignControlledAgentsWithMaterializedArmy(mission, source);
            TryRefreshMaterializedCombatProfileDrivenStats(mission, source + " tick");
            LogMaterializedEquipmentCoverageSummaryIfNeeded();
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "compatibility-audit-before", source);
            TryWriteExactEntryCompatibilityAuditSafely(source + " tick");
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "compatibility-audit-after", source);
            TryWriteEntryStatusSnapshot(mission, source + " tick");
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "shared-tick", "complete", source);
        }

        private static bool ShouldDeferBattleMapStartupRuntime(Mission mission, out string reason)
        {
            reason = string.Empty;
            if (mission == null || !IsSceneAwareBattleMapRuntime(mission))
                return false;

            string missionMode = "unknown";
            float missionTime = -1f;
            int synchronizedPeerCount = 0;
            bool isExactCampaignBattleScene = false;

            try { missionMode = mission.Mode.ToString(); } catch { }
            try { missionTime = mission.CurrentTime; } catch { }
            try { isExactCampaignBattleScene = SceneRuntimeClassifier.IsExactCampaignBattleScene(mission.SceneName ?? string.Empty); } catch { }
            bool useFieldMaterializedSiegeReplayRuntime = ShouldUseFieldMaterializedSiegeReplayRuntime(mission);
            bool useFullNativeSiegeArmySpawnRuntime =
                ExactCampaignSiegeAssaultWithDeploymentRuntime
                    .ShouldUseFullNativeArmySpawnRuntime(mission);

            if (GameNetwork.NetworkPeers != null)
            {
                foreach (NetworkCommunicator peer in GameNetwork.NetworkPeers)
                {
                    if (peer == null || peer.IsServerPeer || !peer.IsConnectionActive || !peer.IsSynchronized)
                        continue;

                    synchronizedPeerCount++;
                }
            }

            if (string.Equals(missionMode, "StartUp", StringComparison.OrdinalIgnoreCase))
            {
                CoopBattlePhase currentPhase = CoopBattlePhaseRuntimeState.GetPhase();
                if (useFieldMaterializedSiegeReplayRuntime &&
                    missionTime >= 1.5f &&
                    synchronizedPeerCount > 0 &&
                    IsBattleSnapshotReadyForMaterialization(mission, out string fieldMaterializedSnapshotReadiness))
                {
                    reason =
                        "MissionMode=" + missionMode +
                        " MissionTime=" + missionTime.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) +
                        " SynchronizedPeers=" + synchronizedPeerCount +
                        " FieldMaterializedSiegeStartupGate=ready" +
                        " Phase=" + currentPhase +
                        " SnapshotReadiness={" + fieldMaterializedSnapshotReadiness + "}";
                    return false;
                }

                if (useFullNativeSiegeArmySpawnRuntime &&
                    missionTime >= 1.5f &&
                    synchronizedPeerCount > 0 &&
                    IsBattleSnapshotReadyForMaterialization(mission, out string fullNativeSnapshotReadiness))
                {
                    reason =
                        "MissionMode=" + missionMode +
                        " MissionTime=" + missionTime.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) +
                        " SynchronizedPeers=" + synchronizedPeerCount +
                        " FullNativeSiegeStartupGate=ready" +
                        " Phase=" + currentPhase +
                        " SnapshotReadiness={" + fullNativeSnapshotReadiness + "}";
                    return false;
                }

                if (ShouldDedicatedObserverOwnExactSiegeLifecycle(mission) &&
                    currentPhase >= CoopBattlePhase.PreBattleHold &&
                    synchronizedPeerCount > 0 &&
                    AreBattlefieldArmiesReadyForStart(
                        mission,
                        out string readinessSource,
                        out int attackerActive,
                        out int defenderActive))
                {
                    reason =
                        "MissionMode=" + missionMode +
                        " MissionTime=" + missionTime.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) +
                        " SynchronizedPeers=" + synchronizedPeerCount +
                        " ExactSiegeStartupGate=ready" +
                        " Phase=" + currentPhase +
                        " ReadinessSource=" + readinessSource +
                        " AttackerActive=" + attackerActive +
                        " DefenderActive=" + defenderActive;
                    return false;
                }

                reason =
                    "MissionMode=" + missionMode +
                    " MissionTime=" + missionTime.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) +
                    " SynchronizedPeers=" + synchronizedPeerCount;
                return true;
            }

            if (missionTime >= 0f && missionTime < 1.5f)
            {
                reason =
                    "MissionMode=" + missionMode +
                    " MissionTime=" + missionTime.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) +
                    " SynchronizedPeers=" + synchronizedPeerCount;
                return true;
            }

            if (isExactCampaignBattleScene && synchronizedPeerCount <= 0)
            {
                reason =
                    "MissionMode=" + missionMode +
                    " MissionTime=" + missionTime.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) +
                    " SynchronizedPeers=" + synchronizedPeerCount +
                    " ExactScenePeerGate=pending";
                return true;
            }

            return false;
        }

        private static bool IsSceneAwareBattleMapRuntime(Mission mission)
        {
            string sceneName = mission?.SceneName ?? string.Empty;
            return SceneRuntimeClassifier.IsSceneAwareBattleRuntimeScene(sceneName);
        }

        public static bool ShouldDedicatedObserverUseStrictNativeReadyGate(Mission mission)
        {
            return ShouldDedicatedObserverOwnExactSiegeLifecycle(mission);
        }

        internal static bool ShouldDedicatedObserverOwnExactSiegeLifecycle(Mission mission)
        {
            if (mission == null ||
                !GameNetwork.IsDedicatedServer ||
                !IsSceneAwareBattleMapRuntime(mission) ||
                !SceneRuntimeClassifier.IsExactCampaignBattleScene(mission.SceneName ?? string.Empty))
            {
                return false;
            }

            BattleScenarioContextMessage scenarioContext = null;
            try
            {
                scenarioContext = BattleSnapshotRuntimeState.GetCurrent()?.ScenarioContext ??
                                  BattleSnapshotRuntimeState.GetState()?.ScenarioContext ??
                                  BattleSnapshotRuntimeState.GetScenarioContext();
            }
            catch
            {
            }

            return ExactCampaignSiegeAssaultWithDeploymentRuntime.IsExactSiegeWithDeploymentScenario(scenarioContext) ||
                   ExactCampaignSiegeAssaultNoDeploymentRuntime.IsSiegeAssaultScenario(scenarioContext);
        }

        private static void LogBattleMapStartupDeferralIfNeeded(Mission mission, string source, string reason)
        {
            DateTime nowUtc = DateTime.UtcNow;
            if (nowUtc < _nextBattleMapStartupDeferLogUtc)
                return;

            _nextBattleMapStartupDeferLogUtc = nowUtc.AddSeconds(2);
            ModLogger.Info(
                "CoopMissionSpawnLogic: deferred risky battle-map startup runtime. " +
                "Mission=" + (mission?.SceneName ?? "null") +
                " Source=" + (source ?? "unknown") +
                " Reason=" + (reason ?? "unknown"));
        }

        public static void RunCoopBattleSpawnOwnerTick(Mission mission, string source)
        {
            string spawnSource = string.IsNullOrWhiteSpace(source) ? "CoopBattle spawn owner" : source;
            RunSharedServerBattleLifecycleTick(
                mission,
                spawnSource,
                applyPreMaterializationPeerNudges: true);
            RunVanillaSpawnBridgeTick(
                mission,
                spawnSource);
        }

        public static void RunCoopBattlePhaseOwnerTick(Mission mission, string source)
        {
            if (mission == null || !GameNetwork.IsServer)
                return;

            string phaseSource = string.IsNullOrWhiteSpace(source) ? "CoopBattle phase owner" : source;
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "enter", phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "update-phase-before", phaseSource);
            TryUpdateBattlePhaseState(mission, phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "update-phase-after", phaseSource);
            TryConsumeBattlePhaseRequests(mission);
            ExactCampaignArmyBootstrap.TrySyncMissionTeamAiActivationState(
                mission,
                CoopBattlePhaseRuntimeState.GetPhase(),
                phaseSource + " exact-team-ai-gate");
            ExactCampaignArmyBootstrap.TryRepairSiegeAssaultWithDeploymentTeamAiLifecycle(
                mission,
                CoopBattlePhaseRuntimeState.GetPhase(),
                phaseSource + " siege-team-ai-lifecycle");
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "warmup-fallback-before", phaseSource);
            TryApplyNativeBattleMapWarmupFallback(mission, phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "warmup-fallback-after", phaseSource);
            TryApplyBattlePhaseAiHold(mission, phaseSource);
            TryApplyBattlePhaseFormationHold(mission, phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "native-reinforcement-sync-before", phaseSource);
            TrySyncExactCampaignNativeArmyBootstrapReinforcements(mission, phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "native-reinforcement-sync-after", phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "materialized-reinforcement-before", phaseSource);
            TrySpawnMaterializedBattlefieldReinforcements(mission, phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "materialized-reinforcement-after", phaseSource);
            TryCompleteBattleIfResolved(mission, phaseSource);
            AppendExactBattleAgentSpawnTraceLifecycleStep(mission, "phase-tick", "complete", phaseSource);
        }

        public static void TryRunClientExactCampaignVisualObserver(Mission mission)
        {
            if (mission == null || GameNetwork.IsServer || !IsClientExactCampaignVisualOverlayRuntime(mission))
                return;

            if (GameNetwork.IsClient &&
                !CoopMissionNetworkBridge.IsClientCurrentBattleSnapshotApplied(out string snapshotReadinessSummary))
            {
                string readinessSignature = snapshotReadinessSummary ?? string.Empty;
                if (!string.Equals(_lastDeferredClientExactVisualObserverSnapshotReadiness, readinessSignature, StringComparison.Ordinal))
                {
                    _lastDeferredClientExactVisualObserverSnapshotReadiness = readinessSignature;
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: deferred battle-map client exact visual observer until authoritative V2 battle snapshot is applied. " +
                        "Mission=" + (mission.SceneName ?? "null") +
                        " SnapshotReadiness=" + readinessSignature);
                }

                return;
            }

            _lastDeferredClientExactVisualObserverSnapshotReadiness = string.Empty;
            EnsureClientBattleSnapshotFreshForMission(mission, "client-exact-visual-observer");
            TryRefreshClientPostPossessionExactVisualPauseWindow(mission, "client-exact-visual-observer");
            TryProcessPendingClientExactCampaignVisualOverlays(mission);

            DateTime nowUtc = DateTime.UtcNow;
            if (nowUtc < _nextClientExactVisualWatchdogUtc)
                return;

            _nextClientExactVisualWatchdogUtc = nowUtc + ClientExactVisualWatchdogInterval;
            TryMaintainClientPeerHeroExactVisualOverlays(mission);
            TryMaintainClientBattlefieldTroopExactVisualOverlays(mission);
        }

        private static bool TryQueueClientExactCampaignVisualOverlay(
            Mission mission,
            Agent agent,
            string preferredEntryId,
            string source,
            double delaySeconds,
            bool force = false,
            bool includeWeaponsForRefresh = false)
        {
            if (mission == null || agent == null || agent.IsMount || !agent.IsActive() || GameNetwork.IsServer)
                return false;

            if (!IsClientExactCampaignVisualOverlayRuntime(mission))
                return false;

            if (!IsMissionPeerAgentEligibleForClientExactVisualOverlay(agent))
                return false;

            EnsureClientBattleSnapshotFreshForMission(mission, source ?? "client exact visual queue");

            string entryId = preferredEntryId;
            if (string.IsNullOrWhiteSpace(entryId) || BattleSnapshotRuntimeState.GetEntryState(entryId) == null)
                entryId = ResolveClientExactCampaignVisualOverlayEntryId(agent);

            if (string.IsNullOrWhiteSpace(entryId))
                return false;

            RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
            if (entryState == null)
                return false;

            bool exactHeroEntry = IsHeroEntryEligibleForExactPersonalPerks(entryState);
            if (exactHeroEntry && !IsExactCampaignHeroClientVisualBattleDataReady(mission))
                return false;

            if (exactHeroEntry &&
                ExactSiegeMaterializationModule.ShouldTreatClientHeroVisualAsServerPreSpawnResolved(
                    agent,
                    entryState,
                    out string serverPreSpawnReason,
                    out bool serverPreSpawnIncludesWeapons))
            {
                MarkClientHeroVisualAsServerPreSpawnResolved(
                    agent,
                    entryId,
                    entryState,
                    serverPreSpawnIncludesWeapons,
                    source ?? "client exact visual queue",
                    serverPreSpawnReason);
                return false;
            }

            if (exactHeroEntry &&
                SceneRuntimeClassifier.IsValidatedLordsHallScene(
                    mission.SceneName ?? string.Empty))
            {
                MarkClientHeroVisualAsServerPreSpawnResolved(
                    agent,
                    entryId,
                    entryState,
                    true,
                    source ?? "client exact visual queue",
                    "lordshall-server-create-time-equipment-owned-no-destructive-recovery");
                return false;
            }

            if (ShouldSuppressCampaignMirrorHeroesClientDestructiveVisualOverlay(
                    mission,
                    agent,
                    entryState,
                    source ?? "client exact visual queue",
                    out string campaignMirrorHeroesQueueSuppressReason))
            {
                MarkCampaignMirrorHeroesClientDestructiveVisualOverlaySuppressed(
                    agent,
                    entryId,
                    entryState,
                    source ?? "client exact visual queue",
                    campaignMirrorHeroesQueueSuppressReason);
                return false;
            }

            if (!IsHeroEntryEligibleForExactPersonalPerks(entryState) &&
                ShouldTreatClientExactSiegeTroopVisualAsServerPreSpawnResolved(
                    agent,
                    entryState,
                    out _,
                    out bool resolvedIncludesWeapons))
            {
                _pendingExactNativeClientVisualOverlaysByAgentIndex.Remove(agent.Index);
                _materializedArmyEntryIdByAgentIndex[agent.Index] = entryId;
                _exactNativeClientVisualOverlayEntryIdByAgentIndex[agent.Index] = entryId;
                _exactNativeClientVisualOverlayAppliedAgentIndices.Add(agent.Index);
                _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex[agent.Index] = resolvedIncludesWeapons;
                return false;
            }

            if (force &&
                ShouldSuppressRepeatedClientDestructiveVisualRefresh(
                    agent,
                    entryState,
                    includeWeaponsForRefresh,
                    source ?? "client exact visual queue"))
            {
                _pendingExactNativeClientVisualOverlaysByAgentIndex.Remove(agent.Index);
                return false;
            }

            if (ShouldPauseClientExactVisualOverlaysForReconnectFinalize(out _))
                return false;
            if (!IsHeroEntryEligibleForExactPersonalPerks(entryState) &&
                ShouldSuppressClientTroopExactVisualOverlayForLiveControl(agent, out _))
            {
                return false;
            }
            if (ShouldAwaitMountedHeroEquipmentSyncBeforeClientExactVisualRefresh(
                    agent,
                    entryState,
                    includeWeaponsForRefresh,
                    out string deferredHeroReason))
            {
                _pendingExactNativeClientVisualOverlaysByAgentIndex.Remove(agent.Index);
                ClearClientExactCampaignVisualOverlayAppliedState(agent.Index);
                TryLogDeferredHeroEquipmentSyncVisualGate(
                    agent,
                    entryId,
                    entryState,
                    includeWeaponsForRefresh,
                    source ?? "client exact visual queue",
                    deferredHeroReason);
                return false;
            }
            if (IsHeroEntryEligibleForExactPersonalPerks(entryState))
                UpdateStrictExactHeroTransferEntryState(agent.Index, entryId, entryState, source ?? "client exact visual queue");

            RefreshClientExactCampaignVisualOverlayAgentIndexState(
                agent,
                source ?? "client exact visual queue",
                preferredEntryId: entryId,
                logRefresh: true);

            _exactNativeClientVisualOverlayAgentByIndex[agent.Index] = agent;
            _exactNativeClientVisualOverlayEntryIdByAgentIndex[agent.Index] = entryId;
            TryApplyEntryIdentityToAgent(
                agent,
                entryState,
                applyBodyProperties: !ShouldPreserveSallyOutCreateTimeBodyProperties(agent, entryState));

            if (!force &&
                (_exactNativeClientVisualOverlayAppliedAgentIndices.Contains(agent.Index) ||
                 _pendingExactNativeClientVisualOverlaysByAgentIndex.ContainsKey(agent.Index)))
            {
                return false;
            }

            if (force)
            {
                _exactNativeClientVisualOverlayAppliedAgentIndices.Remove(agent.Index);
                _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex.Remove(agent.Index);
            }

            bool effectiveIncludeWeaponsForRefresh = includeWeaponsForRefresh;
            bool allowLocalControlledExactSiegeTroopWeaponRefresh =
                ShouldAllowLocalControlledExactSiegeTroopWeaponOverlayRefresh(
                    agent,
                    entryState,
                    out string localControlledExactSiegeWeaponRefreshReason);
            if (effectiveIncludeWeaponsForRefresh &&
                IsLocalPeerControlledAgent(agent) &&
                !allowLocalControlledExactSiegeTroopWeaponRefresh)
            {
                effectiveIncludeWeaponsForRefresh = false;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: suppressed weapon-inclusive pending client exact visual overlay for locally controlled agent. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + entryId +
                    " Reason=" + (localControlledExactSiegeWeaponRefreshReason ?? "local-controlled-live-wield-owned-by-client") +
                    " Source=" + (source ?? "unknown"));
            }
            else if (effectiveIncludeWeaponsForRefresh &&
                     allowLocalControlledExactSiegeTroopWeaponRefresh)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: allowed weapon-inclusive pending client exact visual overlay for local exact siege possessed troop repair. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + entryId +
                    " Reason=" + (localControlledExactSiegeWeaponRefreshReason ?? "local-controlled-exact-siege-possession-repair") +
                    " Source=" + (source ?? "unknown"));
            }
            else if (effectiveIncludeWeaponsForRefresh &&
                     ShouldSuppressClientTroopWeaponOverlayRefreshForExactSiege(agent, entryState, out string exactSiegeWeaponOverlayReason))
            {
                effectiveIncludeWeaponsForRefresh = false;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: suppressed weapon-inclusive pending client exact visual overlay for exact siege non-hero troop. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + entryId +
                    " Reason=" + (exactSiegeWeaponOverlayReason ?? "unknown") +
                    " Source=" + (source ?? "unknown"));
            }
            else if (effectiveIncludeWeaponsForRefresh &&
                     ShouldDowngradeClientMountedTroopWeaponOverlayRefresh(agent, entryState, out string mountedCooldownReason))
            {
                effectiveIncludeWeaponsForRefresh = false;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: downgraded weapon-inclusive pending client exact visual overlay for mounted non-local troop during local post-possession combat stabilization. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + entryId +
                    " Reason=" + (mountedCooldownReason ?? "unknown") +
                    " Source=" + (source ?? "unknown"));
            }

            DateTime notBeforeUtc = DateTime.UtcNow.AddSeconds(Math.Max(0.01, delaySeconds));
            if (!IsHeroEntryEligibleForExactPersonalPerks(entryState) &&
                ShouldPauseClientPostPossessionExactVisualForAgent(agent, out string postPossessionPauseReason) &&
                _clientPostPossessionExactVisualPauseResumeUtc > notBeforeUtc)
            {
                notBeforeUtc = _clientPostPossessionExactVisualPauseResumeUtc;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: deferred queued client exact visual overlay until local post-possession stabilization window completes. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + entryId +
                    " IncludeWeapons=" + effectiveIncludeWeaponsForRefresh +
                    " Reason=" + (postPossessionPauseReason ?? "unknown") +
                    " Source=" + (source ?? "unknown"));
            }

            _pendingExactNativeClientVisualOverlaysByAgentIndex[agent.Index] = new PendingClientExactVisualOverlayState
            {
                EntryId = entryId,
                CreatedUtc = DateTime.UtcNow,
                NotBeforeUtc = notBeforeUtc,
                RetryCount = 0,
                Source = source ?? "client exact visual queue",
                IncludeWeaponsForRefresh = effectiveIncludeWeaponsForRefresh
            };
            UpdateStrictExactHeroTransferVisualQueuedState(agent.Index, entryId, source ?? "client exact visual queue");
            ModLogger.Info(
                "CoopMissionSpawnLogic: queued client exact visual overlay refresh. " +
                "AgentIndex=" + agent.Index +
                " EntryId=" + entryId +
                " IncludeWeapons=" + effectiveIncludeWeaponsForRefresh +
                " Force=" + force +
                " DelaySeconds=" + Math.Max(0.01, (notBeforeUtc - DateTime.UtcNow).TotalSeconds).ToString("0.00") +
                " Source=" + (source ?? "unknown"));
            return true;
        }

        private static bool IsExactCampaignHeroClientVisualBattleDataReady(Mission mission)
        {
            if (mission == null ||
                !SceneRuntimeClassifier.IsExactCampaignArmyMaterializationScene(
                    mission.SceneName ?? string.Empty))
            {
                return true;
            }

            if (!CoopMissionNetworkBridge.IsClientCurrentBattleSnapshotApplied(out _))
                return false;

            CoopBattleEntryStatusBridgeFile.EntryStatusSnapshot status =
                CoopBattleEntryStatusBridgeFile.ReadStatus();
            return status?.BattleDataReady == true;
        }

        private static void MarkClientHeroVisualAsServerPreSpawnResolved(
            Agent agent,
            string entryId,
            RosterEntryState entryState,
            bool includesWeapons,
            string source,
            string reason)
        {
            if (agent == null || agent.Index < 0)
                return;

            bool alreadyResolved =
                _exactNativeClientVisualOverlayAppliedAgentIndices.Contains(agent.Index) &&
                _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex.TryGetValue(
                    agent.Index,
                    out bool appliedIncludesWeapons) &&
                (!includesWeapons || appliedIncludesWeapons);

            _pendingExactNativeClientVisualOverlaysByAgentIndex.Remove(agent.Index);
            _exactNativeClientVisualOverlayAgentByIndex[agent.Index] = agent;
            if (!string.IsNullOrWhiteSpace(entryId))
            {
                _materializedArmyEntryIdByAgentIndex[agent.Index] = entryId;
                _exactNativeClientVisualOverlayEntryIdByAgentIndex[agent.Index] = entryId;
            }

            _exactNativeClientVisualOverlayAppliedAgentIndices.Add(agent.Index);
            _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex[agent.Index] = includesWeapons;
            _clientHeroExactVisualWatchdogFirstSeenUtcByAgentIndex.Remove(agent.Index);
            _clientHeroExactVisualWatchdogLastAttemptUtcByAgentIndex.Remove(agent.Index);
            UpdateStrictExactHeroTransferVisualAppliedState(
                agent.Index,
                entryId,
                includesWeapons,
                (source ?? "server pre-spawn exact hero") + " resolved");

            if (alreadyResolved)
                return;

            ModLogger.Info(
                "CoopMissionSpawnLogic: accepted server pre-spawn exact hero visuals without destructive client refresh. " +
                "AgentIndex=" + agent.Index +
                " EntryId=" + (entryId ?? "null") +
                " TroopId=" + (agent.Character?.StringId ?? "null") +
                " Hero=" + (entryState?.IsHero ?? false) +
                " IncludesWeapons=" + includesWeapons +
                " Reason=" + (reason ?? "unknown") +
                " Source=" + (source ?? "unknown"));
        }

        private static bool ShouldSuppressCampaignMirrorHeroesClientDestructiveVisualOverlay(
            Mission mission,
            Agent agent,
            RosterEntryState entryState,
            string source,
            out string reason)
        {
            reason = null;
            if (GameNetwork.IsServer ||
                agent == null ||
                agent.IsMount ||
                entryState == null ||
                !IsCampaignMirrorHeroesRuntime() ||
                !IsHeroEntryEligibleForExactPersonalPerks(entryState))
            {
                return false;
            }

            Mission effectiveMission = mission ?? agent.Mission ?? Mission.Current;
            if (effectiveMission != null && !IsClientExactCampaignVisualOverlayRuntime(effectiveMission))
                return false;

            reason = "campaign-mirror-heroes-server-create-time-equipment-owned";
            return true;
        }

        private static void MarkCampaignMirrorHeroesClientDestructiveVisualOverlaySuppressed(
            Agent agent,
            string entryId,
            RosterEntryState entryState,
            string source,
            string reason)
        {
            if (agent == null || agent.Index < 0)
                return;

            bool alreadySuppressed =
                _exactNativeClientVisualOverlayAppliedAgentIndices.Contains(agent.Index) &&
                _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex.TryGetValue(agent.Index, out bool includesWeapons) &&
                includesWeapons;

            _pendingExactNativeClientVisualOverlaysByAgentIndex.Remove(agent.Index);
            _exactNativeClientVisualOverlayAgentByIndex[agent.Index] = agent;
            if (!string.IsNullOrWhiteSpace(entryId))
            {
                _materializedArmyEntryIdByAgentIndex[agent.Index] = entryId;
                _exactNativeClientVisualOverlayEntryIdByAgentIndex[agent.Index] = entryId;
            }

            _exactNativeClientVisualOverlayAppliedAgentIndices.Add(agent.Index);
            _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex[agent.Index] = true;
            _clientHeroExactVisualWatchdogFirstSeenUtcByAgentIndex.Remove(agent.Index);
            _clientHeroExactVisualWatchdogLastAttemptUtcByAgentIndex.Remove(agent.Index);
            UpdateStrictExactHeroTransferVisualAppliedState(
                agent.Index,
                entryId,
                true,
                (source ?? "campaign mirror heroes client overlay suppression") + " suppressed");

            if (!alreadySuppressed)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: suppressed campaign mirror heroes client destructive visual overlay. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + (entryId ?? "null") +
                    " TroopId=" + (agent.Character?.StringId ?? "null") +
                    " Hero=" + (entryState?.IsHero ?? false) +
                    " Reason=" + (reason ?? "unknown") +
                    " Source=" + (source ?? "unknown"));
            }
        }

        private static void ClearClientExactCampaignVisualOverlayAgentIndexState(
            int agentIndex,
            string source,
            bool logClear = false,
            string reason = null)
        {
            if (agentIndex < 0)
                return;

            bool hadTrackedAgent = _exactNativeClientVisualOverlayAgentByIndex.Remove(agentIndex);
            bool hadApplied = _exactNativeClientVisualOverlayAppliedAgentIndices.Remove(agentIndex);
            bool hadIncludesWeapons = _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex.Remove(agentIndex);
            bool hadEntryId = _exactNativeClientVisualOverlayEntryIdByAgentIndex.Remove(agentIndex);
            bool hadTrackedMount = ClearTrackedClientMountedHeroMountAgentIndexState(agentIndex);
            bool hadPending = _pendingExactNativeClientVisualOverlaysByAgentIndex.Remove(agentIndex);
            bool hadCreateAgentRuntime = _clientCreateAgentExactVisualStateByAgentIndex.Remove(agentIndex);
            bool hadAuthoritativeMaterializedObserved = _clientAuthoritativeMaterializedEntryObservedAgentIndices.Remove(agentIndex);
            bool hadWatchdogFirstSeen = _clientHeroExactVisualWatchdogFirstSeenUtcByAgentIndex.Remove(agentIndex);
            bool hadWatchdogLastAttempt = _clientHeroExactVisualWatchdogLastAttemptUtcByAgentIndex.Remove(agentIndex);
            _lastLoggedDeferredHeroEquipmentSyncVisualSignatureByAgentIndex.Remove(agentIndex);
            bool hadStrictTransferState = _strictExactHeroTransferStateByRiderAgentIndex.ContainsKey(agentIndex);
            ClearStrictExactHeroTransferState(agentIndex, source, reason, logClear: false);
            if (logClear &&
                (hadTrackedAgent || hadApplied || hadIncludesWeapons || hadEntryId || hadTrackedMount || hadPending || hadCreateAgentRuntime || hadAuthoritativeMaterializedObserved || hadWatchdogFirstSeen || hadWatchdogLastAttempt || hadStrictTransferState))
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: cleared client exact visual overlay agent-index state. " +
                    "AgentIndex=" + agentIndex +
                    " Reason=" + (reason ?? "unknown") +
                    " Source=" + (source ?? "unknown") +
                    " HadTrackedAgent=" + hadTrackedAgent +
                    " HadApplied=" + hadApplied +
                    " HadIncludesWeapons=" + hadIncludesWeapons +
                    " HadEntryId=" + hadEntryId +
                    " HadTrackedMount=" + hadTrackedMount +
                    " HadPending=" + hadPending +
                    " HadCreateAgentRuntime=" + hadCreateAgentRuntime +
                    " HadAuthoritativeMaterializedObserved=" + hadAuthoritativeMaterializedObserved +
                    " HadStrictTransferState=" + hadStrictTransferState +
                    " HadWatchdogFirstSeen=" + hadWatchdogFirstSeen +
                    " HadWatchdogLastAttempt=" + hadWatchdogLastAttempt);
            }
        }

        private static void ClearClientExactCampaignVisualOverlayAppliedState(int agentIndex)
        {
            if (agentIndex < 0)
                return;

            _exactNativeClientVisualOverlayAppliedAgentIndices.Remove(agentIndex);
            _exactNativeClientVisualOverlayIncludesWeaponsByAgentIndex.Remove(agentIndex);
        }

        private static ClientCreateAgentExactVisualRuntimeState GetOrCreateClientCreateAgentExactVisualState(int agentIndex)
        {
            if (agentIndex < 0)
                return null;

            if (_clientCreateAgentExactVisualStateByAgentIndex.TryGetValue(agentIndex, out ClientCreateAgentExactVisualRuntimeState state) &&
                state != null)
            {
                return state;
            }

            state = new ClientCreateAgentExactVisualRuntimeState
            {
                AuthoritativeMaterializedEntryObserved =
                    _clientAuthoritativeMaterializedEntryObservedAgentIndices.Contains(agentIndex),
                LifecycleGeneration = 1,
                FirstObservedUtc = DateTime.UtcNow,
                LastObservedUtc = DateTime.UtcNow
            };
            _clientCreateAgentExactVisualStateByAgentIndex[agentIndex] = state;
            return state;
        }

        private static bool TryGetClientCreateAgentExactVisualState(int agentIndex, out ClientCreateAgentExactVisualRuntimeState state)
        {
            return _clientCreateAgentExactVisualStateByAgentIndex.TryGetValue(agentIndex, out state) && state != null;
        }

        private static ClientCreateAgentExactVisualRuntimeState PrepareClientCreateAgentExactVisualStateForPayload(
            int agentIndex,
            string resolvedEntryId,
            string source)
        {
            if (agentIndex < 0)
                return null;

            int nextLifecycleGeneration = 1;
            if (TryGetClientCreateAgentExactVisualState(agentIndex, out ClientCreateAgentExactVisualRuntimeState existingState) &&
                existingState != null)
            {
                nextLifecycleGeneration = Math.Max(1, existingState.LifecycleGeneration + 1);
                bool resolvedEntryChanged =
                    !string.IsNullOrWhiteSpace(resolvedEntryId) &&
                    !string.IsNullOrWhiteSpace(existingState.EntryId) &&
                    !string.Equals(existingState.EntryId, resolvedEntryId, StringComparison.Ordinal);
                Agent currentAgent = null;
                try
                {
                    currentAgent = Mission.MissionNetworkHelper.GetAgentFromIndex(agentIndex, canBeNull: true);
                }
                catch
                {
                    currentAgent = null;
                }

                bool sameMaterializedLifecycle =
                    existingState.CreateAgentPostfixObserved &&
                    existingState.MaterializedAgent != null &&
                    currentAgent != null &&
                    ReferenceEquals(existingState.MaterializedAgent, currentAgent) &&
                    currentAgent.IsActive();
                bool beginNewLifecycle =
                    existingState.CreateAgentPostfixObserved &&
                    (resolvedEntryChanged || !sameMaterializedLifecycle);
                if (beginNewLifecycle)
                {
                    string previousEntryId = existingState.EntryId;
                    int previousLifecycleGeneration = existingState.LifecycleGeneration;
                    ClearClientExactCampaignVisualOverlayAgentIndexState(
                        agentIndex,
                        source ?? "client create-agent payload",
                        logClear: ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics,
                        reason: "new-create-agent-lifecycle");
                    ClientCreateAgentExactVisualRuntimeState resetState =
                        GetOrCreateClientCreateAgentExactVisualState(agentIndex);
                    if (resetState != null)
                    {
                        resetState.LifecycleGeneration = nextLifecycleGeneration;
                        if (ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics)
                        {
                            ModLogger.Info(
                                "CoopMissionSpawnLogic: began new client create-agent exact visual lifecycle. " +
                                "AgentIndex=" + agentIndex +
                                " PreviousEntryId=" + (previousEntryId ?? "null") +
                                " NewEntryId=" + (resolvedEntryId ?? "null") +
                                " PreviousGeneration=" + previousLifecycleGeneration +
                                " NewGeneration=" + resetState.LifecycleGeneration +
                                " Source=" + (source ?? "unknown"));
                        }
                    }

                    return resetState;
                }
            }

            return GetOrCreateClientCreateAgentExactVisualState(agentIndex);
        }

        private static string BuildClientExactVisualRefreshRuntimeSignature(
            Agent agent,
            RosterEntryState entryState,
            bool includeWeaponsForRefresh)
        {
            if (agent == null || entryState == null)
                return null;

            Agent mountAgent = agent.MountAgent;
            return
                "EntryId=" + (entryState.EntryId ?? "null") +
                "|IncludeWeapons=" + includeWeaponsForRefresh +
                "|ExpectedWeapons={" + Infrastructure.ExactCreateAgentPayloadDiagnostics.BuildEntryWeaponLayoutSummary(entryState) + "}" +
                "|SpawnWeapons={" + BuildExactEntryEquipmentSummary(
                    agent.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3) + "}" +
                "|MissionWeapons={" + BuildMissionEquipmentSummary(
                    agent.Equipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3) + "}" +
                "|Armor={" + BuildExactEntryEquipmentSummary(
                    agent.SpawnEquipment,
                    EquipmentIndex.Head,
                    EquipmentIndex.Body,
                    EquipmentIndex.Leg,
                    EquipmentIndex.Gloves,
                    EquipmentIndex.Cape) + "}" +
                "|MountAgentIndex=" + (mountAgent?.Index.ToString() ?? "null") +
                "|Mount={" + BuildExactEntryEquipmentSummary(
                    mountAgent?.SpawnEquipment,
                    EquipmentIndex.Horse,
                    EquipmentIndex.HorseHarness) + "}";
        }

        private static bool ShouldSuppressRepeatedClientDestructiveVisualRefresh(
            Agent agent,
            RosterEntryState entryState,
            bool includeWeaponsForRefresh,
            string source)
        {
            if (GameNetwork.IsServer ||
                agent == null ||
                entryState == null ||
                IsHeroEntryEligibleForExactPersonalPerks(entryState) ||
                !TryGetClientCreateAgentExactVisualState(agent.Index, out ClientCreateAgentExactVisualRuntimeState state) ||
                state == null ||
                !string.Equals(state.EntryId, entryState.EntryId, StringComparison.Ordinal) ||
                string.IsNullOrWhiteSpace(state.LastCompletedDestructiveRefreshRuntimeSignature))
            {
                return false;
            }

            string currentRuntimeSignature =
                BuildClientExactVisualRefreshRuntimeSignature(agent, entryState, includeWeaponsForRefresh);
            if (!string.Equals(
                    state.LastCompletedDestructiveRefreshRuntimeSignature,
                    currentRuntimeSignature,
                    StringComparison.Ordinal))
            {
                state.RepeatedDestructiveRefreshSuppressionLogged = false;
                return false;
            }

            if (!state.RepeatedDestructiveRefreshSuppressionLogged &&
                ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics)
            {
                state.RepeatedDestructiveRefreshSuppressionLogged = true;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: suppressed repeated client destructive visual refresh because runtime equipment state is unchanged since the previous refresh. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + (entryState.EntryId ?? "null") +
                    " IncludeWeapons=" + includeWeaponsForRefresh +
                    " LifecycleGeneration=" + state.LifecycleGeneration +
                    " Source=" + (source ?? "unknown"));
            }

            return true;
        }

        internal static void ObserveClientCreateAgentPayloadResolvedEntry(CreateAgent createAgent, string source)
        {
            if (GameNetwork.IsServer || createAgent == null)
                return;

            bool payloadResolved = ExactCreateAgentCorridorDiagnostics.TryResolveClientCreateAgentPayloadEntryId(
                createAgent,
                out string entryId,
                out string resolutionState,
                out string payloadComparisonSummary);
            bool payloadResolutionStrongEnough =
                payloadResolved &&
                (string.Equals(resolutionState, "resolved-strong", StringComparison.Ordinal) ||
                 string.Equals(resolutionState, "resolved-layout", StringComparison.Ordinal)) &&
                !string.IsNullOrWhiteSpace(entryId);
            ClientCreateAgentExactVisualRuntimeState state =
                PrepareClientCreateAgentExactVisualStateForPayload(
                    createAgent.AgentIndex,
                    payloadResolutionStrongEnough ? entryId : null,
                    source);
            if (state == null)
                return;

            state.CreateAgentPayloadObserved = true;
            state.AuthoritativeMaterializedEntryObserved =
                _clientAuthoritativeMaterializedEntryObservedAgentIndices.Contains(createAgent.AgentIndex);
            state.LastObservedUtc = DateTime.UtcNow;
            if (state.InitialMissionWeaponItemIds == null)
                state.InitialMissionWeaponItemIds = CaptureClientMissionWeaponItemIds(createAgent.MissionEquipment);

            if (!payloadResolved)
                return;

            if (!payloadResolutionStrongEnough || string.IsNullOrWhiteSpace(entryId))
                return;

            state.EntryId = entryId;
            state.ResolutionState = resolutionState ?? "resolved";
            state.ResolutionSource = source ?? "unknown";
            _materializedArmyEntryIdByAgentIndex[createAgent.AgentIndex] = entryId;
            _exactNativeClientVisualOverlayEntryIdByAgentIndex[createAgent.AgentIndex] = entryId;
            BattleSideEnum payloadSide = ResolveCreateAgentPayloadBattleSide(createAgent.TeamIndex);
            if (payloadSide != BattleSideEnum.None)
                _materializedArmySideByAgentIndex[createAgent.AgentIndex] = payloadSide;

            ModLogger.Info(
                "CoopMissionSpawnLogic: registered client create-agent payload entry mapping. " +
                "AgentIndex=" + createAgent.AgentIndex +
                " EntryId=" + entryId +
                " ResolutionState=" + (resolutionState ?? "unknown") +
                " PayloadCompare=" + payloadComparisonSummary +
                " Source=" + (source ?? "unknown"));
        }

        internal static void ObserveClientCreateAgentPostfix(Agent agent, string source)
        {
            if (GameNetwork.IsServer || agent == null || agent.Index < 0)
                return;

            ClientCreateAgentExactVisualRuntimeState state = GetOrCreateClientCreateAgentExactVisualState(agent.Index);
            if (state == null)
                return;

            state.CreateAgentPostfixObserved = true;
            state.MaterializedAgent = agent;
            state.LastObservedUtc = DateTime.UtcNow;
            if (state.InitialMissionWeaponItemIds == null)
                state.InitialMissionWeaponItemIds = CaptureClientMissionWeaponItemIds(agent.Equipment);
            if (string.IsNullOrWhiteSpace(state.EntryId) &&
                _materializedArmyEntryIdByAgentIndex.TryGetValue(agent.Index, out string trackedEntryId) &&
                !string.IsNullOrWhiteSpace(trackedEntryId))
            {
                state.EntryId = trackedEntryId;
            }

            if (string.IsNullOrWhiteSpace(state.EntryId) &&
                _exactNativeClientVisualOverlayEntryIdByAgentIndex.TryGetValue(agent.Index, out string overlayEntryId) &&
                !string.IsNullOrWhiteSpace(overlayEntryId))
            {
                state.EntryId = overlayEntryId;
            }

            if (!string.IsNullOrWhiteSpace(state.EntryId))
            {
                CacheExactDisplayNameForAgent(
                    agent,
                    state.EntryId,
                    BattleSnapshotRuntimeState.GetEntryState(state.EntryId));
            }

            TryObserveClientInitialExactSiegeTroopWeaponLayout(agent, state);
        }

