        private static string ResolveRoleMatrixStreamSlotItemId(RoleMatrixStreamPalette palette, RoleMatrixStreamSlotRole role)
        {
            if (palette == null)
                return null;

            switch (role)
            {
                case RoleMatrixStreamSlotRole.Bow:
                    return palette.BowId;
                case RoleMatrixStreamSlotRole.Crossbow:
                    return palette.CrossbowId;
                case RoleMatrixStreamSlotRole.Bolt:
                    return palette.BoltId;
                case RoleMatrixStreamSlotRole.Arrow:
                    return palette.ArrowId;
                case RoleMatrixStreamSlotRole.Throwing:
                    return palette.ThrowingId;
                case RoleMatrixStreamSlotRole.Shield:
                    return palette.ShieldId;
                case RoleMatrixStreamSlotRole.OneHanded:
                    return palette.OneHandedId;
                case RoleMatrixStreamSlotRole.Bastard:
                    return palette.BastardId;
                case RoleMatrixStreamSlotRole.TwoHanded:
                    return palette.TwoHandedId;
                case RoleMatrixStreamSlotRole.Polearm:
                    return palette.PolearmId;
                default:
                    return null;
            }
        }

        private static string FormatRoleMatrixStreamSlotRole(RoleMatrixStreamSlotRole role)
        {
            switch (role)
            {
                case RoleMatrixStreamSlotRole.Bow:
                    return "bow";
                case RoleMatrixStreamSlotRole.Crossbow:
                    return "crossbow";
                case RoleMatrixStreamSlotRole.Bolt:
                    return "bolt";
                case RoleMatrixStreamSlotRole.Arrow:
                    return "arrow";
                case RoleMatrixStreamSlotRole.Throwing:
                    return "throwing";
                case RoleMatrixStreamSlotRole.Shield:
                    return "shield";
                case RoleMatrixStreamSlotRole.OneHanded:
                    return "one_handed";
                case RoleMatrixStreamSlotRole.Bastard:
                    return "bastard";
                case RoleMatrixStreamSlotRole.TwoHanded:
                    return "two_handed";
                case RoleMatrixStreamSlotRole.Polearm:
                    return "polearm";
                default:
                    return "empty";
            }
        }

        private static ItemObject TryResolveRoleMatrixStreamItem(string itemId)
        {
            if (string.IsNullOrWhiteSpace(itemId) || MBObjectManager.Instance == null)
                return null;

            try
            {
                return MBObjectManager.Instance.GetObject<ItemObject>(itemId);
            }
            catch
            {
                return null;
            }
        }

        private static string SetIfEmpty(string target, string value)
        {
            return string.IsNullOrWhiteSpace(target) && !string.IsNullOrWhiteSpace(value)
                ? value
                : target;
        }

        private static bool ContainsAnyOrdinal(string value, params string[] tokens)
        {
            if (string.IsNullOrWhiteSpace(value) || tokens == null)
                return false;

            foreach (string token in tokens)
            {
                if (!string.IsNullOrWhiteSpace(token) &&
                    value.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private static void EnsureRoleMatrixStreamRuntimeInitialized(Mission mission, string source)
        {
            if (ReferenceEquals(_roleMatrixStreamMission, mission))
                return;

            ResetRoleMatrixStreamRuntime("new-mission");
            _roleMatrixStreamMission = mission;
            _hasMaterializedBattlefieldArmies = false;
            _hasTriggeredAuthoritativeBattleCompletion = false;
            _authoritativeBattleCompletionReason = string.Empty;
            _authoritativeBattleWinnerSide = string.Empty;
            _materializedArmyEntryIdByAgentIndex.Clear();
            ResetAuthoritativeMaterializedAgentEntryLedger(mission);
            MarkAuthoritativeMaterializedAgentEntryCacheDirty();
            _materializedArmySideByAgentIndex.Clear();
            _materializedAgentInstanceByIndex.Clear();
            _customAiTargetPulseStateByAgentIndex.Clear();
            ResetMaterializedCombatProfileRuntimeState();

            IReadOnlyList<RoleMatrixStreamEntryDefinition> allDefinitions =
                BuildRoleMatrixStreamDefinitionsFromRuntime();
            HashSet<string> unsafeMatrixIds = CoopRoleMatrixStreamBridgeFile.ReadUnsafeMatrixIds();
            _roleMatrixStreamTotalMatrixCount = allDefinitions.Count;
            _roleMatrixStreamSkippedUnsafeCount = unsafeMatrixIds.Count;
            _roleMatrixStreamDefinitions = allDefinitions
                .Where(definition => definition != null &&
                                     !unsafeMatrixIds.Contains(definition.MatrixId ?? string.Empty))
                .OrderBy(definition => definition.MatrixIndex)
                .ToList();
            _roleMatrixStreamSkippedUnsafeCount = Math.Max(0, allDefinitions.Count - _roleMatrixStreamDefinitions.Count);
            _roleMatrixStreamCursor = 0;
            _roleMatrixStreamWave = 0;
            _roleMatrixStreamFinished = false;
            _roleMatrixStreamKillingWave = false;
            _roleMatrixStreamSpectatorAutoStartRequested = false;
            _roleMatrixStreamBattleStartedFromSpectator = false;
            _roleMatrixStreamWaveStartedUtc = DateTime.MinValue;
            _nextRoleMatrixStreamLogUtc = DateTime.MinValue;
            _nextRoleMatrixStreamAiPulseUtc = DateTime.MinValue;
            WriteRoleMatrixStreamProgress(mission, "Initialized", source);
            BattleSnapshotMessage currentSnapshot = BattleSnapshotRuntimeState.GetCurrent();
            int activeLimit = ResolveRoleMatrixStreamEffectiveActiveLimit(currentSnapshot);
            float waveLifetime = CoopTestBattleOptions.ResolveRoleMatrixStreamWaveLifetimeSeconds(currentSnapshot);
            ModLogger.Info(
                "CoopMissionSpawnLogic: role-matrix stream initialized. " +
                "Definitions=" + _roleMatrixStreamDefinitions.Count +
                " Total=" + _roleMatrixStreamTotalMatrixCount +
                " SkippedUnsafe=" + _roleMatrixStreamSkippedUnsafeCount +
                " ActiveLimit=" + activeLimit +
                " WaveLifetime=" + waveLifetime.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                " WeaponPriority=" + IsCampaignMirrorAllWeaponPriorityRuntime() +
                " WeaponPriorityFocus=" + CoopTestBattleOptions.ResolveWeaponPriorityFocus(currentSnapshot) +
                " Source=" + (source ?? "unknown"));
        }

        private static BattleSideEnum ResolveRoleMatrixStreamDefinitionSide(RoleMatrixStreamEntryDefinition definition)
        {
            if (definition?.CampaignMirrorEntry != null)
            {
                BattleSideEnum campaignSide = ResolveRoleMatrixStreamSide(
                    definition.CampaignMirrorEntry.SideId,
                    null);
                if (campaignSide != BattleSideEnum.None)
                    return campaignSide;
            }

            return definition != null && definition.MatrixIndex % 2 == 0
                ? BattleSideEnum.Defender
                : BattleSideEnum.Attacker;
        }

        private static string GetRoleMatrixStreamSourceLabel()
        {
            return IsCampaignMirrorAllRuntime()
                ? "campaign-mirror-stream"
                : "role-matrix-stream";
        }

        private static void SpawnRoleMatrixStreamWave(Mission mission, string source)
        {
            if (mission == null || _roleMatrixStreamDefinitions.Count == 0)
                return;

            Team attackerTeam = mission.Teams?.Attacker;
            Team defenderTeam = mission.Teams?.Defender;
            if (attackerTeam == null || defenderTeam == null)
                return;

            int activeLimit = ResolveRoleMatrixStreamEffectiveActiveLimit(BattleSnapshotRuntimeState.GetCurrent());
            int spawned = 0;
            int attempted = 0;
            _roleMatrixStreamWave++;
            CoopBattlePhase currentPhase = CoopBattlePhaseRuntimeState.GetPhase();
            _roleMatrixStreamWaveStartedUtc =
                currentPhase >= CoopBattlePhase.BattleActive &&
                currentPhase < CoopBattlePhase.BattleEnded
                    ? DateTime.UtcNow
                    : DateTime.MinValue;
            WriteRoleMatrixStreamProgress(mission, "Starting", source);

            while (_roleMatrixStreamCursor < _roleMatrixStreamDefinitions.Count &&
                   _roleMatrixStreamActiveAgentsByIndex.Count < activeLimit)
            {
                RoleMatrixStreamEntryDefinition definition =
                    _roleMatrixStreamDefinitions[_roleMatrixStreamCursor++];
                BattleSideEnum side = ResolveRoleMatrixStreamDefinitionSide(definition);
                Team team = side == BattleSideEnum.Defender ? defenderTeam : attackerTeam;
                RosterEntryState entryState = BuildRoleMatrixStreamEntryState(definition, side);
                BasicCharacterObject troop = ResolveRoleMatrixStreamTroop(entryState);
                attempted++;

                if (entryState == null || troop == null || team == null)
                {
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: role-matrix stream skipped matrix because spawn template was unavailable. " +
                        "MatrixId=" + (definition.MatrixId ?? "null") +
                        " EntryId=" + (entryState?.EntryId ?? "null") +
                        " SpawnTemplateId=" + (entryState?.SpawnTemplateId ?? "null") +
                        " Side=" + side +
                        " Source=" + (source ?? "unknown"));
                    continue;
                }

                int beforeCount = _roleMatrixStreamActiveAgentsByIndex.Count;
                int sideOffset = CountRoleMatrixStreamActiveAgentsForSide(side);
                WriteRoleMatrixStreamPlannedProgress(mission, definition, entryState, side, source);
                int spawnedForEntry = SpawnMaterializedAgentsForEntry(
                    mission,
                    team,
                    side,
                    troop,
                    entryState,
                    spawnCount: 1,
                    sideOffset: sideOffset,
                    source: GetRoleMatrixStreamSourceLabel() + " " + (source ?? "unknown"),
                    isReinforcement: false);
                if (spawnedForEntry <= 0)
                    continue;

                TrackRoleMatrixStreamSpawnedAgent(definition, entryState, side, source);
                if (_roleMatrixStreamActiveAgentsByIndex.Count > beforeCount)
                    spawned++;
            }

            if (spawned > 0)
            {
                _hasMaterializedBattlefieldArmies = true;
                _nextRoleMatrixStreamLogUtc = DateTime.UtcNow.AddSeconds(5);
            }

            WriteRoleMatrixStreamProgress(mission, spawned > 0 ? "Spawned" : "SpawnAttempted", source);
            int attackerActive = CountRoleMatrixStreamActiveAgentsForSide(BattleSideEnum.Attacker);
            int defenderActive = CountRoleMatrixStreamActiveAgentsForSide(BattleSideEnum.Defender);
            ModLogger.Info(
                "CoopMissionSpawnLogic: role-matrix stream wave spawned. " +
                "Wave=" + _roleMatrixStreamWave +
                " Attempted=" + attempted +
                " Spawned=" + spawned +
                " Active=" + _roleMatrixStreamActiveAgentsByIndex.Count +
                " AttackerActive=" + attackerActive +
                " DefenderActive=" + defenderActive +
                " Cursor=" + _roleMatrixStreamCursor + "/" + _roleMatrixStreamDefinitions.Count +
                " WeaponPriority=" + IsCampaignMirrorAllWeaponPriorityRuntime() +
                " WeaponPriorityFocus=" + CoopTestBattleOptions.ResolveWeaponPriorityFocus(BattleSnapshotRuntimeState.GetCurrent()) +
                " Source=" + (source ?? "unknown"));
        }

        private static BasicCharacterObject ResolveRoleMatrixStreamTroop(RosterEntryState entryState)
        {
            if (entryState == null || MBObjectManager.Instance == null)
                return null;

            foreach (string candidateId in new[]
            {
                entryState.SpawnTemplateId,
                entryState.CharacterId,
                entryState.OriginalCharacterId,
                "mp_coop_light_infantry_empire_troop",
                "mp_heavy_infantry_vlandia_troop"
            })
            {
                if (string.IsNullOrWhiteSpace(candidateId))
                    continue;

                try
                {
                    BasicCharacterObject character = MBObjectManager.Instance.GetObject<BasicCharacterObject>(candidateId);
                    if (character != null)
                        return character;
                }
                catch
                {
                }
            }

            return null;
        }

        private static void TrackRoleMatrixStreamSpawnedAgent(
            RoleMatrixStreamEntryDefinition definition,
            RosterEntryState entryState,
            BattleSideEnum side,
            string source)
        {
            if (definition == null || entryState == null || string.IsNullOrWhiteSpace(entryState.EntryId))
                return;

            foreach (KeyValuePair<int, string> pair in _materializedArmyEntryIdByAgentIndex.ToList())
            {
                if (!string.Equals(pair.Value, entryState.EntryId, StringComparison.OrdinalIgnoreCase))
                    continue;

                if (_roleMatrixStreamActiveAgentsByIndex.ContainsKey(pair.Key))
                    continue;

                _materializedAgentInstanceByIndex.TryGetValue(pair.Key, out Agent agent);
                if (agent == null || !agent.IsActive())
                    continue;

                Agent mountAgent = agent.MountAgent;
                var state = new RoleMatrixStreamActiveAgentState
                {
                    AgentIndex = pair.Key,
                    Agent = agent,
                    MountAgentIndex = mountAgent?.Index ?? -1,
                    MountAgent = mountAgent,
                    MatrixId = definition.MatrixId,
                    EntryId = entryState.EntryId,
                    SlotSummary = definition.SlotSummary,
                    Side = side,
                    SpawnedUtc = DateTime.UtcNow,
                    PriorityProfile = definition.PriorityProfile,
                    PrioritySuspect = definition.PrioritySuspect,
                    PriorityControl = definition.PriorityControl,
                    PriorityPairId = definition.PriorityPairId
                };
                _roleMatrixStreamActiveAgentsByIndex[pair.Key] = state;
                ObserveRoleMatrixStreamWeaponPriorityState(state, "spawn", source, force: true);
                return;
            }
        }

        private static int CountRoleMatrixStreamActiveAgentsForSide(BattleSideEnum side)
        {
            return _roleMatrixStreamActiveAgentsByIndex.Values.Count(state => state != null && state.Side == side);
        }

        private static int ResolveRoleMatrixStreamEffectiveActiveLimit(BattleSnapshotMessage snapshot)
        {
            int activeLimit = Math.Max(1, CoopTestBattleOptions.ResolveRoleMatrixStreamActiveLimit(snapshot));
            if (CoopTestBattleOptions.IsCampaignMirrorAllWeaponPrioritySnapshot(snapshot))
            {
                activeLimit = Math.Max(2, activeLimit);
                if (activeLimit > 2 && activeLimit % 2 != 0)
                    activeLimit--;
            }

            return activeLimit;
        }

        private static int TryPulseRoleMatrixStreamActiveWaveAi(Mission mission, string source, bool force)
        {
            if (mission == null || _roleMatrixStreamActiveAgentsByIndex.Count == 0)
                return 0;

            CoopBattlePhase currentPhase = CoopBattlePhaseRuntimeState.GetPhase();
            if (currentPhase < CoopBattlePhase.BattleActive || currentPhase >= CoopBattlePhase.BattleEnded)
                return 0;

            DateTime nowUtc = DateTime.UtcNow;
            if (!force && nowUtc < _nextRoleMatrixStreamAiPulseUtc)
                return 0;

            _nextRoleMatrixStreamAiPulseUtc = nowUtc.AddSeconds(RoleMatrixStreamAiPulseIntervalSeconds);

            int pulsedAgentCount = 0;
            int pulsedFormationCount = 0;
            var pulsedFormationKeys = new HashSet<int>();
            foreach (RoleMatrixStreamActiveAgentState state in _roleMatrixStreamActiveAgentsByIndex.Values.ToList())
            {
                Agent agent = state?.Agent;
                if (agent == null || !agent.IsActive())
                    continue;

                Formation formation = agent.Formation;
                Team team = agent.Team;
                if (formation == null ||
                    team == null ||
                    formation.CountOfUnits <= 0 ||
                    formation.PlayerOwner != null)
                {
                    continue;
                }

                int formationKey = GetBattlePhaseFormationKey(team, formation);
                if (!pulsedFormationKeys.Add(formationKey))
                    continue;

                try
                {
                    formation.SetMovementOrder(MovementOrder.MovementOrderCharge);
                    formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
                    formation.SetControlledByAI(true, true);
                    int pulsed = TryPulseFormationAiEngage(formation, team);
                    pulsedAgentCount += pulsed;
                    if (pulsed > 0)
                        pulsedFormationCount++;
                }
                catch (Exception ex)
                {
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: role-matrix stream AI pulse failed. " +
                        "AgentIndex=" + agent.Index +
                        " MatrixId=" + (state.MatrixId ?? "null") +
                        " EntryId=" + (state.EntryId ?? "null") +
                        " TeamSide=" + team.Side +
                        " Formation=" + formation.FormationIndex +
                        " Message=" + ex.Message +
                        " Source=" + (source ?? "unknown"));
                }
            }

            int attackerActiveCount = CountRoleMatrixStreamActiveAgentsForSide(BattleSideEnum.Attacker);
            int defenderActiveCount = CountRoleMatrixStreamActiveAgentsForSide(BattleSideEnum.Defender);
            if (IsWeaponPrioritySuspectFocusRuntime() &&
                attackerActiveCount > 0 &&
                defenderActiveCount > 0)
            {
                pulsedAgentCount += TryPulseWeaponPriorityDirectTargets(source);
            }
            else if (IsCampaignMirrorAllWeaponPriorityRuntime() &&
                     pulsedAgentCount == 0 &&
                     attackerActiveCount > 0 &&
                     defenderActiveCount > 0)
            {
                pulsedAgentCount += TryPulseWeaponPriorityDirectTargets(source);
            }

            if (force)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: role-matrix stream AI pulse. " +
                    "Formations=" + pulsedFormationCount +
                    " Agents=" + pulsedAgentCount +
                    " Active=" + _roleMatrixStreamActiveAgentsByIndex.Count +
                    " AttackerActive=" + attackerActiveCount +
                    " DefenderActive=" + defenderActiveCount +
                    " WeaponPriority=" + IsCampaignMirrorAllWeaponPriorityRuntime() +
                    " WeaponPriorityFocus=" + CoopTestBattleOptions.ResolveWeaponPriorityFocus(BattleSnapshotRuntimeState.GetCurrent()) +
                    " Source=" + (source ?? "unknown"));
            }

            return pulsedAgentCount;
        }

        private static int TryPulseWeaponPriorityDirectTargets(string source)
        {
            if (!IsWeaponPriorityTraceRuntime())
                return 0;

            List<RoleMatrixStreamActiveAgentState> attackers = _roleMatrixStreamActiveAgentsByIndex.Values
                .Where(state => state?.Side == BattleSideEnum.Attacker && state.Agent != null && state.Agent.IsActive())
                .OrderBy(state => state.AgentIndex)
                .ToList();
            List<RoleMatrixStreamActiveAgentState> defenders = _roleMatrixStreamActiveAgentsByIndex.Values
                .Where(state => state?.Side == BattleSideEnum.Defender && state.Agent != null && state.Agent.IsActive())
                .OrderBy(state => state.AgentIndex)
                .ToList();
            if (attackers.Count == 0 || defenders.Count == 0)
                return 0;

            int pulsed = 0;
            foreach (RoleMatrixStreamActiveAgentState state in _roleMatrixStreamActiveAgentsByIndex.Values.ToList())
            {
                Agent agent = state?.Agent;
                if (agent == null || !agent.IsActive() || agent.Controller != AgentControllerType.AI)
                    continue;

                List<RoleMatrixStreamActiveAgentState> enemyStates =
                    state.Side == BattleSideEnum.Attacker
                        ? defenders
                        : state.Side == BattleSideEnum.Defender
                            ? attackers
                            : null;
                if (enemyStates == null || enemyStates.Count == 0)
                    continue;

                RoleMatrixStreamActiveAgentState targetState =
                    enemyStates[Math.Abs(state.AgentIndex) % enemyStates.Count];
                Agent targetAgent = targetState?.Agent;
                if (targetAgent == null || !targetAgent.IsActive())
                    continue;

                try
                {
                    agent.SetAutomaticTargetSelection(true);
                    agent.SetWatchState(Agent.WatchState.Alarmed);
                    agent.SetAlarmState(Agent.AIStateFlag.Alarmed);
                    if (targetAgent.Formation != null)
                        agent.SetTargetFormationIndex((int)targetAgent.Formation.FormationIndex);
                    agent.SetTargetAgent(targetAgent);
                    agent.ForceAiBehaviorSelection();
                    if (IsWeaponPrioritySuspectFocusRuntime())
                        TryTraceWeaponPrioritySuspectDirectTarget(state, targetState, source);
                    pulsed++;
                }
                catch (Exception ex)
                {
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: WeaponPriorityDirectTarget failed. " +
                        "AgentIndex=" + state.AgentIndex +
                        " TargetAgentIndex=" + targetAgent.Index +
                        " Message=" + ex.Message +
                        " Source=" + (source ?? "unknown"));
                }
            }

            ModLogger.Info(
                "CoopMissionSpawnLogic: WeaponPriorityDirectTarget. " +
                "Agents=" + pulsed +
                " AttackerActive=" + attackers.Count +
                " DefenderActive=" + defenders.Count +
                " Source=" + (source ?? "unknown"));
            return pulsed;
        }

        private static void TryTraceWeaponPrioritySuspectDirectTarget(
            RoleMatrixStreamActiveAgentState state,
            RoleMatrixStreamActiveAgentState targetState,
            string source)
        {
            if (state?.Agent == null ||
                targetState?.Agent == null ||
                !IsWeaponPrioritySuspectFocusRuntime())
            {
                return;
            }

            try
            {
                Agent agent = state.Agent;
                Agent targetAgent = targetState.Agent;
                float targetDistance = SafeLength(targetAgent.Position - agent.Position);
                string missionWeapons = BuildMissionEquipmentSummary(
                    agent.Equipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);
                string targetMissionWeapons = BuildMissionEquipmentSummary(
                    targetAgent.Equipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);
                string focusRole = state.PrioritySuspect
                    ? "Suspect"
                    : state.PriorityControl
                        ? "Control"
                        : "Candidate";
                TryAddWeaponPriorityTransitionSample(
                    state,
                    "target:agent=" + targetAgent.Index +
                    ",distance=" + FormatProjectileLaunchFloat(targetDistance) +
                    ",targetEntry=" + (targetState.EntryId ?? "null"));
                ModLogger.Info(
                    "CoopMissionSpawnLogic: WeaponPrioritySuspectTarget. " +
                    "FocusRole=" + focusRole +
                    " PairId=" + (state.PriorityPairId ?? "null") +
                    " MatrixId=" + (state.MatrixId ?? "null") +
                    " EntryId=" + (state.EntryId ?? "null") +
                    " AgentIndex=" + state.AgentIndex +
                    " Side=" + state.Side +
                    " TargetMatrixId=" + (targetState.MatrixId ?? "null") +
                    " TargetEntryId=" + (targetState.EntryId ?? "null") +
                    " TargetAgentIndex=" + targetAgent.Index +
                    " TargetSide=" + targetState.Side +
                    " TargetDistance=" + FormatProjectileLaunchFloat(targetDistance) +
                    " MainRole=" + (state.LastMainRole ?? "unknown") +
                    " MainItem=" + (state.LastMainItemId ?? "unknown") +
                    " MissionWeapons={" + missionWeapons + "}" +
                    " TargetMissionWeapons={" + targetMissionWeapons + "}" +
                    " Source=" + (source ?? "unknown"));
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: WeaponPrioritySuspectTarget failed. " +
                    "AgentIndex=" + (state?.AgentIndex.ToString(System.Globalization.CultureInfo.InvariantCulture) ?? "null") +
                    " Message=" + ex.Message +
                    " Source=" + (source ?? "unknown"));
            }
        }

        private static void EnqueueRoleMatrixStreamActiveWaveForKill()
        {
            foreach (int agentIndex in _roleMatrixStreamActiveAgentsByIndex.Keys.ToList())
            {
                if (!_roleMatrixStreamKillQueue.Contains(agentIndex))
                    _roleMatrixStreamKillQueue.Enqueue(agentIndex);
            }
        }

        private static void DrainRoleMatrixStreamKillQueue(Mission mission, string source)
        {
            if (mission == null)
                return;

            int processed = 0;
            while (_roleMatrixStreamKillQueue.Count > 0 && processed < RoleMatrixStreamKillBatchPerTick)
            {
                int agentIndex = _roleMatrixStreamKillQueue.Dequeue();
                processed++;
                if (!_roleMatrixStreamActiveAgentsByIndex.TryGetValue(agentIndex, out RoleMatrixStreamActiveAgentState state))
                    continue;

                Agent agent = state.Agent;
                Agent mountAgent = ResolveRoleMatrixStreamMountAgent(state);
                TryWriteRoleMatrixStreamWeaponPrioritySummary(state, "kill-queue", source);

                if (agent != null && agent.IsActive())
                {
                    try
                    {
                        mission.KillAgentCheat(agent);
                    }
                    catch (Exception ex)
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: role-matrix stream failed to kill test agent. " +
                            "AgentIndex=" + agentIndex +
                            " MatrixId=" + (state.MatrixId ?? "null") +
                            " EntryId=" + (state.EntryId ?? "null") +
                            " Message=" + ex.Message +
                            " Source=" + (source ?? "unknown"));
                    }
                }

                if (mountAgent != null && mountAgent.IsActive())
                {
                    try
                    {
                        mission.KillAgentCheat(mountAgent);
                    }
                    catch (Exception ex)
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: role-matrix stream failed to kill test mount agent. " +
                            "AgentIndex=" + agentIndex +
                            " MountAgentIndex=" + mountAgent.Index +
                            " MatrixId=" + (state.MatrixId ?? "null") +
                            " EntryId=" + (state.EntryId ?? "null") +
                            " Message=" + ex.Message +
                            " Source=" + (source ?? "unknown"));
                    }
                }
            }
        }

        private static void PruneRoleMatrixStreamAgents()
        {
            foreach (KeyValuePair<int, RoleMatrixStreamActiveAgentState> pair in _roleMatrixStreamActiveAgentsByIndex.ToList())
            {
                Agent agent = pair.Value?.Agent;
                if (agent == null || !agent.IsActive())
                {
                    TryWriteRoleMatrixStreamWeaponPrioritySummary(pair.Value, "prune-inactive", "prune");
                    TryKillRoleMatrixStreamOrphanMount(pair.Value, "prune-inactive-rider");
                    _roleMatrixStreamActiveAgentsByIndex.Remove(pair.Key);
                }
            }
        }

        private static void TryHandleRoleMatrixStreamAgentRemoved(int agentIndex)
        {
            if (agentIndex < 0)
                return;

            if (_roleMatrixStreamActiveAgentsByIndex.TryGetValue(agentIndex, out RoleMatrixStreamActiveAgentState state))
            {
                TryWriteRoleMatrixStreamWeaponPrioritySummary(state, "agent-removed", "agent-removed");
                TryKillRoleMatrixStreamOrphanMount(state, "agent-removed");
            }

            _roleMatrixStreamActiveAgentsByIndex.Remove(agentIndex);
        }

        private static void ObserveRoleMatrixStreamWeaponPriority(Mission mission, string source, bool force)
        {
            if (mission == null || !IsWeaponPriorityTraceRuntime())
                return;

            foreach (RoleMatrixStreamActiveAgentState state in _roleMatrixStreamActiveAgentsByIndex.Values.ToList())
                ObserveRoleMatrixStreamWeaponPriorityState(state, "observe", source, force);
        }

        private static void ObserveRoleMatrixStreamWeaponPriorityState(
            RoleMatrixStreamActiveAgentState state,
            string eventName,
            string source,
            bool force)
        {
            if (state == null || !IsWeaponPriorityTraceRuntime())
                return;

            Agent agent = state.Agent;
            if (agent == null || !agent.IsActive() || agent.IsMount)
                return;

            RoleMatrixStreamWeaponPriorityWieldSnapshot snapshot =
                BuildRoleMatrixStreamWeaponPriorityWieldSnapshot(agent);
            if (snapshot == null || string.IsNullOrWhiteSpace(snapshot.Signature))
                return;

            bool hasLast = !string.IsNullOrWhiteSpace(state.LastWeaponSignature);
            bool changed = !string.Equals(
                state.LastWeaponSignature,
                snapshot.Signature,
                StringComparison.Ordinal);
            if (!force && hasLast && !changed)
                return;

            if (string.IsNullOrWhiteSpace(state.FirstWeaponSignature))
                state.FirstWeaponSignature = snapshot.Signature;

            if (hasLast && changed)
                state.WeaponChangeCount++;

            UpdateWeaponPriorityObservationFlags(state, snapshot);
            if (changed || !hasLast)
            {
                TryAddWeaponPriorityTransitionSample(
                    state,
                    (eventName ?? "observe") +
                    "#" + state.WeaponChangeCount +
                    ":main=" + snapshot.MainIndex +
                    "/" + (snapshot.MainItemId ?? "none") +
                    "/" + (snapshot.MainRole ?? "none") +
                    ",off=" + snapshot.OffhandIndex +
                    "/" + (snapshot.OffhandItemId ?? "none") +
                    "/" + (snapshot.OffhandRole ?? "none"));

                ModLogger.Info(
                    "CoopMissionSpawnLogic: WeaponPriorityTrace. " +
                    "Event=" + (eventName ?? "observe") +
                    " MatrixId=" + (state.MatrixId ?? "null") +
                    " EntryId=" + (state.EntryId ?? "null") +
                    " AgentIndex=" + state.AgentIndex +
                    " Side=" + state.Side +
                    " FocusRole=" + FormatWeaponPriorityFocusRole(state) +
                    " PairId=" + (state.PriorityPairId ?? "null") +
                    " Changed=" + changed +
                    " ChangeCount=" + state.WeaponChangeCount +
                    " Main=" + snapshot.MainIndex +
                    "/" + (snapshot.MainItemId ?? "none") +
                    "/" + (snapshot.MainRole ?? "none") +
                    " Offhand=" + snapshot.OffhandIndex +
                    "/" + (snapshot.OffhandItemId ?? "none") +
                    "/" + (snapshot.OffhandRole ?? "none") +
                    " Profile={" + (state.PriorityProfile ?? "null") + "}" +
                    " Source=" + (source ?? "unknown"));
            }

            state.LastWeaponSignature = snapshot.Signature;
            state.LastMainRole = snapshot.MainRole;
            state.LastMainItemId = snapshot.MainItemId;
        }

        private static RoleMatrixStreamWeaponPriorityWieldSnapshot BuildRoleMatrixStreamWeaponPriorityWieldSnapshot(Agent agent)
        {
            if (agent == null)
                return null;

            EquipmentIndex mainIndex = EquipmentIndex.None;
            EquipmentIndex offhandIndex = EquipmentIndex.None;
            MissionWeapon mainWeapon = MissionWeapon.Invalid;
            MissionWeapon offhandWeapon = MissionWeapon.Invalid;
            try
            {
                mainIndex = agent.GetPrimaryWieldedItemIndex();
            }
            catch
            {
            }

            try
            {
                offhandIndex = agent.GetOffhandWieldedItemIndex();
            }
            catch
            {
            }

            try
            {
                mainWeapon = agent.WieldedWeapon;
            }
            catch
            {
            }

            try
            {
                offhandWeapon = agent.WieldedOffhandWeapon;
            }
            catch
            {
            }

            string mainItemId = GetWeaponPriorityMissionWeaponItemId(mainWeapon);
            string offhandItemId = GetWeaponPriorityMissionWeaponItemId(offhandWeapon);
            string mainRole = ClassifyWeaponPriorityRole(mainWeapon);
            string offhandRole = ClassifyWeaponPriorityRole(offhandWeapon);
            string mainIndexText = FormatAgentWieldedEquipmentIndex(agent, mainIndex);
            string offhandIndexText = FormatAgentWieldedEquipmentIndex(agent, offhandIndex);
            return new RoleMatrixStreamWeaponPriorityWieldSnapshot
            {
                MainIndex = mainIndexText,
                MainItemId = mainItemId,
                MainRole = mainRole,
                OffhandIndex = offhandIndexText,
                OffhandItemId = offhandItemId,
                OffhandRole = offhandRole,
                Signature =
                    mainIndexText + "|" + (mainItemId ?? "none") + "|" + (mainRole ?? "none") + "|" +
                    offhandIndexText + "|" + (offhandItemId ?? "none") + "|" + (offhandRole ?? "none")
            };
        }

        private static void UpdateWeaponPriorityObservationFlags(
            RoleMatrixStreamActiveAgentState state,
            RoleMatrixStreamWeaponPriorityWieldSnapshot snapshot)
        {
            if (state == null || snapshot == null)
                return;

            string effectiveRole = ResolveWeaponPriorityEffectiveRole(snapshot);
            bool seesRangedOrThrown = IsWeaponPriorityRangedOrThrownRole(effectiveRole);
            bool seesMelee = IsWeaponPriorityMeleeRole(effectiveRole);
            if (seesRangedOrThrown)
                state.SawRangedOrThrown = true;
            if (state.SawRangedOrThrown && seesMelee)
                state.SawMeleeAfterRangedOrThrown = true;
        }

        private static string ResolveWeaponPriorityEffectiveRole(RoleMatrixStreamWeaponPriorityWieldSnapshot snapshot)
        {
            if (snapshot == null)
                return "none";

            if (!IsWeaponPriorityPassiveRole(snapshot.MainRole))
                return snapshot.MainRole;

            return !IsWeaponPriorityPassiveRole(snapshot.OffhandRole)
                ? snapshot.OffhandRole
                : snapshot.MainRole;
        }

        private static void TryTraceRoleMatrixStreamWeaponPriorityProjectile(
            Agent shooterAgent,
            EquipmentIndex weaponIndex,
            int forcedMissileIndex,
            string source)
        {
            if (!IsWeaponPriorityTraceRuntime() ||
                shooterAgent == null ||
                shooterAgent.IsMount ||
                !_roleMatrixStreamActiveAgentsByIndex.TryGetValue(shooterAgent.Index, out RoleMatrixStreamActiveAgentState state))
            {
                return;
            }

            try
            {
                MissionWeapon launchWeapon = ResolveAgentMissionWeapon(shooterAgent, weaponIndex);
                string launchItemId = GetWeaponPriorityMissionWeaponItemId(launchWeapon);
                string launchRole = ClassifyWeaponPriorityRole(launchWeapon);
                bool thrown = IsThrownProjectileLaunchWeapon(launchWeapon) ||
                              string.Equals(launchRole, "thrown", StringComparison.OrdinalIgnoreCase);
                bool ranged = IsWeaponPriorityRangedOrThrownRole(launchRole);
                state.ProjectileLaunchCount++;
                if (thrown)
                    state.ThrownProjectileLaunchCount++;
                else if (ranged)
                    state.RangedProjectileLaunchCount++;

                TryAddWeaponPriorityTransitionSample(
                    state,
                    "projectile#" + state.ProjectileLaunchCount +
                    ":slot=" + weaponIndex +
                    ",item=" + (launchItemId ?? "none") +
                    ",role=" + (launchRole ?? "none") +
                    ",forced=" + forcedMissileIndex);
                ObserveRoleMatrixStreamWeaponPriorityState(state, "projectile", source, force: true);
                ModLogger.Info(
                    "CoopMissionSpawnLogic: WeaponPriorityProjectile. " +
                    "MatrixId=" + (state.MatrixId ?? "null") +
                    " EntryId=" + (state.EntryId ?? "null") +
                    " AgentIndex=" + state.AgentIndex +
                    " FocusRole=" + FormatWeaponPriorityFocusRole(state) +
                    " PairId=" + (state.PriorityPairId ?? "null") +
                    " WeaponIndex=" + weaponIndex +
                    " LaunchItem=" + (launchItemId ?? "none") +
                    " LaunchRole=" + (launchRole ?? "none") +
                    " ProjectileCount=" + state.ProjectileLaunchCount +
                    " ThrownCount=" + state.ThrownProjectileLaunchCount +
                    " RangedCount=" + state.RangedProjectileLaunchCount +
                    " ForcedMissileIndex=" + forcedMissileIndex +
                    " Source=" + (source ?? "unknown"));
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: WeaponPriorityProjectile failed open. " +
                    "AgentIndex=" + shooterAgent.Index +
                    " Message=" + ex.Message +
                    " Source=" + (source ?? "unknown"));
            }
        }

        private static void TryWriteRoleMatrixStreamWeaponPrioritySummary(
            RoleMatrixStreamActiveAgentState state,
            string reason,
            string source)
        {
            if (state == null ||
                state.PrioritySummaryLogged ||
                !IsWeaponPriorityTraceRuntime())
            {
                return;
            }

            ObserveRoleMatrixStreamWeaponPriorityState(state, "summary", source, force: true);
            state.PrioritySummaryLogged = true;
            string result =
                state.SawRangedOrThrown && state.SawMeleeAfterRangedOrThrown
                    ? "ObservedRangedThenMelee"
                    : state.SawRangedOrThrown
                        ? "ObservedRangedOrThrownOnly"
                        : "NoRangedOrThrownWieldObserved";
            ModLogger.Info(
                "CoopMissionSpawnLogic: WeaponPrioritySummary. " +
                "Result=" + result +
                " Reason=" + (reason ?? "unknown") +
                " MatrixId=" + (state.MatrixId ?? "null") +
                " EntryId=" + (state.EntryId ?? "null") +
                " AgentIndex=" + state.AgentIndex +
                " Side=" + state.Side +
                " FocusRole=" + FormatWeaponPriorityFocusRole(state) +
                " PairId=" + (state.PriorityPairId ?? "null") +
                " Profile={" + (state.PriorityProfile ?? "null") + "}" +
                " First={" + (state.FirstWeaponSignature ?? "none") + "}" +
                " Last={" + (state.LastWeaponSignature ?? "none") + "}" +
                " Changes=" + state.WeaponChangeCount +
                " Projectiles=" + state.ProjectileLaunchCount +
                " ThrownProjectiles=" + state.ThrownProjectileLaunchCount +
                " RangedProjectiles=" + state.RangedProjectileLaunchCount +
                " SawRangedOrThrown=" + state.SawRangedOrThrown +
                " SawMeleeAfterRangedOrThrown=" + state.SawMeleeAfterRangedOrThrown +
                " Samples=[" + string.Join(" | ", state.WeaponTransitionSamples) + "]" +
                " Source=" + (source ?? "unknown"));
        }

        private static string FormatWeaponPriorityFocusRole(RoleMatrixStreamActiveAgentState state)
        {
            if (state == null)
                return "Unknown";

            if (state.PrioritySuspect)
                return "Suspect";

            return state.PriorityControl ? "Control" : "Candidate";
        }

        private static void TryAddWeaponPriorityTransitionSample(
            RoleMatrixStreamActiveAgentState state,
            string sample)
        {
            if (state == null ||
                string.IsNullOrWhiteSpace(sample) ||
                state.WeaponTransitionSamples.Count >= 10)
            {
                return;
            }

            state.WeaponTransitionSamples.Add(sample);
        }

        private static string GetWeaponPriorityMissionWeaponItemId(MissionWeapon weapon)
        {
            try
            {
                if (weapon.IsEmpty)
                    return null;

                return weapon.Item?.StringId;
            }
            catch
            {
                return null;
            }
        }

        private static string ClassifyWeaponPriorityRole(MissionWeapon weapon)
        {
            try
            {
                if (weapon.IsEmpty)
                    return "none";

                ItemObject item = weapon.Item;
                WeaponComponentData usage = weapon.CurrentUsageItem ?? item?.PrimaryWeapon;
                if (usage != null)
                {
                    if (usage.IsShield)
                        return "shield";
                    if (usage.IsAmmo)
                        return "ammo";
                    if (usage.RelevantSkill == DefaultSkills.Bow ||
                        usage.WeaponClass == WeaponClass.Bow)
                    {
                        return "bow";
                    }

                    if (usage.RelevantSkill == DefaultSkills.Crossbow ||
                        usage.WeaponClass == WeaponClass.Crossbow)
                    {
                        return "crossbow";
                    }

                    if (usage.RelevantSkill == DefaultSkills.Throwing ||
                        usage.WeaponClass == WeaponClass.Javelin ||
                        usage.WeaponClass == WeaponClass.ThrowingAxe ||
                        usage.WeaponClass == WeaponClass.ThrowingKnife ||
                        usage.WeaponClass == WeaponClass.Stone ||
                        usage.WeaponClass == WeaponClass.SlingStone)
                    {
                        return "thrown";
                    }

                    if (usage.RelevantSkill == DefaultSkills.Polearm || usage.IsPolearm)
                        return "polearm";
                    if (usage.RelevantSkill == DefaultSkills.OneHanded || usage.IsOneHanded)
                        return "one_handed";
                    if (usage.RelevantSkill == DefaultSkills.TwoHanded || usage.IsTwoHanded)
                        return "two_handed";
                    if (usage.IsRangedWeapon)
                        return "ranged";
                    if (usage.IsMeleeWeapon)
                        return "melee";
                }

                switch (item?.ItemType)
                {
                    case ItemObject.ItemTypeEnum.Shield:
                        return "shield";
                    case ItemObject.ItemTypeEnum.Arrows:
                    case ItemObject.ItemTypeEnum.Bolts:
                    case ItemObject.ItemTypeEnum.SlingStones:
                        return "ammo";
                    case ItemObject.ItemTypeEnum.Bow:
                        return "bow";
                    case ItemObject.ItemTypeEnum.Crossbow:
                        return "crossbow";
                    case ItemObject.ItemTypeEnum.Thrown:
                    case ItemObject.ItemTypeEnum.Sling:
                        return "thrown";
                    case ItemObject.ItemTypeEnum.Polearm:
                        return "polearm";
                    case ItemObject.ItemTypeEnum.OneHandedWeapon:
                        return "one_handed";
                    case ItemObject.ItemTypeEnum.TwoHandedWeapon:
                        return "two_handed";
                    default:
                        return item?.ItemType.ToString() ?? "other";
                }
            }
            catch
            {
                return "unknown";
            }
        }

        private static bool IsWeaponPriorityRangedOrThrownRole(string role)
        {
            return string.Equals(role, "bow", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "crossbow", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "thrown", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "ranged", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsWeaponPriorityPassiveRole(string role)
        {
            return string.IsNullOrWhiteSpace(role) ||
                   string.Equals(role, "none", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "shield", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "ammo", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "unknown", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsWeaponPriorityMeleeRole(string role)
        {
            return string.Equals(role, "one_handed", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "two_handed", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "polearm", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(role, "melee", StringComparison.OrdinalIgnoreCase);
        }

        private static void WriteRoleMatrixStreamProgress(Mission mission, string state, string source)
        {
            List<RoleMatrixStreamActiveAgentState> active = _roleMatrixStreamActiveAgentsByIndex.Values
                .Where(item => item != null)
                .OrderBy(item => item.MatrixId, StringComparer.OrdinalIgnoreCase)
                .ToList();
            WriteRoleMatrixStreamProgressSnapshot(
                mission,
                state,
                source,
                active.Count,
                string.Join(",", active.Select(item => item.MatrixId).Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase)),
                string.Join(",", active.Select(item => item.EntryId).Where(id => !string.IsNullOrWhiteSpace(id))),
                string.Join("; ", active.Select(item => (item.MatrixId ?? string.Empty) + "=" + (item.SlotSummary ?? string.Empty))));
        }

        private static void WriteRoleMatrixStreamPlannedProgress(
            Mission mission,
            RoleMatrixStreamEntryDefinition definition,
            RosterEntryState entryState,
            BattleSideEnum side,
            string source)
        {
            if (definition == null)
                return;

            string matrixId = definition.MatrixId ?? string.Empty;
            string entryId = entryState?.EntryId ?? string.Empty;
            string slotSummary = matrixId + "=" + (definition.SlotSummary ?? string.Empty);
            WriteRoleMatrixStreamProgressSnapshot(
                mission,
                "PlanningSpawn",
                (source ?? string.Empty) + " side=" + side,
                1,
                matrixId,
                entryId,
                slotSummary);
        }

        private static void WriteRoleMatrixStreamProgressSnapshot(
            Mission mission,
            string state,
            string source,
            int activeCount,
            string activeMatrixIds,
            string activeEntryIds,
            string activeSlotSummary)
        {
            CoopRoleMatrixStreamBridgeFile.WriteProgress(new CoopRoleMatrixStreamBridgeFile.ProgressSnapshot
            {
                BattleId = BattleSnapshotRuntimeState.GetCurrent()?.BattleId ?? string.Empty,
                MissionName = mission?.SceneName ?? string.Empty,
                Source = source ?? string.Empty,
                State = state ?? string.Empty,
                TotalMatrices = _roleMatrixStreamDefinitions.Count,
                SkippedUnsafeMatrices = _roleMatrixStreamSkippedUnsafeCount,
                Cursor = _roleMatrixStreamCursor,
                Wave = _roleMatrixStreamWave,
                ActiveCount = activeCount,
                ActiveMatrixIds = activeMatrixIds ?? string.Empty,
                ActiveEntryIds = activeEntryIds ?? string.Empty,
                ActiveSlotSummary = activeSlotSummary ?? string.Empty,
                UpdatedUtc = DateTime.UtcNow
            });
        }

        private static Agent ResolveRoleMatrixStreamMountAgent(RoleMatrixStreamActiveAgentState state)
        {
            if (state == null)
                return null;

            Agent mountAgent = state.Agent?.MountAgent;
            if (mountAgent != null)
            {
                state.MountAgent = mountAgent;
                state.MountAgentIndex = mountAgent.Index;
                return mountAgent;
            }

            if (state.MountAgent != null)
                return state.MountAgent;

            return null;
        }

        private static void TryKillRoleMatrixStreamOrphanMount(RoleMatrixStreamActiveAgentState state, string source)
        {
            Agent mountAgent = ResolveRoleMatrixStreamMountAgent(state);
            if (mountAgent == null || !mountAgent.IsActive())
                return;

            Mission mission = mountAgent.Mission;
            if (mission == null)
                return;

            try
            {
                mission.KillAgentCheat(mountAgent);
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: role-matrix stream failed to kill orphan mount agent. " +
                    "MountAgentIndex=" + mountAgent.Index +
                    " MatrixId=" + (state?.MatrixId ?? "null") +
                    " EntryId=" + (state?.EntryId ?? "null") +
                    " Message=" + ex.Message +
                    " Source=" + (source ?? "unknown"));
            }
        }

        private static void ResetRoleMatrixStreamRuntime(string reason)
        {
            bool hadState =
                _roleMatrixStreamMission != null ||
                _roleMatrixStreamDefinitions.Count > 0 ||
                _roleMatrixStreamActiveAgentsByIndex.Count > 0 ||
                _roleMatrixStreamKillQueue.Count > 0;
            foreach (RoleMatrixStreamActiveAgentState state in _roleMatrixStreamActiveAgentsByIndex.Values.ToList())
                TryWriteRoleMatrixStreamWeaponPrioritySummary(state, "reset", reason);
            _roleMatrixStreamMission = null;
            _roleMatrixStreamDefinitions = new List<RoleMatrixStreamEntryDefinition>();
            _roleMatrixStreamActiveAgentsByIndex.Clear();
            _roleMatrixStreamKillQueue.Clear();
            _roleMatrixStreamCursor = 0;
            _roleMatrixStreamWave = 0;
            _roleMatrixStreamTotalMatrixCount = 0;
            _roleMatrixStreamSkippedUnsafeCount = 0;
            _roleMatrixStreamKillingWave = false;
            _roleMatrixStreamFinished = false;
            _roleMatrixStreamSpectatorAutoStartRequested = false;
            _roleMatrixStreamBattleStartedFromSpectator = false;
            _roleMatrixStreamWaveStartedUtc = DateTime.MinValue;
            _nextRoleMatrixStreamLogUtc = DateTime.MinValue;
            _nextRoleMatrixStreamAiPulseUtc = DateTime.MinValue;
            if (hadState && !string.IsNullOrWhiteSpace(reason))
                ModLogger.Info("CoopMissionSpawnLogic: role-matrix stream runtime reset. Reason=" + reason + ".");
        }

        private static void TryEnsureBattlefieldArmiesMaterialized(Mission mission, string source)
        {
            if (mission == null || !GameNetwork.IsServer)
                return;

            if (!ReferenceEquals(_lastMaterializedArmyMission, mission))
            {
                _lastMaterializedArmyMission = mission;
                _hasMaterializedBattlefieldArmies = false;
                _hasLoggedMaterializedEquipmentCoverageSummary = false;
                _lastAlignedControlledAgentIndexByPeer.Clear();
                _commanderDeploymentOrderLeasesByPeer.Clear();
                _deferredDeploymentSpawnsByPeer.Clear();
                _materializedArmyEntryIdByAgentIndex.Clear();
                ResetAuthoritativeMaterializedAgentEntryLedger(mission);
                MarkAuthoritativeMaterializedAgentEntryCacheDirty();
                _materializedArmySideByAgentIndex.Clear();
                _materializedAgentInstanceByIndex.Clear();
                _customAiTargetPulseStateByAgentIndex.Clear();
                _pendingExactCampaignNativeSpawnRegistrationsByAgentIndex.Clear();
                _clientAuthoritativeMaterializedEntryObservedAgentIndices.Clear();
                _lastClientAuthoritativeMaterializedEntrySnapshotObservedUtc = DateTime.MinValue;
                _lastClientAuthoritativeMaterializedEntrySnapshotEntryCount = 0;
                _loggedAutomatedMaterializedEntrySkipIds.Clear();
                _loggedSuppressedMaterializedEquipmentKeys.Clear();
                _loggedManualMaterializedSiegeRespawnRejectKeys.Clear();
                MaterializedEquipmentResolutionSourceCounts.Clear();
                MaterializedEquipmentMissCounts.Clear();
                MaterializedEquipmentNormalizedFallbackCounts.Clear();
                ResetMaterializedCombatProfileRuntimeState();
                ResetMaterializedSiegeReinforcementWaveRuntimeState();
                _nextIncompleteBattleSnapshotRefreshUtc = DateTime.MinValue;
                _nextIncompleteBattleSnapshotLogUtc = DateTime.MinValue;
                _nextExactSceneMaterializationDeferLogUtc = DateTime.MinValue;
                _exactScenePostPossessionMaterializationResumeUtc = DateTime.MinValue;
                _nextInitialMaterializedArmyPulseUtc = DateTime.MinValue;
                _nextMaterializedArmyReinforcementPulseUtc = DateTime.MinValue;
                _nextExactSceneNativeBootstrapDeferLogUtc = DateTime.MinValue;
            }

            if (_hasMaterializedBattlefieldArmies)
                return;

            bool useFieldMaterializedSiegeReplayRuntime = ShouldUseFieldMaterializedSiegeReplayRuntime(mission);
            bool useFullNativeSiegeArmySpawnRuntime =
                ExactCampaignSiegeAssaultWithDeploymentRuntime
                    .ShouldUseFullNativeArmySpawnRuntime(mission);
            if (IsUsingNativeExactCampaignArmyBootstrap(mission) &&
                !useFieldMaterializedSiegeReplayRuntime &&
                !useFullNativeSiegeArmySpawnRuntime)
            {
                return;
            }

            Team attackerTeam = mission.Teams?.Attacker;
            Team defenderTeam = mission.Teams?.Defender;
            if (attackerTeam == null || defenderTeam == null)
                return;

            if (!useFieldMaterializedSiegeReplayRuntime &&
                !useFullNativeSiegeArmySpawnRuntime &&
                ShouldDeferOpenSiegeBattlefieldMaterializationUntilSpawnPath(mission, out string siegeSpawnPathDeferReason))
            {
                CampaignMapPatchMissionInit.TryRepairLiveMissionContract(
                    mission,
                    (source ?? "unknown") + " siege-spawn-path-gate");
                DateTime nowUtc = DateTime.UtcNow;
                if (nowUtc >= _nextExactSceneMaterializationDeferLogUtc)
                {
                    _nextExactSceneMaterializationDeferLogUtc = nowUtc.AddSeconds(2);
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: deferring battlefield materialization on open siege scene until native spawn path is ready. " +
                        siegeSpawnPathDeferReason +
                        " Source=" + (source ?? "unknown"));
                }

                return;
            }

            if (!useFullNativeSiegeArmySpawnRuntime &&
                ShouldDeferExactSceneInitialBattlefieldMaterialization(mission, out string exactSceneMaterializationDeferReason))
            {
                DateTime nowUtc = DateTime.UtcNow;
                if (nowUtc >= _nextExactSceneMaterializationDeferLogUtc)
                {
                    _nextExactSceneMaterializationDeferLogUtc = nowUtc.AddSeconds(2);
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: deferring initial battlefield materialization on exact campaign scene until a synchronized peer has an authoritative side. " +
                        exactSceneMaterializationDeferReason +
                        " Source=" + (source ?? "unknown"));
                }

                return;
            }

            if (!useFullNativeSiegeArmySpawnRuntime &&
                ShouldDeferExactScenePostPossessionMaterialization(mission, out string exactScenePostPossessionDeferReason))
            {
                DateTime nowUtc = DateTime.UtcNow;
                if (nowUtc >= _nextExactSceneMaterializationDeferLogUtc)
                {
                    _nextExactSceneMaterializationDeferLogUtc = nowUtc.AddSeconds(2);
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: deferring automated battlefield materialization on exact campaign scene after player possession to let spawn handoff settle. " +
                        exactScenePostPossessionDeferReason +
                        " Source=" + (source ?? "unknown"));
                }

                return;
            }

            if (!IsBattleSnapshotReadyForMaterialization(mission, out string readinessSummary))
            {
                DateTime nowUtc = DateTime.UtcNow;
                if (nowUtc >= _nextIncompleteBattleSnapshotRefreshUtc)
                {
                    _nextIncompleteBattleSnapshotRefreshUtc = nowUtc.AddMilliseconds(750);
                    RefreshAllowedTroopsFromRoster(source + " awaiting snapshot");
                }

                if (!IsBattleSnapshotReadyForMaterialization(mission, out readinessSummary))
                {
                    if (nowUtc >= _nextIncompleteBattleSnapshotLogUtc)
                    {
                        _nextIncompleteBattleSnapshotLogUtc = nowUtc.AddSeconds(2);
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: delaying battlefield materialization because battle snapshot is incomplete. " +
                            readinessSummary +
                            " Source=" + (source ?? "unknown"));
                    }
                    return;
                }

                _nextIncompleteBattleSnapshotLogUtc = DateTime.MinValue;
            }

            if (useFullNativeSiegeArmySpawnRuntime)
            {
                if (!ExactCampaignArmyBootstrap.TryStartNativeInitialSpawners(
                        mission,
                        source + " full-native-initial-armies",
                        out string nativeStartDiagnostics))
                {
                    DateTime nowUtc = DateTime.UtcNow;
                    if (nowUtc >= _nextExactSceneMaterializationDeferLogUtc)
                    {
                        _nextExactSceneMaterializationDeferLogUtc = nowUtc.AddSeconds(2);
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: waiting to start native initial siege armies. " +
                            "Diagnostics=" + nativeStartDiagnostics +
                            " Source=" + (source ?? "unknown"));
                    }

                    return;
                }

                if (!ExactCampaignArmyBootstrap.IsInitialSpawnMaterializationComplete(
                        mission,
                        out string nativeInitialSpawnDiagnostics))
                {
                    DateTime nowUtc = DateTime.UtcNow;
                    if (nowUtc >= _nextExactSceneMaterializationDeferLogUtc)
                    {
                        _nextExactSceneMaterializationDeferLogUtc = nowUtc.AddSeconds(2);
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: native initial siege armies are still spawning. " +
                            "Diagnostics=" + nativeInitialSpawnDiagnostics +
                            " Source=" + (source ?? "unknown"));
                    }

                    return;
                }

                int nativeAttackerCount = CountActiveTeamAgents(mission, BattleSideEnum.Attacker);
                int nativeDefenderCount = CountActiveTeamAgents(mission, BattleSideEnum.Defender);
                if (nativeAttackerCount <= 0 || nativeDefenderCount <= 0)
                    return;

                _hasMaterializedBattlefieldArmies = true;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: native initial siege armies are ready. " +
                    "AttackerAgents=" + nativeAttackerCount +
                    " DefenderAgents=" + nativeDefenderCount +
                    " InitialSpawn={" + nativeInitialSpawnDiagnostics + "}" +
                    " Source=" + (source ?? "unknown"));
                return;
            }

            DateTime pulseNowUtc = DateTime.UtcNow;
            if (pulseNowUtc < _nextInitialMaterializedArmyPulseUtc)
                return;

            _nextInitialMaterializedArmyPulseUtc = pulseNowUtc.AddSeconds(InitialMaterializedArmyPulseIntervalSeconds);

            int attackerTargetCount = GetInitialMaterializedArmyTargetCount(BattleSideEnum.Attacker);
            int defenderTargetCount = GetInitialMaterializedArmyTargetCount(BattleSideEnum.Defender);
            int attackerCurrentCount = GetCurrentMaterializedSpawnCountForSide(BattleSideEnum.Attacker);
            int defenderCurrentCount = GetCurrentMaterializedSpawnCountForSide(BattleSideEnum.Defender);

            bool exactCampaignSceneHasControlledPeer = false;
            if (SceneRuntimeClassifier.IsExactCampaignBattleScene(mission.SceneName ?? string.Empty) &&
                GameNetwork.NetworkPeers != null)
            {
                foreach (NetworkCommunicator peer in GameNetwork.NetworkPeers)
                {
                    if (peer == null || peer.IsServerPeer || !peer.IsConnectionActive || !peer.IsSynchronized)
                        continue;

                    MissionPeer missionPeer = peer.GetComponent<MissionPeer>();
                    if (HasActiveControlledAgent(missionPeer))
                    {
                        exactCampaignSceneHasControlledPeer = true;
                        break;
                    }
                }
            }

            int initialMaterializedArmySpawnPulseBudgetPerSide = GetInitialMaterializedArmySpawnPulseBudgetPerSide(mission);
            int attackerSpawnBudget = Math.Min(
                initialMaterializedArmySpawnPulseBudgetPerSide,
                Math.Max(0, attackerTargetCount - attackerCurrentCount));
            int defenderSpawnBudget = Math.Min(
                initialMaterializedArmySpawnPulseBudgetPerSide,
                Math.Max(0, defenderTargetCount - defenderCurrentCount));

            if (exactCampaignSceneHasControlledPeer &&
                defenderSpawnBudget > 0 &&
                defenderCurrentCount <= 0)
            {
                attackerSpawnBudget = 0;
                if (pulseNowUtc >= _nextExactSceneMaterializationDeferLogUtc)
                {
                    _nextExactSceneMaterializationDeferLogUtc = pulseNowUtc.AddSeconds(2);
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: prioritizing defender-side initial battlefield materialization on exact campaign scene after player possession. " +
                        "Scene=" + (mission.SceneName ?? "null") +
                        " AttackerCurrent=" + attackerCurrentCount +
                        " DefenderCurrent=" + defenderCurrentCount +
                        " AttackerTarget=" + attackerTargetCount +
                        " DefenderTarget=" + defenderTargetCount +
                        " Source=" + (source ?? "unknown"));
                }
            }

            int attackerCount = attackerSpawnBudget > 0
                ? MaterializeArmyForSide(mission, attackerTeam, BattleSideEnum.Attacker, source, attackerSpawnBudget)
                : 0;
            int defenderCount = defenderSpawnBudget > 0
                ? MaterializeArmyForSide(mission, defenderTeam, BattleSideEnum.Defender, source, defenderSpawnBudget)
                : 0;

            attackerCurrentCount = GetCurrentMaterializedSpawnCountForSide(BattleSideEnum.Attacker);
            defenderCurrentCount = GetCurrentMaterializedSpawnCountForSide(BattleSideEnum.Defender);

            bool attackerReady = attackerTargetCount <= 0 || attackerCurrentCount >= attackerTargetCount;
            bool defenderReady = defenderTargetCount <= 0 || defenderCurrentCount >= defenderTargetCount;
            if (!attackerReady || !defenderReady)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: initial battlefield materialization pulse. " +
                    "AttackerSpawnedThisPulse=" + attackerCount +
                    " AttackerCurrent=" + attackerCurrentCount + "/" + attackerTargetCount +
                    " DefenderSpawnedThisPulse=" + defenderCount +
                    " DefenderCurrent=" + defenderCurrentCount + "/" + defenderTargetCount +
                    " Source=" + (source ?? "unknown"));
                return;
            }

            if (attackerCurrentCount <= 0 && defenderCurrentCount <= 0)
                return;

            if (ShouldUseMaterializedSiegeReinforcements(mission))
            {
                InitializeMaterializedSiegeReinforcementWaveState(
                    mission,
                    BattleSideEnum.Attacker,
                    attackerTargetCount,
                    attackerCurrentCount,
                    Math.Max(0, GetBattleSideAvailableCount(BattleSideEnum.Attacker) - attackerCurrentCount),
                    source + " initial-army-ready");
                InitializeMaterializedSiegeReinforcementWaveState(
                    mission,
                    BattleSideEnum.Defender,
                    defenderTargetCount,
                    defenderCurrentCount,
                    Math.Max(0, GetBattleSideAvailableCount(BattleSideEnum.Defender) - defenderCurrentCount),
                    source + " initial-army-ready");
            }

            _hasMaterializedBattlefieldArmies = true;
            ModLogger.Info(
                "CoopMissionSpawnLogic: battlefield armies materialized. " +
                "AttackerAgents=" + attackerCurrentCount +
                " DefenderAgents=" + defenderCurrentCount +
                " BattleSizeBudget=" + GetConfiguredBattleSizeBudget() +
                " AttackerSideCap=" + GetMaterializedArmyAgentsPerSideCap(BattleSideEnum.Attacker, GetAllowedControlEntryStatesSnapshot(BattleSideEnum.Attacker).Count) +
                " DefenderSideCap=" + GetMaterializedArmyAgentsPerSideCap(BattleSideEnum.Defender, GetAllowedControlEntryStatesSnapshot(BattleSideEnum.Defender).Count) +
                " Source=" + (source ?? "unknown"));
        }

        private static void TrySpawnMaterializedBattlefieldReinforcements(Mission mission, string source)
        {
            if (mission == null || !GameNetwork.IsServer)
                return;

            if (IsRoleMatrixStreamRuntime())
                return;

            bool useMaterializedSiegeReinforcements = ShouldUseMaterializedSiegeReinforcements(mission);
            if (!_hasMaterializedBattlefieldArmies && !useMaterializedSiegeReinforcements)
                return;

            if (IsUsingNativeExactCampaignArmyBootstrap(mission) && !useMaterializedSiegeReinforcements)
                return;

            CoopBattlePhase currentPhase = CoopBattlePhaseRuntimeState.GetPhase();
            if (currentPhase < CoopBattlePhase.BattleActive || currentPhase >= CoopBattlePhase.BattleEnded)
                return;

            if (useMaterializedSiegeReinforcements &&
                ExactCampaignSiegeAssaultWithDeploymentRuntime.IsDeploymentPhaseBlockingBattleStart(mission))
            {
                return;
            }

            if (useMaterializedSiegeReinforcements &&
                (!HasTrackedBattlefieldEntryStateForSide(mission, BattleSideEnum.Attacker) ||
                 !HasTrackedBattlefieldEntryStateForSide(mission, BattleSideEnum.Defender)))
            {
                return;
            }

            if (useMaterializedSiegeReinforcements)
            {
                EnsureMaterializedSiegeReinforcementWaveRuntimeMission(mission);
                float missionTime = mission.CurrentTime;
                if (missionTime < _nextMaterializedSiegeReinforcementCheckMissionTime)
                    return;

                bool hasPendingWave = RequiresFrequentMaterializedSiegeReinforcementTick(mission);
                _nextMaterializedSiegeReinforcementCheckMissionTime =
                    missionTime + (hasPendingWave
                        ? MaterializedSiegeReinforcementBatchIntervalSeconds
                        : MaterializedSiegeReinforcementCheckIntervalSeconds);
            }
            else
            {
                DateTime nowUtc = DateTime.UtcNow;
                if (nowUtc < _nextMaterializedArmyReinforcementPulseUtc)
                    return;

                _nextMaterializedArmyReinforcementPulseUtc =
                    nowUtc.AddSeconds(MaterializedArmyReinforcementPulseIntervalSeconds);
            }

            Team attackerTeam = mission.Teams?.Attacker;
            Team defenderTeam = mission.Teams?.Defender;
            if (attackerTeam == null || defenderTeam == null)
                return;

            if (useMaterializedSiegeReinforcements)
                SynchronizeMaterializedBattleResultActiveCountsFromLiveAgents(
                    mission,
                    (source ?? "unknown") + " materialized-siege-reinforcement-active-sync");

            int remainingSpawnBudget = useMaterializedSiegeReinforcements
                ? MaterializedSiegeReinforcementBatchAgentBudget
                : int.MaxValue;
            int attackerSpawned;
            int defenderSpawned;
            if (useMaterializedSiegeReinforcements &&
                _nextMaterializedSiegeReinforcementBatchFirstSide == BattleSideEnum.Defender)
            {
                defenderSpawned = SpawnMaterializedReinforcementWaveForSide(
                    mission,
                    defenderTeam,
                    BattleSideEnum.Defender,
                    source,
                    ref remainingSpawnBudget);
                attackerSpawned = SpawnMaterializedReinforcementWaveForSide(
                    mission,
                    attackerTeam,
                    BattleSideEnum.Attacker,
                    source,
                    ref remainingSpawnBudget);
            }
            else
            {
                attackerSpawned = SpawnMaterializedReinforcementWaveForSide(
                    mission,
                    attackerTeam,
                    BattleSideEnum.Attacker,
                    source,
                    ref remainingSpawnBudget);
                defenderSpawned = SpawnMaterializedReinforcementWaveForSide(
                    mission,
                    defenderTeam,
                    BattleSideEnum.Defender,
                    source,
                    ref remainingSpawnBudget);
            }

            if (useMaterializedSiegeReinforcements &&
                (attackerSpawned > 0 ||
                 defenderSpawned > 0 ||
                 RequiresFrequentMaterializedSiegeReinforcementTick(mission)))
            {
                _nextMaterializedSiegeReinforcementBatchFirstSide =
                    _nextMaterializedSiegeReinforcementBatchFirstSide == BattleSideEnum.Attacker
                        ? BattleSideEnum.Defender
                        : BattleSideEnum.Attacker;
                _nextMaterializedSiegeReinforcementCheckMissionTime =
                    mission.CurrentTime + MaterializedSiegeReinforcementBatchIntervalSeconds;
            }

            if (attackerSpawned <= 0 && defenderSpawned <= 0)
                return;

            int pulsedAgents = 0;
            if (!useMaterializedSiegeReinforcements)
            {
                if (attackerSpawned > 0)
                    pulsedAgents += TryActivateBattleActiveReinforcementAi(attackerTeam);
                if (defenderSpawned > 0)
                    pulsedAgents += TryActivateBattleActiveReinforcementAi(defenderTeam);
            }

            if (ExperimentalFeatures.EnableExactCampaignArmyRuntimeDiagnostics)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: materialized reinforcement batch spawned. " +
                    "AttackerSpawned=" + attackerSpawned +
                    " DefenderSpawned=" + defenderSpawned +
                    " PulsedAgents=" + pulsedAgents +
                    " BattleSizeBudget=" + GetConfiguredBattleSizeBudget() +
                    " SiegeMaterializedReinforcements=" + useMaterializedSiegeReinforcements +
                    " Source=" + (source ?? "unknown"));
            }
        }

        private static int SpawnMaterializedReinforcementWaveForSide(
            Mission mission,
            Team team,
            BattleSideEnum side,
            string source,
            ref int remainingGlobalSpawnBudget)
        {
            if (mission == null || team == null || side == BattleSideEnum.None || remainingGlobalSpawnBudget <= 0)
                return 0;

            bool useMaterializedSiegeReinforcements = ShouldUseMaterializedSiegeReinforcements(mission);
            IReadOnlyList<RosterEntryState> entryStates = GetAutomatedMaterializableEntryStatesSnapshot(
                side,
                preferFullBattleSideRoster: useMaterializedSiegeReinforcements);
            if (entryStates == null || entryStates.Count == 0)
                return 0;

            int sideCap = GetMaterializedArmyAgentsPerSideCap(side, entryStates.Count);
            int totalAvailableForSide = 0;
            int activeForSide = 0;
            var candidates = new List<MaterializedArmyReinforcementCandidate>();

            foreach (RosterEntryState entryState in entryStates)
            {
                string spawnTemplateId = ResolveEntrySpawnTemplateId(entryState);
                if (entryState == null || string.IsNullOrWhiteSpace(spawnTemplateId))
                    continue;

                int availableCount = Math.Max(0, entryState.Count - entryState.WoundedCount);
                if (availableCount <= 0)
                    continue;

                totalAvailableForSide += availableCount;

                _materializedBattleResultEntriesByEntryId.TryGetValue(entryState.EntryId ?? string.Empty, out MaterializedBattleResultEntryRuntimeState runtimeState);
                int spawnedCount = Math.Max(0, runtimeState?.MaterializedSpawnCount ?? 0);
                int activeCount = Math.Max(0, runtimeState?.ActiveCount ?? 0);
                activeForSide += activeCount;

                int totalRemainingCount = Math.Max(0, availableCount - spawnedCount);
                int concurrentRemainingCapacity = GetMaterializedReinforcementConcurrentCapacity(
                    mission,
                    side,
                    entryStates.Count,
                    availableCount,
                    activeCount,
                    totalRemainingCount);
                if (totalRemainingCount <= 0 || concurrentRemainingCapacity <= 0)
                    continue;

                string resolvedTroopSource;
                BasicCharacterObject troop = ResolveMaterializedArmyCharacter(entryState, spawnTemplateId, out resolvedTroopSource);
                if (troop == null)
                    continue;

                candidates.Add(new MaterializedArmyReinforcementCandidate
                {
                    EntryState = entryState,
                    Troop = troop,
                    ResolvedTroopSource = resolvedTroopSource,
                    AvailableCount = availableCount,
                    ActiveCount = activeCount,
                    SpawnedCount = spawnedCount,
                    TotalRemainingCount = totalRemainingCount,
                    ConcurrentRemainingCapacity = concurrentRemainingCapacity,
                });
            }

            int targetActiveForSide = Math.Min(sideCap, totalAvailableForSide);
            int remainingSideNeed = Math.Max(0, targetActiveForSide - activeForSide);
            MaterializedSiegeReinforcementWaveState siegeWaveState = null;
            int spawnableReserveForSide = candidates.Sum(candidate => Math.Max(0, candidate.TotalRemainingCount));
            if (useMaterializedSiegeReinforcements)
            {
                siegeWaveState = GetOrInitializeMaterializedSiegeReinforcementWaveState(
                    mission,
                    side,
                    targetActiveForSide,
                    activeForSide,
                    spawnableReserveForSide,
                    (source ?? "unknown") + " batch-wave-state");
                if (siegeWaveState == null)
                {
                    return 0;
                }

                bool hasPendingPlan = HasPendingMaterializedSiegeReinforcementWave(siegeWaveState);
                if (!hasPendingPlan)
                {
                    int wavePreparationTargetCount =
                        Math.Min(siegeWaveState.WaveSize, spawnableReserveForSide);
                    if (candidates.Count == 0 ||
                        (siegeWaveState.MaximumWaveCount > 0 &&
                         siegeWaveState.SpawnedWaveCount >= siegeWaveState.MaximumWaveCount) ||
                        wavePreparationTargetCount <= 0)
                    {
                        return 0;
                    }

                    if (!TryAdvancePendingMaterializedSiegeReinforcementWavePreparation(
                            siegeWaveState,
                            candidates,
                            wavePreparationTargetCount))
                    {
                        return 0;
                    }
                }
                else if (!siegeWaveState.PendingWavePreflightStarted &&
                          siegeWaveState.PendingWavePlannedCount < siegeWaveState.PendingWavePreparationTargetCount)
                {
                    if (!TryAdvancePendingMaterializedSiegeReinforcementWavePreparation(
                            siegeWaveState,
                            candidates,
                            siegeWaveState.PendingWavePreparationTargetCount))
                    {
                        return 0;
                    }
                }

                if (!siegeWaveState.PendingWaveArmed)
                {
                    if (!siegeWaveState.PendingWavePreflightStarted)
                    {
                        if (siegeWaveState.PendingWavePlannedCount < siegeWaveState.PendingWavePreparationTargetCount ||
                            remainingSideNeed < siegeWaveState.WaveSize)
                        {
                            return 0;
                        }

                        if (!TryGetMaterializedSiegeReinforcementWaveBudget(
                                mission,
                                side,
                                targetActiveForSide,
                                activeForSide,
                                spawnableReserveForSide,
                                source,
                                out siegeWaveState,
                                out int siegeWaveBudget))
                        {
                            return 0;
                        }

                        if (!TryInitializePendingMaterializedSiegeReinforcementWavePlan(
                                siegeWaveState,
                                candidates,
                                siegeWaveBudget))
                        {
                            ExactSiegeMoraleDiagnostics.RecordReinforcementWaveDecision(
                                mission,
                                side,
                                siegeWaveState.InitialActiveCount,
                                activeForSide,
                                spawnableReserveForSide,
                                siegeWaveState.WaveSize,
                                siegeWaveState.MaximumWaveCount,
                                siegeWaveState.SpawnedWaveCount,
                                0,
                                "wave-plan-empty",
                                source);
                            return 0;
                        }

                        siegeWaveState.PendingWavePreparationTargetCount = siegeWaveBudget;
                        if (!TryBeginPendingMaterializedSiegeReinforcementWavePreflight(
                                mission,
                                siegeWaveState,
                                source))
                        {
                            return 0;
                        }
                    }

                    if (!CoopMissionNetworkBridge.AreMaterializedReinforcementBatchPeersPrepared(
                            mission,
                            siegeWaveState.PendingWaveBatchId))
                    {
                        return 0;
                    }

                    siegeWaveState.PendingWaveArmed = true;
                }

                if (siegeWaveState.PendingWaveMaterializationComplete)
                {
                    TryReleasePendingMaterializedSiegeReinforcementWave(
                        mission,
                        team,
                        siegeWaveState,
                        source);
                    return 0;
                }

                int pendingWaveRemaining = Math.Max(
                    0,
                    siegeWaveState.PendingWavePlannedCount - siegeWaveState.PendingWaveSpawnedCount);
                int requestedBatchCount = Math.Min(remainingGlobalSpawnBudget, pendingWaveRemaining);
                int maximumPhysicalCostPerTroop = GetMaximumPendingMaterializedSiegeReinforcementPhysicalCostPerTroop(
                    mission,
                    side,
                    siegeWaveState);
                int capacityLimitedBatchCount = BattleAgentCapacityPolicy.GetAvailablePhysicalAgentSlots(mission) /
                                                Math.Max(1, maximumPhysicalCostPerTroop);
                requestedBatchCount = Math.Min(requestedBatchCount, capacityLimitedBatchCount);
                if (requestedBatchCount <= 0)
                {
                    ExactSiegeMoraleDiagnostics.RecordReinforcementWaveDecision(
                        mission,
                        side,
                        siegeWaveState.InitialActiveCount,
                        activeForSide,
                        spawnableReserveForSide,
                        siegeWaveState.WaveSize,
                        siegeWaveState.MaximumWaveCount,
                        siegeWaveState.SpawnedWaveCount,
                        0,
                        "physical-capacity-deferred",
                        source);
                    return 0;
                }

                int requiredPhysicalSlots = requestedBatchCount * Math.Max(1, maximumPhysicalCostPerTroop);
                if (requiredPhysicalSlots > 0 &&
                    !BattleAgentCapacityPolicy.CanSpawnPhysicalAgents(
                        mission,
                        requiredPhysicalSlots,
                        (source ?? "unknown") + " reinforcement-wave-preflight"))
                {
                    if (siegeWaveState != null)
                    {
                        ExactSiegeMoraleDiagnostics.RecordReinforcementWaveDecision(
                            mission,
                            side,
                            siegeWaveState.InitialActiveCount,
                            activeForSide,
                            spawnableReserveForSide,
                            siegeWaveState.WaveSize,
                            siegeWaveState.MaximumWaveCount,
                            siegeWaveState.SpawnedWaveCount,
                            0,
                            "physical-capacity-deferred",
                            source);
                    }
                    return 0;
                }

                int spawnedBatchCount = SpawnPendingMaterializedSiegeReinforcementWaveBatch(
                    mission,
                    team,
                    side,
                    siegeWaveState,
                    activeForSide,
                    requestedBatchCount,
                    source);
                remainingGlobalSpawnBudget = Math.Max(0, remainingGlobalSpawnBudget - spawnedBatchCount);

                bool waveCompleted =
                    siegeWaveState.PendingWavePlannedCount > 0 &&
                    siegeWaveState.PendingWaveSpawnedCount >= siegeWaveState.PendingWavePlannedCount;
                string decision = spawnedBatchCount > 0
                    ? (waveCompleted ? "wave-materialized-awaiting-clients" : "wave-batch-spawned")
                    : "wave-batch-no-progress";
                if (waveCompleted)
                {
                    siegeWaveState.PendingWaveMaterializationComplete = true;
                }

                ExactSiegeMoraleDiagnostics.RecordReinforcementWaveDecision(
                    mission,
                    side,
                    siegeWaveState.InitialActiveCount,
                    activeForSide,
                    Math.Max(0, spawnableReserveForSide - spawnedBatchCount),
                    siegeWaveState.WaveSize,
                    siegeWaveState.MaximumWaveCount,
                    siegeWaveState.SpawnedWaveCount,
                    spawnedBatchCount,
                    decision,
                    source);
                return spawnedBatchCount;
            }

            if (candidates.Count == 0 || remainingSideNeed <= 0)
                return 0;

            remainingSideNeed = Math.Min(remainingSideNeed, remainingGlobalSpawnBudget);
            int spawnedCountForSide = 0;
            var queuedByEntryId = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

            foreach (MaterializedArmyReinforcementCandidate candidate in candidates.Where(item => item.ActiveCount <= 0))
            {
                if (remainingSideNeed <= 0)
                    break;

                int seedCount = GetReinforcementSpawnCount(candidate, queuedByEntryId, remainingSideNeed, seedOneBody: true);
                if (seedCount <= 0)
                    continue;

                int spawned = SpawnMaterializedAgentsForEntry(
                    mission,
                    team,
                    side,
                    candidate.Troop,
                    candidate.EntryState,
                    seedCount,
                    GetMaterializedReinforcementPlacementOffset(
                        useMaterializedSiegeReinforcements,
                        activeForSide,
                        spawnedCountForSide),
                    source + " reinforcement character=" + candidate.ResolvedTroopSource + " pass=seed",
                    isReinforcement: true);
                if (spawned <= 0)
                    continue;

                queuedByEntryId[candidate.EntryState.EntryId ?? string.Empty] = GetQueuedReinforcementCount(queuedByEntryId, candidate.EntryState.EntryId) + spawned;
                spawnedCountForSide += spawned;
                remainingSideNeed = Math.Max(0, remainingSideNeed - spawned);
            }

            foreach (MaterializedArmyReinforcementCandidate candidate in candidates)
            {
                if (remainingSideNeed <= 0)
                    break;

                int fillCount = GetReinforcementSpawnCount(candidate, queuedByEntryId, remainingSideNeed, seedOneBody: false);
                if (fillCount <= 0)
                    continue;

                int spawned = SpawnMaterializedAgentsForEntry(
                    mission,
                    team,
                    side,
                    candidate.Troop,
                    candidate.EntryState,
                    fillCount,
                    GetMaterializedReinforcementPlacementOffset(
                        useMaterializedSiegeReinforcements,
                        activeForSide,
                        spawnedCountForSide),
                    source + " reinforcement character=" + candidate.ResolvedTroopSource + " pass=fill",
                    isReinforcement: true);
                if (spawned <= 0)
                    continue;

                queuedByEntryId[candidate.EntryState.EntryId ?? string.Empty] = GetQueuedReinforcementCount(queuedByEntryId, candidate.EntryState.EntryId) + spawned;
                spawnedCountForSide += spawned;
                remainingSideNeed = Math.Max(0, remainingSideNeed - spawned);
            }

            remainingGlobalSpawnBudget = Math.Max(0, remainingGlobalSpawnBudget - spawnedCountForSide);
            return spawnedCountForSide;
        }

        private static bool HasPendingMaterializedSiegeReinforcementWave(Mission mission)
        {
            if (mission == null)
                return false;

            return MaterializedSiegeReinforcementWaveStates.Values.Any(state =>
                ReferenceEquals(state?.Mission, mission) &&
                HasPendingMaterializedSiegeReinforcementWave(state));
        }

        private static bool HasPendingMaterializedSiegeReinforcementWave(MaterializedSiegeReinforcementWaveState state)
        {
            return state != null &&
                   state.PendingWavePlan != null &&
                   state.PendingWavePlan.Count > 0 &&
                   state.PendingWavePlannedCount > 0;
        }

        private static bool RequiresFrequentMaterializedSiegeReinforcementTick(Mission mission)
        {
            if (mission == null)
                return false;

            return MaterializedSiegeReinforcementWaveStates.Values.Any(state =>
                ReferenceEquals(state?.Mission, mission) &&
                HasPendingMaterializedSiegeReinforcementWave(state) &&
                (state.PendingWavePlannedCount < state.PendingWavePreparationTargetCount ||
                 state.PendingWavePreflightStarted ||
                 state.PendingWaveArmed ||
                 state.PendingWaveMaterializationComplete));
        }

        private static bool TryAdvancePendingMaterializedSiegeReinforcementWavePreparation(
            MaterializedSiegeReinforcementWaveState waveState,
            IReadOnlyList<MaterializedArmyReinforcementCandidate> candidates,
            int targetCount)
        {
            if (waveState == null || candidates == null || candidates.Count == 0 || targetCount <= 0)
                return false;

            int nextPreparedCount = Math.Min(
                targetCount,
                Math.Max(1, waveState.PendingWavePlannedCount + 1));
            if (!TryInitializePendingMaterializedSiegeReinforcementWavePlan(
                    waveState,
                    candidates,
                    nextPreparedCount))
            {
                return false;
            }

            waveState.PendingWavePreparationTargetCount = targetCount;
            return true;
        }

        private static bool TryBeginPendingMaterializedSiegeReinforcementWavePreflight(
            Mission mission,
            MaterializedSiegeReinforcementWaveState waveState,
            string source)
        {
            if (mission == null ||
                waveState == null ||
                waveState.PendingWavePreflightStarted ||
                waveState.PendingWavePlan == null ||
                waveState.PendingWavePlan.Count <= 0)
            {
                return false;
            }

            var plannedAgentCountByEntryId = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (MaterializedSiegeReinforcementPlanEntry plannedEntry in waveState.PendingWavePlan)
            {
                string entryId = plannedEntry?.EntryState?.EntryId;
                int plannedCount = Math.Max(0, plannedEntry?.PlannedCount ?? 0);
                if (string.IsNullOrWhiteSpace(entryId) || plannedCount <= 0)
                    continue;

                plannedAgentCountByEntryId.TryGetValue(entryId, out int existingCount);
                plannedAgentCountByEntryId[entryId] = existingCount + plannedCount;
            }

            int manifestAgentCount = plannedAgentCountByEntryId.Values.Sum();
            if (manifestAgentCount != waveState.PendingWavePlannedCount)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: reinforcement batch preflight manifest did not match the frozen wave plan. " +
                    "Side=" + waveState.Side +
                    " PlannedAgents=" + waveState.PendingWavePlannedCount +
                    " ManifestAgents=" + manifestAgentCount +
                    " Contracts=" + plannedAgentCountByEntryId.Count +
                    " Source=" + (source ?? "unknown"));
                return false;
            }

            if (_nextMaterializedSiegeReinforcementBatchId == int.MaxValue)
                _nextMaterializedSiegeReinforcementBatchId = 1;

            int batchId = _nextMaterializedSiegeReinforcementBatchId++;

            bool began = CoopMissionNetworkBridge.TryBeginMaterializedReinforcementBatch(
                mission,
                batchId,
                waveState.Side,
                waveState.PendingWavePlannedCount,
                plannedAgentCountByEntryId,
                out string diagnostics);
            if (!began)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: reinforcement batch preflight could not start; materialization remains blocked. " +
                    "BatchId=" + batchId +
                    " Side=" + waveState.Side +
                    " Diagnostics=" + (diagnostics ?? "unknown") +
                    " Source=" + (source ?? "unknown"));
                return false;
            }

            waveState.PendingWaveBatchId = batchId;
            waveState.PendingWaveBindingSequence = 0;
            waveState.PendingWavePreflightStarted = true;
            waveState.PendingWaveArmed = false;
            waveState.PendingWaveMaterializationComplete = false;
            waveState.PendingWaveBindingFailureLogged = false;
            waveState.HeldAgentsByIndex.Clear();
            return true;
        }

        private static void HoldMaterializedSiegeReinforcementAgent(
            Mission mission,
            MaterializedSiegeReinforcementWaveState waveState,
            Agent agent,
            string entryId,
            string source)
        {
            if (mission == null || waveState == null || agent == null || !agent.IsActive())
                return;

            var heldState = new MaterializedSiegeReinforcementHeldAgentState
            {
                Agent = agent,
                PreviousMortalityState = agent.CurrentMortalityState,
                PreviousAiPaused = agent.IsPaused,
                MountAgent = agent.MountAgent,
                PreviousMountMortalityState = agent.MountAgent?.CurrentMortalityState ?? Agent.MortalityState.Mortal,
                PreviousMountAiPaused = agent.MountAgent?.IsPaused == true
            };
            waveState.HeldAgentsByIndex[agent.Index] = heldState;

            agent.SetMortalityState(Agent.MortalityState.Invulnerable);
            agent.SetAutomaticTargetSelection(false);
            agent.SetFiringOrder(FiringOrder.RangedWeaponUsageOrderEnum.HoldYourFire);
            agent.SetIsAIPaused(true);
            if (heldState.MountAgent != null && heldState.MountAgent.IsActive())
            {
                heldState.MountAgent.SetMortalityState(Agent.MortalityState.Invulnerable);
                heldState.MountAgent.SetIsAIPaused(true);
            }

            waveState.PendingWaveBindingSequence++;
            bool sent = CoopMissionNetworkBridge.TryBroadcastMaterializedReinforcementAgentBinding(
                mission,
                waveState.PendingWaveBatchId,
                agent.Index,
                waveState.PendingWaveBindingSequence,
                waveState.PendingWavePlannedCount,
                entryId,
                out string diagnostics);
            if (!sent && !waveState.PendingWaveBindingFailureLogged)
            {
                waveState.PendingWaveBindingFailureLogged = true;
                ModLogger.Info(
                    "CoopMissionSpawnLogic: reinforcement agent binding send failed; materialization remains held. " +
                    "BatchId=" + waveState.PendingWaveBatchId +
                    " AgentIndex=" + agent.Index +
                    " Diagnostics=" + (diagnostics ?? "unknown") +
                    " Source=" + (source ?? "unknown"));
            }
        }

        private static bool TryReleasePendingMaterializedSiegeReinforcementWave(
            Mission mission,
            Team team,
            MaterializedSiegeReinforcementWaveState waveState,
            string source)
        {
            if (mission == null || team == null || waveState == null || !waveState.PendingWaveMaterializationComplete)
                return false;

            bool peersReady = CoopMissionNetworkBridge.AreMaterializedReinforcementBatchPeersReady(
                mission,
                waveState.PendingWaveBatchId,
                out _);
            if (!peersReady)
                return false;

            foreach (MaterializedSiegeReinforcementHeldAgentState heldState in
                     waveState.HeldAgentsByIndex.Values.ToArray())
            {
                Agent agent = heldState?.Agent;
                if (agent == null || !agent.IsActive())
                    continue;

                Agent mountAgent = heldState.MountAgent;
                if (mountAgent != null && mountAgent.IsActive())
                {
                    mountAgent.SetMortalityState(heldState.PreviousMountMortalityState);
                    mountAgent.SetIsAIPaused(heldState.PreviousMountAiPaused);
                }

                agent.SetMortalityState(heldState.PreviousMortalityState);
                agent.SetIsAIPaused(false);
                agent.SetAlarmState(Agent.AIStateFlag.Alarmed);
                agent.SetAutomaticTargetSelection(true);
                agent.SetFiringOrder(FiringOrder.RangedWeaponUsageOrderEnum.FireAtWill);
                agent.ResetEnemyCaches();
                agent.HumanAIComponent?.SyncBehaviorParamsIfNecessary();
            }

            int completedWaveCount = waveState.PendingWavePlannedCount;
            int completedBatchId = waveState.PendingWaveBatchId;
            waveState.SpawnedWaveCount++;
            waveState.SpawnedReinforcementCount += completedWaveCount;
            CoopMissionNetworkBridge.CompleteMaterializedReinforcementBatch(mission, completedBatchId);
            ClearPendingMaterializedSiegeReinforcementWavePlan(waveState);
            TryActivateBattleActiveReinforcementAi(team);

            return true;
        }

        private static bool TryInitializePendingMaterializedSiegeReinforcementWavePlan(
            MaterializedSiegeReinforcementWaveState waveState,
            IReadOnlyList<MaterializedArmyReinforcementCandidate> candidates,
            int waveBudget)
        {
            if (waveState == null || candidates == null || candidates.Count == 0 || waveBudget <= 0)
                return false;

            ClearPendingMaterializedSiegeReinforcementWavePlan(waveState);
            int remainingWaveBudget = waveBudget;
            var queuedByEntryId = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

            foreach (MaterializedArmyReinforcementCandidate candidate in candidates.Where(item => item.ActiveCount <= 0))
            {
                if (remainingWaveBudget <= 0)
                    break;

                int seedCount = GetReinforcementSpawnCount(candidate, queuedByEntryId, remainingWaveBudget, seedOneBody: true);
                if (seedCount <= 0)
                    continue;

                AddPendingMaterializedSiegeReinforcementPlanEntry(waveState, candidate, seedCount);
                queuedByEntryId[candidate.EntryState.EntryId ?? string.Empty] =
                    GetQueuedReinforcementCount(queuedByEntryId, candidate.EntryState.EntryId) + seedCount;
                remainingWaveBudget -= seedCount;
            }

            foreach (MaterializedArmyReinforcementCandidate candidate in candidates)
            {
                if (remainingWaveBudget <= 0)
                    break;

                int fillCount = GetReinforcementSpawnCount(candidate, queuedByEntryId, remainingWaveBudget, seedOneBody: false);
                if (fillCount <= 0)
                    continue;

                AddPendingMaterializedSiegeReinforcementPlanEntry(waveState, candidate, fillCount);
                queuedByEntryId[candidate.EntryState.EntryId ?? string.Empty] =
                    GetQueuedReinforcementCount(queuedByEntryId, candidate.EntryState.EntryId) + fillCount;
                remainingWaveBudget -= fillCount;
            }

            waveState.PendingWavePlannedCount = waveState.PendingWavePlan.Sum(entry => Math.Max(0, entry.PlannedCount));
            waveState.PendingWaveSpawnedCount = 0;
            waveState.PendingWavePlanCursor = 0;
            return waveState.PendingWavePlannedCount > 0;
        }

        private static void AddPendingMaterializedSiegeReinforcementPlanEntry(
            MaterializedSiegeReinforcementWaveState waveState,
            MaterializedArmyReinforcementCandidate candidate,
            int count)
        {
            if (waveState == null || candidate?.EntryState == null || candidate.Troop == null || count <= 0)
                return;

            string entryId = candidate.EntryState.EntryId ?? string.Empty;
            MaterializedSiegeReinforcementPlanEntry plannedEntry = waveState.PendingWavePlan.FirstOrDefault(entry =>
                string.Equals(entry?.EntryState?.EntryId ?? string.Empty, entryId, StringComparison.OrdinalIgnoreCase));
            if (plannedEntry == null)
            {
                plannedEntry = new MaterializedSiegeReinforcementPlanEntry
                {
                    EntryState = candidate.EntryState,
                    Troop = candidate.Troop,
                    ResolvedTroopSource = candidate.ResolvedTroopSource,
                };
                waveState.PendingWavePlan.Add(plannedEntry);
            }

            plannedEntry.PlannedCount += count;
        }

        private static int SpawnPendingMaterializedSiegeReinforcementWaveBatch(
            Mission mission,
            Team team,
            BattleSideEnum side,
            MaterializedSiegeReinforcementWaveState waveState,
            int activeForSide,
            int batchBudget,
            string source)
        {
            if (mission == null || team == null || waveState?.PendingWavePlan == null || batchBudget <= 0)
                return 0;

            int spawnedForBatch = 0;
            int noProgressEntryCount = 0;
            while (batchBudget > 0 && HasPendingMaterializedSiegeReinforcementWave(waveState))
            {
                int planCount = waveState.PendingWavePlan.Count;
                if (planCount <= 0)
                    break;

                int planIndex = waveState.PendingWavePlanCursor % planCount;
                waveState.PendingWavePlanCursor = (planIndex + 1) % planCount;
                MaterializedSiegeReinforcementPlanEntry plannedEntry = waveState.PendingWavePlan[planIndex];
                int remainingForEntry = Math.Max(0, (plannedEntry?.PlannedCount ?? 0) - (plannedEntry?.SpawnedCount ?? 0));
                if (plannedEntry?.EntryState == null || plannedEntry.Troop == null || remainingForEntry <= 0)
                {
                    noProgressEntryCount++;
                    if (noProgressEntryCount >= planCount)
                        break;
                    continue;
                }

                int activePlanEntryCount = waveState.PendingWavePlan.Count(entry =>
                    entry != null && entry.PlannedCount > entry.SpawnedCount);
                int requestedCount = Math.Min(
                    remainingForEntry,
                    Math.Max(1, (int)Math.Ceiling((double)batchBudget / Math.Max(1, activePlanEntryCount))));
                int spawned = SpawnMaterializedAgentsForEntry(
                    mission,
                    team,
                    side,
                    plannedEntry.Troop,
                    plannedEntry.EntryState,
                    requestedCount,
                    GetMaterializedReinforcementPlacementOffset(true, activeForSide, spawnedForBatch),
                    (source ?? "unknown") + " reinforcement-batch character=" + (plannedEntry.ResolvedTroopSource ?? "unknown"),
                    isReinforcement: true,
                    reinforcementWaveState: waveState);
                if (spawned <= 0)
                {
                    noProgressEntryCount++;
                    if (noProgressEntryCount >= planCount)
                        break;
                    continue;
                }

                noProgressEntryCount = 0;
                plannedEntry.SpawnedCount += spawned;
                waveState.PendingWaveSpawnedCount += spawned;
                spawnedForBatch += spawned;
                batchBudget -= spawned;
            }

            return spawnedForBatch;
        }

        private static int GetMaximumPendingMaterializedSiegeReinforcementPhysicalCostPerTroop(
            Mission mission,
            BattleSideEnum side,
            MaterializedSiegeReinforcementWaveState waveState)
        {
            if (mission == null ||
                waveState?.PendingWavePlan == null)
            {
                return 1;
            }

            int maximumPhysicalCostPerTroop = 1;
            foreach (MaterializedSiegeReinforcementPlanEntry plannedEntry in waveState.PendingWavePlan)
            {
                if (plannedEntry?.EntryState == null ||
                    plannedEntry.Troop == null ||
                    plannedEntry.PlannedCount <= plannedEntry.SpawnedCount)
                {
                    continue;
                }

                FormationClass formationClass = plannedEntry.Troop.DefaultFormationClass;
                bool fallbackMounted =
                    formationClass == FormationClass.Cavalry ||
                    formationClass == FormationClass.HorseArcher;
                int physicalCost = BattleAgentCapacityPolicy.GetExpectedTroopPhysicalCost(
                    mission,
                    side,
                    plannedEntry.EntryState,
                    fallbackMounted);
                maximumPhysicalCostPerTroop = Math.Max(maximumPhysicalCostPerTroop, physicalCost);
            }

            return maximumPhysicalCostPerTroop;
        }

        private static void ClearPendingMaterializedSiegeReinforcementWavePlan(
            MaterializedSiegeReinforcementWaveState waveState)
        {
            if (waveState == null)
                return;

            waveState.PendingWavePlan?.Clear();
            waveState.PendingWavePlannedCount = 0;
            waveState.PendingWaveSpawnedCount = 0;
            waveState.PendingWavePlanCursor = 0;
            waveState.PendingWavePreparationTargetCount = 0;
            waveState.PendingWavePreflightStarted = false;
            waveState.PendingWaveArmed = false;
            waveState.PendingWaveBatchId = 0;
            waveState.PendingWaveBindingSequence = 0;
            waveState.PendingWaveMaterializationComplete = false;
            waveState.PendingWaveBindingFailureLogged = false;
            waveState.HeldAgentsByIndex?.Clear();
        }

        private static int GetMaterializedReinforcementWavePhysicalCost(
            Mission mission,
            BattleSideEnum side,
            IReadOnlyList<MaterializedArmyReinforcementCandidate> candidates,
            int requestedTroopCount)
        {
            if (mission == null || candidates == null || requestedTroopCount <= 0)
                return 0;

            int remaining = requestedTroopCount;
            int physicalCost = 0;
            var queuedByEntryId = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

            foreach (MaterializedArmyReinforcementCandidate candidate in candidates.Where(item => item.ActiveCount <= 0))
            {
                if (remaining <= 0)
                    break;

                int count = GetReinforcementSpawnCount(candidate, queuedByEntryId, remaining, seedOneBody: true);
                if (count <= 0)
                    continue;

                string entryId = candidate.EntryState?.EntryId ?? string.Empty;
                queuedByEntryId[entryId] = GetQueuedReinforcementCount(queuedByEntryId, entryId) + count;
                physicalCost += count * GetMaterializedCandidatePhysicalCost(mission, side, candidate);
                remaining -= count;
            }

            foreach (MaterializedArmyReinforcementCandidate candidate in candidates)
            {
                if (remaining <= 0)
                    break;

                int count = GetReinforcementSpawnCount(candidate, queuedByEntryId, remaining, seedOneBody: false);
                if (count <= 0)
                    continue;

                string entryId = candidate.EntryState?.EntryId ?? string.Empty;
                queuedByEntryId[entryId] = GetQueuedReinforcementCount(queuedByEntryId, entryId) + count;
                physicalCost += count * GetMaterializedCandidatePhysicalCost(mission, side, candidate);
                remaining -= count;
            }

            return remaining > 0 ? int.MaxValue : physicalCost;
        }

        private static int GetMaterializedCandidatePhysicalCost(
            Mission mission,
            BattleSideEnum side,
            MaterializedArmyReinforcementCandidate candidate)
        {
            FormationClass formationClass = candidate?.Troop?.DefaultFormationClass ?? FormationClass.Infantry;
            bool fallbackMounted =
                formationClass == FormationClass.Cavalry ||
                formationClass == FormationClass.HorseArcher;
            return BattleAgentCapacityPolicy.GetExpectedTroopPhysicalCost(
                mission,
                side,
                candidate?.EntryState,
                fallbackMounted);
        }

        private static int GetReinforcementSpawnCount(
            MaterializedArmyReinforcementCandidate candidate,
            IReadOnlyDictionary<string, int> queuedByEntryId,
            int remainingSideNeed,
            bool seedOneBody)
        {
            if (candidate == null || remainingSideNeed <= 0)
                return 0;

            int alreadyQueued = GetQueuedReinforcementCount(queuedByEntryId, candidate.EntryState?.EntryId);
            int remainingTotalCount = Math.Max(0, candidate.TotalRemainingCount - alreadyQueued);
            int remainingConcurrentCapacity = Math.Max(0, candidate.ConcurrentRemainingCapacity - alreadyQueued);
            int allowed = Math.Min(remainingSideNeed, Math.Min(remainingTotalCount, remainingConcurrentCapacity));
            if (allowed <= 0)
                return 0;

            return seedOneBody ? Math.Min(1, allowed) : allowed;
        }

        private static int GetQueuedReinforcementCount(IReadOnlyDictionary<string, int> queuedByEntryId, string entryId)
        {
            if (queuedByEntryId == null || string.IsNullOrWhiteSpace(entryId))
                return 0;

            return queuedByEntryId.TryGetValue(entryId, out int queuedCount)
                ? Math.Max(0, queuedCount)
                : 0;
        }

        private static int GetMaterializedReinforcementConcurrentCapacity(
            Mission mission,
            BattleSideEnum side,
            int requestedEntryCount,
            int availableCount,
            int activeCount,
            int totalRemainingCount)
        {
            if (availableCount <= 0 || totalRemainingCount <= 0)
                return 0;

            return Math.Max(0, Math.Min(totalRemainingCount, availableCount - activeCount));
        }

        private static bool TryGetMaterializedSiegeReinforcementWaveBudget(
            Mission mission,
            BattleSideEnum side,
            int targetActiveCount,
            int activeCount,
            int reserveCount,
            string source,
            out MaterializedSiegeReinforcementWaveState waveState,
            out int waveBudget)
        {
            waveBudget = 0;
            waveState = GetOrInitializeMaterializedSiegeReinforcementWaveState(
                mission,
                side,
                targetActiveCount,
                activeCount,
                reserveCount,
                source + " lazy-wave-state");
            if (waveState == null)
                return false;

            int deficit = Math.Max(0, waveState.InitialActiveCount - activeCount);
            string decision = null;
            if (reserveCount <= 0)
            {
                decision = "reserve-exhausted";
            }
            else if (waveState.MaximumWaveCount > 0 &&
                     waveState.SpawnedWaveCount >= waveState.MaximumWaveCount)
            {
                decision = "maximum-wave-count-reached";
            }
            else if (deficit < waveState.WaveSize)
            {
                decision = "waiting-for-threshold";
            }
            else
            {
                waveBudget = Math.Min(deficit, Math.Min(waveState.WaveSize, reserveCount));
                if (waveBudget <= 0)
                    decision = "no-wave-budget";
            }

            if (decision != null)
            {
                ExactSiegeMoraleDiagnostics.RecordReinforcementWaveDecision(
                    mission,
                    side,
                    waveState.InitialActiveCount,
                    activeCount,
                    reserveCount,
                    waveState.WaveSize,
                    waveState.MaximumWaveCount,
                    waveState.SpawnedWaveCount,
                    0,
                    decision,
                    source);
                return false;
            }

            return true;
        }

        private static void InitializeMaterializedSiegeReinforcementWaveState(
            Mission mission,
            BattleSideEnum side,
            int initialActiveCount,
            int currentActiveCount,
            int reserveCount,
            string source)
        {
            if (mission == null || side == BattleSideEnum.None)
                return;

            EnsureMaterializedSiegeReinforcementWaveRuntimeMission(mission);
            if (MaterializedSiegeReinforcementWaveStates.TryGetValue(side, out MaterializedSiegeReinforcementWaveState existingState) &&
                ReferenceEquals(existingState?.Mission, mission))
            {
                return;
            }

            int resolvedInitialActiveCount = Math.Max(0, currentActiveCount);
            if (resolvedInitialActiveCount <= 0)
                resolvedInitialActiveCount = Math.Max(0, initialActiveCount);

            var waveState = new MaterializedSiegeReinforcementWaveState
            {
                Mission = mission,
                Side = side,
                InitialActiveCount = resolvedInitialActiveCount,
                WaveSize = Math.Max(
                    1,
                    (int)Math.Max(
                        1f,
                        resolvedInitialActiveCount * MaterializedSiegeReinforcementWavePercentage)),
                MaximumWaveCount = ResolveMaterializedSiegeMaximumReinforcementWaveCount(),
                SpawnedWaveCount = 0,
                SpawnedReinforcementCount = 0,
            };
            MaterializedSiegeReinforcementWaveStates[side] = waveState;

            ExactSiegeMoraleDiagnostics.RecordReinforcementWaveDecision(
                mission,
                side,
                waveState.InitialActiveCount,
                currentActiveCount,
                reserveCount,
                waveState.WaveSize,
                waveState.MaximumWaveCount,
                waveState.SpawnedWaveCount,
                0,
                "initialized",
                source);
        }

        private static MaterializedSiegeReinforcementWaveState GetOrInitializeMaterializedSiegeReinforcementWaveState(
            Mission mission,
            BattleSideEnum side,
            int initialActiveCount,
            int currentActiveCount,
            int reserveCount,
            string source)
        {
            if (mission == null || side == BattleSideEnum.None)
                return null;

            EnsureMaterializedSiegeReinforcementWaveRuntimeMission(mission);
            if (!MaterializedSiegeReinforcementWaveStates.TryGetValue(side, out MaterializedSiegeReinforcementWaveState waveState) ||
                !ReferenceEquals(waveState?.Mission, mission))
            {
                InitializeMaterializedSiegeReinforcementWaveState(
                    mission,
                    side,
                    initialActiveCount,
                    currentActiveCount,
                    reserveCount,
                    source);
                MaterializedSiegeReinforcementWaveStates.TryGetValue(side, out waveState);
            }

            return waveState;
        }

        private static void EnsureMaterializedSiegeReinforcementWaveRuntimeMission(Mission mission)
        {
            if (ReferenceEquals(_materializedSiegeReinforcementWaveMission, mission))
                return;

            ResetMaterializedSiegeReinforcementWaveRuntimeState();
            _materializedSiegeReinforcementWaveMission = mission;
            _nextMaterializedSiegeReinforcementCheckMissionTime = mission != null
                ? mission.CurrentTime + MaterializedSiegeReinforcementCheckIntervalSeconds
                : float.MinValue;
        }

        private static void ResetMaterializedSiegeReinforcementWaveRuntimeState()
        {
            foreach (MaterializedSiegeReinforcementWaveState waveState in
                     MaterializedSiegeReinforcementWaveStates.Values)
            {
                if (waveState == null)
                    continue;

                foreach (MaterializedSiegeReinforcementHeldAgentState heldState in
                         waveState.HeldAgentsByIndex.Values)
                {
                    Agent agent = heldState?.Agent;
                    if (agent != null && agent.IsActive())
                    {
                        agent.SetMortalityState(heldState.PreviousMortalityState);
                        agent.SetIsAIPaused(heldState.PreviousAiPaused);
                    }

                    Agent mountAgent = heldState?.MountAgent;
                    if (mountAgent != null && mountAgent.IsActive())
                    {
                        mountAgent.SetMortalityState(heldState.PreviousMountMortalityState);
                        mountAgent.SetIsAIPaused(heldState.PreviousMountAiPaused);
                    }
                }

                CoopMissionNetworkBridge.CompleteMaterializedReinforcementBatch(
                    waveState.Mission,
                    waveState.PendingWaveBatchId);
            }

            MaterializedSiegeReinforcementWaveStates.Clear();
            _materializedSiegeReinforcementWaveMission = null;
            _nextMaterializedSiegeReinforcementCheckMissionTime = float.MinValue;
            _nextMaterializedSiegeReinforcementBatchFirstSide = BattleSideEnum.Attacker;
            _nextMaterializedSiegeReinforcementBatchId = 1;
        }

        private static int ResolveMaterializedSiegeMaximumReinforcementWaveCount()
        {
            int maximumWaveCount = BattleSnapshotRuntimeState.GetState()?.ReinforcementWaveCount ?? 0;
            if (maximumWaveCount <= 0)
                maximumWaveCount = BattleSnapshotRuntimeState.GetCurrent()?.ReinforcementWaveCount ?? 0;

            return Math.Max(0, maximumWaveCount);
        }

        private static int GetMaterializedReinforcementPlacementOffset(
            bool useMaterializedSiegeReinforcements,
            int activeForSide,
            int spawnedCountForSide)
        {
            return useMaterializedSiegeReinforcements
                ? Math.Max(0, spawnedCountForSide)
                : Math.Max(0, activeForSide + spawnedCountForSide);
        }

        private static int TryActivateBattleActiveReinforcementAi(Team team)
        {
            if (team == null || team.Side == BattleSideEnum.None || ReferenceEquals(team, team.Mission?.SpectatorTeam))
                return 0;

            bool useNativeExactSiegeFormationAi = ShouldUseMaterializedSiegeReinforcements(team.Mission);
            int pulsedAgentCount = 0;
            foreach (Formation formation in team.FormationsIncludingSpecialAndEmpty)
            {
                if (formation == null ||
                    formation.CountOfUnits <= 0 ||
                    formation.PlayerOwner != null)
                {
                    continue;
                }

                if (useNativeExactSiegeFormationAi)
                {
                    formation.SetControlledByAI(true, true);
                    ExactSiegeMoraleDiagnostics.RecordFormationAiHandoff(
                        formation,
                        "reinforcement-wave",
                        "TryActivateBattleActiveReinforcementAi");
                }
                else
                {
                    formation.SetMovementOrder(MovementOrder.MovementOrderCharge);
                    formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
                    formation.SetControlledByAI(true, true);
                    pulsedAgentCount += TryPulseFormationAiEngage(formation, team);
                }
            }

            if (team.HasTeamAi && team.HasAnyEnemyTeamsWithAgents(false))
            {
                team.ResetTactic();
                CoopMissionNetworkBridge.ReapplyDelegatedFormationOwnership(
                    team.Mission,
                    team,
                    "reinforcement-wave-after-tactic-reset");
            }

            return pulsedAgentCount;
        }

        private static int CountMaterializedUnspawnedReserveForSide(Mission mission, BattleSideEnum side)
        {
            if (side == BattleSideEnum.None)
                return 0;

            int reserveCount = 0;
            IReadOnlyList<RosterEntryState> entryStates = GetAutomatedMaterializableEntryStatesSnapshot(
                side,
                preferFullBattleSideRoster: ShouldUseMaterializedSiegeReinforcements(mission));
            foreach (RosterEntryState entryState in entryStates)
            {
                if (entryState == null)
                    continue;

                int availableCount = Math.Max(0, entryState.Count - entryState.WoundedCount);
                if (availableCount <= 0)
                    continue;

                _materializedBattleResultEntriesByEntryId.TryGetValue(entryState.EntryId ?? string.Empty, out MaterializedBattleResultEntryRuntimeState runtimeState);
                int spawnedCount = Math.Max(0, runtimeState?.MaterializedSpawnCount ?? 0);
                reserveCount += Math.Max(0, availableCount - spawnedCount);
            }

            if (reserveCount > 0 && ShouldUseMaterializedSiegeReinforcements(mission))
            {
                int targetActiveCount = GetInitialMaterializedArmyTargetCount(side);
                MaterializedSiegeReinforcementWaveState waveState =
                    GetOrInitializeMaterializedSiegeReinforcementWaveState(
                        mission,
                        side,
                        targetActiveCount,
                        GetCurrentMaterializedActiveCountForSide(side),
                        reserveCount,
                        "battle-completion-reserve-count");
                if (waveState != null && waveState.MaximumWaveCount > 0)
                {
                    int remainingWaveCount = Math.Max(
                        0,
                        waveState.MaximumWaveCount - waveState.SpawnedWaveCount);
                    long eligibleReserveCount = (long)remainingWaveCount * waveState.WaveSize;
                    reserveCount = (int)Math.Min(reserveCount, Math.Min(int.MaxValue, eligibleReserveCount));
                }
            }

            return reserveCount;
        }

        private static int GetInitialMaterializedArmyTargetCount(BattleSideEnum side)
        {
            if (side == BattleSideEnum.None)
                return 0;

            IReadOnlyList<RosterEntryState> entryStates = GetAutomatedMaterializableEntryStatesSnapshot(side);
            if (entryStates != null && entryStates.Count > 0)
            {
                int sideCap = GetMaterializedArmyAgentsPerSideCap(side, entryStates.Count);
                int totalAvailable = entryStates.Sum(entryState =>
                    Math.Max(0, (entryState?.Count ?? 0) - (entryState?.WoundedCount ?? 0)));
                return Math.Max(0, Math.Min(sideCap, totalAvailable));
            }

            IReadOnlyList<string> troopIds = GetGenericMaterializedTroopFallbackIds(side);
            if (troopIds == null || troopIds.Count <= 0)
                return 0;

            int fallbackSideCap = GetMaterializedArmyAgentsPerSideCap(side, troopIds.Count);
            int fallbackAvailable = troopIds.Count * GetFallbackMaterializedAgentsPerTroopCap(side, troopIds.Count);
            return Math.Max(0, Math.Min(fallbackSideCap, fallbackAvailable));
        }

        private static int GetInitialMaterializedArmySpawnPulseBudgetPerSide(Mission mission)
        {
            return ShouldUseFieldMaterializedSiegeReplayRuntime(mission)
                ? FieldMaterializedSiegeInitialMaterializedArmySpawnPulseBudgetPerSide
                : InitialMaterializedArmySpawnPulseBudgetPerSide;
        }

        private static int GetCurrentMaterializedSpawnCountForSide(BattleSideEnum side)
        {
            if (side == BattleSideEnum.None || _materializedBattleResultEntriesByEntryId.Count == 0)
                return 0;

            string sideId = side.ToString();
            int spawnedCount = 0;
            foreach (MaterializedBattleResultEntryRuntimeState entryState in _materializedBattleResultEntriesByEntryId.Values)
            {
                if (entryState == null || !string.Equals(entryState.SideId, sideId, StringComparison.OrdinalIgnoreCase))
                    continue;

                spawnedCount += Math.Max(0, entryState.MaterializedSpawnCount);
            }

            return spawnedCount;
        }

        private static int GetCurrentMaterializedActiveCountForSide(BattleSideEnum side)
        {
            if (side == BattleSideEnum.None || _materializedBattleResultEntriesByEntryId.Count == 0)
                return 0;

            string sideId = side.ToString();
            int activeCount = 0;
            foreach (MaterializedBattleResultEntryRuntimeState entryState in _materializedBattleResultEntriesByEntryId.Values)
            {
                if (entryState == null || !string.Equals(entryState.SideId, sideId, StringComparison.OrdinalIgnoreCase))
                    continue;

                activeCount += Math.Max(0, entryState.ActiveCount);
            }

            return activeCount;
        }

        private static IReadOnlyList<RosterEntryState> GetAutomatedMaterializableEntryStatesSnapshot(BattleSideEnum side)
        {
            return GetAutomatedMaterializableEntryStatesSnapshot(side, preferFullBattleSideRoster: false);
        }

        private static IReadOnlyList<RosterEntryState> GetAutomatedMaterializableEntryStatesSnapshot(
            BattleSideEnum side,
            bool preferFullBattleSideRoster)
        {
            IReadOnlyList<RosterEntryState> entryStates = GetMaterializedArmySourceEntryStatesSnapshot(
                side,
                preferFullBattleSideRoster);
            if (entryStates == null || entryStates.Count == 0)
                return Array.Empty<RosterEntryState>();

            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            RosterEntryState commanderEntry = ShouldUseFieldMaterializedSiegeReplayRuntime(Mission.Current)
                ? BattleCommanderResolver.ResolveCommanderEntry(runtimeState, side, entryStates)
                : null;
            string commanderEntryId = commanderEntry?.EntryId;
            bool commanderEntryIncluded = false;
            bool preserveExactCampaignHeroes = ShouldUseFieldMaterializedSiegeReplayRuntime(Mission.Current);
            var filteredEntries = new List<RosterEntryState>(entryStates.Count);
            var exactPlayerPartyFallbackEntries = new List<RosterEntryState>(entryStates.Count);
            foreach (RosterEntryState entryState in entryStates)
            {
                string skipReason = GetAutomatedMaterializedSpawnEntrySkipReason(entryState);
                if (string.IsNullOrEmpty(skipReason))
                {
                    filteredEntries.Add(entryState);
                    continue;
                }

                if (!string.IsNullOrWhiteSpace(commanderEntryId) &&
                    string.Equals(entryState.EntryId, commanderEntryId, StringComparison.Ordinal))
                {
                    filteredEntries.Add(entryState);
                    commanderEntryIncluded = true;
                    string commanderLogKey = "commander-entry-automated-materialization:" + side + ":" + commanderEntryId;
                    if (_loggedAutomatedMaterializedEntrySkipIds.Add(commanderLogKey))
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: preserving commander entry for automated field-materialized siege materialization. " +
                            "Side=" + side +
                            " EntryId=" + (entryState.EntryId ?? "null") +
                            " PreviousSkipReason=" + skipReason +
                            " Hero=" + entryState.IsHero +
                            " HeroRole=" + (entryState.HeroRole ?? "null"));
                    }
                    continue;
                }

                bool isLivingCampaignHero =
                    preserveExactCampaignHeroes &&
                    (entryState.IsHero || !string.IsNullOrWhiteSpace(entryState.HeroRole)) &&
                    entryState.Count - entryState.WoundedCount > 0 &&
                    !string.IsNullOrWhiteSpace(ResolveEntrySpawnTemplateId(entryState));
                if (isLivingCampaignHero)
                {
                    filteredEntries.Add(entryState);
                    string heroLogKey = "campaign-hero-automated-materialization:" + side + ":" + entryState.EntryId;
                    if (_loggedAutomatedMaterializedEntrySkipIds.Add(heroLogKey))
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: preserving living campaign hero for automated field-materialized siege materialization. " +
                            "Side=" + side +
                            " EntryId=" + (entryState.EntryId ?? "null") +
                            " PreviousSkipReason=" + skipReason +
                            " HeroRole=" + (entryState.HeroRole ?? "null") +
                            " HeroLevel=" + entryState.HeroLevel);
                    }
                    continue;
                }

                if (string.Equals(skipReason, "player-party-entry", StringComparison.OrdinalIgnoreCase) &&
                    IsAutomatedMaterializedExactPlayerPartyFallbackCandidate(entryState))
                {
                    exactPlayerPartyFallbackEntries.Add(entryState);
                    continue;
                }

                LogAutomatedMaterializedSpawnEntrySkip(entryState, skipReason);
            }

            if (filteredEntries.Count > 0)
            {
                if (commanderEntryIncluded && exactPlayerPartyFallbackEntries.Count > 0)
                {
                    string fallbackMergeLogKey = "commander-player-party-fallback-merge:" + side;
                    if (_loggedAutomatedMaterializedEntrySkipIds.Add(fallbackMergeLogKey))
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: preserving non-hero player-party entries alongside commander materialization for field-materialized siege runtime. " +
                            "Side=" + side +
                            " CommanderEntryId=" + (commanderEntryId ?? "null") +
                            " PreservedEntryCount=" + exactPlayerPartyFallbackEntries.Count);
                    }

                    foreach (RosterEntryState fallbackEntry in exactPlayerPartyFallbackEntries)
                    {
                        if (fallbackEntry == null ||
                            filteredEntries.Any(entry => string.Equals(entry?.EntryId, fallbackEntry.EntryId, StringComparison.Ordinal)))
                        {
                            continue;
                        }

                        filteredEntries.Add(fallbackEntry);
                    }
                }

                if (!string.IsNullOrWhiteSpace(commanderEntryId) && filteredEntries.Count > 1)
                {
                    filteredEntries = filteredEntries
                        .OrderBy(entry =>
                            string.Equals(entry?.EntryId, commanderEntryId, StringComparison.Ordinal)
                                ? -1
                                : GetAllowedEntrySelectionPriority(entry))
                        .ThenByDescending(entry => entry?.HeroLevel ?? 0)
                        .ThenBy(entry => entry?.EntryId, StringComparer.Ordinal)
                        .ToList();
                }

                return filteredEntries;
            }

            if (exactPlayerPartyFallbackEntries.Count > 0)
            {
                string logKey = "exact-player-party-fallback:" + side;
                if (_loggedAutomatedMaterializedEntrySkipIds.Add(logKey))
                {
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: preserving non-hero player-party exact roster entries for automated materialization because filtering would otherwise leave side empty. " +
                        "Side=" + side +
                        " RawEntryCount=" + entryStates.Count +
                        " PreservedEntryCount=" + exactPlayerPartyFallbackEntries.Count);
                }

                return exactPlayerPartyFallbackEntries;
            }

            return Array.Empty<RosterEntryState>();
        }

        private static IReadOnlyList<RosterEntryState> GetMaterializedArmySourceEntryStatesSnapshot(
            BattleSideEnum side,
            bool preferFullBattleSideRoster)
        {
            if (side == BattleSideEnum.None)
                return Array.Empty<RosterEntryState>();

            if (preferFullBattleSideRoster)
            {
                BattleSideState sideState = BattleSnapshotRuntimeState.GetSideState(side.ToString());
                if (sideState?.Entries != null && sideState.Entries.Count > 0)
                    return sideState.Entries.Where(entry => entry != null).ToArray();
            }

            return GetAllowedControlEntryStatesSnapshot(side);
        }

        private static string GetAutomatedMaterializedSpawnEntrySkipReason(RosterEntryState entryState)
        {
            if (entryState == null)
                return "null-entry";

            bool isHeroEntry =
                entryState.IsHero ||
                !string.IsNullOrWhiteSpace(entryState.HeroRole) ||
                string.Equals(entryState.OriginalCharacterId, "main_hero", StringComparison.OrdinalIgnoreCase);
            if (isHeroEntry && !IsCampaignMirrorHeroesRuntime())
                return "hero-entry";

            bool isPlayerPartyEntry =
                string.Equals(entryState.PartyId, "player_party", StringComparison.OrdinalIgnoreCase);
            return isPlayerPartyEntry
                ? "player-party-entry"
                : string.Empty;
        }

        private static bool IsAutomatedMaterializedExactPlayerPartyFallbackCandidate(RosterEntryState entryState)
        {
            if (entryState == null)
                return false;

            return string.Equals(entryState.PartyId, "player_party", StringComparison.OrdinalIgnoreCase) &&
                   !entryState.IsHero &&
                   string.IsNullOrWhiteSpace(entryState.HeroRole) &&
                   !string.Equals(entryState.OriginalCharacterId, "main_hero", StringComparison.OrdinalIgnoreCase) &&
                   !string.IsNullOrWhiteSpace(ResolveEntrySpawnTemplateId(entryState));
        }

        private static void LogAutomatedMaterializedSpawnEntrySkip(RosterEntryState entryState, string reason)
        {
            string spawnTemplateId = ResolveEntrySpawnTemplateId(entryState);
            string entryKey = entryState?.EntryId ?? entryState?.OriginalCharacterId ?? spawnTemplateId ?? "(unknown)";
            if (!_loggedAutomatedMaterializedEntrySkipIds.Add(entryKey))
                return;

            ModLogger.Info(
                "CoopMissionSpawnLogic: skipping automated materialized spawn entry. " +
                "Reason=" + (reason ?? "unknown") +
                " " +
                "EntryId=" + (entryState?.EntryId ?? "null") +
                " PartyId=" + (entryState?.PartyId ?? "null") +
                " OriginalCharacterId=" + (entryState?.OriginalCharacterId ?? "null") +
                " HeroRole=" + (entryState?.HeroRole ?? "null") +
                " IsHero=" + (entryState?.IsHero ?? false) +
                " SpawnTemplateId=" + (spawnTemplateId ?? "null"));
        }

        private static IReadOnlyList<string> GetGenericMaterializedTroopFallbackIds(BattleSideEnum side)
        {
            if (side == BattleSideEnum.None)
                return Array.Empty<string>();

            IReadOnlyList<RosterEntryState> rawEntryStates = GetAllowedControlEntryStatesSnapshot(side);
            IReadOnlyList<string> allowedTroopIds = GetAllowedControlTroopIdsSnapshot(side);
            if (allowedTroopIds == null || allowedTroopIds.Count <= 0)
                return Array.Empty<string>();

            if (rawEntryStates == null || rawEntryStates.Count <= 0)
                return allowedTroopIds;

            IReadOnlyList<RosterEntryState> automatedEntryStates = GetAutomatedMaterializableEntryStatesSnapshot(side);
            if (automatedEntryStates != null && automatedEntryStates.Count > 0)
            {
                string logKey = "generic-fallback-suppressed:" + side;
                if (_loggedAutomatedMaterializedEntrySkipIds.Add(logKey))
                {
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: suppressed generic allowed-troop fallback for automated materialization because materializable roster entries exist. " +
                        "Side=" + side +
                        " RawEntryCount=" + rawEntryStates.Count +
                        " MaterializableEntryCount=" + automatedEntryStates.Count);
                }

                return Array.Empty<string>();
            }

            var safeTroopIds = new List<string>(allowedTroopIds.Count);
            foreach (string troopId in allowedTroopIds)
            {
                if (string.IsNullOrWhiteSpace(troopId))
                    continue;

                BasicCharacterObject troop = ResolveAllowedCharacter(troopId);
                bool isHeroTroop =
                    troop?.IsHero == true ||
                    troopId.IndexOf("_hero", StringComparison.OrdinalIgnoreCase) >= 0;
                if (isHeroTroop)
                    continue;

                if (safeTroopIds.Contains(troopId, StringComparer.OrdinalIgnoreCase))
                    continue;

                safeTroopIds.Add(troopId);
            }

            if (safeTroopIds.Count > 0)
            {
                string logKey = "generic-fallback-sanitized:" + side;
                if (_loggedAutomatedMaterializedEntrySkipIds.Add(logKey))
                {
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: using sanitized generic allowed-troop fallback for automated materialization because filtered roster entries left side empty. " +
                        "Side=" + side +
                        " RawEntryCount=" + rawEntryStates.Count +
                        " SafeTroopIds=[" + string.Join(", ", safeTroopIds) + "]");
                }

                return safeTroopIds;
            }

            string emptyLogKey = "generic-fallback-empty:" + side;
            if (_loggedAutomatedMaterializedEntrySkipIds.Add(emptyLogKey))
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: suppressed generic allowed-troop fallback for automated materialization because only hero-class fallback ids remained after filtering. " +
                    "Side=" + side +
                    " RawEntryCount=" + rawEntryStates.Count +
                    " AllowedTroopIds=[" + string.Join(", ", allowedTroopIds) + "]");
            }

            return Array.Empty<string>();
        }

        private static bool IsBattleSnapshotReadyForMaterialization(Mission mission, out string readinessSummary)
        {
            BattleRuntimeState rosterState = BattleSnapshotRuntimeState.GetState();
            BattleSnapshotMessage snapshot = BattleSnapshotRuntimeState.GetCurrent();
            int sideCount = 0;
            int populatedSideCount = 0;
            bool hasAttacker = false;
            bool hasDefender = false;

            if (rosterState?.Sides != null && rosterState.Sides.Count > 0)
            {
                sideCount = rosterState.Sides.Count;
                foreach (BattleSideState sideState in rosterState.Sides)
                {
                    BattleSideEnum side = ResolveBattleSideFromState(sideState);
                    int entryCount = sideState?.Entries?.Count ?? 0;
                    if (entryCount <= 0)
                        continue;

                    populatedSideCount++;
                    if (side == BattleSideEnum.Attacker)
                        hasAttacker = true;
                    else if (side == BattleSideEnum.Defender)
                        hasDefender = true;
                }
            }
            else if (snapshot?.Sides != null && snapshot.Sides.Count > 0)
            {
                sideCount = snapshot.Sides.Count;
                foreach (BattleSideSnapshotMessage sideSnapshot in snapshot.Sides)
                {
                    BattleSideEnum side = ResolveBattleSideFromSnapshot(sideSnapshot);
                    int troopCount = sideSnapshot?.Troops?.Count ?? 0;
                    if (troopCount <= 0)
                        continue;

                    populatedSideCount++;
                    if (side == BattleSideEnum.Attacker)
                        hasAttacker = true;
                    else if (side == BattleSideEnum.Defender)
                        hasDefender = true;
                }
            }

            readinessSummary =
                "BattleId=" + (snapshot?.BattleId ?? "null") +
                " SnapshotSource=" + (BattleSnapshotRuntimeState.GetSource() ?? "unknown") +
                " Sides=" + sideCount +
                " PopulatedSides=" + populatedSideCount +
                " HasAttacker=" + hasAttacker +
                " HasDefender=" + hasDefender;
            bool snapshotReady = sideCount >= 2 && populatedSideCount >= 2 && hasAttacker && hasDefender;
            bool peerSnapshotAckReady =
                CoopMissionNetworkBridge.HaveAllEligiblePeersAcknowledgedCurrentBattleSnapshot(
                    mission,
                    out string peerSnapshotAckSummary);
            readinessSummary += " PeerSnapshotAck={" + (peerSnapshotAckSummary ?? "unknown") + "}";
            return snapshotReady && peerSnapshotAckReady;
        }

        private static bool ShouldDeferExactSceneInitialBattlefieldMaterialization(Mission mission, out string reason)
        {
            reason = string.Empty;
            if (mission == null || !IsSceneAwareBattleMapRuntime(mission))
                return false;

            bool useFieldMaterializedSiegeReplayRuntime = ShouldUseFieldMaterializedSiegeReplayRuntime(mission);
            if (IsUsingNativeExactCampaignArmyBootstrap(mission) && !useFieldMaterializedSiegeReplayRuntime)
            {
                reason = "native exact-scene bootstrap active";
                return true;
            }

            if (!SceneRuntimeClassifier.IsExactCampaignBattleScene(mission.SceneName))
                return false;

            if (IsBattleSnapshotReadyForMaterialization(mission, out _))
                return false;

            if (HasExactSceneMaterializationAuthorityAnchor(mission, out string authorityAnchorSummary))
                return false;

            reason = authorityAnchorSummary;
            return true;
        }

        private static bool ShouldDeferOpenSiegeBattlefieldMaterializationUntilSpawnPath(Mission mission, out string reason)
        {
            reason = string.Empty;
            if (mission == null || !IsSceneAwareBattleMapRuntime(mission))
                return false;

            BattleScenarioContextMessage scenarioContext =
                BattleSnapshotRuntimeState.GetCurrent()?.ScenarioContext ??
                BattleSnapshotRuntimeState.GetState()?.ScenarioContext;
            string siegeSubtype = scenarioContext?.SiegeContext?.SiegeSubtype ?? string.Empty;
            if (scenarioContext?.IsSiegeBattle != true ||
                !string.Equals(siegeSubtype, "SiegeAssault", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            if (mission.HasSpawnPath)
                return false;

            bool hasSceneMapPatch = false;
            try
            {
                hasSceneMapPatch = mission.HasSceneMapPatch();
            }
            catch
            {
            }

            reason =
                "Scene=" + (mission.SceneName ?? "null") +
                " Mode=" + mission.Mode +
                " MissionState=" + mission.CurrentState +
                " HasSceneMapPatch=" + hasSceneMapPatch +
                " SiegeSubtype=" + siegeSubtype;
            return true;
        }

        private static bool HasExactSceneMaterializationAuthorityAnchor(Mission mission, out string reason)
        {
            reason = string.Empty;
            int synchronizedPeerCount = 0;
            int requestedPeerCount = 0;
            int assignedPeerCount = 0;
            int selectedPeerCount = 0;

            if (GameNetwork.NetworkPeers != null)
            {
                foreach (NetworkCommunicator peer in GameNetwork.NetworkPeers)
                {
                    if (peer == null || peer.IsServerPeer || !peer.IsConnectionActive || !peer.IsSynchronized)
                        continue;

                    synchronizedPeerCount++;
                    MissionPeer missionPeer = peer.GetComponent<MissionPeer>();
                    if (missionPeer == null)
                        continue;

                    CoopBattleAuthorityState.PeerSelectionState selectionState = CoopBattleAuthorityState.GetSelectionState(missionPeer);
                    if (selectionState.RequestedSide != BattleSideEnum.None)
                        requestedPeerCount++;

                    BattleSideEnum authoritativeSide = selectionState.Side;
                    if (authoritativeSide == BattleSideEnum.None)
                        authoritativeSide = ResolveAuthoritativeSide(missionPeer, mission, "initial-materialization-anchor");
                    if (authoritativeSide != BattleSideEnum.None)
                        assignedPeerCount++;

                    if (!string.IsNullOrWhiteSpace(selectionState.EntryId) ||
                        !string.IsNullOrWhiteSpace(selectionState.TroopId) ||
                        CoopBattleSpawnRequestState.HasPendingRequest(missionPeer))
                    {
                        selectedPeerCount++;
                    }
                }
            }

            if (assignedPeerCount > 0)
                return true;

            reason =
                "Scene=" + (mission?.SceneName ?? "null") +
                " SynchronizedPeers=" + synchronizedPeerCount +
                " RequestedPeers=" + requestedPeerCount +
                " AssignedPeers=" + assignedPeerCount +
                " SelectedPeers=" + selectedPeerCount;
            return false;
        }

        private static bool ShouldDeferExactScenePostPossessionMaterialization(Mission mission, out string reason)
        {
            reason = string.Empty;
            if (mission == null || _hasMaterializedBattlefieldArmies || !IsSceneAwareBattleMapRuntime(mission))
                return false;

            bool useFieldMaterializedSiegeReplayRuntime = ShouldUseFieldMaterializedSiegeReplayRuntime(mission);
            if (IsUsingNativeExactCampaignArmyBootstrap(mission) && !useFieldMaterializedSiegeReplayRuntime)
            {
                reason = "native exact-scene bootstrap active";
                return true;
            }

            if (!SceneRuntimeClassifier.IsExactCampaignBattleScene(mission.SceneName ?? string.Empty))
                return false;

            DateTime nowUtc = DateTime.UtcNow;
            if (_exactScenePostPossessionMaterializationResumeUtc <= nowUtc)
                return false;

            int controlledPeerCount = 0;
            if (GameNetwork.NetworkPeers != null)
            {
                foreach (NetworkCommunicator peer in GameNetwork.NetworkPeers)
                {
                    if (peer == null || peer.IsServerPeer || !peer.IsConnectionActive || !peer.IsSynchronized)
                        continue;

                    MissionPeer missionPeer = peer.GetComponent<MissionPeer>();
                    if (HasActiveControlledAgent(missionPeer))
                        controlledPeerCount++;
                }
            }

            if (controlledPeerCount <= 0)
                return false;

            reason =
                "Scene=" + (mission.SceneName ?? "null") +
                " ControlledPeers=" + controlledPeerCount +
                " RemainingSeconds=" + (_exactScenePostPossessionMaterializationResumeUtc - nowUtc)
                    .TotalSeconds
                    .ToString("0.0", System.Globalization.CultureInfo.InvariantCulture);
            return true;
        }

        private static int MaterializeArmyForSide(
            Mission mission,
            Team team,
            BattleSideEnum side,
            string source,
            int maxSpawnCount = int.MaxValue)
        {
            if (mission == null || team == null || side == BattleSideEnum.None || maxSpawnCount <= 0)
                return 0;

            int spawnedCount = 0;
            int currentSpawnedForSide = GetCurrentMaterializedSpawnCountForSide(side);
            IReadOnlyList<RosterEntryState> entryStates = GetAutomatedMaterializableEntryStatesSnapshot(side);
            int sideCap = GetMaterializedArmyAgentsPerSideCap(side, entryStates.Count);
            if (entryStates.Count > 0)
            {
                var materializableEntries = new List<(RosterEntryState EntryState, BasicCharacterObject Troop, int AvailableCount, string ResolvedTroopSource)>();
                foreach (RosterEntryState entryState in entryStates)
                {
                    string spawnTemplateId = ResolveEntrySpawnTemplateId(entryState);
                    if (entryState == null || string.IsNullOrWhiteSpace(spawnTemplateId))
                        continue;

                    int availableCount = Math.Max(0, entryState.Count - entryState.WoundedCount);
                    if (availableCount <= 0)
                        continue;

                    string resolvedTroopSource;
                    BasicCharacterObject troop = ResolveMaterializedArmyCharacter(entryState, spawnTemplateId, out resolvedTroopSource);
                    if (troop == null)
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: materialized entry character resolution failed. " +
                            "Side=" + side +
                            " EntryId=" + (entryState.EntryId ?? "null") +
                            " OriginalCharacterId=" + (entryState.OriginalCharacterId ?? "null") +
                            " SpawnTemplateId=" + (spawnTemplateId ?? "null") +
                            " Source=" + (source ?? "unknown"));
                        continue;
                    }

                    materializableEntries.Add((entryState, troop, availableCount, resolvedTroopSource));
                }

                // First pass: ensure each distinct roster entry gets at least one spawned body
                // before large stacks consume the side cap. This preserves representation for
                // hero/ranged/specialized entries such as crossbowmen under tight limits.
                foreach ((RosterEntryState entryState, BasicCharacterObject troop, int availableCount, string resolvedTroopSource) in materializableEntries)
                {
                    int remainingCapacity = sideCap - (currentSpawnedForSide + spawnedCount);
                    int remainingPulseBudget = maxSpawnCount - spawnedCount;
                    if (remainingCapacity <= 0 || remainingPulseBudget <= 0)
                        break;

                    _materializedBattleResultEntriesByEntryId.TryGetValue(entryState.EntryId ?? string.Empty, out MaterializedBattleResultEntryRuntimeState runtimeState);
                    int alreadySpawnedCount = Math.Max(0, runtimeState?.MaterializedSpawnCount ?? 0);
                    if (alreadySpawnedCount > 0)
                        continue;

                    int remainingAvailableCount = Math.Max(0, availableCount - alreadySpawnedCount);
                    int seedCount = Math.Min(1, Math.Min(remainingAvailableCount, Math.Min(remainingCapacity, remainingPulseBudget)));
                    if (seedCount <= 0)
                        continue;

                    spawnedCount += SpawnMaterializedAgentsForEntry(
                        mission,
                        team,
                        side,
                        troop,
                        entryState,
                        seedCount,
                        currentSpawnedForSide + spawnedCount,
                        source + " character=" + resolvedTroopSource + " pass=seed");
                }

                // Second pass: fill remaining side capacity up to per-entry caps.
                foreach ((RosterEntryState entryState, BasicCharacterObject troop, int availableCount, string resolvedTroopSource) in materializableEntries)
                {
                    int remainingCapacity = sideCap - (currentSpawnedForSide + spawnedCount);
                    int remainingPulseBudget = maxSpawnCount - spawnedCount;
                    if (remainingCapacity <= 0 || remainingPulseBudget <= 0)
                        break;

                    _materializedBattleResultEntriesByEntryId.TryGetValue(entryState.EntryId ?? string.Empty, out MaterializedBattleResultEntryRuntimeState runtimeState);
                    int alreadySpawnedCount = Math.Max(0, runtimeState?.MaterializedSpawnCount ?? 0);
                    int remainingEntryCapacity = Math.Min(availableCount, GetMaterializedAgentsPerEntryCap(side, entryStates.Count)) - alreadySpawnedCount;
                    if (remainingEntryCapacity <= 0)
                        continue;

                    int extraCount = Math.Min(remainingEntryCapacity, Math.Min(remainingCapacity, remainingPulseBudget));
                    if (extraCount <= 0)
                        continue;

                    spawnedCount += SpawnMaterializedAgentsForEntry(
                        mission,
                        team,
                        side,
                        troop,
                        entryState,
                        extraCount,
                        currentSpawnedForSide + spawnedCount,
                        source + " character=" + resolvedTroopSource + " pass=fill");
                }

                // Final spillover pass: the equal per-entry cap is only a representation
                // preference. Small stacks must not leave the configured side budget empty
                // while another roster entry still has healthy troops available.
                foreach ((RosterEntryState entryState, BasicCharacterObject troop, int availableCount, string resolvedTroopSource) in materializableEntries)
                {
                    int remainingCapacity = sideCap - (currentSpawnedForSide + spawnedCount);
                    int remainingPulseBudget = maxSpawnCount - spawnedCount;
                    if (remainingCapacity <= 0 || remainingPulseBudget <= 0)
                        break;

                    _materializedBattleResultEntriesByEntryId.TryGetValue(entryState.EntryId ?? string.Empty, out MaterializedBattleResultEntryRuntimeState runtimeState);
                    int alreadySpawnedCount = Math.Max(0, runtimeState?.MaterializedSpawnCount ?? 0);
                    int remainingAvailableCount = Math.Max(0, availableCount - alreadySpawnedCount);
                    if (remainingAvailableCount <= 0)
                        continue;

                    int spilloverCount = Math.Min(
                        remainingAvailableCount,
                        Math.Min(remainingCapacity, remainingPulseBudget));
                    if (spilloverCount <= 0)
                        continue;

                    spawnedCount += SpawnMaterializedAgentsForEntry(
                        mission,
                        team,
                        side,
                        troop,
                        entryState,
                        spilloverCount,
                        currentSpawnedForSide + spawnedCount,
                        source + " character=" + resolvedTroopSource + " pass=spillover");
                }

                return spawnedCount;
            }

            IReadOnlyList<string> troopIds = GetGenericMaterializedTroopFallbackIds(side);
            sideCap = GetMaterializedArmyAgentsPerSideCap(side, troopIds.Count);
            foreach (string troopId in troopIds)
            {
                BasicCharacterObject troop = ResolveAllowedCharacter(troopId);
                if (troop == null)
                    continue;

                int remainingCapacity = sideCap - (currentSpawnedForSide + spawnedCount);
                int remainingPulseBudget = maxSpawnCount - spawnedCount;
                if (remainingCapacity <= 0 || remainingPulseBudget <= 0)
                    break;

                int spawnCount = Math.Min(
                    GetFallbackMaterializedAgentsPerTroopCap(side, troopIds.Count),
                    Math.Min(remainingCapacity, remainingPulseBudget));
                spawnedCount += SpawnMaterializedAgentsForEntry(
                    mission,
                    team,
                    side,
                    troop,
                    null,
                    spawnCount,
                    currentSpawnedForSide + spawnedCount,
                    source);
            }

            return spawnedCount;
        }

        private static bool IsSyntheticAllCampaignTroopsRuntime()
        {
            BattleSnapshotMessage snapshot = BattleSnapshotRuntimeState.GetCurrent();
            return string.Equals(snapshot?.BattleId, SyntheticAllCampaignTroopsBattleId, StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsSyntheticLiveHeroesRuntime()
        {
            BattleSnapshotMessage snapshot = BattleSnapshotRuntimeState.GetCurrent();
            return string.Equals(snapshot?.BattleId, SyntheticLiveHeroesBattleId, StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsCoopTestBattleRuntime()
        {
            return CoopTestBattleOptions.IsTestBattleSnapshot(BattleSnapshotRuntimeState.GetCurrent());
        }

        private static bool IsSyntheticRuntime()
        {
            return IsSyntheticAllCampaignTroopsRuntime() || IsSyntheticLiveHeroesRuntime() || IsCoopTestBattleRuntime();
        }

        private static int GetMaterializedArmyAgentsPerSideCap(BattleSideEnum side, int requestedEntryCount)
        {
            if (side == BattleSideEnum.None)
                return MaxMaterializedArmyAgentsPerSide;

            if (IsSyntheticRuntime())
                return Math.Max(MaxMaterializedArmyAgentsPerSide, Math.Max(0, requestedEntryCount));

            int totalBattleBudget = GetConfiguredBattleSizeBudget();
            int attackerAvailable = GetBattleSideAvailableCount(BattleSideEnum.Attacker);
            int defenderAvailable = GetBattleSideAvailableCount(BattleSideEnum.Defender);
            int totalAvailable = attackerAvailable + defenderAvailable;
            int sideAvailable = side == BattleSideEnum.Attacker ? attackerAvailable : defenderAvailable;

            if (totalBattleBudget <= 0 || totalAvailable <= 0 || sideAvailable <= 0)
                return MaxMaterializedArmyAgentsPerSide;

            BattleAgentCapacityPolicy.AllocateInitialTroops(
                defenderAvailable,
                attackerAvailable,
                totalBattleBudget,
                out int defenderCap,
                out int attackerCap);
            int sideCap = side == BattleSideEnum.Attacker ? attackerCap : defenderCap;
            return Math.Max(0, Math.Min(sideAvailable, sideCap));
        }

        private static int GetMaterializedAgentsPerEntryCap(BattleSideEnum side, int requestedEntryCount)
        {
            if (IsSyntheticRuntime())
                return 1;

            if (requestedEntryCount <= 0)
                return MaxMaterializedAgentsPerEntry;

            int sideCap = GetMaterializedArmyAgentsPerSideCap(side, requestedEntryCount);
            if (sideCap <= 0)
                return MaxMaterializedAgentsPerEntry;

            return Math.Max(1, (int)Math.Ceiling((double)sideCap / requestedEntryCount));
        }

        private static int GetFallbackMaterializedAgentsPerTroopCap(BattleSideEnum side, int requestedTroopCount)
        {
            if (IsSyntheticRuntime())
                return 1;

            if (requestedTroopCount <= 0)
                return FallbackMaterializedAgentsPerTroop;

            int sideCap = GetMaterializedArmyAgentsPerSideCap(side, requestedTroopCount);
            if (sideCap <= 0)
                return FallbackMaterializedAgentsPerTroop;

            return Math.Max(1, (int)Math.Ceiling((double)sideCap / requestedTroopCount));
        }

        private static int GetConfiguredBattleSizeBudget()
        {
            int resolvedBudget = BattleAgentCapacityPolicy.GetResolvedBattleSize(
                Mission.Current,
                "CoopMissionSpawnLogic.GetConfiguredBattleSizeBudget");
            if (resolvedBudget > 0)
                return resolvedBudget;

            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            int snapshotBudget = runtimeState?.BattleSizeBudget ?? BattleSnapshotRuntimeState.GetCurrent()?.BattleSizeBudget ?? 0;
            if (snapshotBudget > 0)
                return snapshotBudget;

            return MaxMaterializedArmyAgentsPerSide * 2;
        }

        private static int GetBattleSideAvailableCount(BattleSideEnum side)
        {
            if (side == BattleSideEnum.None)
                return 0;

            IReadOnlyList<RosterEntryState> entryStates = GetAllowedControlEntryStatesSnapshot(side);
            if (entryStates != null && entryStates.Count > 0)
            {
                int entryTotal = entryStates.Sum(entryState => Math.Max(0, (entryState?.Count ?? 0) - (entryState?.WoundedCount ?? 0)));
                if (entryTotal > 0)
                    return entryTotal;
            }

            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            if (runtimeState?.Sides != null)
            {
                BattleSideState sideState = runtimeState.Sides.FirstOrDefault(candidate =>
                    ResolveBattleSideFromState(candidate) == side);
                int fallbackTotal = Math.Max(0, sideState?.TotalManCount ?? 0);
                if (fallbackTotal > 0)
                    return fallbackTotal;
            }

            return 0;
        }

        private static bool TryRepairMaterializedDeploymentPlan(
            Mission mission,
            Team team,
            BattleSideEnum side,
            string source)
        {
            if (mission == null || team == null || side == BattleSideEnum.None)
                return false;

            BattleMapContractDiagnostics.LogDeploymentPlanContract(
                mission,
                team,
                focusFormation: null,
                isReinforcement: false,
                source: (source ?? "unknown") + " pre-repair");

            if (!mission.GetDeploymentPlan<DefaultMissionDeploymentPlan>(out DefaultMissionDeploymentPlan deploymentPlan) || deploymentPlan == null)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: materialized deployment plan repair skipped because DefaultMissionDeploymentPlan is unavailable. " +
                    "TeamSide=" + side +
                    " TeamIndex=" + team.TeamIndex +
                    " Source=" + (source ?? "unknown"));
                return false;
            }

            if (!EnsureMaterializedDeploymentPlanHasTeamPlan(mission, deploymentPlan, team, side, source))
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: materialized deployment plan repair skipped because no team plan is registered for the current mission team. " +
                    "TeamSide=" + side +
                    " TeamIndex=" + team.TeamIndex +
                    " Source=" + (source ?? "unknown"));
                return false;
            }

            Dictionary<FormationClass, (int Foot, int Mounted)> formationCounts =
                BuildMaterializedDeploymentCountsForSide(mission, side, out int plannedAgents, out bool hasMountedUnits);
            if (formationCounts.Count == 0 || plannedAgents <= 0)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: materialized deployment plan repair skipped because no planned troop counts were resolved. " +
                    "TeamSide=" + side +
                    " TeamIndex=" + team.TeamIndex +
                    " Source=" + (source ?? "unknown"));
                return false;
            }

            try
            {
                if (deploymentPlan.IsPlanMade(team))
                {
                    deploymentPlan.ClearAddedTroops(team);
                    deploymentPlan.ClearDeploymentPlan(team);
                }

                if (deploymentPlan.IsReinforcementPlanMade(team))
                {
                    deploymentPlan.ClearAddedTroops(team, isReinforcement: true);
                    deploymentPlan.ClearReinforcementPlan(team);
                }

                deploymentPlan.SetSpawnWithHorses(team, hasMountedUnits);
                foreach (KeyValuePair<FormationClass, (int Foot, int Mounted)> formationCount in formationCounts.OrderBy(pair => (int)pair.Key))
                {
                    if (formationCount.Value.Foot <= 0 && formationCount.Value.Mounted <= 0)
                        continue;

                    deploymentPlan.AddTroops(team, formationCount.Key, formationCount.Value.Foot, formationCount.Value.Mounted);
                    deploymentPlan.AddTroops(team, formationCount.Key, formationCount.Value.Foot, formationCount.Value.Mounted, isReinforcement: true);
                }

                deploymentPlan.MakeDeploymentPlan(team);
                deploymentPlan.MakeReinforcementDeploymentPlan(team);

                bool hasSceneMapPatch = false;
                try
                {
                    hasSceneMapPatch = mission.HasSceneMapPatch();
                }
                catch
                {
                }

                bool initialPlanMade = deploymentPlan.IsPlanMade(team);
                bool reinforcementPlanMade = deploymentPlan.IsReinforcementPlanMade(team);
                BattleMapContractDiagnostics.LogDeploymentPlanContract(
                    mission,
                    team,
                    focusFormation: null,
                    isReinforcement: false,
                    source: (source ?? "unknown") + " post-repair");
                ModLogger.Info(
                    "CoopMissionSpawnLogic: repaired materialized deployment plan. " +
                    "TeamSide=" + side +
                    " TeamIndex=" + team.TeamIndex +
                    " PlannedAgents=" + plannedAgents +
                    " HasMountedUnits=" + hasMountedUnits +
                    " HasSceneMapPatch=" + hasSceneMapPatch +
                    " InitialPlanMade=" + initialPlanMade +
                    " ReinforcementPlanMade=" + reinforcementPlanMade +
                    " FormationCounts=" + BuildMaterializedDeploymentCountSummary(formationCounts) +
                    " Source=" + (source ?? "unknown"));
                return initialPlanMade;
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: materialized deployment plan repair failed. " +
                    "TeamSide=" + side +
                    " TeamIndex=" + team.TeamIndex +
                    " Source=" + (source ?? "unknown") +
                    " Message=" + ex.Message);
                return false;
            }
        }

        private static readonly FieldInfo DefaultMissionDeploymentPlanTeamDeploymentPlansField =
            typeof(DefaultMissionDeploymentPlan).GetField("_teamDeploymentPlans", BindingFlags.Instance | BindingFlags.NonPublic);
        private static readonly Dictionary<string, DateTime> NextMaterializedDeploymentPlanRepairUtcByTeamAndMode =
            new Dictionary<string, DateTime>(StringComparer.Ordinal);
        private static readonly HashSet<string> RepairedMaterializedDeploymentPlanTeamAndModeKeys =
            new HashSet<string>(StringComparer.Ordinal);
        private static Mission _materializedDeploymentPlanRepairMission;
        private static readonly TimeSpan MaterializedDeploymentPlanRepairRetryInterval = TimeSpan.FromMilliseconds(250);

        private static bool EnsureMaterializedDeploymentPlanHasTeamPlan(
            Mission mission,
            DefaultMissionDeploymentPlan deploymentPlan,
            Team team,
            BattleSideEnum side,
            string source)
        {
            if (mission == null || deploymentPlan == null || team == null)
                return false;

            bool hasTeamPlan = TryHasMaterializedDeploymentTeamPlan(deploymentPlan, team, out int registeredPlanCountBefore);
            if (hasTeamPlan)
                return true;

            int missionTeamCount = 0;
            try
            {
                missionTeamCount = mission.Teams?.Count ?? 0;
            }
            catch
            {
            }

            ModLogger.Info(
                "CoopMissionSpawnLogic: refreshing deployment plan team snapshot for materialized spawn repair. " +
                "TeamSide=" + side +
                " TeamIndex=" + team.TeamIndex +
                " MissionTeamCount=" + missionTeamCount +
                " RegisteredPlanCountBefore=" + registeredPlanCountBefore +
                " Source=" + (source ?? "unknown"));

            try
            {
                deploymentPlan.Initialize();
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: deployment plan team snapshot refresh failed. " +
                    "TeamSide=" + side +
                    " TeamIndex=" + team.TeamIndex +
                    " Source=" + (source ?? "unknown") +
                    " Message=" + ex.Message);
                return false;
            }

            bool readyAfterRefresh = TryHasMaterializedDeploymentTeamPlan(deploymentPlan, team, out int registeredPlanCountAfter);
            ModLogger.Info(
                "CoopMissionSpawnLogic: deployment plan team snapshot refresh completed. " +
                "TeamSide=" + side +
                " TeamIndex=" + team.TeamIndex +
                " RegisteredPlanCountAfter=" + registeredPlanCountAfter +
                " Ready=" + readyAfterRefresh +
                " Source=" + (source ?? "unknown"));
            return readyAfterRefresh;
        }

        private static bool TryHasMaterializedDeploymentTeamPlan(
            DefaultMissionDeploymentPlan deploymentPlan,
            Team team,
            out int registeredPlanCount)
        {
            registeredPlanCount = 0;
            if (deploymentPlan == null || team == null || DefaultMissionDeploymentPlanTeamDeploymentPlansField == null)
                return false;

            if (!(DefaultMissionDeploymentPlanTeamDeploymentPlansField.GetValue(deploymentPlan) is IEnumerable entries))
                return false;

            foreach (object entry in entries)
            {
                if (entry == null)
                    continue;

                registeredPlanCount++;
                FieldInfo item1Field = entry.GetType().GetField("Item1", BindingFlags.Instance | BindingFlags.Public);
                if (item1Field == null)
                    continue;

                if (ReferenceEquals(item1Field.GetValue(entry), team))
                    return true;
            }

            return false;
        }

        private static Dictionary<FormationClass, (int Foot, int Mounted)> BuildMaterializedDeploymentCountsForSide(
            Mission mission,
            BattleSideEnum side,
            out int plannedAgents,
            out bool hasMountedUnits)
        {
            var formationCounts = new Dictionary<FormationClass, (int Foot, int Mounted)>();
            plannedAgents = 0;
            hasMountedUnits = false;

            IReadOnlyList<RosterEntryState> entryStates = GetAutomatedMaterializableEntryStatesSnapshot(side);
            int requestedEntryCount = entryStates?.Count ?? 0;
            int sideCap = GetMaterializedArmyAgentsPerSideCap(side, requestedEntryCount);
            if (entryStates != null && entryStates.Count > 0)
            {
                var materializableEntries = new List<(RosterEntryState EntryState, BasicCharacterObject Troop, int AvailableCount)>();
                var plannedByEntryId = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                foreach (RosterEntryState entryState in entryStates)
                {
                    string spawnTemplateId = ResolveEntrySpawnTemplateId(entryState);
                    if (entryState == null || string.IsNullOrWhiteSpace(spawnTemplateId))
                        continue;

                    int availableCount = Math.Max(0, entryState.Count - entryState.WoundedCount);
                    if (availableCount <= 0)
                        continue;

                    BasicCharacterObject troop = ResolveMaterializedArmyCharacter(entryState, spawnTemplateId, out _);
                    if (troop == null)
                        continue;

                    materializableEntries.Add((entryState, troop, availableCount));
                }

                foreach ((RosterEntryState entryState, BasicCharacterObject troop, int availableCount) in materializableEntries)
                {
                    int remainingCapacity = sideCap - plannedAgents;
                    if (remainingCapacity <= 0)
                        break;

                    int seedCount = Math.Min(1, Math.Min(availableCount, remainingCapacity));
                    if (seedCount <= 0)
                        continue;

                    AccumulateMaterializedDeploymentCount(
                        formationCounts,
                        mission,
                        side,
                        troop,
                        entryState,
                        seedCount,
                        ref plannedAgents,
                        ref hasMountedUnits);
                    string entryId = entryState.EntryId ?? string.Empty;
                    plannedByEntryId[entryId] =
                        (plannedByEntryId.TryGetValue(entryId, out int existingSeedCount) ? existingSeedCount : 0) + seedCount;
                }

                foreach ((RosterEntryState entryState, BasicCharacterObject troop, int availableCount) in materializableEntries)
                {
                    int remainingCapacity = sideCap - plannedAgents;
                    if (remainingCapacity <= 0)
                        break;

                    string entryId = entryState.EntryId ?? string.Empty;
                    int alreadyPlannedForEntry = plannedByEntryId.TryGetValue(entryId, out int existingPlannedCount)
                        ? existingPlannedCount
                        : 0;
                    int remainingEntryCapacity =
                        Math.Min(availableCount, GetMaterializedAgentsPerEntryCap(side, entryStates.Count)) -
                        alreadyPlannedForEntry;
                    if (remainingEntryCapacity <= 0)
                        continue;

                    int extraCount = Math.Min(remainingEntryCapacity, remainingCapacity);
                    if (extraCount <= 0)
                        continue;

                    AccumulateMaterializedDeploymentCount(
                        formationCounts,
                        mission,
                        side,
                        troop,
                        entryState,
                        extraCount,
                        ref plannedAgents,
                        ref hasMountedUnits);
                    plannedByEntryId[entryId] = alreadyPlannedForEntry + extraCount;
                }

                foreach ((RosterEntryState entryState, BasicCharacterObject troop, int availableCount) in materializableEntries)
                {
                    int remainingCapacity = sideCap - plannedAgents;
                    if (remainingCapacity <= 0)
                        break;

                    string entryId = entryState.EntryId ?? string.Empty;
                    int alreadyPlannedForEntry = plannedByEntryId.TryGetValue(entryId, out int existingPlannedCount)
                        ? existingPlannedCount
                        : 0;
                    int remainingAvailableCount = Math.Max(0, availableCount - alreadyPlannedForEntry);
                    int spilloverCount = Math.Min(remainingAvailableCount, remainingCapacity);
                    if (spilloverCount <= 0)
                        continue;

                    AccumulateMaterializedDeploymentCount(
                        formationCounts,
                        mission,
                        side,
                        troop,
                        entryState,
                        spilloverCount,
                        ref plannedAgents,
                        ref hasMountedUnits);
                    plannedByEntryId[entryId] = alreadyPlannedForEntry + spilloverCount;
                }

                return formationCounts;
            }

            IReadOnlyList<string> troopIds = GetGenericMaterializedTroopFallbackIds(side);
            sideCap = GetMaterializedArmyAgentsPerSideCap(side, troopIds.Count);
            foreach (string troopId in troopIds)
            {
                BasicCharacterObject troop = ResolveAllowedCharacter(troopId);
                if (troop == null)
                    continue;

                int remainingCapacity = sideCap - plannedAgents;
                if (remainingCapacity <= 0)
                    break;

                int spawnCount = Math.Min(GetFallbackMaterializedAgentsPerTroopCap(side, troopIds.Count), remainingCapacity);
                if (spawnCount <= 0)
                    continue;

                AccumulateMaterializedDeploymentCount(
                    formationCounts,
                    mission,
                    side,
                    troop,
                    entryState: null,
                    spawnCount,
                    ref plannedAgents,
                    ref hasMountedUnits);
            }

            return formationCounts;
        }

        private static void AccumulateMaterializedDeploymentCount(
            Dictionary<FormationClass, (int Foot, int Mounted)> formationCounts,
            Mission mission,
            BattleSideEnum side,
            BasicCharacterObject troop,
            RosterEntryState entryState,
            int count,
            ref int plannedAgents,
            ref bool hasMountedUnits)
        {
            if (formationCounts == null || troop == null || count <= 0)
                return;

            FormationClass formationClass = ResolveSiegeAwareFormationClass(mission, side, troop, entryState);
            if ((int)formationClass < 0 || (int)formationClass >= (int)FormationClass.NumberOfRegularFormations)
                formationClass = FormationClass.Infantry;

            bool forceDismountedSiegeProjection = ShouldUseDismountedSiegeProjection(mission, side);
            bool isMounted =
                !forceDismountedSiegeProjection &&
                (entryState?.IsMounted ?? (formationClass == FormationClass.Cavalry || formationClass == FormationClass.HorseArcher));
            if (!formationCounts.TryGetValue(formationClass, out (int Foot, int Mounted) existingCounts))
                existingCounts = (0, 0);

            existingCounts = isMounted
                ? (existingCounts.Foot, existingCounts.Mounted + count)
                : (existingCounts.Foot + count, existingCounts.Mounted);
            formationCounts[formationClass] = existingCounts;

            plannedAgents += count;
            if (isMounted)
                hasMountedUnits = true;
        }

        private static FormationClass ResolveSiegeAwareFormationClass(
            Mission mission,
            BattleSideEnum side,
            BasicCharacterObject troop)
        {
            return ResolveSiegeAwareFormationClass(mission, side, troop, null, out _);
        }

        private static FormationClass ResolveSiegeAwareFormationClass(
            Mission mission,
            BattleSideEnum side,
            BasicCharacterObject troop,
            RosterEntryState entryState)
        {
            return ResolveSiegeAwareFormationClass(mission, side, troop, entryState, out _);
        }

        private static FormationClass ResolveSiegeAwareFormationClass(
            Mission mission,
            BattleSideEnum side,
            BasicCharacterObject troop,
            RosterEntryState entryState,
            out string formationSource)
        {
            FormationClass formationClass = ResolveCampaignMirrorAllCampaignAiFormationClass(troop, entryState, out formationSource);
            try
            {
                if (troop != null && ShouldUseDismountedSiegeProjection(mission, side))
                    formationClass = mission.GetAgentTroopClass(side, troop);
            }
            catch
            {
            }

            formationClass = formationClass.FallbackClass();
            if (ShouldUseDismountedSiegeProjection(mission, side))
                formationClass = DismountSiegeFormationClass(formationClass);

            int formationIndex = (int)formationClass;
            if (formationIndex < 0 || formationIndex >= (int)FormationClass.NumberOfRegularFormations)
                return FormationClass.Infantry;

            return formationClass;
        }

        private static FormationClass ResolveCampaignMirrorAllCampaignAiFormationClass(
            BasicCharacterObject troop,
            RosterEntryState entryState,
            out string formationSource)
        {
            FormationClass fallbackFormationClass = troop?.DefaultFormationClass ?? FormationClass.Infantry;
            formationSource = "troop-default";
            if (TryParseCampaignFormationClass(entryState?.CampaignFormationClass, out FormationClass snapshotFormationClass))
            {
                formationSource = "snapshot-campaign";
                return snapshotFormationClass;
            }

            if (!IsCampaignMirrorAllCampaignAiRuntime())
                return fallbackFormationClass;

            BasicCharacterObject originalCharacter = TryResolveCampaignMirrorOriginalCharacter(entryState);
            if (originalCharacter != null &&
                IsRegularFormationClass(originalCharacter.DefaultFormationClass))
            {
                formationSource = "original-character";
                return originalCharacter.DefaultFormationClass;
            }

            if (TryDeriveCampaignMirrorAiFormationClassFromEquipment(entryState, out FormationClass derivedFormationClass, out _))
            {
                formationSource = "equipment-derived";
                return derivedFormationClass;
            }

            formationSource = "troop-default-fallback";
            return fallbackFormationClass;
        }

        internal static int ResolveExactCampaignFormationIndex(
            RosterEntryState entryState,
            Mission mission,
            BattleSideEnum side)
        {
            BasicCharacterObject troop = BattleSnapshotRuntimeState.TryResolveCharacterObject(entryState?.EntryId);
            if (troop == null)
                return -1;

            FormationClass formationClass = ResolveSiegeAwareFormationClass(
                mission,
                side,
                troop,
                entryState);
            return IsRegularFormationClass(formationClass)
                ? (int)formationClass
                : -1;
        }

        private static bool TryParseCampaignFormationClass(string value, out FormationClass formationClass)
        {
            formationClass = FormationClass.Infantry;
            if (string.IsNullOrWhiteSpace(value))
                return false;

            if (!Enum.TryParse(value.Trim(), ignoreCase: true, out formationClass))
                return false;

            return IsRegularFormationClass(formationClass);
        }

        private static bool IsRegularFormationClass(FormationClass formationClass)
        {
            int formationIndex = (int)formationClass;
            return formationIndex >= 0 && formationIndex < (int)FormationClass.NumberOfRegularFormations;
        }

        private static BasicCharacterObject TryResolveCampaignMirrorOriginalCharacter(RosterEntryState entryState)
        {
            string originalCharacterId = entryState?.OriginalCharacterId;
            if (string.IsNullOrWhiteSpace(originalCharacterId))
                return null;

            try
            {
                return MBObjectManager.Instance?.GetObject<BasicCharacterObject>(originalCharacterId);
            }
            catch
            {
                return null;
            }
        }

        private sealed class CampaignMirrorAiWeaponRoleSnapshot
        {
            public bool HasHorse { get; set; }
            public bool HasBow { get; set; }
            public bool HasCrossbow { get; set; }
            public bool HasAmmo { get; set; }
            public bool HasThrown { get; set; }
            public bool HasShield { get; set; }
            public bool HasMelee { get; set; }
            public bool HasPolearm { get; set; }
            public string SlotSummary { get; set; }
        }

        private static bool TryDeriveCampaignMirrorAiFormationClassFromEquipment(
            RosterEntryState entryState,
            out FormationClass formationClass,
            out CampaignMirrorAiWeaponRoleSnapshot roleSnapshot)
        {
            roleSnapshot = BuildCampaignMirrorAiWeaponRoleSnapshot(entryState);
            formationClass = FormationClass.Infantry;
            if (entryState == null)
                return false;

            bool hasDedicatedRangedWeapon = roleSnapshot.HasBow || roleSnapshot.HasCrossbow;
            if (roleSnapshot.HasHorse)
            {
                formationClass = hasDedicatedRangedWeapon || roleSnapshot.HasThrown
                    ? FormationClass.HorseArcher
                    : FormationClass.Cavalry;
                return true;
            }

            formationClass = hasDedicatedRangedWeapon || (roleSnapshot.HasThrown && !roleSnapshot.HasMelee)
                ? FormationClass.Ranged
                : FormationClass.Infantry;
            return true;
        }

        private static CampaignMirrorAiWeaponRoleSnapshot BuildCampaignMirrorAiWeaponRoleSnapshot(RosterEntryState entryState)
        {
            var snapshot = new CampaignMirrorAiWeaponRoleSnapshot
            {
                HasHorse = entryState?.IsMounted == true || !string.IsNullOrWhiteSpace(entryState?.CombatHorseId)
            };
            var slotParts = new List<string>();
            AppendCampaignMirrorAiWeaponRole(snapshot, entryState?.CombatItem0Id, "Item0", entryState, slotParts);
            AppendCampaignMirrorAiWeaponRole(snapshot, entryState?.CombatItem1Id, "Item1", entryState, slotParts);
            AppendCampaignMirrorAiWeaponRole(snapshot, entryState?.CombatItem2Id, "Item2", entryState, slotParts);
            AppendCampaignMirrorAiWeaponRole(snapshot, entryState?.CombatItem3Id, "Item3", entryState, slotParts);
            snapshot.SlotSummary = slotParts.Count > 0 ? string.Join(",", slotParts) : "(none)";
            return snapshot;
        }

        private static void AppendCampaignMirrorAiWeaponRole(
            CampaignMirrorAiWeaponRoleSnapshot snapshot,
            string itemId,
            string slotLabel,
            RosterEntryState entryState,
            List<string> slotParts)
        {
            if (snapshot == null || string.IsNullOrWhiteSpace(itemId))
                return;

            string resolvedItemId;
            string resolutionSource;
            ItemObject item = ResolveMaterializedEquipmentItem(
                itemId,
                entryState,
                slotLabel,
                out resolvedItemId,
                out resolutionSource,
                trackCoverage: false);
            if (item == null)
            {
                slotParts?.Add(slotLabel + "=" + itemId + "(unresolved)");
                return;
            }

            ApplyCampaignMirrorAiWeaponRoleToken(snapshot, item.Type.ToString());
            try
            {
                if (item.Weapons != null)
                {
                    foreach (WeaponComponentData weapon in item.Weapons)
                    {
                        ApplyCampaignMirrorAiWeaponRoleToken(snapshot, weapon?.WeaponClass.ToString());
                    }
                }
            }
            catch
            {
            }

            slotParts?.Add(
                slotLabel + "=" + item.StringId +
                (string.Equals(itemId, item.StringId, StringComparison.OrdinalIgnoreCase)
                    ? string.Empty
                    : "(from:" + itemId + ",via:" + (resolutionSource ?? "unknown") + ")"));
        }

        private static void ApplyCampaignMirrorAiWeaponRoleToken(
            CampaignMirrorAiWeaponRoleSnapshot snapshot,
            string token)
        {
            if (snapshot == null || string.IsNullOrWhiteSpace(token))
                return;

            if (token.IndexOf("Crossbow", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                snapshot.HasCrossbow = true;
                return;
            }

            if (token.IndexOf("Bow", StringComparison.OrdinalIgnoreCase) >= 0)
                snapshot.HasBow = true;

            if (token.IndexOf("Arrow", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Bolt", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                snapshot.HasAmmo = true;
            }

            if (token.IndexOf("Throw", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Javelin", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Stone", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Sling", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                snapshot.HasThrown = true;
            }

            if (token.IndexOf("Shield", StringComparison.OrdinalIgnoreCase) >= 0)
                snapshot.HasShield = true;

            if (token.IndexOf("Polearm", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Spear", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Pike", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Lance", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                snapshot.HasPolearm = true;
                snapshot.HasMelee = true;
            }

            if (token.IndexOf("OneHanded", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("TwoHanded", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Sword", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Axe", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Mace", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Dagger", StringComparison.OrdinalIgnoreCase) >= 0 ||
                token.IndexOf("Pick", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                snapshot.HasMelee = true;
            }
        }

        private static string BuildCampaignMirrorAiRoleDiagnostics(
            RosterEntryState entryState,
            BasicCharacterObject troop,
            FormationClass formationClass,
            string formationSource)
        {
            if (!IsCampaignMirrorAllCampaignAiRuntime())
                return string.Empty;

            CampaignMirrorAiWeaponRoleSnapshot roleSnapshot = BuildCampaignMirrorAiWeaponRoleSnapshot(entryState);
            return "CampaignFieldAI={" +
                   "SnapshotFormation=" + (entryState?.CampaignFormationClass ?? "null") +
                   ",TroopDefault=" + (troop?.DefaultFormationClass.ToString() ?? "null") +
                   ",ResolvedFormation=" + formationClass +
                   ",FormationSource=" + (formationSource ?? "unknown") +
                   ",Mounted=" + roleSnapshot.HasHorse +
                   ",Bow=" + roleSnapshot.HasBow +
                   ",Crossbow=" + roleSnapshot.HasCrossbow +
                   ",Ammo=" + roleSnapshot.HasAmmo +
                   ",Thrown=" + roleSnapshot.HasThrown +
                   ",Shield=" + roleSnapshot.HasShield +
                   ",Melee=" + roleSnapshot.HasMelee +
                   ",Polearm=" + roleSnapshot.HasPolearm +
                   ",Slots=" + (roleSnapshot.SlotSummary ?? "(none)") +
                   "}";
        }

        private static FormationClass DismountSiegeFormationClass(FormationClass formationClass)
        {
            if (formationClass == FormationClass.Cavalry)
                return FormationClass.Infantry;

            if (formationClass == FormationClass.HorseArcher)
                return FormationClass.Ranged;

            return formationClass;
        }

        public static bool ShouldUseDismountedSiegeProjection(Mission mission, BattleSideEnum side)
        {
            if (mission == null || side == BattleSideEnum.None)
                return false;

            if (ShouldUseFieldMaterializedSiegeReplayRuntime(mission))
                return true;

            BattleScenarioContextMessage scenarioContext =
                BattleSnapshotRuntimeState.GetScenarioContext() ??
                BattleSnapshotRuntimeState.GetCurrent()?.ScenarioContext ??
                BattleSnapshotRuntimeState.GetState()?.ScenarioContext;
            bool isSiegeAssaultScenario =
                ExactCampaignSiegeAssaultWithDeploymentRuntime.IsSiegeAssaultScenario(scenarioContext);
            bool isActiveSiegeDeployment =
                ExactCampaignArmyBootstrap.IsSiegeAssaultWithDeploymentActive(mission);
            bool isMissionSiegeBattle = false;
            try
            {
                isMissionSiegeBattle = mission.IsSiegeBattle;
            }
            catch
            {
                isMissionSiegeBattle = true;
            }

            if (!isSiegeAssaultScenario &&
                !isActiveSiegeDeployment &&
                !isMissionSiegeBattle)
            {
                return false;
            }

            if (ExactCampaignArmyBootstrap.TryGetSpawnHorses(mission, side, out bool spawnHorses))
                return !spawnHorses;

            return isMissionSiegeBattle;
        }

        public static bool ShouldClearDismountedSiegeSynchronizeAgentMountVisuals(
            Mission mission,
            Agent agent,
            Equipment spawnEquipment)
        {
            if (mission == null ||
                agent == null ||
                spawnEquipment == null ||
                agent.IsMount ||
                !agent.IsActive() ||
                agent.Team == null ||
                agent.Team.Side == BattleSideEnum.None ||
                agent.MountAgent != null ||
                agent.MissionPeer != null ||
                agent.Character?.IsHero == true)
            {
                return false;
            }

            if (!ShouldUseDismountedSiegeProjection(mission, agent.Team.Side))
                return false;

            return spawnEquipment[EquipmentIndex.Horse].Item != null ||
                   spawnEquipment[EquipmentIndex.HorseHarness].Item != null;
        }

        private static bool ShouldIncludeMaterializedSpawnMountVisuals(
            Mission mission,
            Team team,
            BasicCharacterObject troop,
            RosterEntryState entryState)
        {
            BattleSideEnum side = team?.Side ?? BattleSideEnum.None;
            if (ShouldUseDismountedSiegeProjection(mission, side))
                return false;

            if (entryState != null)
                return ExactSiegeMaterializationModule.ShouldIncludeMountVisuals(mission, side, entryState);

            try
            {
                return troop?.HasMount() == true;
            }
            catch
            {
                return false;
            }
        }

        private static void ClearMaterializedSpawnMountVisualSlots(Equipment spawnEquipment)
        {
            if (spawnEquipment == null)
                return;

            spawnEquipment[EquipmentIndex.Horse] = default(EquipmentElement);
            spawnEquipment[EquipmentIndex.HorseHarness] = default(EquipmentElement);
        }

        private static Equipment BuildFieldMaterializedSiegeSpawnEquipment(
            BasicCharacterObject troop,
            RosterEntryState entryState,
            bool includeMountVisuals,
            out string appliedEquipment)
        {
            appliedEquipment = "(none)";
            Equipment spawnEquipment = troop?.Equipment?.Clone(false) ?? new Equipment();
            if (entryState == null)
                return spawnEquipment;

            appliedEquipment = TryApplyDismountedMaterializedEquipmentOverrides(
                spawnEquipment,
                entryState,
                null,
                trackCoverage: true,
                includeMountVisuals: includeMountVisuals);
            return spawnEquipment;
        }

        private static string BuildMaterializedDeploymentCountSummary(
            Dictionary<FormationClass, (int Foot, int Mounted)> formationCounts)
        {
            if (formationCounts == null || formationCounts.Count == 0)
                return "(none)";

            return string.Join(
                ",",
                formationCounts
                    .OrderBy(pair => (int)pair.Key)
                    .Select(pair => pair.Key + "(F=" + pair.Value.Foot + ",M=" + pair.Value.Mounted + ")"));
        }

        private static BasicCharacterObject ResolveMaterializedArmyCharacter(
            RosterEntryState entryState,
            string spawnTemplateId,
            out string resolvedTroopSource)
        {
            resolvedTroopSource = "spawn-template";
            if (entryState == null)
                return null;

            ExactEntryCompatibilityDiagnostic entryDiagnostic = GetExactEntryCompatibilityDiagnostic(entryState);
            if (entryDiagnostic != null)
            {
                resolvedTroopSource = entryDiagnostic.CharacterResolutionSource ?? resolvedTroopSource;
                if (!IsMaterializedExactEntryCharacterSupported(entryDiagnostic))
                {
                    string rejectionReason = BuildMaterializedExactEntryContractRejectionReason(entryDiagnostic);
                    LogExactEntryCompatibilityDiagnostic(entryDiagnostic, "materialized-character-skip");
                    TraceMaterializedEntryContractDecision(
                        "materialized-character-skip",
                        entryState,
                        spawnTemplateId,
                        entryDiagnostic,
                        rejectionReason,
                        "ResolveMaterializedArmyCharacter");
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: skipped materialized entry because exact character contract is not admissible for hosted MP materialization. " +
                        "EntryId=" + (entryState.EntryId ?? "null") +
                        " Status=" + (entryDiagnostic.Status ?? "unknown") +
                        " Reason=" + rejectionReason +
                        " CharacterSource=" + (entryDiagnostic.CharacterResolutionSource ?? "unknown") +
                        " CharacterId=" + (entryDiagnostic.ResolvedCharacter?.StringId ?? "null") +
                        " SpawnTemplateId=" + (spawnTemplateId ?? "null"));
                    return null;
                }

                LogExactEntryCompatibilityDiagnostic(entryDiagnostic, "materialized-character");
                return entryDiagnostic.ResolvedCharacter;
            }

            BasicCharacterObject templateCharacter = BattleSnapshotRuntimeState.TryResolveCharacterObject(entryState.EntryId);
            if (templateCharacter == null)
                return null;

            resolvedTroopSource = "snapshot-runtime";
            return templateCharacter;
        }

        private static int SpawnMaterializedAgentsForEntry(
            Mission mission,
            Team team,
            BattleSideEnum side,
            BasicCharacterObject troop,
            RosterEntryState entryState,
            int spawnCount,
            int sideOffset,
            string source,
            bool isReinforcement = false,
            MaterializedSiegeReinforcementWaveState reinforcementWaveState = null)
        {
            if (mission == null || team == null || troop == null || spawnCount <= 0)
                return 0;

            string entryId = entryState?.EntryId;

            FormationClass formationClass = ResolveSiegeAwareFormationClass(
                mission,
                side,
                troop,
                entryState,
                out string formationSource);
            ResolveMaterializedArmySpawnFrame(
                mission,
                team,
                side,
                troop,
                formationClass,
                isReinforcement,
                out Vec3 formationSpawnPosition,
                out Vec2 formationDirection,
                out string spawnFrameSource,
                out float formationPlannedWidth,
                out float formationPlannedDepth,
                out int formationPlannedTroopCount);
            if (isReinforcement)
            {
                ExactSiegeMoraleDiagnostics.RecordReinforcementSpawnFrame(
                    mission,
                    team,
                    formationClass,
                    formationSpawnPosition,
                    spawnFrameSource,
                    source);
            }

            if (formationDirection.LengthSquared < 0.001f)
                formationDirection = side == BattleSideEnum.Attacker ? new Vec2(1f, 0f) : new Vec2(-1f, 0f);

            formationDirection.Normalize();
            Vec3 forward = new Vec3(formationDirection.x, formationDirection.y, 0f);
            Vec3 right = new Vec3(-formationDirection.y, formationDirection.x, 0f);
            Vec3 basePosition = formationSpawnPosition;
            Formation targetFormation = team.GetFormation(formationClass);
            bool useNativeFormationSpawn =
                !isReinforcement &&
                targetFormation != null &&
                formationPlannedTroopCount > 0 &&
                string.Equals(spawnFrameSource, "formation-repaired", StringComparison.Ordinal);

            bool materializationDiagnosticsEnabled =
                ExperimentalFeatures.EnableExactCampaignArmyRuntimeDiagnostics ||
                ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics;
            string exactEntryCompatibilitySummary = string.Empty;
            string equipmentOverrideDiagnostics = string.Empty;
            string combatProfileDiagnostics = "AppliedCombatProfile=(none)";
            string identityDiagnostics = "AppliedIdentity=(none)";
            string campaignAiDiagnostics = string.Empty;
            int spawnedCount = 0;
            if (materializationDiagnosticsEnabled)
            {
                ExactEntryCompatibilityDiagnostic exactEntryCompatibility = GetExactEntryCompatibilityDiagnostic(entryState);
                exactEntryCompatibilitySummary = BuildExactEntryCompatibilityShortSummary(exactEntryCompatibility);
                equipmentOverrideDiagnostics = BuildMaterializedEquipmentOverrideDiagnostics(entryState, troop);
                campaignAiDiagnostics = BuildCampaignMirrorAiRoleDiagnostics(
                    entryState,
                    troop,
                    formationClass,
                    formationSource);
                ModLogger.Info(
                    "CoopMissionSpawnLogic: materialized battlefield entry spawn begin. " +
                    "Side=" + side +
                    " TroopId=" + troop.StringId +
                    " EntryId=" + (entryId ?? "null") +
                    " RequestedCount=" + spawnCount +
                    " Reinforcement=" + isReinforcement +
                    " FormationClass=" + formationClass +
                    " " + campaignAiDiagnostics +
                    " SpawnFrameSource=" + spawnFrameSource +
                    " " + exactEntryCompatibilitySummary +
                    " Source=" + (source ?? "unknown"));
            }
            for (int i = 0; i < spawnCount; i++)
            {
                bool fallbackMounted =
                    entryState?.IsMounted == true ||
                    formationClass == FormationClass.Cavalry ||
                    formationClass == FormationClass.HorseArcher;
                int requiredPhysicalAgentCount = BattleAgentCapacityPolicy.GetExpectedTroopPhysicalCost(
                    mission,
                    side,
                    entryState,
                    fallbackMounted);
                if (!BattleAgentCapacityPolicy.CanSpawnPhysicalAgents(
                        mission,
                        requiredPhysicalAgentCount,
                        (source ?? "unknown") + " materialized-entry"))
                {
                    break;
                }

                int absoluteIndex = sideOffset + spawnedCount;
                bool useSiegeReinforcementSpread =
                    isReinforcement &&
                    ShouldUseMaterializedSiegeReinforcements(mission);
                int placementCount = useSiegeReinforcementSpread
                    ? Math.Max(spawnCount + Math.Max(0, sideOffset), spawnCount)
                    : 0;
                int columnCount = useSiegeReinforcementSpread
                    ? GetMaterializedSiegeReinforcementColumnCount(formationPlannedWidth, placementCount)
                    : 4;
                int column = absoluteIndex % columnCount;
                int row = absoluteIndex / columnCount;
                float lateralSpacing = useSiegeReinforcementSpread
                    ? MaterializedSiegeReinforcementLateralSpacing
                    : 1.8f;
                float depthSpacing = useSiegeReinforcementSpread
                    ? GetMaterializedSiegeReinforcementDepthSpacing(formationPlannedDepth)
                    : 2.2f;
                float lateralOffset = (column - ((columnCount - 1) * 0.5f)) * lateralSpacing;
                float depthOffset = row * depthSpacing * (side == BattleSideEnum.Attacker ? -1f : 1f);
                Vec3 spawnPosition = basePosition + right * lateralOffset + forward * depthOffset;
                int formationTroopSpawnIndex = targetFormation?.CountOfUnits ?? absoluteIndex;
                int formationTroopSpawnCount = Math.Max(
                    formationPlannedTroopCount,
                    formationTroopSpawnIndex + 1);

                string appliedArmorOverrides;
                string appliedCombatProfile;
                string appliedIdentity;
                Agent agent = SpawnBattlefieldArmyAgent(
                    mission,
                    team,
                    troop,
                    entryState,
                    formationClass,
                    targetFormation,
                    formationTroopSpawnCount,
                    formationTroopSpawnIndex,
                    useNativeFormationSpawn,
                    isReinforcement,
                    spawnPosition,
                    formationDirection,
                    out appliedArmorOverrides,
                    out appliedCombatProfile,
                    out appliedIdentity);
                if (agent == null)
                    continue;

                _materializedArmyEntryIdByAgentIndex[agent.Index] = entryId ?? string.Empty;
                _materializedArmySideByAgentIndex[agent.Index] = side;
                RegisterMaterializedBattleResultEntry(agent, entryState, side);
                if (reinforcementWaveState != null)
                {
                    HoldMaterializedSiegeReinforcementAgent(
                        mission,
                        reinforcementWaveState,
                        agent,
                        entryId,
                        source);
                }
                combatProfileDiagnostics = appliedCombatProfile;
                identityDiagnostics = appliedIdentity;
                spawnedCount++;
            }

            if (materializationDiagnosticsEnabled && spawnedCount > 0)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: materialized battlefield entry. " +
                    "Side=" + side +
                    " TroopId=" + troop.StringId +
                    " EntryId=" + (entryId ?? "null") +
                    " Spawned=" + spawnedCount +
                    " Reinforcement=" + isReinforcement +
                    " SpawnFrameSource=" + spawnFrameSource +
                    " " + exactEntryCompatibilitySummary +
                    " " + equipmentOverrideDiagnostics +
                    " " + identityDiagnostics +
                    " " + combatProfileDiagnostics +
                    " Source=" + (source ?? "unknown"));
            }

            return spawnedCount;
        }

        private static int GetMaterializedSiegeReinforcementColumnCount(float plannedWidth, int placementCount)
        {
            int safePlacementCount = Math.Max(1, placementCount);
            int plannedColumns = plannedWidth > MaterializedSiegeReinforcementLateralSpacing
                ? (int)Math.Floor(plannedWidth / MaterializedSiegeReinforcementLateralSpacing)
                : MaterializedSiegeReinforcementFallbackColumns;

            plannedColumns = Math.Max(1, plannedColumns);
            return Math.Max(1, Math.Min(safePlacementCount, plannedColumns));
        }

        private static float GetMaterializedSiegeReinforcementDepthSpacing(float plannedDepth)
        {
            if (plannedDepth <= 0f)
                return MaterializedSiegeReinforcementDepthSpacing;

            return Math.Max(
                1.25f,
                Math.Min(MaterializedSiegeReinforcementDepthSpacing, plannedDepth / 4f));
        }

        private static void ResolveMaterializedArmySpawnFrame(
            Mission mission,
            Team team,
            BattleSideEnum side,
            BasicCharacterObject troop,
            FormationClass formationClass,
            bool isReinforcement,
            out Vec3 spawnPosition,
            out Vec2 spawnDirection,
            out string spawnFrameSource,
            out float plannedWidth,
            out float plannedDepth,
            out int plannedTroopCount)
        {
            spawnPosition = new Vec3(0f, 0f, 0f);
            spawnDirection = side == BattleSideEnum.Attacker ? new Vec2(1f, 0f) : new Vec2(-1f, 0f);
            spawnFrameSource = "direct-fallback";
            plannedWidth = 0f;
            plannedDepth = 0f;
            plannedTroopCount = 0;

            bool useMaterializedSiegeReinforcements =
                isReinforcement &&
                ShouldUseMaterializedSiegeReinforcements(mission);
            if (!ReferenceEquals(_materializedDeploymentPlanRepairMission, mission))
            {
                _materializedDeploymentPlanRepairMission = mission;
                NextMaterializedDeploymentPlanRepairUtcByTeamAndMode.Clear();
                RepairedMaterializedDeploymentPlanTeamAndModeKeys.Clear();
            }

            string repairKey = team.TeamIndex + "|" + side + "|" + isReinforcement;
            bool canReuseExistingPlan =
                useMaterializedSiegeReinforcements ||
                RepairedMaterializedDeploymentPlanTeamAndModeKeys.Contains(repairKey);
            if (canReuseExistingPlan &&
                TryResolveRepairedMaterializedSpawnFrame(
                    mission,
                    team,
                    formationClass,
                    isReinforcement,
                    out spawnPosition,
                    out spawnDirection,
                    out _,
                    out plannedWidth,
                    out plannedDepth,
                    out plannedTroopCount))
            {
                spawnFrameSource = useMaterializedSiegeReinforcements
                    ? "siege-reinforcement-plan"
                    : (isReinforcement ? "formation-reinforcement-repaired" : "formation-repaired");
                return;
            }

            string repairSource = (isReinforcement ? "reinforcement" : "initial") + "-formation-frame-repair:" + troop.StringId;
            DateTime nowUtc = DateTime.UtcNow;
            bool canAttemptRepair =
                !NextMaterializedDeploymentPlanRepairUtcByTeamAndMode.TryGetValue(repairKey, out DateTime nextRepairUtc) ||
                nowUtc >= nextRepairUtc;
            if (canAttemptRepair)
            {
                NextMaterializedDeploymentPlanRepairUtcByTeamAndMode[repairKey] =
                    nowUtc + MaterializedDeploymentPlanRepairRetryInterval;
                if (TryRepairMaterializedDeploymentPlan(mission, team, side, repairSource))
                {
                    RepairedMaterializedDeploymentPlanTeamAndModeKeys.Add(team.TeamIndex + "|" + side + "|False");
                    RepairedMaterializedDeploymentPlanTeamAndModeKeys.Add(team.TeamIndex + "|" + side + "|True");
                    if (TryResolveRepairedMaterializedSpawnFrame(
                        mission,
                        team,
                        formationClass,
                        isReinforcement,
                        out spawnPosition,
                        out spawnDirection,
                        out string repairedSpawnDiagnostics,
                        out plannedWidth,
                        out plannedDepth,
                        out plannedTroopCount))
                    {
                        spawnFrameSource = isReinforcement ? "formation-reinforcement-repaired" : "formation-repaired";
                        return;
                    }

                    ModLogger.Info(
                        "CoopMissionSpawnLogic: repaired deployment plan did not yield a safe materialized spawn frame for " +
                        troop.StringId +
                        ": " + (repairedSpawnDiagnostics ?? "unknown"));
                }
            }

            if (useMaterializedSiegeReinforcements)
            {
                GetDirectSpawnFrame(mission, team, out Vec3 siegeFallbackSpawnPosition, out Vec2 siegeFallbackSpawnDirection);
                spawnPosition = siegeFallbackSpawnPosition;
                if (siegeFallbackSpawnDirection.LengthSquared > 0.001f)
                    spawnDirection = siegeFallbackSpawnDirection;
                spawnFrameSource = "siege-direct-fallback";
                return;
            }

            try
            {
                var spawnFrameBehavior = new FFASpawnFrameBehavior();
                spawnFrameBehavior.Initialize();
                bool hasMount = formationClass == FormationClass.Cavalry || formationClass == FormationClass.HorseArcher;
                MatrixFrame spawnFrame = spawnFrameBehavior.GetSpawnFrame(team, hasMount: hasMount, isInitialSpawn: !isReinforcement);
                if (spawnFrame.origin != Vec3.Zero)
                {
                    spawnPosition = spawnFrame.origin;
                    Vec2 frameDirection = spawnFrame.rotation.f.AsVec2;
                    if (frameDirection.LengthSquared > 0.001f)
                    {
                        spawnDirection = frameDirection.Normalized();
                    }

                    spawnFrameSource = isReinforcement ? "ffa-scene-reinforcement" : "ffa-scene";
                    return;
                }
            }
            catch (Exception ex)
            {
                ModLogger.Info("CoopMissionSpawnLogic: FFASpawnFrameBehavior materialized spawn fallback failed for " + troop.StringId + ": " + ex.Message);
            }

            GetDirectSpawnFrame(mission, team, out Vec3 fallbackSpawnPosition, out Vec2 fallbackSpawnDirection);
            spawnPosition = fallbackSpawnPosition;
            if (fallbackSpawnDirection.LengthSquared > 0.001f)
                spawnDirection = fallbackSpawnDirection;
        }

        private static bool TryResolveRepairedMaterializedSpawnFrame(
            Mission mission,
            Team team,
            FormationClass formationClass,
            bool isReinforcement,
            out Vec3 spawnPosition,
            out Vec2 spawnDirection,
            out string diagnostics,
            out float plannedWidth,
            out float plannedDepth,
            out int plannedTroopCount)
        {
            spawnPosition = new Vec3(0f, 0f, 0f);
            spawnDirection = Vec2.Invalid;
            diagnostics = null;
            plannedWidth = 0f;
            plannedDepth = 0f;
            plannedTroopCount = 0;

            if (mission == null || team == null)
            {
                diagnostics = "mission-or-team-missing";
                return false;
            }

            if (!mission.GetDeploymentPlan<DefaultMissionDeploymentPlan>(out DefaultMissionDeploymentPlan deploymentPlan) || deploymentPlan == null)
            {
                diagnostics = "deployment-plan-missing";
                return false;
            }

            IFormationDeploymentPlan formationPlan;
            try
            {
                formationPlan = deploymentPlan.GetFormationPlan(team, formationClass, isReinforcement);
            }
            catch (Exception ex)
            {
                diagnostics = "get-formation-plan-failed:" + ex.Message;
                return false;
            }

            if (formationPlan == null)
            {
                diagnostics = "formation-plan-null";
                return false;
            }

            bool hasFrame;
            try
            {
                hasFrame = formationPlan.HasFrame();
            }
            catch (Exception ex)
            {
                diagnostics = "has-frame-failed:" + ex.Message;
                return false;
            }

            if (!hasFrame)
            {
                BattleMapContractDiagnostics.LogDeploymentPlanContract(
                    mission,
                    team,
                    formationClass,
                    isReinforcement,
                    "repaired-frame-missing");
                diagnostics =
                    "formation-plan-has-no-frame" +
                    " PlannedTroopCount=" + formationPlan.PlannedTroopCount +
                    " HasDimensions=" + formationPlan.HasDimensions;
                return false;
            }

            try
            {
                MatrixFrame frame = formationPlan.GetFrame();
                BattleMapContractDiagnostics.LogDeploymentPlanContract(
                    mission,
                    team,
                    formationClass,
                    isReinforcement,
                    "repaired-frame-success");
                spawnPosition = frame.origin;
                if (formationPlan.HasDimensions)
                {
                    plannedWidth = Math.Max(0f, formationPlan.PlannedWidth);
                    plannedDepth = Math.Max(0f, formationPlan.PlannedDepth);
                }
                plannedTroopCount = Math.Max(0, formationPlan.PlannedTroopCount);

                Vec2 direction = formationPlan.GetDirection();
                if (direction.LengthSquared <= 0.001f)
                    direction = frame.rotation.f.AsVec2;

                spawnDirection = direction.LengthSquared > 0.001f
                    ? direction.Normalized()
                    : (team.Side == BattleSideEnum.Attacker ? new Vec2(1f, 0f) : new Vec2(-1f, 0f));

                diagnostics =
                    "frame-ok" +
                    " PlannedTroopCount=" + formationPlan.PlannedTroopCount +
                    " HasDimensions=" + formationPlan.HasDimensions;
                return true;
            }
            catch (Exception ex)
            {
                diagnostics = "extract-frame-failed:" + ex.Message;
                return false;
            }
        }

        private static Agent SpawnBattlefieldArmyAgent(
            Mission mission,
            Team team,
            BasicCharacterObject troop,
            RosterEntryState entryState,
            FormationClass formationClass,
            Formation targetFormation,
            int formationTroopSpawnCount,
            int formationTroopSpawnIndex,
            bool useNativeFormationSpawn,
            bool isReinforcement,
            Vec3 spawnPosition,
            Vec2 direction,
            out string appliedArmorOverrides,
            out string appliedCombatProfile,
            out string appliedIdentity)
        {
            appliedArmorOverrides = "(none)";
            appliedCombatProfile = "AppliedCombatProfile=(none)";
            appliedIdentity = "AppliedIdentity=(none)";
            if (mission == null || team == null || troop == null)
                return null;

            try
            {
                IAgentOriginBase origin = BuildMaterializedAgentOriginForCreateTimePath(
                    mission,
                    troop,
                    entryState,
                    team.Side,
                    team);
                AgentBuildData buildData = new AgentBuildData(troop);
                bool forceDismountedSiegeProjection = ShouldUseDismountedSiegeProjection(mission, team.Side);
                bool includeMountVisuals = ShouldIncludeMaterializedSpawnMountVisuals(
                    mission,
                    team,
                    troop,
                    entryState);
                bool useFieldMaterializedSiegeRuntime = ShouldUseFieldMaterializedSiegeReplayRuntime(mission);
                bool useCampaignMirrorEquipment = IsCampaignMirrorAllRuntime() && entryState != null;
                Equipment spawnEquipment;
                string spawnEquipmentSource;
                if (useCampaignMirrorEquipment)
                {
                    Banner mirrorBanner = ResolveMaterializedCreateTimeBanner(team, team.Side);
                    bool useCampaignMirrorHeroesCraftedCreateTime =
                        CoopTestBattleOptions.IsCampaignMirrorHeroesCraftedWeaponsCreateTimeSnapshot(
                            BattleSnapshotRuntimeState.GetCurrent());
                    CoopCampaignMirrorCraftedWeaponPolicy craftedWeaponPolicy =
                        IsCampaignMirrorHeroesRuntime() && !useCampaignMirrorHeroesCraftedCreateTime
                            ? CoopCampaignMirrorCraftedWeaponPolicy.StripCreateTimeWeapons
                            : CoopCampaignMirrorCraftedWeaponPolicy.UseMirrors;
                    if (!CoopCampaignMirrorEquipmentResolver.TryBuild(
                            entryState,
                            mirrorBanner,
                            "SpawnBattlefieldArmyAgent",
                            out CoopCampaignMirrorEquipmentResult mirrorEquipment,
                            out string mirrorFailure,
                            includeWeapons: true,
                            includeArmorVisuals: true,
                            includeCape: true,
                            includeMountVisuals: includeMountVisuals,
                            craftedWeaponPolicy: craftedWeaponPolicy))
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: campaign mirror materialization skipped entry because mirror equipment failed. " +
                            "EntryId=" + (entryState.EntryId ?? "null") +
                            " TroopId=" + troop.StringId +
                            " Failure=" + (mirrorFailure ?? "unknown"));
                        return null;
                    }

                    spawnEquipment = mirrorEquipment.SpawnEquipment;
                    spawnEquipmentSource = "campaign-mirror";
                    if (useCampaignMirrorHeroesCraftedCreateTime)
                        spawnEquipmentSource += "+crafted-create-time";
                    if (mirrorEquipment.HasDeferredCraftedWeapons)
                    {
                        spawnEquipmentSource += "+crafted-create-time-stripped";
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: deferred campaign mirror crafted weapons from create-time equipment. " +
                            "EntryId=" + (entryState.EntryId ?? "null") +
                            " TroopId=" + troop.StringId +
                            " Deferred=[" + (mirrorEquipment.DeferredCraftedWeaponSummary ?? "(none)") + "]");
                    }

                    appliedArmorOverrides = "MirrorEquipment={" + (mirrorEquipment.Summary ?? "(none)") + "}";
                }
                else if (useFieldMaterializedSiegeRuntime)
                {
                    spawnEquipment = BuildFieldMaterializedSiegeSpawnEquipment(
                        troop,
                        entryState,
                        includeMountVisuals,
                        out appliedArmorOverrides);
                    spawnEquipmentSource = "field-materialized-siege";
                }
                else
                {
                    Equipment snapshotEquipment =
                        ExactSiegeMaterializationModule.TryBuildSiegeSpawnEquipment(mission, team, entryState) ??
                        BuildSnapshotEquipmentForExactRuntime(entryState, includeMountVisuals: includeMountVisuals);
                    spawnEquipment = snapshotEquipment ?? troop.Equipment?.Clone(false);
                    spawnEquipmentSource = snapshotEquipment != null ? "exact-snapshot" : "troop-clone";
                    appliedArmorOverrides = TryApplyMaterializedEquipmentOverrides(
                        spawnEquipment,
                        entryState,
                        null,
                        trackCoverage: true,
                        includeMountVisuals: includeMountVisuals);
                }

                if (forceDismountedSiegeProjection)
                    ClearMaterializedSpawnMountVisualSlots(spawnEquipment);
                TextObject originalTroopName = null;
                bool hasTemporaryNameOverride =
                    TryApplyEntryNameToSpawnCharacter(troop, entryState, out originalTroopName);
                try
                {
                    buildData.Team(team);
                    ApplyResolvedArmyClothingColors(buildData, team);
                    buildData.Controller(AgentControllerType.AI);
                    buildData.TroopOrigin(origin);
                    buildData.IsReinforcement(isReinforcement);
                    if (useNativeFormationSpawn &&
                        targetFormation != null &&
                        formationTroopSpawnCount > 0 &&
                        formationTroopSpawnIndex >= 0)
                    {
                        buildData.Formation(targetFormation);
                        buildData.FormationTroopSpawnCount(formationTroopSpawnCount);
                        buildData.FormationTroopSpawnIndex(formationTroopSpawnIndex);
                    }
                    else
                    {
                        buildData.InitialPosition(in spawnPosition);
                        buildData.InitialDirection(in direction);
                        buildData.SpawnsIntoOwnFormation(true);
                    }
                    buildData.SpawnsUsingOwnTroopClass(true);
                    if (spawnEquipment != null)
                        buildData.Equipment(spawnEquipment);
                    string createTimeBannerState = TryApplyMaterializedCreateTimeBannerOnly(
                        buildData,
                        mission,
                        team,
                        entryState);
                    if (!string.IsNullOrWhiteSpace(createTimeBannerState))
                        spawnEquipmentSource += "+" + createTimeBannerState;
                    string createTimeMissionEquipmentState = TryApplyMaterializedCreateTimeMissionEquipment(
                        buildData,
                        mission,
                        spawnEquipment,
                        team,
                        entryState);
                    if (!string.IsNullOrWhiteSpace(createTimeMissionEquipmentState))
                        spawnEquipmentSource += "+" + createTimeMissionEquipmentState;

                    appliedIdentity = TryApplyEntryIdentityToBuildData(buildData, entryState);
                    Agent agent = mission.SpawnAgent(buildData, spawnFromAgentVisuals: false);
                    if (agent != null)
                    {
                        TryApplyEntryIdentityToAgent(agent, entryState);

                        FormationClass resolvedFormationClass = formationClass;
                        if ((int)resolvedFormationClass < 0 || (int)resolvedFormationClass >= team.FormationsIncludingSpecialAndEmpty.Count())
                            resolvedFormationClass = FormationClass.Infantry;

                        Formation resolvedTargetFormation = targetFormation ?? team.GetFormation(resolvedFormationClass);
                        if (resolvedTargetFormation != null && !ReferenceEquals(agent.Formation, resolvedTargetFormation))
                        {
                            agent.Formation = resolvedTargetFormation;
                            agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: false, arrangementChangeAllowed: false);
                        }

                        agent.SetAutomaticTargetSelection(true);
                        agent.SetWatchState(Agent.WatchState.Alarmed);
                        agent.SetFiringOrder(FiringOrder.RangedWeaponUsageOrderEnum.FireAtWill);
                        appliedCombatProfile = TryApplyMaterializedCombatProfile(agent, entryState);
                        string roleMatrixInitialWield =
                            TryApplyRoleMatrixStreamInitialWield(agent, entryState, "SpawnBattlefieldArmyAgent");
                        TraceMaterializedBattlefieldAgentSpawn(
                            agent,
                            team,
                            troop,
                            entryState,
                            formationClass,
                            useNativeFormationSpawn ? agent.Position : spawnPosition,
                            direction,
                            spawnEquipment,
                            spawnEquipmentSource,
                            appliedArmorOverrides,
                            appliedCombatProfile,
                            appliedIdentity,
                            roleMatrixInitialWield,
                            "SpawnBattlefieldArmyAgent");
                    }
                    else
                    {
                        TraceMaterializedEntryContractDecision(
                            "materialized-spawn-null",
                            entryState,
                            entryState?.SpawnTemplateId,
                            GetExactEntryCompatibilityDiagnostic(entryState),
                            "Mission.SpawnAgent returned null",
                            "SpawnBattlefieldArmyAgent");
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: SpawnBattlefieldArmyAgent returned null. " +
                            "TroopId=" + troop.StringId +
                            " TeamSide=" + team.Side +
                            " TeamIndex=" + team.TeamIndex);
                    }

                    return agent;
                }
                finally
                {
                    RestoreSpawnCharacterName(troop, hasTemporaryNameOverride, originalTroopName);
                }
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: SpawnBattlefieldArmyAgent failed. " +
                    "TroopId=" + (troop?.StringId ?? "null") +
                    " EntryId=" + (entryState?.EntryId ?? "null") +
                    " TeamSide=" + team?.Side +
                    " TeamIndex=" + (team != null ? team.TeamIndex.ToString() : "null") +
                    " FormationClass=" + formationClass +
                    " SpawnPosition=" + spawnPosition +
                    " Direction=" + direction +
                    " Message=" + ex.Message);
                return null;
            }
        }

        private static void ApplyResolvedArmyClothingColors(AgentBuildData buildData, Team team)
        {
            if (buildData == null || team == null)
                return;

            uint clothingColor1 = BattleSnapshotRuntimeState.ResolveSideColor(team.Side, team.Color);
            uint clothingColor2 = BattleSnapshotRuntimeState.ResolveSideColor2(team.Side, team.Color2);
            buildData.ClothingColor1(clothingColor1);
            buildData.ClothingColor2(clothingColor2);
        }

        private static IAgentOriginBase BuildMaterializedAgentOriginForCreateTimePath(
            Mission mission,
            BasicCharacterObject troop,
            RosterEntryState entryState,
            BattleSideEnum side,
            Team team)
        {
            if (troop == null)
                return null;

            if (!ShouldUseCoopTestBattleCreateTimeMaterialization(entryState))
                return BuildBannerAwareBasicAgentOrigin(mission, troop, team, side);

            Banner banner = ResolveMaterializedCreateTimeBanner(team, side);
            uint color = BattleSnapshotRuntimeState.ResolveSideColor(side, team?.Color ?? 0u);
            uint color2 = BattleSnapshotRuntimeState.ResolveSideColor2(side, team?.Color2 ?? 0u);
            bool isPlayerSide = BattleSnapshotRuntimeState.GetSideState(side)?.IsPlayerSide == true;
            string entryId = entryState?.EntryId ?? string.Empty;
            string troopId =
                !string.IsNullOrWhiteSpace(entryState?.OriginalCharacterId)
                    ? entryState.OriginalCharacterId
                    : troop.StringId;

            return new ExactCampaignSnapshotAgentOrigin(
                null,
                troop,
                entryId,
                troopId,
                side,
                isPlayerSide,
                color,
                color2,
                banner,
                ComputeStableMaterializedOriginSeed(entryId, troopId, side));
        }

        private static IAgentOriginBase BuildBannerAwareBasicAgentOrigin(
            Mission mission,
            BasicCharacterObject troop,
            Team team,
            BattleSideEnum side)
        {
            if (troop == null)
                return null;

            IAgentOriginBase origin = new BasicBattleAgentOrigin(troop);
            if (mission == null ||
                team == null ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return origin;
            }

            Banner banner = ResolveMaterializedCreateTimeBanner(team, side);
            return BannerAwareAgentOrigin.Ensure(origin, banner);
        }

        private static bool ShouldUseCoopTestBattleCreateTimeMaterialization(RosterEntryState entryState)
        {
            return entryState != null &&
                   CoopTestBattleOptions.IsTestBattleSnapshot(BattleSnapshotRuntimeState.GetCurrent());
        }

        private static bool ShouldUseMaterializedCreateTimeMissionEquipment(Mission mission, RosterEntryState entryState)
        {
            if (entryState == null)
                return false;

            if (ShouldUseCoopTestBattleCreateTimeMaterialization(entryState))
                return true;

            return ExactSiegeMaterializationModule.ShouldUseCreateTimeMissionEquipment(mission);
        }

        private static string TryApplyMaterializedCreateTimeBannerOnly(
            AgentBuildData buildData,
            Mission mission,
            Team team,
            RosterEntryState entryState)
        {
            if (buildData == null ||
                mission == null ||
                team == null ||
                entryState == null ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty) ||
                ShouldUseCoopTestBattleCreateTimeMaterialization(entryState))
            {
                return null;
            }

            try
            {
                Banner banner = ResolveMaterializedCreateTimeBanner(team, team.Side);
                if (banner == null)
                    return "siege-create-time-banner-missing";

                buildData.Banner(banner);
                return "siege-create-time-banner";
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: failed to apply siege create-time banner. " +
                    "EntryId=" + (entryState.EntryId ?? "null") +
                    " TeamSide=" + team.Side +
                    " Message=" + ex.Message);
                return "siege-create-time-banner-failed";
            }
        }

        private static string TryApplyMaterializedCreateTimeMissionEquipment(
            AgentBuildData buildData,
            Mission mission,
            Equipment spawnEquipment,
            Team team,
            RosterEntryState entryState)
        {
            if (buildData == null ||
                spawnEquipment == null ||
                !ShouldUseMaterializedCreateTimeMissionEquipment(mission, entryState))
            {
                return null;
            }

            try
            {
                bool useCoopTestCreateTimeMissionEquipment =
                    ShouldUseCoopTestBattleCreateTimeMaterialization(entryState);
                Banner banner = ResolveMaterializedCreateTimeBanner(team, team?.Side ?? BattleSideEnum.None);
                buildData.Banner(banner);
                MissionEquipment missionEquipment = new MissionEquipment(spawnEquipment, banner);
                string usageProjection = TryApplyWeaponPrioritySuspectThrownUsageProjection(
                    missionEquipment,
                    entryState,
                    "TryApplyMaterializedCreateTimeMissionEquipment");
                if (IsShieldBannersRuntime())
                {
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: shield banner create-time mission equipment. " +
                        "EntryId=" + (entryState?.EntryId ?? "null") +
                        " Side=" + (team?.Side.ToString() ?? "none") +
                        " BannerCodeLength=" + (banner?.BannerCode?.Length ?? 0) +
                        " MissionWeapons={" + BuildMissionEquipmentSummary(
                            missionEquipment,
                            EquipmentIndex.Weapon0,
                            EquipmentIndex.Weapon1,
                            EquipmentIndex.Weapon2,
                            EquipmentIndex.Weapon3) + "}");
                }

                buildData.MissionEquipment(missionEquipment);
                return (useCoopTestCreateTimeMissionEquipment
                    ? "coop-test-create-time-mission-equipment"
                    : "siege-create-time-mission-equipment") + usageProjection;
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: failed to apply materialized create-time mission equipment. " +
                    "EntryId=" + (entryState?.EntryId ?? "null") +
                    " Mission=" + (mission?.SceneName ?? "null") +
                    " Message=" + ex.Message);
                return "materialized-create-time-mission-equipment-failed";
            }
        }

        private static string TryApplyRoleMatrixStreamInitialWield(
            Agent agent,
            RosterEntryState entryState,
            string source)
        {
            bool shouldApplyInitialWield =
                IsRoleMatrixStreamMatrixEntryId(entryState?.EntryId) ||
                IsCampaignMirrorAllRuntime() ||
                IsShieldBannersRuntime();
            if (agent == null || !shouldApplyInitialWield)
            {
                return null;
            }

            try
            {
                EquipmentIndex preMainHandIndex = agent.GetPrimaryWieldedItemIndex();
                EquipmentIndex preOffHandIndex = agent.GetOffhandWieldedItemIndex();
                string usageProjection = TryApplyWeaponPrioritySuspectThrownUsageProjection(
                    agent.Equipment,
                    entryState,
                    (source ?? "unknown") + " pre-initial-wield");
                agent.WieldInitialWeapons(
                    Agent.WeaponWieldActionType.Instant,
                    Equipment.InitialWeaponEquipPreference.Any);
                EquipmentIndex postMainHandIndex = agent.GetPrimaryWieldedItemIndex();
                EquipmentIndex postOffHandIndex = agent.GetOffhandWieldedItemIndex();
                bool success = postMainHandIndex != EquipmentIndex.None || postOffHandIndex != EquipmentIndex.None;
                return
                    "RoleMatrixInitialWield={Success=" + success +
                    ",PreMain=" + FormatAgentWieldedEquipmentIndex(agent, preMainHandIndex) +
                    ",PreOff=" + FormatAgentWieldedEquipmentIndex(agent, preOffHandIndex) +
                    ",PostMain=" + FormatAgentWieldedEquipmentIndex(agent, postMainHandIndex) +
                    ",PostOff=" + FormatAgentWieldedEquipmentIndex(agent, postOffHandIndex) +
                    ",PostWieldedItem=" + (agent.WieldedWeapon.Item?.StringId ?? "none") +
                    ",PostOffhandItem=" + (agent.WieldedOffhandWeapon.Item?.StringId ?? "none") +
                    ",UsageProjection=" + (string.IsNullOrWhiteSpace(usageProjection) ? "(none)" : usageProjection) +
                    "}";
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: role-matrix stream initial wield failed. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + (entryState?.EntryId ?? "null") +
                    " Message=" + ex.Message +
                    " Source=" + (source ?? "unknown"));
                return "RoleMatrixInitialWield={Success=False,Error=" + ex.GetType().Name + "}";
            }
        }

        private static string TryApplyWeaponPrioritySuspectThrownUsageProjection(
            MissionEquipment missionEquipment,
            RosterEntryState entryState,
            string source)
        {
            if (missionEquipment == null ||
                entryState == null ||
                !IsWeaponPrioritySuspectFocusRuntime() ||
                !IsCampaignMirrorWeaponPrioritySuspectEntry(entryState))
            {
                return string.Empty;
            }

            try
            {
                var appliedSlots = new List<string>();
                for (EquipmentIndex slot = EquipmentIndex.Weapon0; slot <= EquipmentIndex.Weapon3; slot++)
                {
                    MissionWeapon missionWeapon = missionEquipment[slot];
                    if (!TryResolveWeaponPriorityDualUseThrownUsageIndex(
                            missionWeapon,
                            out int thrownUsageIndex,
                            out int rangedUsageIndex,
                            out string usageSummary))
                    {
                        continue;
                    }

                    int beforeUsageIndex = SafeGetMissionWeaponCurrentUsageIndex(missionWeapon);
                    missionEquipment.SetUsageIndexOfSlot(slot, thrownUsageIndex);
                    MissionWeapon projectedWeapon = missionEquipment[slot];
                    int afterUsageIndex = SafeGetMissionWeaponCurrentUsageIndex(projectedWeapon);
                    appliedSlots.Add(
                        GetEquipmentSlotLabel(slot) +
                        "=" + (missionWeapon.Item?.StringId ?? "unknown") +
                        "(before=" + beforeUsageIndex +
                        ",after=" + afterUsageIndex +
                        ",ranged=" + rangedUsageIndex +
                        ",thrown=" + thrownUsageIndex +
                        ",usages={" + usageSummary + "})");
                }

                string catalog = BuildWeaponPriorityMissionEquipmentUsageCatalog(missionEquipment);
                ModLogger.Info(
                    "CoopMissionSpawnLogic: WeaponPriorityUsageCatalog. " +
                    "FocusRole=Suspect" +
                    " EntryId=" + (entryState.EntryId ?? "null") +
                    " CharacterId=" + (GetCampaignMirrorWeaponPriorityCharacterKey(entryState) ?? "null") +
                    " AppliedThrownUsageSlots=[" + string.Join("; ", appliedSlots) + "]" +
                    " Catalog={" + catalog + "}" +
                    " Source=" + (source ?? "unknown"));

                return appliedSlots.Count > 0
                    ? "+weapon-priority-suspect-thrown-usage"
                    : "+weapon-priority-suspect-usage-catalog";
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: WeaponPriorityUsageCatalog failed open. " +
                    "EntryId=" + (entryState?.EntryId ?? "null") +
                    " CharacterId=" + (GetCampaignMirrorWeaponPriorityCharacterKey(entryState) ?? "null") +
                    " Message=" + ex.Message +
                    " Source=" + (source ?? "unknown"));
                return "+weapon-priority-suspect-thrown-usage-failed";
            }
        }

        private static bool TryResolveWeaponPriorityDualUseThrownUsageIndex(
            MissionWeapon missionWeapon,
            out int thrownUsageIndex,
            out int rangedUsageIndex,
            out string usageSummary)
        {
            thrownUsageIndex = -1;
            rangedUsageIndex = -1;
            usageSummary = "(none)";

            try
            {
                if (missionWeapon.IsEmpty || missionWeapon.Item == null)
                    return false;

                int weaponsCount = missionWeapon.WeaponsCount;
                if (weaponsCount <= 0)
                    return false;

                try
                {
                    rangedUsageIndex = missionWeapon.GetRangedUsageIndex();
                }
                catch
                {
                    rangedUsageIndex = -1;
                }

                bool hasThrownUsage = false;
                bool hasMeleeUsage = false;
                int firstThrownUsageIndex = -1;
                var usageParts = new List<string>();
                for (int usageIndex = 0; usageIndex < weaponsCount; usageIndex++)
                {
                    WeaponComponentData usage = null;
                    try
                    {
                        usage = missionWeapon.GetWeaponComponentDataForUsage(usageIndex);
                    }
                    catch
                    {
                    }

                    bool thrown = IsWeaponPriorityThrownUsage(usage);
                    bool melee = IsWeaponPriorityMeleeUsage(usage);
                    if (thrown)
                    {
                        hasThrownUsage = true;
                        if (firstThrownUsageIndex < 0)
                            firstThrownUsageIndex = usageIndex;
                    }

                    if (melee)
                        hasMeleeUsage = true;

                    usageParts.Add(FormatWeaponPriorityUsageComponent(usageIndex, usage, thrown, melee));
                }

                usageSummary = string.Join("|", usageParts);
                if (!hasThrownUsage || !hasMeleeUsage)
                    return false;

                if (rangedUsageIndex >= 0 && rangedUsageIndex < weaponsCount)
                {
                    WeaponComponentData rangedUsage = missionWeapon.GetWeaponComponentDataForUsage(rangedUsageIndex);
                    if (IsWeaponPriorityThrownUsage(rangedUsage))
                    {
                        thrownUsageIndex = rangedUsageIndex;
                        return true;
                    }
                }

                thrownUsageIndex = firstThrownUsageIndex;
                return thrownUsageIndex >= 0;
            }
            catch
            {
                return false;
            }
        }

        private static string BuildWeaponPriorityMissionEquipmentUsageCatalog(MissionEquipment missionEquipment)
        {
            if (missionEquipment == null)
                return "(none)";

            var parts = new List<string>();
            for (EquipmentIndex slot = EquipmentIndex.Weapon0; slot <= EquipmentIndex.Weapon3; slot++)
            {
                try
                {
                    MissionWeapon missionWeapon = missionEquipment[slot];
                    if (missionWeapon.IsEmpty || missionWeapon.Item == null)
                    {
                        parts.Add(GetEquipmentSlotLabel(slot) + "=empty");
                        continue;
                    }

                    TryResolveWeaponPriorityDualUseThrownUsageIndex(
                        missionWeapon,
                        out int thrownUsageIndex,
                        out int rangedUsageIndex,
                        out string usageSummary);
                    parts.Add(
                        GetEquipmentSlotLabel(slot) +
                        "=" + missionWeapon.Item.StringId +
                        "(current=" + SafeGetMissionWeaponCurrentUsageIndex(missionWeapon) +
                        ",ranged=" + rangedUsageIndex +
                        ",thrown=" + thrownUsageIndex +
                        ",usages={" + usageSummary + "})");
                }
                catch (Exception ex)
                {
                    parts.Add(GetEquipmentSlotLabel(slot) + "=error:" + ex.GetType().Name);
                }
            }

            return parts.Count > 0 ? string.Join("; ", parts) : "(empty)";
        }

        private static string FormatWeaponPriorityUsageComponent(
            int usageIndex,
            WeaponComponentData usage,
            bool thrown,
            bool melee)
        {
            if (usage == null)
                return usageIndex + ":null";

            return
                usageIndex +
                ":" + usage.WeaponClass +
                "/skill=" + (usage.RelevantSkill?.StringId ?? "none") +
                "/itemUsage=" + (usage.ItemUsage ?? "none") +
                "/thrown=" + thrown +
                "/melee=" + melee +
                "/ranged=" + usage.IsRangedWeapon +
                "/polearm=" + usage.IsPolearm +
                "/shield=" + usage.IsShield +
                "/ammo=" + usage.IsAmmo;
        }

        private static bool IsWeaponPriorityThrownUsage(WeaponComponentData usage)
        {
            return usage != null &&
                   (usage.RelevantSkill == DefaultSkills.Throwing ||
                    usage.WeaponClass == WeaponClass.Javelin ||
                    usage.WeaponClass == WeaponClass.ThrowingAxe ||
                    usage.WeaponClass == WeaponClass.ThrowingKnife ||
                    usage.WeaponClass == WeaponClass.Stone ||
                    usage.WeaponClass == WeaponClass.SlingStone);
        }

        private static bool IsWeaponPriorityMeleeUsage(WeaponComponentData usage)
        {
            return usage != null &&
                   (usage.IsMeleeWeapon ||
                    usage.IsPolearm ||
                    usage.IsOneHanded ||
                    usage.IsTwoHanded ||
                    usage.RelevantSkill == DefaultSkills.Polearm ||
                    usage.RelevantSkill == DefaultSkills.OneHanded ||
                    usage.RelevantSkill == DefaultSkills.TwoHanded);
        }

        private static int SafeGetMissionWeaponCurrentUsageIndex(MissionWeapon missionWeapon)
        {
            try
            {
                return missionWeapon.CurrentUsageIndex;
            }
            catch
            {
                return -1;
            }
        }

        private static Banner ResolveMaterializedCreateTimeBanner(Team team, BattleSideEnum side)
        {
            uint color = BattleSnapshotRuntimeState.ResolveSideColor(side, team?.Color ?? 0u);
            uint color2 = BattleSnapshotRuntimeState.ResolveSideColor2(side, team?.Color2 ?? 0u);
            string bannerCode = BattleSnapshotRuntimeState.ResolveSideBannerCode(side, team?.Banner?.BannerCode);
            if (!string.IsNullOrWhiteSpace(bannerCode))
            {
                try
                {
                    return new Banner(bannerCode, color, color2);
                }
                catch
                {
                }
            }

            return team?.Banner;
        }

        private static int ComputeStableMaterializedOriginSeed(string entryId, string troopId, BattleSideEnum side)
        {
            unchecked
            {
                int hash = 17;
                string key = (entryId ?? string.Empty) + "|" + (troopId ?? string.Empty) + "|" + side;
                for (int i = 0; i < key.Length; i++)
                    hash = hash * 31 + key[i];
                return NormalizeNetworkSafeOriginSeed(hash == 0 ? 17 : hash);
            }
        }

        private static int NormalizeNetworkSafeOriginSeed(int seed)
        {
            const int maxInclusive = 2000;
            int normalized = seed % (maxInclusive + 1);
            return normalized < 0 ? -normalized : normalized;
        }

        private static string TryApplyEntryIdentityToBuildData(AgentBuildData buildData, RosterEntryState entryState)
        {
            if (buildData == null || !HasEntryHeroIdentity(entryState))
                return "AppliedIdentity=(none)";

            var parts = new List<string>();
            try
            {
                buildData.IsFemale(entryState.HeroIsFemale);
                parts.Add("Female=" + entryState.HeroIsFemale);
            }
            catch (Exception ex)
            {
                parts.Add("FemaleApplyFailed=" + ex.GetType().Name);
            }

            if (entryState.HeroAge > 0.01f)
            {
                try
                {
                    int roundedAge = Math.Max(1, Math.Min(120, (int)Math.Round(entryState.HeroAge)));
                    buildData.Age(roundedAge);
                    parts.Add("Age=" + entryState.HeroAge.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception ex)
                {
                    parts.Add("AgeApplyFailed=" + ex.GetType().Name);
                }
            }

            if (TryResolveEntryBodyProperties(entryState, out BodyProperties bodyProperties))
            {
                try
                {
                    buildData.BodyProperties(bodyProperties);
                    parts.Add("Body=applied");
                }
                catch (Exception ex)
                {
                    parts.Add("BodyApplyFailed=" + ex.GetType().Name);
                }
            }

            if (!string.IsNullOrWhiteSpace(entryState.TroopName))
                parts.Add("Name=" + entryState.TroopName.Replace('\r', ' ').Replace('\n', ' '));

            return parts.Count == 0
                ? "AppliedIdentity=(none)"
                : "AppliedIdentity=" + string.Join(", ", parts);
        }

        internal static bool ShouldPreserveSallyOutCreateTimeBodyProperties(
            Agent agent,
            RosterEntryState entryState)
        {
            if (GameNetwork.IsServer ||
                agent == null ||
                entryState == null ||
                !IsHeroEntryEligibleForExactPersonalPerks(entryState) ||
                string.IsNullOrWhiteSpace(entryState.HeroBodyProperties))
            {
                return false;
            }

            Mission mission = agent.Mission ?? Mission.Current;
            if (mission == null)
                return false;

            BattleScenarioContextMessage scenarioContext =
                BattleSnapshotRuntimeState.GetScenarioContext() ??
                BattleSnapshotRuntimeState.GetCurrent()?.ScenarioContext ??
                BattleSnapshotRuntimeState.GetState()?.ScenarioContext ??
                CoopPreMissionTopologyRuntimeState.GetActiveScenarioContext();
            return SallyOutScenarioContract.IsValidatedScenario(
                scenarioContext,
                mission.SceneName ?? string.Empty,
                out string _);
        }

        internal static void TryApplyEntryIdentityToAgent(
            Agent agent,
            RosterEntryState entryState,
            bool applyBodyProperties = true)
        {
            if (agent == null || entryState == null)
                return;

            if (HasEntryHeroIdentity(entryState))
            {
                try
                {
                    agent.IsFemale = entryState.HeroIsFemale;
                }
                catch
                {
                }

                if (entryState.HeroAge > 0.01f)
                {
                    try
                    {
                        agent.Age = entryState.HeroAge;
                    }
                    catch
                    {
                    }
                }

                if (applyBodyProperties &&
                    TryResolveEntryBodyProperties(entryState, out BodyProperties bodyProperties))
                {
                    try
                    {
                        agent.UpdateBodyProperties(bodyProperties);
                    }
                    catch
                    {
                    }
                }
            }

            CacheExactDisplayNameForAgent(
                agent,
                entryState.EntryId,
                entryState);

            if (string.IsNullOrWhiteSpace(entryState.TroopName))
                return;

            try
            {
                FieldInfo agentNameField = typeof(Agent).GetField("_name", BindingFlags.Instance | BindingFlags.NonPublic);
                if (agentNameField != null)
                    agentNameField.SetValue(agent, new TextObject(entryState.TroopName));
            }
            catch
            {
            }
        }

        internal static bool TryApplyEntryNameToSpawnCharacter(BasicCharacterObject troop, RosterEntryState entryState, out TextObject originalName)
        {
            originalName = null;
            if (troop == null || !HasEntryHeroIdentity(entryState) || string.IsNullOrWhiteSpace(entryState.TroopName))
                return false;

            string currentName = troop.Name?.ToString() ?? string.Empty;
            if (string.Equals(currentName, entryState.TroopName, StringComparison.Ordinal))
                return false;

            try
            {
                originalName = new TextObject(string.IsNullOrWhiteSpace(currentName) ? troop.StringId ?? string.Empty : currentName);
                if (!TrySetCharacterName(troop, new TextObject(entryState.TroopName)))
                    return false;
                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: failed to apply temporary spawn-character name override. " +
                    "TroopId=" + troop.StringId +
                    " EntryId=" + (entryState?.EntryId ?? "null") +
                    " Name=" + (entryState?.TroopName ?? string.Empty).Replace('\r', ' ').Replace('\n', ' ') +
                    " Message=" + ex.Message);
                return false;
            }
        }

        internal static void RestoreSpawnCharacterName(BasicCharacterObject troop, bool restore, TextObject originalName)
        {
            if (!restore || troop == null || originalName == null)
                return;

            try
            {
                TrySetCharacterName(troop, originalName);
            }
            catch
            {
            }
        }

        private static bool TrySetCharacterName(BasicCharacterObject troop, TextObject name)
        {
            if (troop == null || name == null)
                return false;

            try
            {
                MethodInfo setNameMethod = troop.GetType().GetMethod(
                    "SetName",
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                    null,
                    new[] { typeof(TextObject) },
                    null);
                if (setNameMethod == null)
                    return false;

                setNameMethod.Invoke(troop, new object[] { name });
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static bool HasEntryHeroIdentity(RosterEntryState entryState)
        {
            return entryState != null &&
                   (entryState.IsHero ||
                    !string.IsNullOrWhiteSpace(entryState.HeroId) ||
                    !string.IsNullOrWhiteSpace(entryState.HeroRole) ||
                    !string.IsNullOrWhiteSpace(entryState.HeroTemplateId) ||
                    !string.IsNullOrWhiteSpace(entryState.HeroBodyProperties));
        }

        private static bool TryResolveEntryBodyProperties(RosterEntryState entryState, out BodyProperties bodyProperties)
        {
            bodyProperties = default;
            if (string.IsNullOrWhiteSpace(entryState?.HeroBodyProperties))
                return false;

            try
            {
                return BodyProperties.FromString(entryState.HeroBodyProperties, out bodyProperties);
            }
            catch
            {
                return false;
            }
        }

        private static string TryApplyMaterializedCombatProfile(Agent agent, RosterEntryState entryState)
        {
            if (agent == null || entryState == null)
                return "AppliedCombatProfile=(none)";

            RegisterMaterializedCombatProfile(agent, entryState);
            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            BattlePartyState partyState = null;
            if (runtimeState?.PartiesById != null && !string.IsNullOrWhiteSpace(entryState.PartyId))
                runtimeState.PartiesById.TryGetValue(entryState.PartyId, out partyState);

            var parts = new List<string>();
            if (entryState.BaseHitPoints > 0)
            {
                float targetHitPoints = Math.Max(1f, entryState.BaseHitPoints);
                try
                {
                    AgentStatCalculateModel statModel = MissionGameModels.Current?.AgentStatCalculateModel;
                    if (statModel != null)
                        targetHitPoints = Math.Max(1f, statModel.GetEffectiveMaxHealth(agent));

                    agent.HealthLimit = targetHitPoints;
                    agent.Health = targetHitPoints;
                    parts.Add("Hp=" + targetHitPoints.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception ex)
                {
                    parts.Add("HpApplyFailed=" + ex.GetType().Name);
                }
            }

            Agent mountAgent = agent.MountAgent;
            if (mountAgent != null && mountAgent.IsActive())
            {
                try
                {
                    float targetMountHitPoints = Math.Max(1f, mountAgent.HealthLimit);
                    AgentStatCalculateModel statModel = MissionGameModels.Current?.AgentStatCalculateModel;
                    if (statModel != null)
                        targetMountHitPoints = Math.Max(1f, statModel.GetEffectiveMaxHealth(mountAgent));

                    mountAgent.HealthLimit = targetMountHitPoints;
                    mountAgent.Health = targetMountHitPoints;
                    parts.Add("MountHp=" + targetMountHitPoints.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception ex)
                {
                    parts.Add("MountHpApplyFailed=" + ex.GetType().Name);
                }
            }

            if (IsHeroEntryEligibleForExactPersonalPerks(entryState))
            {
                if (TryApplyExactCampaignMissionEquipmentPerks(agent, entryState, partyState, out string equipmentSummary))
                    parts.Add(equipmentSummary);
                if (TryApplyExactCampaignHeroFlags(agent, entryState, out string flagSummary))
                    parts.Add(flagSummary);
            }

            return parts.Count == 0
                ? "AppliedCombatProfile=(none)"
                : "AppliedCombatProfile=" + string.Join(", ", parts);
        }

        private static bool TryApplyExactCampaignMissionEquipmentPerks(
            Agent agent,
            RosterEntryState entryState,
            BattlePartyState partyState,
            out string summary)
        {
            summary = null;
            if (agent == null || entryState == null || !agent.IsHuman || !IsHeroEntryEligibleForExactPersonalPerks(entryState))
                return false;

            MissionEquipment equipment = agent.Equipment;
            if (equipment == null)
                return false;

            IEnumerable<string> personalPerkIds = entryState.PerkIds ?? Enumerable.Empty<string>();
            IEnumerable<string> partyLeaderPerkIds = partyState?.Modifiers?.PartyLeaderPerkIds ?? Enumerable.Empty<string>();
            bool isMounted = agent.HasMount || agent.MountAgent != null;
            var changes = new List<string>();

            for (EquipmentIndex index = EquipmentIndex.Weapon0; index <= EquipmentIndex.Weapon3; index++)
            {
                MissionWeapon missionWeapon = equipment[index];
                ItemObject item = missionWeapon.Item;
                WeaponComponentData currentUsageItem = missionWeapon.CurrentUsageItem;
                if (item == null || currentUsageItem == null)
                    continue;

                if (currentUsageItem.IsConsumable && currentUsageItem.RelevantSkill != null)
                {
                    float ammoBonus = 0f;
                    if (currentUsageItem.RelevantSkill == DefaultSkills.Bow)
                    {
                        if (HasPerkId(personalPerkIds, "BowDeepQuivers"))
                            ammoBonus += 3f;
                        if (HasPerkId(partyLeaderPerkIds, "BowDeepQuivers"))
                            ammoBonus += 1f;
                    }
                    else if (currentUsageItem.RelevantSkill == DefaultSkills.Crossbow)
                    {
                        if (HasPerkId(personalPerkIds, "CrossbowFletcher"))
                            ammoBonus += 4f;
                        if (HasPerkId(partyLeaderPerkIds, "CrossbowFletcher"))
                            ammoBonus += 2f;
                    }
                    else if (currentUsageItem.RelevantSkill == DefaultSkills.Throwing)
                    {
                        if (HasPerkId(personalPerkIds, "ThrowingWellPrepared"))
                            ammoBonus += 1f;
                        if (HasPerkId(personalPerkIds, "ThrowingResourceful"))
                            ammoBonus += 2f;
                        if (isMounted && HasPerkId(personalPerkIds, "ThrowingSaddlebags"))
                            ammoBonus += 2f;
                        if (HasPerkId(partyLeaderPerkIds, "ThrowingWellPrepared"))
                            ammoBonus += 1f;
                    }

                    int currentAmount = missionWeapon.Amount;
                    int roundedAmmoBonus = Math.Max(0, MathF.Round(ammoBonus));
                    int? snapshotBaseAmount = GetSnapshotCombatItemBaseAmount(entryState, index, item.StringId);
                    int targetAmount = snapshotBaseAmount.HasValue && snapshotBaseAmount.Value > 0
                        ? Math.Max(0, snapshotBaseAmount.Value + roundedAmmoBonus)
                        : Math.Max(0, currentAmount + roundedAmmoBonus);
                    if (targetAmount != currentAmount)
                    {
                        if (GameNetwork.IsServerOrRecorder)
                        {
                            agent.SetWeaponAmountInSlot(index, (short)targetAmount, enforcePrimaryItem: true);
                        }
                        else
                        {
                            equipment.SetAmountOfSlot(index, (short)targetAmount, true);
                        }
                        changes.Add(
                            snapshotBaseAmount.HasValue && snapshotBaseAmount.Value > 0
                                ? index + "Ammo=" + currentAmount + "->" + targetAmount + "(base:" + snapshotBaseAmount.Value + ",+" + roundedAmmoBonus + ")"
                                : index + "Ammo=" + currentAmount + "->" + targetAmount + "(" + (roundedAmmoBonus >= 0 ? "+" : string.Empty) + roundedAmmoBonus + ")");
                    }
                }
                else if (currentUsageItem.IsShield)
                {
                    int currentHitPoints = missionWeapon.HitPoints;
                    float targetHitPointsValue = currentHitPoints;
                    if (HasPerkId(personalPerkIds, "EngineeringScaffolds"))
                        targetHitPointsValue *= 1.3f;
                    int targetHitPoints = Math.Max(1, MathF.Round(targetHitPointsValue));
                    if (targetHitPoints != currentHitPoints)
                    {
                        equipment.SetHitPointsOfSlot(index, (short)targetHitPoints, true);
                        int delta = targetHitPoints - currentHitPoints;
                        changes.Add(index + "Shield=" + (delta >= 0 ? "+" : string.Empty) + delta);
                    }
                }
            }

            if (changes.Count == 0)
                return false;

            try
            {
                agent.UpdateWeapons();
            }
            catch (Exception ex)
            {
                changes.Add("WeaponRefreshFailed=" + ex.GetType().Name);
            }

            summary = "ExactPerks=" + string.Join("/", changes);
            return true;
        }

        private static int? GetSnapshotCombatItemBaseAmount(
            RosterEntryState entryState,
            EquipmentIndex index,
            string currentItemId = null)
        {
            if (entryState == null)
                return null;

            if (!string.IsNullOrWhiteSpace(currentItemId))
            {
                string directItemId = GetSnapshotCombatItemId(entryState, index);
                int? directAmount = GetSnapshotCombatItemBaseAmountByIndex(entryState, index);
                if (string.Equals(directItemId, currentItemId, StringComparison.OrdinalIgnoreCase))
                    return directAmount;

                int? matchedAmount = GetSnapshotCombatItemBaseAmountByItemId(entryState, currentItemId);
                if (matchedAmount.HasValue)
                    return matchedAmount;
            }

            return GetSnapshotCombatItemBaseAmountByIndex(entryState, index);
        }

        private static int? GetSnapshotCombatItemBaseAmountByIndex(RosterEntryState entryState, EquipmentIndex index)
        {
            if (entryState == null)
                return null;

            switch (index)
            {
                case EquipmentIndex.Weapon0:
                    return entryState.CombatItem0Amount;
                case EquipmentIndex.Weapon1:
                    return entryState.CombatItem1Amount;
                case EquipmentIndex.Weapon2:
                    return entryState.CombatItem2Amount;
                case EquipmentIndex.Weapon3:
                    return entryState.CombatItem3Amount;
                default:
                    return null;
            }
        }

        private static string GetSnapshotCombatItemId(RosterEntryState entryState, EquipmentIndex index)
        {
            if (entryState == null)
                return null;

            switch (index)
            {
                case EquipmentIndex.Weapon0:
                    return entryState.CombatItem0Id;
                case EquipmentIndex.Weapon1:
                    return entryState.CombatItem1Id;
                case EquipmentIndex.Weapon2:
                    return entryState.CombatItem2Id;
                case EquipmentIndex.Weapon3:
                    return entryState.CombatItem3Id;
                default:
                    return null;
            }
        }

        private static int? GetSnapshotCombatItemBaseAmountByItemId(RosterEntryState entryState, string itemId)
        {
            if (entryState == null || string.IsNullOrWhiteSpace(itemId))
                return null;

            if (string.Equals(entryState.CombatItem0Id, itemId, StringComparison.OrdinalIgnoreCase))
                return entryState.CombatItem0Amount;
            if (string.Equals(entryState.CombatItem1Id, itemId, StringComparison.OrdinalIgnoreCase))
                return entryState.CombatItem1Amount;
            if (string.Equals(entryState.CombatItem2Id, itemId, StringComparison.OrdinalIgnoreCase))
                return entryState.CombatItem2Amount;
            if (string.Equals(entryState.CombatItem3Id, itemId, StringComparison.OrdinalIgnoreCase))
                return entryState.CombatItem3Amount;

            return null;
        }

        private static bool TryApplyExactCampaignHeroFlags(Agent agent, RosterEntryState entryState, out string summary)
        {
            summary = null;
            if (agent == null || entryState?.PerkIds == null || entryState.PerkIds.Count == 0 || !agent.IsHuman || !IsHeroEntryEligibleForExactPersonalPerks(entryState))
                return false;

            int desiredFlagBits = 0;
            if (HasPerkId(entryState.PerkIds, "BowHorseMaster"))
                desiredFlagBits |= AgentFlagHorseMasterBit;
            if (HasPerkId(entryState.PerkIds, "CrossbowMountedCrossbowman"))
                desiredFlagBits |= AgentFlagMountedCrossbowmanBit;
            if (HasPerkId(entryState.PerkIds, "TwoHandedProjectileDeflection"))
                desiredFlagBits |= AgentFlagProjectileDeflectionBit;

            if (desiredFlagBits == 0)
                return false;

            AgentFlag currentFlags = agent.GetAgentFlags();
            int currentFlagBits = (int)currentFlags;
            int updatedFlagBits = currentFlagBits | desiredFlagBits;
            if (updatedFlagBits == currentFlagBits)
                return false;

            agent.SetAgentFlags((AgentFlag)updatedFlagBits);

            var appliedFlags = new List<string>();
            if ((desiredFlagBits & AgentFlagHorseMasterBit) != 0 && (currentFlagBits & AgentFlagHorseMasterBit) == 0)
                appliedFlags.Add("HorseMaster");
            if ((desiredFlagBits & AgentFlagMountedCrossbowmanBit) != 0 && (currentFlagBits & AgentFlagMountedCrossbowmanBit) == 0)
                appliedFlags.Add("MountedCrossbowman");
            if ((desiredFlagBits & AgentFlagProjectileDeflectionBit) != 0 && (currentFlagBits & AgentFlagProjectileDeflectionBit) == 0)
                appliedFlags.Add("ProjectileDeflection");

            if (appliedFlags.Count == 0)
                return false;

            summary = "HeroFlags=" + string.Join("/", appliedFlags);
            return true;
        }

        private static bool IsHeroEntryEligibleForExactPersonalPerks(RosterEntryState entryState)
        {
            return HasEntryExactPersonalPerkHeroIdentity(entryState);
        }

        private static bool IsHeroProfileEligibleForExactPersonalPerks(MaterializedCombatProfileRuntimeState profile)
        {
            return profile != null &&
                   (profile.IsHero ||
                   string.Equals(profile.OriginalCharacterId, "main_hero", StringComparison.OrdinalIgnoreCase));
        }

        private static bool HasEntryExactPersonalPerkHeroIdentity(RosterEntryState entryState)
        {
            return entryState != null &&
                   (entryState.IsHero ||
                    !string.IsNullOrWhiteSpace(entryState.HeroId) ||
                    string.Equals(entryState.OriginalCharacterId, "main_hero", StringComparison.OrdinalIgnoreCase));
        }

        private static bool HasPerkId(IEnumerable<string> perkIds, string perkId)
        {
            if (perkIds == null || string.IsNullOrWhiteSpace(perkId))
                return false;

            foreach (string candidate in perkIds)
            {
                if (string.Equals(candidate, perkId, StringComparison.OrdinalIgnoreCase))
                    return true;
            }

            return false;
        }

        private static void ResetMaterializedCombatProfileRuntimeState()
        {
            _materializedCombatProfilesByAgentIndex.Clear();
            _pendingMaterializedCombatProfileRefreshAgentIndices.Clear();
            _pendingMaterializedCombatProfileRefreshAgentsByIndex.Clear();
            MaterializedCombatProfileApplyCounts.Clear();
            _lastMaterializedCombatProfileMission = null;
            _lastCombatProfileDrivenRefreshMission = null;
            _lastCombatProfileDrivenRefreshMissionTime = -1f;
            _hasLoggedManualCombatProfileRefreshForMission = false;
        }

        private static void ResetMaterializedBattleResultRuntimeState()
        {
            ResetMaterializedSiegeReinforcementWaveRuntimeState();
            _materializedBattleResultEntriesByEntryId.Clear();
            _materializedBattleResultRemovedAgentIndices.Clear();
            _materializedBattleResultSpawnInstanceIdsByAgentIndex.Clear();
            _materializedBattleResultTerminalSpawnInstanceIds.Clear();
            _materializedBattleResultCasualtyEvents.Clear();
            _nextMaterializedBattleResultSpawnOrdinal = 0;
            _materializedBattleResultLastHitDebugByVictimAgentIndex.Clear();
            _materializedBattleResultCombatEvents.Clear();
            _materializedBattleResultRawOnScoreHitCount = 0;
            _materializedBattleResultRawOnAgentRemovedCount = 0;
            _materializedBattleResultOnScoreHitCount = 0;
            _materializedBattleResultOnAgentRemovedCount = 0;
            _materializedBattleResultRemovalDebugLogCount = 0;
            _mountedCombatDamageDiagnosticLogCount = 0;
            _hasLoggedMountedCombatDamageDiagnosticFailure = false;
            _mountedCombatDamageDiagnosticKeys.Clear();
            _materializedBattleResultOnScoreHitSamples.Clear();
            _materializedBattleResultOnAgentRemovedSamples.Clear();
            _materializedBattleResultReconcileRemovedSamples.Clear();
            _lastMaterializedBattleResultMission = null;
            _hasWrittenBattleResultSnapshotForMission = false;
            _droppedMaterializedBattleResultCombatEventCount = 0;
        }

        private static void EnsureMaterializedCombatProfileMission(Mission mission)
        {
            if (ReferenceEquals(_lastMaterializedCombatProfileMission, mission))
                return;

            _materializedCombatProfilesByAgentIndex.Clear();
            _pendingMaterializedCombatProfileRefreshAgentIndices.Clear();
            _pendingMaterializedCombatProfileRefreshAgentsByIndex.Clear();
            MaterializedCombatProfileApplyCounts.Clear();
            _lastMaterializedCombatProfileMission = mission;
            _lastCombatProfileDrivenRefreshMission = null;
            _lastCombatProfileDrivenRefreshMissionTime = -1f;
            _hasLoggedManualCombatProfileRefreshForMission = false;
        }

        private static void EnsureMaterializedBattleResultMission(Mission mission)
        {
            if (ReferenceEquals(_lastMaterializedBattleResultMission, mission))
                return;

            ResetMaterializedSiegeReinforcementWaveRuntimeState();
            _materializedBattleResultEntriesByEntryId.Clear();
            _materializedBattleResultRemovedAgentIndices.Clear();
            _materializedBattleResultSpawnInstanceIdsByAgentIndex.Clear();
            _materializedBattleResultTerminalSpawnInstanceIds.Clear();
            _materializedBattleResultCasualtyEvents.Clear();
            _nextMaterializedBattleResultSpawnOrdinal = 0;
            _materializedBattleResultLastHitDebugByVictimAgentIndex.Clear();
            _materializedBattleResultCombatEvents.Clear();
            _materializedBattleResultRawOnScoreHitCount = 0;
            _materializedBattleResultRawOnAgentRemovedCount = 0;
            _materializedBattleResultOnScoreHitCount = 0;
            _materializedBattleResultOnAgentRemovedCount = 0;
            _materializedBattleResultRemovalDebugLogCount = 0;
            _mountedCombatDamageDiagnosticLogCount = 0;
            _hasLoggedMountedCombatDamageDiagnosticFailure = false;
            _mountedCombatDamageDiagnosticKeys.Clear();
            _materializedBattleResultOnScoreHitSamples.Clear();
            _materializedBattleResultOnAgentRemovedSamples.Clear();
            _materializedBattleResultReconcileRemovedSamples.Clear();
            _lastMaterializedBattleResultMission = mission;
            _hasWrittenBattleResultSnapshotForMission = false;
            _droppedMaterializedBattleResultCombatEventCount = 0;
        }

        private static void RegisterMaterializedCombatProfile(Agent agent, RosterEntryState entryState)
        {
            if (agent?.Mission == null || entryState == null)
                return;

            EnsureMaterializedCombatProfileMission(agent.Mission);
            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            BattlePartyState partyState = null;
            BattleSideState sideState = null;
            if (runtimeState?.PartiesById != null && !string.IsNullOrWhiteSpace(entryState.PartyId))
            {
                runtimeState.PartiesById.TryGetValue(entryState.PartyId, out partyState);
                if (partyState != null && runtimeState.SidesByKey != null && !string.IsNullOrWhiteSpace(partyState.SideId))
                    runtimeState.SidesByKey.TryGetValue(partyState.SideId, out sideState);
            }

            _materializedCombatProfilesByAgentIndex[agent.Index] = new MaterializedCombatProfileRuntimeState
            {
                EntryId = entryState.EntryId,
                PartyId = entryState.PartyId,
                OriginalCharacterId = entryState.OriginalCharacterId,
                IsHero = HasEntryExactPersonalPerkHeroIdentity(entryState),
                AttributeVigor = entryState.AttributeVigor,
                AttributeControl = entryState.AttributeControl,
                AttributeEndurance = entryState.AttributeEndurance,
                SkillOneHanded = entryState.SkillOneHanded,
                SkillTwoHanded = entryState.SkillTwoHanded,
                SkillPolearm = entryState.SkillPolearm,
                SkillBow = entryState.SkillBow,
                SkillCrossbow = entryState.SkillCrossbow,
                SkillThrowing = entryState.SkillThrowing,
                SkillRiding = entryState.SkillRiding,
                SkillAthletics = entryState.SkillAthletics,
                BaseHitPoints = entryState.BaseHitPoints,
                SideMorale = sideState?.SideMorale ?? 0f,
                PartyMorale = partyState?.Modifiers?.Morale ?? 0f,
                LeaderLeadershipSkill = partyState?.Modifiers?.LeaderLeadershipSkill ?? 0,
                LeaderTacticsSkill = partyState?.Modifiers?.LeaderTacticsSkill ?? 0,
                ScoutScoutingSkill = partyState?.Modifiers?.ScoutScoutingSkill ?? 0,
                QuartermasterStewardSkill = partyState?.Modifiers?.QuartermasterStewardSkill ?? 0,
                EngineerEngineeringSkill = partyState?.Modifiers?.EngineerEngineeringSkill ?? 0,
                SurgeonMedicineSkill = partyState?.Modifiers?.SurgeonMedicineSkill ?? 0,
                PartyLeaderPerkCount = partyState?.Modifiers?.PartyLeaderPerkIds?.Count ?? 0,
                ArmyCommanderPerkCount = partyState?.Modifiers?.ArmyCommanderPerkIds?.Count ?? 0,
                CaptainPerkCount = partyState?.Modifiers?.CaptainPerkIds?.Count ?? 0,
                ScoutRolePerkCount = partyState?.Modifiers?.ScoutPerkIds?.Count ?? 0,
                QuartermasterRolePerkCount = partyState?.Modifiers?.QuartermasterPerkIds?.Count ?? 0,
                EngineerRolePerkCount = partyState?.Modifiers?.EngineerPerkIds?.Count ?? 0,
                SurgeonRolePerkCount = partyState?.Modifiers?.SurgeonPerkIds?.Count ?? 0,
                PerkIds = entryState.PerkIds != null
                    ? entryState.PerkIds.Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase).ToList()
                    : new List<string>()
            };
            MaterializedCombatProfileRuntimeState profile = _materializedCombatProfilesByAgentIndex[agent.Index];
            profile.PerkMeleeCount = CountCombatProfilePerksByPrefix(profile.PerkIds, "OneHanded", "TwoHanded", "Polearm");
            profile.PerkRangedCount = CountCombatProfilePerksByPrefix(profile.PerkIds, "Bow", "Crossbow", "Throwing");
            profile.PerkAthleticsCount = CountCombatProfilePerksByPrefix(profile.PerkIds, "Athletics");
            profile.PerkRidingCount = CountCombatProfilePerksByPrefix(profile.PerkIds, "Riding");
            IncrementMaterializedEquipmentCounter(MaterializedCombatProfileApplyCounts, "registered");
            if (profile.PerkIds.Count > 0)
                CountMaterializedCombatProfileApply(profile, "perks", ref profile.CountedPerkRegistration);
            QueueMaterializedCombatProfilePropertyRefresh(agent);
        }

        private static void RegisterMaterializedBattleResultEntry(Agent agent, RosterEntryState entryState, BattleSideEnum side)
        {
            if (agent?.Mission == null || entryState == null || string.IsNullOrWhiteSpace(entryState.EntryId))
                return;

            EnsureMaterializedBattleResultMission(agent.Mission);
            _materializedAgentInstanceByIndex[agent.Index] = agent;
            _materializedArmyEntryIdByAgentIndex[agent.Index] = entryState.EntryId;
            TrackAuthoritativeMaterializedAgentEntryLedgerMapping(
                agent.Mission,
                agent.Index,
                entryState.EntryId);
            if (side != BattleSideEnum.None)
                _materializedArmySideByAgentIndex[agent.Index] = side;
            _materializedBattleResultRemovedAgentIndices.Remove(agent.Index);
            if (!_materializedBattleResultSpawnInstanceIdsByAgentIndex.ContainsKey(agent.Index))
            {
                _nextMaterializedBattleResultSpawnOrdinal++;
                string battleInstanceId = BattleSnapshotRuntimeState.GetCurrent()?.BattleInstanceId ?? "legacy";
                _materializedBattleResultSpawnInstanceIdsByAgentIndex[agent.Index] =
                    battleInstanceId + "|" + entryState.EntryId + "|" + _nextMaterializedBattleResultSpawnOrdinal.ToString(System.Globalization.CultureInfo.InvariantCulture);
            }

            if (!_materializedBattleResultEntriesByEntryId.TryGetValue(entryState.EntryId, out MaterializedBattleResultEntryRuntimeState state))
            {
                state = new MaterializedBattleResultEntryRuntimeState
                {
                    EntryId = entryState.EntryId,
                    SideId = entryState.SideId,
                    PartyId = entryState.PartyId,
                    CharacterId = entryState.CharacterId,
                    OriginalCharacterId = entryState.OriginalCharacterId,
                    SpawnTemplateId = ResolveEntrySpawnTemplateId(entryState),
                    TroopName = entryState.TroopName,
                    HeroId = entryState.HeroId,
                    HeroRole = entryState.HeroRole,
                    IsHero = entryState.IsHero,
                    SnapshotCount = entryState.Count,
                    SnapshotWoundedCount = entryState.WoundedCount
                };
                if (string.IsNullOrWhiteSpace(state.SideId))
                    state.SideId = side == BattleSideEnum.None ? string.Empty : side.ToString();
                _materializedBattleResultEntriesByEntryId[entryState.EntryId] = state;
            }

            state.MaterializedSpawnCount++;
            state.ActiveCount++;
        }

        public static bool TryGetMaterializedBattleResultEntryId(Agent agent, out string entryId)
        {
            entryId = null;
            if (agent == null)
                return false;

            if (ExactCampaignArmyBootstrap.TryGetEntryId(agent, out entryId) && !string.IsNullOrWhiteSpace(entryId))
                return true;

            return _materializedArmyEntryIdByAgentIndex.TryGetValue(agent.Index, out entryId) &&
                   !string.IsNullOrWhiteSpace(entryId);
        }

        private static void AddBattleResultDebugSample(ICollection<string> samples, string value)
        {
            if (samples == null || string.IsNullOrWhiteSpace(value) || samples.Count >= MaxBattleResultDebugSampleCount)
                return;

            samples.Add(value);
        }

        private static void TryTrackMaterializedBattleResultScoreHit(
            Agent affectedAgent,
            Agent affectorAgent,
            WeaponComponentData attackerWeapon,
            bool isBlocked,
            bool isSiegeEngineHit,
            in Blow blow,
            in AttackCollisionData collisionData,
            float damagedHp,
            float hitDistance,
            float shotDifficulty)
        {
            if (affectorAgent == null || affectedAgent == null || affectorAgent.Mission == null || damagedHp <= 0.01f)
                return;

            Agent normalizedAffectorAgent = NormalizeBattleResultCombatAffectorAgent(affectorAgent);
            if (normalizedAffectorAgent == null || normalizedAffectorAgent.Mission == null)
                return;

            CoopBattlePhase currentPhase = CoopBattlePhaseRuntimeState.GetPhase();
            if (currentPhase < CoopBattlePhase.BattleActive || currentPhase >= CoopBattlePhase.BattleEnded)
                return;

            _materializedBattleResultOnScoreHitCount++;

            MaterializedBattleResultEntryRuntimeState attackerEntry = TryGetMaterializedBattleResultEntryByAgent(normalizedAffectorAgent, out string attackerEntryId);
            MaterializedBattleResultEntryRuntimeState victimEntry = TryGetMaterializedBattleResultEntryByAgent(affectedAgent, out string victimEntryId);
            if (attackerEntry == null && victimEntry == null)
                return;

            if (attackerEntry != null)
            {
                attackerEntry.ScoreHitCount++;
                attackerEntry.DamageDealt += Math.Max(0f, damagedHp);
            }

            if (victimEntry != null)
            {
                victimEntry.HitsTakenCount++;
                victimEntry.DamageTaken += Math.Max(0f, damagedHp);
            }

            WeaponFlags weaponFlags = attackerWeapon?.WeaponFlags ?? (WeaponFlags)0;
            if (weaponFlags == (WeaponFlags)0)
                weaponFlags = blow.WeaponRecord.WeaponFlags;
            _materializedBattleResultLastHitDebugByVictimAgentIndex[affectedAgent.Index] = new MaterializedBattleResultLastHitDebugState
            {
                AttackerAgentIndex = normalizedAffectorAgent.Index,
                DamageType = ((DamageTypes)collisionData.DamageType).ToString(),
                WeaponClass = ResolveCombatEventWeaponClassHint(attackerWeapon),
                WeaponFlags = weaponFlags.ToString(),
                CanKillEvenIfBlunt = (weaponFlags & WeaponFlags.CanKillEvenIfBlunt) != 0,
                IsHorseCharge = collisionData.IsHorseCharge,
                IsAlternativeAttack = collisionData.IsAlternativeAttack,
                IsFallDamage = collisionData.IsFallDamage,
                IsMissile = collisionData.IsMissile,
                IsBlocked = isBlocked,
                IsSiegeEngineHit = isSiegeEngineHit,
                VictimBodyPart = collisionData.VictimHitBodyPart.ToString(),
                IsHeadShot = collisionData.VictimHitBodyPart == BoneBodyPartType.Head,
                BlowBaseMagnitude = blow.BaseMagnitude,
                CollisionBaseMagnitude = collisionData.BaseMagnitude,
                AbsorbedByArmor = collisionData.AbsorbedByArmor,
                MovementSpeedDamageModifier = collisionData.MovementSpeedDamageModifier,
                MissileVelocity = collisionData.MissileVelocity.Length,
                MissileStartSpeed = collisionData.MissileStartingBaseSpeed,
                MissileTotalDamage = collisionData.MissileTotalDamage,
                Damage = Math.Max(0f, damagedHp),
                MissionTime = normalizedAffectorAgent.Mission.CurrentTime
            };
            AddBattleResultDebugSample(
                _materializedBattleResultOnScoreHitSamples,
                "V=" + affectedAgent.Index +
                " A=" + normalizedAffectorAgent.Index +
                " DmgType=" + ((DamageTypes)collisionData.DamageType) +
                " Horse=" + collisionData.IsHorseCharge +
                " Alt=" + collisionData.IsAlternativeAttack +
                " Fall=" + collisionData.IsFallDamage +
                " Blocked=" + isBlocked +
                " BodyPart=" + collisionData.VictimHitBodyPart +
                " Siege=" + isSiegeEngineHit +
                " Dmg=" + Math.Max(0f, damagedHp).ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) +
                " Flags=" + weaponFlags);

            if (_materializedBattleResultCombatEvents.Count >= MaxRecordedBattleResultCombatEvents)
            {
                _droppedMaterializedBattleResultCombatEventCount++;
                return;
            }

            string weaponItemId = ResolveCombatEventWeaponItemId(normalizedAffectorAgent, attackerWeapon);
            ResolveCombatEventCaptainIdentity(
                normalizedAffectorAgent,
                attackerEntry,
                out string captainHeroId,
                out string captainCharacterId,
                out string captainOriginalCharacterId);
            string commanderHeroId = ResolveCombatEventCommanderHeroId(normalizedAffectorAgent, attackerEntry);
            string attackerCharacterId;
            string attackerOriginalCharacterId;
            ResolveBattleResultCharacterIds(normalizedAffectorAgent, attackerEntry, out attackerCharacterId, out attackerOriginalCharacterId);
            string victimCharacterId;
            string victimOriginalCharacterId;
            ResolveBattleResultCharacterIds(affectedAgent, victimEntry, out victimCharacterId, out victimOriginalCharacterId);
            float hitPointRatio = affectedAgent.HealthLimit > 0f
                ? Math.Max(0f, Math.Min(Math.Max(0f, damagedHp), affectedAgent.HealthLimit) / Math.Max(1f, affectedAgent.HealthLimit))
                : 0f;

            _materializedBattleResultCombatEvents.Add(new CoopBattleResultBridgeFile.BattleResultCombatEventSnapshot
            {
                AttackerEntryId = attackerEntryId,
                AttackerSideId = attackerEntry?.SideId,
                AttackerPartyId = attackerEntry?.PartyId,
                AttackerCharacterId = attackerCharacterId,
                AttackerOriginalCharacterId = attackerOriginalCharacterId,
                WeaponItemId = weaponItemId,
                CaptainHeroId = captainHeroId,
                CaptainCharacterId = captainCharacterId,
                CaptainOriginalCharacterId = captainOriginalCharacterId,
                CommanderHeroId = commanderHeroId,
                VictimEntryId = victimEntryId,
                VictimSideId = victimEntry?.SideId,
                VictimPartyId = victimEntry?.PartyId,
                VictimCharacterId = victimCharacterId,
                VictimOriginalCharacterId = victimOriginalCharacterId,
                WeaponSkillHint = ResolveCombatEventSkillHint(attackerWeapon, affectorAgent, isSiegeEngineHit),
                WeaponClassHint = ResolveCombatEventWeaponClassHint(attackerWeapon),
                IsBlocked = isBlocked,
                IsSiegeEngineHit = isSiegeEngineHit,
                IsTeamKill = normalizedAffectorAgent.Team != null && normalizedAffectorAgent.Team == affectedAgent.Team,
                IsFatal = false,
                IsAttackerMounted = normalizedAffectorAgent.MountAgent != null,
                IsAttackerUnderCommand = ResolveCombatEventIsAttackerUnderCommand(normalizedAffectorAgent, attackerEntry, commanderHeroId),
                IsHorseCharge = collisionData.IsHorseCharge,
                IsSneakAttack = collisionData.IsSneakAttack,
                Damage = Math.Max(0f, damagedHp),
                HitDistance = Math.Max(0f, hitDistance),
                MovementSpeedBonus = Math.Max(0f, collisionData.MovementSpeedDamageModifier),
                HitPointRatio = hitPointRatio,
                ShotDifficulty = Math.Max(0f, shotDifficulty),
                MissionTime = normalizedAffectorAgent.Mission.CurrentTime
            });
        }

        private static void TryTrackMaterializedBattleResultRemoval(Agent affectedAgent, Agent affectorAgent, AgentState agentState)
        {
            if (affectedAgent == null || affectedAgent.IsMount || affectedAgent.Mission == null)
                return;

            CoopBattlePhase currentPhase = CoopBattlePhaseRuntimeState.GetPhase();
            if (currentPhase < CoopBattlePhase.BattleActive || currentPhase >= CoopBattlePhase.BattleEnded)
                return;

            _materializedBattleResultOnAgentRemovedCount++;
            AddBattleResultDebugSample(
                _materializedBattleResultOnAgentRemovedSamples,
                "V=" + affectedAgent.Index +
                " A=" + (affectorAgent?.Index.ToString() ?? "none") +
                " State=" + agentState +
                " Health=" + affectedAgent.Health.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture));

            if (!TryRefreshMaterializedAgentIdentityCache(
                    affectedAgent,
                    out string entryId,
                    out BattleSideEnum side,
                    out bool requiresRegistration,
                    "battle-result-removal-victim",
                    logRefresh: true))
            {
                return;
            }

            if (requiresRegistration)
            {
                RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
                if (entryState != null)
                    RegisterMaterializedBattleResultEntry(affectedAgent, entryState, side);
            }

            if (!_materializedBattleResultSpawnInstanceIdsByAgentIndex.TryGetValue(affectedAgent.Index, out string spawnInstanceId))
            {
                _nextMaterializedBattleResultSpawnOrdinal++;
                string battleInstanceId = BattleSnapshotRuntimeState.GetCurrent()?.BattleInstanceId ?? "legacy";
                spawnInstanceId = battleInstanceId + "|" + entryId + "|" + _nextMaterializedBattleResultSpawnOrdinal.ToString(System.Globalization.CultureInfo.InvariantCulture);
                _materializedBattleResultSpawnInstanceIdsByAgentIndex[affectedAgent.Index] = spawnInstanceId;
            }

            if (!_materializedBattleResultTerminalSpawnInstanceIds.Add(spawnInstanceId))
                return;

            _materializedBattleResultRemovedAgentIndices.Add(affectedAgent.Index);

            if (!_materializedBattleResultEntriesByEntryId.TryGetValue(entryId, out MaterializedBattleResultEntryRuntimeState state) || state == null)
                return;

            state.ActiveCount = Math.Max(0, state.ActiveCount - 1);
            state.RemovedCount++;

            string removedState = agentState.ToString();
            if (string.Equals(removedState, "Killed", StringComparison.OrdinalIgnoreCase))
                state.KilledCount++;
            else if (string.Equals(removedState, "Unconscious", StringComparison.OrdinalIgnoreCase))
                state.UnconsciousCount++;
            else if (string.Equals(removedState, "Routed", StringComparison.OrdinalIgnoreCase))
                state.RoutedCount++;
            else
                state.OtherRemovedCount++;

            MaterializedBattleResultEntryRuntimeState attackerState = TryGetMaterializedBattleResultEntryByAgent(affectorAgent, out string attackerEntryId);
            if (attackerState != null)
            {
                if (string.Equals(removedState, "Killed", StringComparison.OrdinalIgnoreCase))
                {
                    attackerState.KillsInflictedCount++;
                    attackerState.FatalHitCount++;
                }
                else if (string.Equals(removedState, "Unconscious", StringComparison.OrdinalIgnoreCase))
                    attackerState.UnconsciousInflictedCount++;
                else if (string.Equals(removedState, "Routed", StringComparison.OrdinalIgnoreCase))
                    attackerState.RoutedInflictedCount++;
            }

            if (string.Equals(removedState, "Killed", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(removedState, "Unconscious", StringComparison.OrdinalIgnoreCase))
            {
                _materializedBattleResultLastHitDebugByVictimAgentIndex.TryGetValue(
                    affectedAgent.Index,
                    out MaterializedBattleResultLastHitDebugState lastHit);
                _materializedBattleResultCasualtyEvents.Add(new CoopBattleResultBridgeFile.BattleResultCasualtyEventSnapshot
                {
                    CasualtyEventId = spawnInstanceId + "|terminal",
                    SpawnInstanceId = spawnInstanceId,
                    Outcome = string.Equals(removedState, "Killed", StringComparison.OrdinalIgnoreCase) ? "Killed" : "Wounded",
                    VictimEntryId = entryId,
                    VictimSideId = state.SideId,
                    VictimPartyId = state.PartyId,
                    VictimCharacterId = state.CharacterId,
                    VictimOriginalCharacterId = state.OriginalCharacterId,
                    VictimHeroId = state.HeroId,
                    VictimIsHero = state.IsHero,
                    AttackerEntryId = attackerEntryId,
                    AttackerPartyId = attackerState?.PartyId,
                    DamageType = lastHit?.DamageType,
                    WeaponFlags = lastHit?.WeaponFlags,
                    MissionTime = affectedAgent.Mission?.CurrentTime ?? 0f
                });
            }

            bool matchedExistingCombatEvent = false;
            if (_materializedBattleResultCombatEvents.Count > 0)
            {
                for (int i = _materializedBattleResultCombatEvents.Count - 1; i >= 0; i--)
                {
                    CoopBattleResultBridgeFile.BattleResultCombatEventSnapshot combatEvent = _materializedBattleResultCombatEvents[i];
                    if (combatEvent == null)
                        continue;

                    if (!string.Equals(combatEvent.VictimEntryId, entryId, StringComparison.OrdinalIgnoreCase))
                        continue;

                    matchedExistingCombatEvent = true;
                    if (combatEvent.IsFatal)
                        break;

                    combatEvent.IsFatal = string.Equals(removedState, "Killed", StringComparison.OrdinalIgnoreCase);
                    break;
                }
            }

            TryTrackSyntheticRemovalCombatEvent(
                affectedAgent,
                affectorAgent,
                removedState,
                entryId,
                state,
                attackerState,
                matchedExistingCombatEvent);
        }

        private static void TryLogMaterializedBattleResultRemovalDebug(
            Agent affectedAgent,
            Agent affectorAgent,
            AgentState agentState,
            KillingBlow killingBlow)
        {
            if (!ExperimentalFeatures.EnableExactCampaignArmyRuntimeDiagnostics ||
                affectedAgent == null ||
                affectedAgent.IsMount ||
                affectedAgent.Mission == null)
            {
                return;
            }

            _materializedBattleResultRemovalDebugLogCount++;

            TryRefreshMaterializedAgentIdentityCache(
                affectedAgent,
                out string victimEntryId,
                out _,
                out _,
                "battle-result-removal-debug-victim",
                logRefresh: true);
            TryRefreshMaterializedAgentIdentityCache(
                affectorAgent,
                out string attackerEntryId,
                out _,
                out _,
                "battle-result-removal-debug-attacker",
                logRefresh: true);
            string removedState = agentState.ToString();
            string victimCharacterId = (affectedAgent.Character as BasicCharacterObject)?.StringId ?? string.Empty;
            string attackerCharacterId = (affectorAgent?.Character as BasicCharacterObject)?.StringId ?? string.Empty;
            WeaponFlags killingBlowFlags = killingBlow.WeaponRecordWeaponFlags;
            bool canKillEvenIfBlunt = (killingBlowFlags & WeaponFlags.CanKillEvenIfBlunt) != 0;

            _materializedBattleResultLastHitDebugByVictimAgentIndex.TryGetValue(affectedAgent.Index, out MaterializedBattleResultLastHitDebugState lastHit);

            ModLogger.Info(
                "CoopMissionSpawnLogic: removal debug. " +
                "VictimAgent=" + affectedAgent.Index +
                " VictimEntry=" + (victimEntryId ?? string.Empty) +
                " VictimCharacter=" + (victimCharacterId ?? string.Empty) +
                " AttackerAgent=" + (affectorAgent?.Index.ToString() ?? "none") +
                " AttackerEntry=" + (attackerEntryId ?? string.Empty) +
                " AttackerCharacter=" + (attackerCharacterId ?? string.Empty) +
                " RemovedState=" + removedState +
                " KillingBlow[Valid=" + killingBlow.IsValid +
                " DamageType=" + killingBlow.DamageType +
                " AttackType=" + killingBlow.AttackType +
                " WeaponClass=" + ((WeaponClass)killingBlow.WeaponClass) +
                " WeaponFlags=" + killingBlowFlags +
                " CanKillEvenIfBlunt=" + canKillEvenIfBlunt +
                " IsMissile=" + killingBlow.IsMissile +
                " InflictedDamage=" + killingBlow.InflictedDamage + "]" +
                " LastHit[" + BuildMaterializedBattleResultLastHitDebugSummary(lastHit) + "].");

            _materializedBattleResultLastHitDebugByVictimAgentIndex.Remove(affectedAgent.Index);
        }

        private static string BuildMaterializedBattleResultLastHitDebugSummary(MaterializedBattleResultLastHitDebugState state)
        {
            if (state == null)
                return "none";

            return
                "AttackerAgent=" + state.AttackerAgentIndex +
                " DamageType=" + (state.DamageType ?? string.Empty) +
                " WeaponClass=" + (state.WeaponClass ?? string.Empty) +
                " WeaponFlags=" + (state.WeaponFlags ?? string.Empty) +
                " CanKillEvenIfBlunt=" + state.CanKillEvenIfBlunt +
                " HorseCharge=" + state.IsHorseCharge +
                " AltAttack=" + state.IsAlternativeAttack +
                " FallDamage=" + state.IsFallDamage +
                " Missile=" + state.IsMissile +
                " Blocked=" + state.IsBlocked +
                " Siege=" + state.IsSiegeEngineHit +
                " BodyPart=" + (state.VictimBodyPart ?? string.Empty) +
                " HeadShot=" + state.IsHeadShot +
                " BlowBaseMagnitude=" + state.BlowBaseMagnitude.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                " CollisionBaseMagnitude=" + state.CollisionBaseMagnitude +
                " AbsorbedByArmor=" + state.AbsorbedByArmor +
                " MoveSpeedMod=" + state.MovementSpeedDamageModifier.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                " MissileVelocity=" + state.MissileVelocity.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                " MissileStartSpeed=" + state.MissileStartSpeed.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                " MissileTotalDamage=" + state.MissileTotalDamage.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                " Damage=" + state.Damage.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) +
                " MissionTime=" + state.MissionTime.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture);
        }

        private static void ClearMaterializedAgentIndexScopedRuntimeCaches(
            int agentIndex,
            bool clearRemovedGuard,
            bool preserveClientMountedHeroPayloadState = false)
        {
            if (agentIndex < 0)
                return;

            if (_materializedArmyEntryIdByAgentIndex.Remove(agentIndex))
                MarkAuthoritativeMaterializedAgentEntryCacheDirty();
            _materializedArmySideByAgentIndex.Remove(agentIndex);
            _materializedAgentInstanceByIndex.Remove(agentIndex);
            _customAiTargetPulseStateByAgentIndex.Remove(agentIndex);
            _clientAuthoritativeMaterializedEntryObservedAgentIndices.Remove(agentIndex);
            _materializedCombatProfilesByAgentIndex.Remove(agentIndex);
            _materializedBattleResultSpawnInstanceIdsByAgentIndex.Remove(agentIndex);
            _materializedBattleResultLastHitDebugByVictimAgentIndex.Remove(agentIndex);
            if (clearRemovedGuard)
                _materializedBattleResultRemovedAgentIndices.Remove(agentIndex);
            _exactNativeSnapshotOverlayAppliedAgentIndices.Remove(agentIndex);
            ClearClientExactCampaignVisualOverlayAgentIndexState(agentIndex, "clear-materialized-agent-index-runtime-caches");
            if (!preserveClientMountedHeroPayloadState)
                ExactTransferContractRuntimeCache.TryCompleteCleanupForAgentIndex(agentIndex, "clear-materialized-agent-index-runtime-caches");
            if (!preserveClientMountedHeroPayloadState)
                ClearClientMountedHeroPayloadMountAgentIndexState(agentIndex);
        }

        private static bool TryRefreshMaterializedAgentIdentityCache(
            Agent agent,
            out string entryId,
            out BattleSideEnum side,
            out bool requiresRegistration,
            string source = null,
            bool logRefresh = false)
        {
            entryId = null;
            side = BattleSideEnum.None;
            requiresRegistration = false;
            if (agent == null || agent.IsMount)
                return false;

            bool hadCachedEntry = _materializedArmyEntryIdByAgentIndex.TryGetValue(agent.Index, out string cachedEntryId) &&
                                  !string.IsNullOrWhiteSpace(cachedEntryId);
            bool hadCachedSide = _materializedArmySideByAgentIndex.TryGetValue(agent.Index, out BattleSideEnum cachedSide) &&
                                 cachedSide != BattleSideEnum.None;
            bool hadCachedAgentInstance = _materializedAgentInstanceByIndex.TryGetValue(agent.Index, out Agent cachedAgentInstance);
            bool agentIndexRebound = hadCachedAgentInstance && !ReferenceEquals(cachedAgentInstance, agent);

            string exactEntryId = null;
            ExactCampaignArmyBootstrap.TryGetEntryId(agent, out exactEntryId);
            BattleSideEnum exactSide = BattleSideEnum.None;
            ExactCampaignArmyBootstrap.TryGetSide(agent, out exactSide);

            string resolvedEntryId = !string.IsNullOrWhiteSpace(exactEntryId)
                ? exactEntryId
                : cachedEntryId;
            BattleSideEnum resolvedSide = exactSide != BattleSideEnum.None
                ? exactSide
                : cachedSide;

            if (string.IsNullOrWhiteSpace(resolvedEntryId))
                return false;

            bool entryChanged = !hadCachedEntry || !string.Equals(cachedEntryId, resolvedEntryId, StringComparison.OrdinalIgnoreCase);
            bool sideChanged = resolvedSide != BattleSideEnum.None &&
                               (!hadCachedSide || cachedSide != resolvedSide);
            bool shouldResetIndexState = agentIndexRebound || (hadCachedEntry && entryChanged) || (hadCachedSide && sideChanged);
            bool clearedRemovedGuard = false;

            if (shouldResetIndexState)
            {
                clearedRemovedGuard = _materializedBattleResultRemovedAgentIndices.Contains(agent.Index);
                ClearMaterializedAgentIndexScopedRuntimeCaches(
                    agent.Index,
                    clearRemovedGuard: true,
                    preserveClientMountedHeroPayloadState: true);
            }
            else if (agent.IsActive())
            {
                clearedRemovedGuard = _materializedBattleResultRemovedAgentIndices.Remove(agent.Index);
            }

            _materializedAgentInstanceByIndex[agent.Index] = agent;
            _materializedArmyEntryIdByAgentIndex[agent.Index] = resolvedEntryId;
            if (GameNetwork.IsServer &&
                (agentIndexRebound || entryChanged || sideChanged || !hadCachedEntry))
            {
                TrackAuthoritativeMaterializedAgentEntryLedgerMapping(
                    agent.Mission,
                    agent.Index,
                    resolvedEntryId);
            }
            if (resolvedSide != BattleSideEnum.None)
                _materializedArmySideByAgentIndex[agent.Index] = resolvedSide;

            requiresRegistration =
                shouldResetIndexState ||
                clearedRemovedGuard ||
                !hadCachedEntry;
            entryId = resolvedEntryId;
            side = resolvedSide;

            if (logRefresh && (shouldResetIndexState || clearedRemovedGuard))
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: refreshed materialized agent identity cache from exact origin. " +
                    "AgentIndex=" + agent.Index +
                    " PreviousEntryId=" + (cachedEntryId ?? "null") +
                    " EntryId=" + resolvedEntryId +
                    " PreviousSide=" + (hadCachedSide ? cachedSide.ToString() : "none") +
                    " Side=" + (resolvedSide == BattleSideEnum.None ? "none" : resolvedSide.ToString()) +
                    " Character=" + ((agent.Character as BasicCharacterObject)?.StringId ?? "null") +
                    " Rebound=" + agentIndexRebound +
                    " ClearedRemovedGuard=" + clearedRemovedGuard +
                    " Source=" + (source ?? "unknown"));
            }

            return true;
        }

        private static MaterializedBattleResultEntryRuntimeState TryGetMaterializedBattleResultEntryByAgent(Agent agent, out string entryId)
        {
            entryId = null;
            if (!TryRefreshMaterializedAgentIdentityCache(
                    agent,
                    out entryId,
                    out BattleSideEnum side,
                    out bool requiresRegistration,
                    "battle-result-agent-resolve"))
            {
                return null;
            }

            if (requiresRegistration)
            {
                RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
                if (entryState != null)
                    RegisterMaterializedBattleResultEntry(agent, entryState, side);
            }

            if (!_materializedBattleResultEntriesByEntryId.TryGetValue(entryId, out MaterializedBattleResultEntryRuntimeState state))
                return null;

            return state;
        }

        private static Agent NormalizeBattleResultCombatAffectorAgent(Agent affectorAgent)
        {
            if (affectorAgent == null)
                return null;

            try
            {
                if (affectorAgent.IsMount && affectorAgent.RiderAgent != null)
                    return affectorAgent.RiderAgent;
            }
            catch
            {
            }

            return affectorAgent;
        }

        private static void ResolveBattleResultCharacterIds(
            Agent agent,
            MaterializedBattleResultEntryRuntimeState entryState,
            out string characterId,
            out string originalCharacterId)
        {
            characterId = entryState?.CharacterId;
            originalCharacterId = entryState?.OriginalCharacterId;

            BasicCharacterObject character = agent?.Character as BasicCharacterObject;
            if (string.IsNullOrWhiteSpace(characterId))
                characterId = character?.StringId ?? string.Empty;
            if (string.IsNullOrWhiteSpace(originalCharacterId))
                originalCharacterId = character?.StringId ?? string.Empty;
        }

        private static string ResolveCombatEventWeaponItemId(Agent affectorAgent, WeaponComponentData attackerWeapon)
        {
            try
            {
                MissionWeapon wieldedWeapon = affectorAgent?.WieldedWeapon ?? MissionWeapon.Invalid;
                string wieldedItemId = wieldedWeapon.Item?.StringId;
                if (!string.IsNullOrWhiteSpace(wieldedItemId))
                    return wieldedItemId;
            }
            catch
            {
            }

            MissionEquipment affectorEquipment = affectorAgent?.Equipment;
            ItemObject primaryItem = TryResolveAgentPrimaryCombatItem(affectorAgent, affectorEquipment, out _, out _);
            if (!string.IsNullOrWhiteSpace(primaryItem?.StringId))
                return primaryItem.StringId;

            return string.Empty;
        }

        private static void ResolveCombatEventCaptainIdentity(
            Agent affectorAgent,
            MaterializedBattleResultEntryRuntimeState attackerEntry,
            out string captainHeroId,
            out string captainCharacterId,
            out string captainOriginalCharacterId)
        {
            captainHeroId = string.Empty;
            captainCharacterId = string.Empty;
            captainOriginalCharacterId = string.Empty;

            Agent captainAgent = null;
            try
            {
                captainAgent = affectorAgent?.Formation?.Captain;
            }
            catch
            {
                captainAgent = null;
            }

            captainAgent = NormalizeBattleResultCombatAffectorAgent(captainAgent);
            if (captainAgent != null && !ReferenceEquals(captainAgent, affectorAgent))
            {
                MaterializedBattleResultEntryRuntimeState captainEntry = TryGetMaterializedBattleResultEntryByAgent(captainAgent, out _);
                captainHeroId = captainEntry?.HeroId ?? string.Empty;
                ResolveBattleResultCharacterIds(captainAgent, captainEntry, out captainCharacterId, out captainOriginalCharacterId);
                if (!string.IsNullOrWhiteSpace(captainHeroId) || !string.IsNullOrWhiteSpace(captainCharacterId))
                    return;
            }

            if (string.IsNullOrWhiteSpace(attackerEntry?.PartyId))
                return;

            captainHeroId = TryResolvePartyLeaderHeroIdForCombatEvent(attackerEntry.PartyId);
            if (string.IsNullOrWhiteSpace(captainHeroId))
                return;

            RosterEntryState leaderEntry = TryResolveRuntimeEntryByHeroIdForCombatEvent(attackerEntry.PartyId, captainHeroId);
            if (leaderEntry == null)
                return;

            captainCharacterId = leaderEntry.CharacterId ?? string.Empty;
            captainOriginalCharacterId = leaderEntry.OriginalCharacterId ?? leaderEntry.CharacterId ?? string.Empty;
        }

        private static string ResolveCombatEventCommanderHeroId(
            Agent affectorAgent,
            MaterializedBattleResultEntryRuntimeState attackerEntry)
        {
            Agent commanderAgent = null;
            try
            {
                commanderAgent = affectorAgent?.Team?.Leader;
            }
            catch
            {
                commanderAgent = null;
            }

            commanderAgent = NormalizeBattleResultCombatAffectorAgent(commanderAgent);
            if (commanderAgent != null)
            {
                MaterializedBattleResultEntryRuntimeState commanderEntry = TryGetMaterializedBattleResultEntryByAgent(commanderAgent, out _);
                if (!string.IsNullOrWhiteSpace(commanderEntry?.HeroId))
                    return commanderEntry.HeroId;
            }

            string sideLeaderHeroId = TryResolveSideLeaderHeroIdForCombatEvent(attackerEntry?.SideId);
            if (!string.IsNullOrWhiteSpace(sideLeaderHeroId))
                return sideLeaderHeroId;

            return TryResolvePartyLeaderHeroIdForCombatEvent(attackerEntry?.PartyId);
        }

        private static bool ResolveCombatEventIsAttackerUnderCommand(
            Agent affectorAgent,
            MaterializedBattleResultEntryRuntimeState attackerEntry,
            string commanderHeroId)
        {
            if (affectorAgent == null || string.IsNullOrWhiteSpace(commanderHeroId))
                return false;

            if (!string.IsNullOrWhiteSpace(attackerEntry?.HeroId) &&
                string.Equals(attackerEntry.HeroId, commanderHeroId, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            return true;
        }

        private static string TryResolvePartyLeaderHeroIdForCombatEvent(string partyId)
        {
            if (string.IsNullOrWhiteSpace(partyId))
                return string.Empty;

            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            if (runtimeState?.PartiesById == null ||
                !runtimeState.PartiesById.TryGetValue(partyId, out BattlePartyState partyState))
            {
                return string.Empty;
            }

            return partyState?.Modifiers?.LeaderHeroId ?? string.Empty;
        }

        private static string TryResolveSideLeaderHeroIdForCombatEvent(string sideId)
        {
            if (string.IsNullOrWhiteSpace(sideId))
                return string.Empty;

            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            if (runtimeState?.SidesByKey == null ||
                !runtimeState.SidesByKey.TryGetValue(sideId, out BattleSideState sideState))
            {
                return string.Empty;
            }

            return TryResolvePartyLeaderHeroIdForCombatEvent(sideState?.LeaderPartyId);
        }

        private static RosterEntryState TryResolveRuntimeEntryByHeroIdForCombatEvent(string partyId, string heroId)
        {
            if (string.IsNullOrWhiteSpace(partyId) || string.IsNullOrWhiteSpace(heroId))
                return null;

            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            if (runtimeState?.PartiesById == null ||
                !runtimeState.PartiesById.TryGetValue(partyId, out BattlePartyState partyState) ||
                partyState?.Entries == null)
            {
                return null;
            }

            return partyState.Entries.FirstOrDefault(entry =>
                entry != null &&
                string.Equals(entry.HeroId, heroId, StringComparison.OrdinalIgnoreCase));
        }

        private static string ResolveCombatEventSkillHint(WeaponComponentData attackerWeapon, Agent affectorAgent, bool isSiegeEngineHit)
        {
            try
            {
                SkillObject relevantSkill = attackerWeapon?.RelevantSkill;
                if (!string.IsNullOrWhiteSpace(relevantSkill?.StringId))
                    return relevantSkill.StringId;
            }
            catch
            {
            }

            if (attackerWeapon != null)
            {
                string byWeaponClass = MapCombatEventWeaponClassToSkillHint(attackerWeapon.WeaponClass.ToString(), isSiegeEngineHit);
                if (!string.IsNullOrWhiteSpace(byWeaponClass))
                    return byWeaponClass;
            }

            MissionEquipment affectorEquipment = affectorAgent?.Equipment;
            ItemObject primaryItem = TryResolveAgentPrimaryCombatItem(affectorAgent, affectorEquipment, out WeaponComponentData primaryWeapon, out SkillObject relevantSkillObject);
            if (primaryItem != null)
            {
                if (!string.IsNullOrWhiteSpace(relevantSkillObject?.StringId))
                    return relevantSkillObject.StringId;

                if (primaryWeapon != null)
                {
                    string byPrimaryWeaponClass = MapCombatEventWeaponClassToSkillHint(primaryWeapon.WeaponClass.ToString(), isSiegeEngineHit);
                    if (!string.IsNullOrWhiteSpace(byPrimaryWeaponClass))
                        return byPrimaryWeaponClass;
                }
            }

            return string.Empty;
        }

        private static string ResolveCombatEventWeaponClassHint(WeaponComponentData attackerWeapon)
        {
            try
            {
                return attackerWeapon?.WeaponClass.ToString() ?? string.Empty;
            }
            catch
            {
                return string.Empty;
            }
        }

        private static void TryTrackSyntheticRemovalCombatEvent(
            Agent affectedAgent,
            Agent affectorAgent,
            string removedState,
            string victimEntryId,
            MaterializedBattleResultEntryRuntimeState victimEntry,
            MaterializedBattleResultEntryRuntimeState attackerEntry,
            bool matchedExistingCombatEvent)
        {
            Agent normalizedAffectorAgent = NormalizeBattleResultCombatAffectorAgent(affectorAgent);
            if (matchedExistingCombatEvent ||
                affectedAgent == null ||
                victimEntry == null ||
                normalizedAffectorAgent == null ||
                attackerEntry == null ||
                _materializedBattleResultCombatEvents.Count >= MaxRecordedBattleResultCombatEvents)
            {
                return;
            }

            bool isFatal = string.Equals(removedState, "Killed", StringComparison.OrdinalIgnoreCase);
            bool isUnconscious = string.Equals(removedState, "Unconscious", StringComparison.OrdinalIgnoreCase);
            if (!isFatal && !isUnconscious)
                return;

            WeaponComponentData attackerWeapon = TryResolveCurrentWeaponComponent(normalizedAffectorAgent);
            float syntheticDamage = Math.Max(1f, affectedAgent.HealthLimit);
            attackerEntry.ScoreHitCount++;
            attackerEntry.DamageDealt += syntheticDamage;
            victimEntry.HitsTakenCount++;
            victimEntry.DamageTaken += syntheticDamage;

            string attackerEntryId;
            TryGetMaterializedBattleResultEntryByAgent(normalizedAffectorAgent, out attackerEntryId);
            ResolveBattleResultCharacterIds(normalizedAffectorAgent, attackerEntry, out string attackerCharacterId, out string attackerOriginalCharacterId);
            ResolveBattleResultCharacterIds(affectedAgent, victimEntry, out string victimCharacterId, out string victimOriginalCharacterId);
            ResolveCombatEventCaptainIdentity(
                normalizedAffectorAgent,
                attackerEntry,
                out string captainHeroId,
                out string captainCharacterId,
                out string captainOriginalCharacterId);
            string commanderHeroId = ResolveCombatEventCommanderHeroId(normalizedAffectorAgent, attackerEntry);

            _materializedBattleResultCombatEvents.Add(new CoopBattleResultBridgeFile.BattleResultCombatEventSnapshot
            {
                AttackerEntryId = attackerEntryId,
                AttackerSideId = attackerEntry.SideId,
                AttackerPartyId = attackerEntry.PartyId,
                AttackerCharacterId = attackerCharacterId,
                AttackerOriginalCharacterId = attackerOriginalCharacterId,
                WeaponItemId = ResolveCombatEventWeaponItemId(normalizedAffectorAgent, attackerWeapon),
                CaptainHeroId = captainHeroId,
                CaptainCharacterId = captainCharacterId,
                CaptainOriginalCharacterId = captainOriginalCharacterId,
                CommanderHeroId = commanderHeroId,
                VictimEntryId = victimEntryId,
                VictimSideId = victimEntry.SideId,
                VictimPartyId = victimEntry.PartyId,
                VictimCharacterId = victimCharacterId,
                VictimOriginalCharacterId = victimOriginalCharacterId,
                WeaponSkillHint = ResolveCombatEventSkillHint(attackerWeapon, affectorAgent, false),
                WeaponClassHint = ResolveCombatEventWeaponClassHint(attackerWeapon),
                IsBlocked = false,
                IsSiegeEngineHit = false,
                IsTeamKill = normalizedAffectorAgent.Team != null && normalizedAffectorAgent.Team == affectedAgent.Team,
                IsFatal = isFatal,
                IsAttackerMounted = normalizedAffectorAgent.MountAgent != null,
                IsAttackerUnderCommand = ResolveCombatEventIsAttackerUnderCommand(normalizedAffectorAgent, attackerEntry, commanderHeroId),
                IsHorseCharge = false,
                IsSneakAttack = false,
                Damage = syntheticDamage,
                HitDistance = 0f,
                MovementSpeedBonus = 0f,
                HitPointRatio = 1f,
                ShotDifficulty = 0f,
                MissionTime = affectedAgent.Mission?.CurrentTime ?? 0f
            });
        }

        private static WeaponComponentData TryResolveCurrentWeaponComponent(Agent agent)
        {
            try
            {
                MissionWeapon wieldedWeapon = agent?.WieldedWeapon ?? MissionWeapon.Invalid;
                return wieldedWeapon.CurrentUsageItem;
            }
            catch
            {
                return null;
            }
        }

        private static string MapCombatEventWeaponClassToSkillHint(string weaponClass, bool isSiegeEngineHit)
        {
            if (isSiegeEngineHit)
                return "SiegeEngine";

            string normalized = weaponClass ?? string.Empty;
            if (normalized.IndexOf("Crossbow", StringComparison.OrdinalIgnoreCase) >= 0)
                return "Crossbow";
            if (normalized.IndexOf("Bow", StringComparison.OrdinalIgnoreCase) >= 0)
                return "Bow";
            if (normalized.IndexOf("Throw", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Javelin", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Stone", StringComparison.OrdinalIgnoreCase) >= 0)
                return "Throwing";
            if (normalized.IndexOf("Polearm", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Spear", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Lance", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Pike", StringComparison.OrdinalIgnoreCase) >= 0)
                return "Polearm";
            if (normalized.IndexOf("TwoHanded", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("TwoHand", StringComparison.OrdinalIgnoreCase) >= 0)
                return "TwoHanded";
            if (normalized.IndexOf("OneHanded", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("OneHand", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Mace", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Axe", StringComparison.OrdinalIgnoreCase) >= 0 || normalized.IndexOf("Sword", StringComparison.OrdinalIgnoreCase) >= 0)
                return "OneHanded";
            return string.Empty;
        }

        private static void TryWriteBattleResultSnapshot(Mission mission, string source)
        {
            if (mission == null || !GameNetwork.IsServer)
                return;

            EnsureMaterializedBattleResultMission(mission);
            if (_hasWrittenBattleResultSnapshotForMission)
                return;

            CoopBattleResultBridgeFile.BattleResultSnapshot snapshot = BuildBattleResultSnapshot(mission, source);
            if (snapshot == null)
                return;

            if (!CoopBattleResultBridgeFile.WriteResult(snapshot))
                return;

            _hasWrittenBattleResultSnapshotForMission = true;
            ModLogger.Info(
                "CoopMissionSpawnLogic: battle result snapshot written. " +
                "BattleId=" + (snapshot.BattleId ?? "null") +
                " WinnerSide=" + (snapshot.WinnerSide ?? "none") +
                " Entries=" + snapshot.Entries.Count +
                " Summary=[" + BuildBattleResultEntryAuditSummary(snapshot) + "].");
        }

        private static void SynchronizeMaterializedBattleResultActiveCountsFromLiveAgents(Mission mission, string source)
        {
            if (mission?.AllAgents == null || _materializedBattleResultEntriesByEntryId.Count == 0)
                return;

            var activeCountsByEntryId = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < mission.AllAgents.Count; i++)
            {
                Agent agent = mission.AllAgents[i];
                if (agent == null || !agent.IsActive() || agent.IsMount)
                    continue;

                if (!TryRefreshMaterializedAgentIdentityCache(
                        agent,
                        out string entryId,
                        out BattleSideEnum side,
                        out bool requiresRegistration,
                        source))
                {
                    continue;
                }

                if (string.IsNullOrWhiteSpace(entryId))
                    continue;

                if (requiresRegistration)
                {
                    RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
                    if (entryState != null)
                        RegisterMaterializedBattleResultEntry(agent, entryState, side);
                }

                if (!_materializedBattleResultEntriesByEntryId.ContainsKey(entryId))
                    continue;

                activeCountsByEntryId[entryId] =
                    activeCountsByEntryId.TryGetValue(entryId, out int activeCount)
                        ? activeCount + 1
                        : 1;
            }

            foreach (KeyValuePair<string, MaterializedBattleResultEntryRuntimeState> pair in _materializedBattleResultEntriesByEntryId)
            {
                MaterializedBattleResultEntryRuntimeState runtimeState = pair.Value;
                if (runtimeState == null)
                    continue;

                runtimeState.ActiveCount = activeCountsByEntryId.TryGetValue(pair.Key, out int activeCount)
                    ? Math.Max(0, activeCount)
                    : 0;
            }
        }

        private static void ReconcileMaterializedBattleResultStateFromMission(Mission mission, string source)
        {
            if (mission == null || _materializedBattleResultEntriesByEntryId.Count == 0)
                return;

            var countsByEntryId = new Dictionary<string, MaterializedBattleResultReconciledCounts>(StringComparer.OrdinalIgnoreCase);
            foreach (KeyValuePair<string, MaterializedBattleResultEntryRuntimeState> pair in _materializedBattleResultEntriesByEntryId)
            {
                if (pair.Value == null || string.IsNullOrWhiteSpace(pair.Key))
                    continue;

                countsByEntryId[pair.Key] = new MaterializedBattleResultReconciledCounts();
            }

            int trackedAgents = 0;
            int activeTotal = 0;
            int removedTotal = 0;
            int killedTotal = 0;
            int unconsciousTotal = 0;
            int routedTotal = 0;
            int otherRemovedTotal = 0;
            int exactOriginFallbackAgents = 0;
            _materializedBattleResultReconcileRemovedSamples.Clear();

            for (int i = 0; i < mission.AllAgents.Count; i++)
            {
                Agent agent = mission.AllAgents[i];
                if (agent == null || agent.IsMount)
                    continue;

                bool usedExactOriginFallback = false;
                if (!TryRefreshMaterializedAgentIdentityCache(
                        agent,
                        out string entryId,
                        out BattleSideEnum originSide,
                        out bool requiresRegistration,
                        source,
                        logRefresh: true))
                {
                    continue;
                }

                if (string.IsNullOrWhiteSpace(entryId) ||
                    !countsByEntryId.TryGetValue(entryId, out MaterializedBattleResultReconciledCounts counts))
                {
                    continue;
                }

                if (requiresRegistration)
                {
                    usedExactOriginFallback = true;
                    RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
                    if (entryState != null)
                        RegisterMaterializedBattleResultEntry(agent, entryState, originSide);
                }

                if (usedExactOriginFallback)
                    exactOriginFallbackAgents++;

                trackedAgents++;
                counts.ObservedDamageTaken += Math.Max(0f, agent.HealthLimit - agent.Health);
                if (agent.IsActive())
                {
                    counts.ActiveCount++;
                    activeTotal++;
                    continue;
                }

                string stateText = agent.State.ToString();
                if (string.Equals(stateText, "Killed", StringComparison.OrdinalIgnoreCase))
                {
                    counts.KilledCount++;
                    killedTotal++;
                    AddBattleResultDebugSample(
                        _materializedBattleResultReconcileRemovedSamples,
                        "V=" + agent.Index +
                        " Entry=" + entryId +
                        " State=Killed" +
                        " Health=" + agent.Health.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture));
                }
                else if (string.Equals(stateText, "Unconscious", StringComparison.OrdinalIgnoreCase))
                {
                    counts.UnconsciousCount++;
                    unconsciousTotal++;
                    AddBattleResultDebugSample(
                        _materializedBattleResultReconcileRemovedSamples,
                        "V=" + agent.Index +
                        " Entry=" + entryId +
                        " State=Unconscious" +
                        " Health=" + agent.Health.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture));
                }
                else if (string.Equals(stateText, "Routed", StringComparison.OrdinalIgnoreCase))
                {
                    counts.RoutedCount++;
                    routedTotal++;
                    AddBattleResultDebugSample(
                        _materializedBattleResultReconcileRemovedSamples,
                        "V=" + agent.Index +
                        " Entry=" + entryId +
                        " State=Routed" +
                        " Health=" + agent.Health.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture));
                }
                else
                {
                    counts.OtherRemovedCount++;
                    otherRemovedTotal++;
                    AddBattleResultDebugSample(
                        _materializedBattleResultReconcileRemovedSamples,
                        "V=" + agent.Index +
                        " Entry=" + entryId +
                        " State=" + stateText +
                        " Health=" + agent.Health.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture));
                }

                removedTotal++;
            }

            int finalActiveTotal = 0;
            int finalRemovedTotal = 0;
            int finalKilledTotal = 0;
            int finalUnconsciousTotal = 0;
            int finalRoutedTotal = 0;
            int finalOtherRemovedTotal = 0;
            foreach (KeyValuePair<string, MaterializedBattleResultEntryRuntimeState> pair in _materializedBattleResultEntriesByEntryId)
            {
                string entryId = pair.Key;
                MaterializedBattleResultEntryRuntimeState runtimeState = pair.Value;
                if (runtimeState == null || string.IsNullOrWhiteSpace(entryId))
                    continue;

                if (!countsByEntryId.TryGetValue(entryId, out MaterializedBattleResultReconciledCounts counts))
                    counts = new MaterializedBattleResultReconciledCounts();

                int activeCount = Math.Max(0, counts.ActiveCount);
                int killedCount = Math.Max(Math.Max(0, runtimeState.KilledCount), Math.Max(0, counts.KilledCount));
                int unconsciousCount = Math.Max(Math.Max(0, runtimeState.UnconsciousCount), Math.Max(0, counts.UnconsciousCount));
                int routedCount = Math.Max(Math.Max(0, runtimeState.RoutedCount), Math.Max(0, counts.RoutedCount));
                int otherRemovedCount = Math.Max(Math.Max(0, runtimeState.OtherRemovedCount), Math.Max(0, counts.OtherRemovedCount));
                int preservedRemovedCount = Math.Max(0, runtimeState.RemovedCount);
                int classifiedRemovedCount =
                    killedCount +
                    unconsciousCount +
                    routedCount +
                    otherRemovedCount;
                if (preservedRemovedCount > classifiedRemovedCount)
                    otherRemovedCount += preservedRemovedCount - classifiedRemovedCount;

                int accountedCount =
                    activeCount +
                    killedCount +
                    unconsciousCount +
                    routedCount +
                    otherRemovedCount;
                int expectedCount = Math.Max(runtimeState.MaterializedSpawnCount, accountedCount);
                int missingCount = Math.Max(0, expectedCount - accountedCount);
                if (missingCount > 0)
                {
                    otherRemovedCount += missingCount;
                }

                runtimeState.ActiveCount = activeCount;
                runtimeState.KilledCount = killedCount;
                runtimeState.UnconsciousCount = unconsciousCount;
                runtimeState.RoutedCount = routedCount;
                runtimeState.OtherRemovedCount = otherRemovedCount;
                runtimeState.RemovedCount =
                    killedCount +
                    unconsciousCount +
                    routedCount +
                    otherRemovedCount;
                runtimeState.DamageTaken = Math.Max(runtimeState.DamageTaken, Math.Max(0f, counts.ObservedDamageTaken));

                finalActiveTotal += runtimeState.ActiveCount;
                finalRemovedTotal += runtimeState.RemovedCount;
                finalKilledTotal += runtimeState.KilledCount;
                finalUnconsciousTotal += runtimeState.UnconsciousCount;
                finalRoutedTotal += runtimeState.RoutedCount;
                finalOtherRemovedTotal += runtimeState.OtherRemovedCount;
            }

            ModLogger.Info(
                "CoopMissionSpawnLogic: reconciled battle result state from mission. " +
                "Entries=" + _materializedBattleResultEntriesByEntryId.Count +
                " TrackedAgents=" + trackedAgents +
                " Active=" + finalActiveTotal +
                " Removed=" + finalRemovedTotal +
                " Killed=" + finalKilledTotal +
                " Unconscious=" + finalUnconsciousTotal +
                " Routed=" + finalRoutedTotal +
                " OtherRemoved=" + finalOtherRemovedTotal +
                " ExactOriginFallbackAgents=" + exactOriginFallbackAgents +
                " RawScoreHitCalls=" + _materializedBattleResultRawOnScoreHitCount +
                " RawAgentRemovedCalls=" + _materializedBattleResultRawOnAgentRemovedCount +
                " ScoreHits=" + _materializedBattleResultOnScoreHitCount +
                " AgentRemovedCalls=" + _materializedBattleResultOnAgentRemovedCount +
                " RemovalDebugLogs=" + _materializedBattleResultRemovalDebugLogCount +
                " ScoreHitSamples=[" + string.Join("; ", _materializedBattleResultOnScoreHitSamples) + "]" +
                " AgentRemovedSamples=[" + string.Join("; ", _materializedBattleResultOnAgentRemovedSamples) + "]" +
                " ReconcileRemovedSamples=[" + string.Join("; ", _materializedBattleResultReconcileRemovedSamples) + "]" +
                " Source=" + (source ?? "unknown") + ".");
        }

        private static CoopBattleResultBridgeFile.BattleResultSnapshot BuildBattleResultSnapshot(Mission mission, string source)
        {
            BattleSnapshotMessage snapshot = BattleSnapshotRuntimeState.GetCurrent();
            BattleRuntimeState runtimeState = BattleSnapshotRuntimeState.GetState();
            if (runtimeState?.EntriesById == null || runtimeState.EntriesById.Count == 0)
                return null;

            ReconcileMaterializedBattleResultStateFromMission(mission, source);

            bool isLordsHallStage = LordsHallScenarioContract.IsLordsHallScenario(snapshot?.ScenarioContext);
            bool isReliefStage = ExactReliefScenarioContract.IsReliefScenario(snapshot?.ScenarioContext);
            bool isSallyOutStage = SallyOutScenarioContract.IsSallyOutScenario(snapshot?.ScenarioContext);
            bool isSiegeAmbushStage = SiegeAmbushScenarioContract.IsSiegeAmbushScenario(snapshot?.ScenarioContext);
            bool isSiegeAssaultStage =
                ExactCampaignSiegeAssaultWithDeploymentRuntime.IsSiegeAssaultScenario(
                    snapshot?.ScenarioContext) ||
                ExactCampaignSiegeAssaultNoDeploymentRuntime.IsSiegeAssaultScenario(
                    snapshot?.ScenarioContext);
            string battleStage = isLordsHallStage
                ? "LordsHall"
                : isReliefStage
                    ? ExactReliefScenarioContract.ResultStage
                    : isSallyOutStage
                        ? SallyOutScenarioContract.ResultStage
                        : isSiegeAmbushStage
                            ? SiegeAmbushScenarioContract.ResultStage
                            : snapshot?.ScenarioContext?.IsSiegeBattle == true
                                ? "SiegeAssault"
                                : "Battle";

            string winnerSide =
                isSiegeAmbushStage &&
                string.IsNullOrWhiteSpace(_authoritativeBattleWinnerSide)
                    ? BattleSideEnum.Defender.ToString()
                    : ResolveBattleResultWinnerSide(mission);
            var result = new CoopBattleResultBridgeFile.BattleResultSnapshot
            {
                BattleId = snapshot?.BattleId,
                BattleInstanceId = snapshot?.BattleInstanceId,
                BattleType = snapshot?.BattleType,
                MapScene = mission.SceneName ?? snapshot?.MapScene ?? string.Empty,
                Source = source ?? "unknown",
                WinnerSide = winnerSide,
                PlayerSide = snapshot?.PlayerSide,
                BattleStage = battleStage,
                CompletionReason = _authoritativeBattleCompletionReason,
                IsSynthetic = IsSyntheticRuntime(),
                UpdatedUtc = DateTime.UtcNow,
                DroppedCombatEventCount = _droppedMaterializedBattleResultCombatEventCount,
                FrozenCaptainEntryIds = GlobalCaptainPerkRuntimeState.GetFrozenCaptainEntryIds().ToList(),
                FrozenCaptainCombatGroups = GlobalCaptainPerkRuntimeState.GetFrozenCombatGroups().ToList()
            };

            if (isSiegeAmbushStage || isSiegeAssaultStage)
            {
                CaptureMissionSiegeEngineResult(
                    mission,
                    result.AttackerSiegeEngines,
                    result.DefenderSiegeEngines);
            }

            foreach (RosterEntryState entryState in runtimeState.EntriesById.Values
                .Where(entry => entry != null)
                .OrderBy(entry => entry.SideId, StringComparer.OrdinalIgnoreCase)
                .ThenBy(entry => entry.PartyId, StringComparer.OrdinalIgnoreCase)
                .ThenBy(entry => entry.EntryId, StringComparer.OrdinalIgnoreCase))
            {
                _materializedBattleResultEntriesByEntryId.TryGetValue(entryState.EntryId ?? string.Empty, out MaterializedBattleResultEntryRuntimeState runtimeEntry);

                result.Entries.Add(new CoopBattleResultBridgeFile.BattleResultEntrySnapshot
                {
                    EntryId = entryState.EntryId,
                    SideId = entryState.SideId,
                    PartyId = entryState.PartyId,
                    CharacterId = entryState.CharacterId,
                    OriginalCharacterId = entryState.OriginalCharacterId,
                    SpawnTemplateId = ResolveEntrySpawnTemplateId(entryState),
                    TroopName = entryState.TroopName,
                    HeroId = entryState.HeroId,
                    HeroRole = entryState.HeroRole,
                    IsHero = entryState.IsHero,
                    SnapshotCount = entryState.Count,
                    SnapshotWoundedCount = entryState.WoundedCount,
                    MaterializedSpawnCount = runtimeEntry?.MaterializedSpawnCount ?? 0,
                    ActiveCount = runtimeEntry?.ActiveCount ?? 0,
                    RemovedCount = runtimeEntry?.RemovedCount ?? 0,
                    KilledCount = runtimeEntry?.KilledCount ?? 0,
                    UnconsciousCount = runtimeEntry?.UnconsciousCount ?? 0,
                    RoutedCount = runtimeEntry?.RoutedCount ?? 0,
                    OtherRemovedCount = runtimeEntry?.OtherRemovedCount ?? 0,
                    ScoreHitCount = runtimeEntry?.ScoreHitCount ?? 0,
                    HitsTakenCount = runtimeEntry?.HitsTakenCount ?? 0,
                    FatalHitCount = runtimeEntry?.FatalHitCount ?? 0,
                    KillsInflictedCount = runtimeEntry?.KillsInflictedCount ?? 0,
                    UnconsciousInflictedCount = runtimeEntry?.UnconsciousInflictedCount ?? 0,
                    RoutedInflictedCount = runtimeEntry?.RoutedInflictedCount ?? 0,
                    DamageDealt = runtimeEntry?.DamageDealt ?? 0f,
                    DamageTaken = runtimeEntry?.DamageTaken ?? 0f,
                    GlobalCaptainPerkEffects = GlobalCaptainPerkRuntimeState
                        .GetEffectsForEntry(entryState.EntryId)
                        .ToList()
                });
            }

            if (_materializedBattleResultCombatEvents.Count > 0)
                result.CombatEvents.AddRange(_materializedBattleResultCombatEvents);
            if (_materializedBattleResultCasualtyEvents.Count > 0)
                result.CasualtyEvents.AddRange(_materializedBattleResultCasualtyEvents);

            result.RoutedDefenderCount = result.Entries
                .Where(entry => entry != null &&
                    string.Equals(entry.SideId, BattleSideEnum.Defender.ToString(), StringComparison.OrdinalIgnoreCase))
                .Sum(entry => Math.Max(0, entry.RoutedCount));
            int successfulPullBackCount =
                snapshot?.ScenarioContext?.SiegeContext?.DefenderTroopNumberForSuccessfulPullBack > 0
                    ? snapshot.ScenarioContext.SiegeContext.DefenderTroopNumberForSuccessfulPullBack
                    : 20;
            result.DefenderPushedBack =
                !isLordsHallStage &&
                !isReliefStage &&
                !isSallyOutStage &&
                !isSiegeAmbushStage &&
                snapshot?.ScenarioContext?.IsSiegeBattle == true &&
                string.Equals(result.WinnerSide, BattleSideEnum.Attacker.ToString(), StringComparison.OrdinalIgnoreCase) &&
                result.RoutedDefenderCount >= successfulPullBackCount;
            result.IsFinalStage =
                isSiegeAmbushStage ||
                isLordsHallStage ||
                !result.DefenderPushedBack;
            result.ResultId =
                (snapshot?.BattleInstanceId ?? snapshot?.BattleId ?? Guid.NewGuid().ToString("N")) +
                "|" + battleStage;

            ExactSiegeMoraleDiagnostics.LogSummary(source);

            return result;
        }

        private static void CaptureMissionSiegeEngineResult(
            Mission mission,
            List<BattleSiegeEngineSnapshotMessage> attackerResult,
            List<BattleSiegeEngineSnapshotMessage> defenderResult)
        {
            if (mission == null || attackerResult == null || defenderResult == null)
                return;

            MissionSiegeEnginesLogic siegeEnginesLogic =
                mission.GetMissionBehavior<MissionSiegeEnginesLogic>();
            if (siegeEnginesLogic == null)
                return;

            try
            {
                siegeEnginesLogic.GetMissionSiegeWeapons(
                    out var defenderWeapons,
                    out var attackerWeapons);
                AppendMissionSiegeEngineResult(attackerWeapons, attackerResult);
                AppendMissionSiegeEngineResult(defenderWeapons, defenderResult);
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "CoopMissionSpawnLogic: failed to capture siege engine result state. " +
                    ex.GetType().Name + ":" + ex.Message);
            }
        }

        private static void AppendMissionSiegeEngineResult(
            IEnumerable<IMissionSiegeWeapon> source,
            List<BattleSiegeEngineSnapshotMessage> target)
        {
            if (source == null || target == null)
                return;

            foreach (MissionSiegeWeapon weapon in source
                .OfType<MissionSiegeWeapon>()
                .OrderBy(item => item.Index))
            {
                string typeId =
                    !string.IsNullOrWhiteSpace(weapon.Type?.StringId)
                        ? weapon.Type.StringId
                        : weapon.Type?.ToString() ?? string.Empty;
                if (string.IsNullOrWhiteSpace(typeId))
                    continue;

                target.Add(new BattleSiegeEngineSnapshotMessage
                {
                    EngineTypeId = typeId,
                    Index = weapon.Index,
                    Health = weapon.Health,
                    InitialHealth = weapon.InitialHealth,
                    MaxHealth = weapon.MaxHealth
                });
            }
        }

        private static string ResolveBattleResultWinnerSide(Mission mission)
        {
            if (!string.IsNullOrWhiteSpace(_authoritativeBattleWinnerSide))
                return _authoritativeBattleWinnerSide;

            if (mission == null)
                return string.Empty;

            ResolveActiveBattleSideCounts(mission, out int attackerActive, out int defenderActive, out _);
            if (attackerActive > 0 && defenderActive <= 0)
                return BattleSideEnum.Attacker.ToString();
            if (defenderActive > 0 && attackerActive <= 0)
                return BattleSideEnum.Defender.ToString();
            if (attackerActive > defenderActive)
                return BattleSideEnum.Attacker.ToString();
            if (defenderActive > attackerActive)
                return BattleSideEnum.Defender.ToString();
            return string.Empty;
        }

        private static void ResolveActiveBattleSideCounts(Mission mission, out int attackerActive, out int defenderActive, out string countSource)
        {
            bool hasMaterializedRuntimeCounts = TryResolveMaterializedActiveBattleSideCounts(
                out int materializedRuntimeAttackerActive,
                out int materializedRuntimeDefenderActive);
            DateTime nowUtc = DateTime.UtcNow;
            bool completionIsNear =
                !hasMaterializedRuntimeCounts ||
                materializedRuntimeAttackerActive <= 2 ||
                materializedRuntimeDefenderActive <= 2;
            if (hasMaterializedRuntimeCounts &&
                !completionIsNear &&
                nowUtc < _nextBattleCompletionLiveReconciliationUtc)
            {
                attackerActive = materializedRuntimeAttackerActive;
                defenderActive = materializedRuntimeDefenderActive;
                countSource = "materialized-runtime-fast";
                return;
            }

            _nextBattleCompletionLiveReconciliationUtc =
                nowUtc + BattleCompletionLiveReconciliationInterval;
            int missionTeamAttackerActive = CountActiveTeamAgents(mission, BattleSideEnum.Attacker);
            int missionTeamDefenderActive = CountActiveTeamAgents(mission, BattleSideEnum.Defender);

            if (TryResolveLiveMaterializedActiveBattleSideCounts(
                mission,
                out int materializedLiveAttackerActive,
                out int materializedLiveDefenderActive,
                out int trackedAttackerAgents,
                out int trackedDefenderAgents))
            {
                attackerActive = materializedLiveAttackerActive;
                defenderActive = materializedLiveDefenderActive;
                countSource =
                    "materialized-live-agents" +
                    " AttackerTracked=" + trackedAttackerAgents +
                    " DefenderTracked=" + trackedDefenderAgents +
                    " | mission-teams Attacker=" + missionTeamAttackerActive +
                    " Defender=" + missionTeamDefenderActive;

                if (hasMaterializedRuntimeCounts)
                {
                    countSource +=
                        " | materialized-runtime Attacker=" + materializedRuntimeAttackerActive +
                        " Defender=" + materializedRuntimeDefenderActive;
                }

                return;
            }

            attackerActive = missionTeamAttackerActive;
            defenderActive = missionTeamDefenderActive;

            if (hasMaterializedRuntimeCounts)
            {
                countSource =
                    "mission-teams" +
                    " | materialized-runtime Attacker=" + materializedRuntimeAttackerActive +
                    " Defender=" + materializedRuntimeDefenderActive;
                return;
            }

            countSource = "mission-teams";
        }

        private static void TryLogBattleCompletionAudit(int attackerActive, int defenderActive, string countSource, string source)
        {
            if (attackerActive > 2 && defenderActive > 2)
                return;

            string auditKey =
                attackerActive + "|" +
                defenderActive + "|" +
                (countSource ?? string.Empty);
            if (string.Equals(_lastLoggedBattleCompletionAuditKey, auditKey, StringComparison.Ordinal))
                return;

            _lastLoggedBattleCompletionAuditKey = auditKey;
            ModLogger.Info(
                "CoopMissionSpawnLogic: battle completion audit. " +
                "AttackerActive=" + attackerActive +
                " DefenderActive=" + defenderActive +
                " CountSource=" + (countSource ?? "unknown") +
                " Source=" + (source ?? "unknown") + ".");
        }

        private static bool TryResolveMaterializedActiveBattleSideCounts(out int attackerActive, out int defenderActive)
        {
            attackerActive = 0;
            defenderActive = 0;

            int attackerSpawned = 0;
            int defenderSpawned = 0;

            foreach (MaterializedBattleResultEntryRuntimeState state in _materializedBattleResultEntriesByEntryId.Values)
            {
                if (state == null || state.MaterializedSpawnCount <= 0 || string.IsNullOrWhiteSpace(state.SideId))
                    continue;

                if (string.Equals(state.SideId, BattleSideEnum.Attacker.ToString(), StringComparison.OrdinalIgnoreCase))
                {
                    attackerSpawned += state.MaterializedSpawnCount;
                    attackerActive += Math.Max(0, state.ActiveCount);
                }
                else if (string.Equals(state.SideId, BattleSideEnum.Defender.ToString(), StringComparison.OrdinalIgnoreCase))
                {
                    defenderSpawned += state.MaterializedSpawnCount;
                    defenderActive += Math.Max(0, state.ActiveCount);
                }
            }

            return attackerSpawned > 0 && defenderSpawned > 0;
        }

        private static bool TryResolveLiveMaterializedActiveBattleSideCounts(
            Mission mission,
            out int attackerActive,
            out int defenderActive,
            out int trackedAttackerAgents,
            out int trackedDefenderAgents)
        {
            attackerActive = 0;
            defenderActive = 0;
            trackedAttackerAgents = 0;
            trackedDefenderAgents = 0;

            if (mission?.AllAgents == null || !_hasMaterializedBattlefieldArmies || _materializedArmySideByAgentIndex.Count == 0)
                return false;

            foreach (BattleSideEnum trackedSide in _materializedArmySideByAgentIndex.Values)
            {
                if (trackedSide == BattleSideEnum.Attacker)
                    trackedAttackerAgents++;
                else if (trackedSide == BattleSideEnum.Defender)
                    trackedDefenderAgents++;
            }

            if (trackedAttackerAgents <= 0 || trackedDefenderAgents <= 0)
                return false;

            for (int i = 0; i < mission.AllAgents.Count; i++)
            {
                Agent agent = mission.AllAgents[i];
                if (agent == null || !agent.IsActive() || agent.IsMount)
                    continue;

                if (!_materializedArmySideByAgentIndex.TryGetValue(agent.Index, out BattleSideEnum trackedSide))
                    continue;

                if (trackedSide == BattleSideEnum.Attacker)
                    attackerActive++;
                else if (trackedSide == BattleSideEnum.Defender)
                    defenderActive++;
            }

            return true;
        }

        private static int CountActiveTeamAgents(Mission mission, BattleSideEnum side)
        {
            if (mission?.Teams == null)
                return 0;

            int count = 0;
            foreach (Team team in mission.Teams)
            {
                if (team == null || team.Side != side || ReferenceEquals(team, mission.SpectatorTeam))
                    continue;

                foreach (Agent agent in team.ActiveAgents)
                {
                    if (agent != null && agent.IsActive() && !agent.IsMount)
                        count++;
                }
            }

            return count;
        }

        private static string BuildBattleResultEntryAuditSummary(CoopBattleResultBridgeFile.BattleResultSnapshot snapshot)
        {
            if (snapshot?.Entries == null || snapshot.Entries.Count == 0)
                return "(none)";

            IEnumerable<string> entries = snapshot.Entries
                .Where(entry => entry != null && (entry.MaterializedSpawnCount > 0 || entry.RemovedCount > 0 || entry.ActiveCount > 0))
                .Take(24)
                .Select(entry =>
                    (entry.SideId ?? "side") + "/" +
                    (entry.EntryId ?? "entry") +
                    " Spawned=" + entry.MaterializedSpawnCount +
                    " Active=" + entry.ActiveCount +
                    " Removed=" + entry.RemovedCount +
                    " Killed=" + entry.KilledCount +
                    " Unconscious=" + entry.UnconsciousCount +
                    " Routed=" + entry.RoutedCount +
                    " Hits=" + entry.ScoreHitCount +
                    " Dmg=" + entry.DamageDealt.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) +
                    " KillsBy=" + entry.KillsInflictedCount);

            string summary = string.Join("; ", entries);
            return string.IsNullOrWhiteSpace(summary) ? "(none)" : summary;
        }

        private static int CountCombatProfilePerksByPrefix(IEnumerable<string> perkIds, params string[] prefixes)
        {
            if (perkIds == null || prefixes == null || prefixes.Length == 0)
                return 0;

            int count = 0;
            foreach (string perkId in perkIds)
            {
                if (string.IsNullOrWhiteSpace(perkId))
                    continue;

                for (int i = 0; i < prefixes.Length; i++)
                {
                    string prefix = prefixes[i];
                    if (string.IsNullOrWhiteSpace(prefix))
                        continue;

                    if (!perkId.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                        continue;

                    count++;
                    break;
                }
            }

            return count;
        }

        private static void QueueMaterializedCombatProfilePropertyRefresh(Agent agent)
        {
            if (!GameNetwork.IsServer || agent?.Mission == null || agent.Index < 0)
                return;

            if (_pendingMaterializedCombatProfileRefreshAgentsByIndex.TryGetValue(
                    agent.Index,
                    out Agent pendingAgent))
            {
                if (!ReferenceEquals(pendingAgent, agent))
                    _pendingMaterializedCombatProfileRefreshAgentsByIndex[agent.Index] = agent;
                return;
            }

            _pendingMaterializedCombatProfileRefreshAgentsByIndex[agent.Index] = agent;
            _pendingMaterializedCombatProfileRefreshAgentIndices.Enqueue(agent.Index);
        }

        private static int ProcessPendingMaterializedCombatProfilePropertyRefreshes(
            Mission mission,
            int batchSize,
            string source)
        {
            if (mission == null || batchSize <= 0)
                return 0;

            int refreshedAgentCount = 0;
            int processedCount = 0;
            while (_pendingMaterializedCombatProfileRefreshAgentIndices.Count > 0 &&
                   processedCount < batchSize)
            {
                int agentIndex = _pendingMaterializedCombatProfileRefreshAgentIndices.Dequeue();
                processedCount++;
                if (!_pendingMaterializedCombatProfileRefreshAgentsByIndex.TryGetValue(
                        agentIndex,
                        out Agent agent))
                {
                    continue;
                }

                _pendingMaterializedCombatProfileRefreshAgentsByIndex.Remove(agentIndex);
                if (agent == null ||
                    !ReferenceEquals(agent.Mission, mission) ||
                    !agent.IsActive() ||
                    !_materializedCombatProfilesByAgentIndex.ContainsKey(agentIndex))
                {
                    continue;
                }

                try
                {
                    agent.UpdateAgentProperties();
                    Agent mountAgent = agent.MountAgent;
                    if (mountAgent != null && mountAgent.IsActive())
                        mountAgent.UpdateAgentProperties();
                    refreshedAgentCount++;
                }
                catch (Exception ex)
                {
                    if (CoopDebugConfig.CombatModelDiagnostics)
                    {
                        ModLogger.Info(
                            "CoopMissionSpawnLogic: queued combat-profile property refresh failed. " +
                            "AgentIndex=" + agentIndex +
                            " Error=" + ex.GetType().Name + ":" + ex.Message +
                            " Source=" + (source ?? "unknown"));
                    }
                }
            }

            return refreshedAgentCount;
        }

        private static void TryRefreshMaterializedCombatProfileDrivenStats(Mission mission, string source)
        {
            if (mission == null || _materializedCombatProfilesByAgentIndex.Count == 0)
                return;

            EnsureMaterializedCombatProfileMission(mission);

            if (CoopCampaignDerivedAgentStatCalculateModel.IsActiveForMission(mission))
            {
                int refreshedAgentCount = ProcessPendingMaterializedCombatProfilePropertyRefreshes(
                    mission,
                    MaterializedCombatProfileRefreshBatchPerTick,
                    source);
                if (refreshedAgentCount > 0 && !_hasLoggedManualCombatProfileRefreshForMission)
                {
                    _hasLoggedManualCombatProfileRefreshForMission = true;
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: activated event-driven combat-profile property refresh. " +
                        "InitialBatch=" + refreshedAgentCount +
                        " Source=" + (source ?? "unknown"));
                }
                return;
            }

            float currentMissionTime = mission.CurrentTime;
            if (ReferenceEquals(_lastCombatProfileDrivenRefreshMission, mission) &&
                currentMissionTime >= _lastCombatProfileDrivenRefreshMissionTime &&
                currentMissionTime - _lastCombatProfileDrivenRefreshMissionTime < 0.25f)
            {
                return;
            }

            _lastCombatProfileDrivenRefreshMission = mission;
            _lastCombatProfileDrivenRefreshMissionTime = currentMissionTime;

            bool appliedAny = false;
            if (mission.AllAgents != null)
            {
                for (int i = 0; i < mission.AllAgents.Count; i++)
                {
                    Agent agent = mission.AllAgents[i];
                    if (agent == null || !agent.IsActive())
                        continue;

                    AgentDrivenProperties agentDrivenProperties = TryGetAgentDrivenProperties(agent);
                    if (agentDrivenProperties == null)
                        continue;

                    if (TryApplyDrivenSkillCombatProfile(agent, agentDrivenProperties))
                        appliedAny = true;
                }
            }

            if (appliedAny)
            {
                if (!_hasLoggedManualCombatProfileRefreshForMission)
                {
                    _hasLoggedManualCombatProfileRefreshForMission = true;
                    ModLogger.Info(
                        "CoopMissionSpawnLogic: applied manual combat-profile driven-stat refresh. " +
                        "MissionTime=" + currentMissionTime.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                        " Source=" + (source ?? "unknown"));
                }
            }
        }

        private static AgentDrivenProperties TryGetAgentDrivenProperties(Agent agent)
        {
            if (agent == null)
                return null;

            if (!_agentDrivenPropertiesPropertyResolved)
            {
                _agentDrivenPropertiesProperty =
                    typeof(Agent).GetProperty("AgentDrivenProperties", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance) ??
                    typeof(Agent).GetProperty("DrivenProperties", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                _agentDrivenPropertiesPropertyResolved = true;

                if (_agentDrivenPropertiesProperty == null && !_loggedMissingAgentDrivenPropertiesAccessor)
                {
                    _loggedMissingAgentDrivenPropertiesAccessor = true;
                    ModLogger.Info("CoopMissionSpawnLogic: AgentDrivenProperties accessor was not found; manual combat-profile refresh is unavailable.");
                }
            }

            if (_agentDrivenPropertiesProperty == null)
                return null;

            try
            {
                return _agentDrivenPropertiesProperty.GetValue(agent, null) as AgentDrivenProperties;
            }
            catch
            {
                return null;
            }
        }

        public static bool TryApplyDrivenSkillCombatProfile(Agent agent, AgentDrivenProperties agentDrivenProperties)
        {
            if (agent == null || agentDrivenProperties == null)
                return false;

            Mission mission = agent.Mission;
            if (mission == null)
                return false;

            EnsureMaterializedCombatProfileMission(mission);

            if (agent.IsMount)
                return TryApplyMountDrivenSkillCombatProfile(agent, agentDrivenProperties);

            if (!agent.IsHuman || !_materializedCombatProfilesByAgentIndex.TryGetValue(agent.Index, out MaterializedCombatProfileRuntimeState profile))
                return false;

            bool applied = false;

            var equipment = agent.Equipment;
            WeaponComponentData primaryWeapon;
            SkillObject relevantSkill;
            ItemObject primaryItem = TryResolveAgentPrimaryCombatItem(agent, equipment, out primaryWeapon, out relevantSkill);
            if (primaryItem == null)
                return false;

            relevantSkill = relevantSkill ?? primaryItem?.RelevantSkill ?? DefaultSkills.Athletics;
            int templateRelevantSkill = TryGetCharacterSkillValue(agent.Character, relevantSkill);
            int desiredRelevantSkill = TryGetCombatProfileSkillValue(profile, relevantSkill, templateRelevantSkill);

            bool suppressApproximateHeroRangedBallistics = ShouldSuppressApproximateHeroRangedBallistics(profile, agent, primaryWeapon);
            bool lowLevelExactHeroRangedBallisticsActive =
                suppressApproximateHeroRangedBallistics &&
                CoopCampaignDerivedAgentStatCalculateModel.IsActiveForMission(mission);

            SetDrivenPropertyBaselineContext(profile, agent, isMountContext: false);
            try
            {
                if (TryApplyPrimaryWeaponSkillDrivenStats(agentDrivenProperties, primaryWeapon, templateRelevantSkill, desiredRelevantSkill))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "weapon-skill", ref profile.CountedWeaponSkillAdjustment);
                }

                if ((!lowLevelExactHeroRangedBallisticsActive &&
                        suppressApproximateHeroRangedBallistics &&
                        TryApplyExactHeroPrimaryRangedAccuracyDrivenStats(
                            agent,
                            profile,
                            agentDrivenProperties,
                            primaryWeapon,
                            relevantSkill,
                            templateRelevantSkill,
                            desiredRelevantSkill)) ||
                    (!suppressApproximateHeroRangedBallistics &&
                        TryApplyPrimaryWeaponInaccuracyDrivenStats(agentDrivenProperties, primaryWeapon, templateRelevantSkill, desiredRelevantSkill)))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "weapon-inaccuracy", ref profile.CountedWeaponInaccuracyAdjustment);
                }

                if (TryApplyLoadoutAttributeDrivenStats(agent, profile, agentDrivenProperties))
                    applied = true;

                if (TryApplyEnduranceDrivenStats(agent, profile, agentDrivenProperties))
                    applied = true;

                if (TryApplyPerkDrivenStats(agent, profile, agentDrivenProperties, primaryWeapon, relevantSkill))
                    applied = true;

                if (TryApplyPartyModifierDrivenStats(agent, profile, agentDrivenProperties))
                    applied = true;

                if (agent.HasMount || agent.MountAgent != null)
                {
                    int templateRiding = TryGetCharacterSkillValue(agent.Character, DefaultSkills.Riding);
                    int desiredRiding = profile.SkillRiding > 0 ? profile.SkillRiding : templateRiding;
                    if (TryApplyMountedHumanRidingDrivenStats(
                            agent,
                            agentDrivenProperties,
                            templateRiding,
                            desiredRiding,
                            includeAccuracyAdjustments: !suppressApproximateHeroRangedBallistics))
                    {
                        applied = true;
                        CountMaterializedCombatProfileApply(profile, "riding", ref profile.CountedRidingAttributeAdjustment);
                        if (!suppressApproximateHeroRangedBallistics)
                            CountMaterializedCombatProfileApply(profile, "mounted-penalty", ref profile.CountedMountedPenaltyAdjustment);
                    }
                }

                return applied;
            }
            finally
            {
                ClearDrivenPropertyBaselineContext();
            }
        }

        internal static bool TryApplyWeaponDamageMultiplierCombatProfile(
            Agent agent,
            WeaponComponentData weapon,
            ref float damageMultiplier)
        {
            if (agent == null || weapon == null || !agent.IsHuman)
                return false;

            Mission mission = agent.Mission;
            if (mission == null)
                return false;

            EnsureMaterializedCombatProfileMission(mission);

            if (!_materializedCombatProfilesByAgentIndex.TryGetValue(agent.Index, out MaterializedCombatProfileRuntimeState profile) ||
                !IsHeroProfileEligibleForExactPersonalPerks(profile))
            {
                return false;
            }

            SkillObject relevantSkill = ResolveWeaponDamageMultiplierRelevantSkill(weapon);
            if (relevantSkill == null)
                return false;

            int templateRelevantSkill = TryGetCharacterSkillValue(agent.Character, relevantSkill);
            int desiredRelevantSkill = TryGetCombatProfileSkillValue(profile, relevantSkill, templateRelevantSkill);
            float desiredSkillMultiplier = ComputeExactPersonalWeaponDamageMultiplier(relevantSkill, desiredRelevantSkill);
            if (desiredSkillMultiplier <= 0f || Math.Abs(desiredSkillMultiplier - 1f) < 0.0001f)
                return false;

            float currentMultiplier = Math.Max(0f, damageMultiplier);
            float updatedMultiplier = Math.Max(0f, currentMultiplier * desiredSkillMultiplier);
            if (Math.Abs(updatedMultiplier - currentMultiplier) < 0.0001f)
                return false;

            damageMultiplier = updatedMultiplier;
            return true;
        }

        private static SkillObject ResolveWeaponDamageMultiplierRelevantSkill(WeaponComponentData weapon)
        {
            if (weapon == null)
                return null;

            SkillObject relevantSkill = weapon.RelevantSkill;
            if (relevantSkill != null)
            {
                if (string.Equals(relevantSkill.StringId, "OneHanded", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(relevantSkill.StringId, "TwoHanded", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(relevantSkill.StringId, "Polearm", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(relevantSkill.StringId, "Bow", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(relevantSkill.StringId, "Crossbow", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(relevantSkill.StringId, "Throwing", StringComparison.OrdinalIgnoreCase))
                {
                    return relevantSkill;
                }
            }

            string skillHint = MapCombatEventWeaponClassToSkillHint(weapon.WeaponClass.ToString(), isSiegeEngineHit: false);
            switch (skillHint)
            {
                case "OneHanded":
                    return DefaultSkills.OneHanded;
                case "TwoHanded":
                    return DefaultSkills.TwoHanded;
                case "Polearm":
                    return DefaultSkills.Polearm;
                case "Bow":
                    return DefaultSkills.Bow;
                case "Crossbow":
                    return DefaultSkills.Crossbow;
                case "Throwing":
                    return DefaultSkills.Throwing;
                default:
                    return relevantSkill;
            }
        }

        private static bool TryApplyAuthoritativeExactPersonalRangedDamageBonusOnScoreHit(
            Agent affectedAgent,
            Agent affectorAgent,
            WeaponComponentData attackerWeapon,
            bool isBlocked,
            bool isSiegeEngineHit,
            in Blow blow,
            in AttackCollisionData collisionData,
            ref float damagedHp)
        {
            if (!GameNetwork.IsServer || GameNetwork.IsClientOrReplay)
                return false;

            if (affectedAgent == null || affectorAgent == null || attackerWeapon == null || !affectorAgent.IsHuman || !affectedAgent.IsActive())
                return false;

            if (CoopCampaignDerivedAgentStatCalculateModel.IsActiveForMission(affectorAgent.Mission))
                return false;

            if (isBlocked || isSiegeEngineHit || damagedHp <= 0.01f || affectedAgent.Health < 1f)
                return false;

            float desiredMultiplier = 1f;
            if (!TryApplyWeaponDamageMultiplierCombatProfile(affectorAgent, attackerWeapon, ref desiredMultiplier) ||
                desiredMultiplier <= 1.0001f)
            {
                return false;
            }

            float currentHealth = affectedAgent.Health;
            if (currentHealth <= 0f)
                return false;

            float desiredDamage = Math.Max(0f, damagedHp) * desiredMultiplier;
            int extraDamage = TaleWorlds.Library.MathF.Ceiling(desiredDamage - damagedHp);
            if (extraDamage <= 0)
                return false;

            float updatedHealth = Math.Max(0f, currentHealth - extraDamage);
            float appliedExtraDamage = currentHealth - updatedHealth;
            if (appliedExtraDamage <= 0.01f)
                return false;

            affectedAgent.Health = updatedHealth;
            if (updatedHealth < 1f && currentHealth >= 1f)
            {
                Agent.KillInfo overrideKillInfo = blow.IsFallDamage ? Agent.KillInfo.Gravity : Agent.KillInfo.Invalid;
                affectedAgent.Die(blow, overrideKillInfo);
            }

            damagedHp += appliedExtraDamage;
            ModLogger.Info(
                "CoopMissionSpawnLogic: applied authoritative exact personal ranged damage bonus. " +
                "Attacker=" + affectorAgent.Index +
                " Victim=" + affectedAgent.Index +
                " WeaponSkill=" + (attackerWeapon.RelevantSkill?.StringId ?? "null") +
                " Multiplier=" + desiredMultiplier.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) +
                " BaseDamage=" + Math.Max(0f, damagedHp - appliedExtraDamage).ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) +
                " ExtraDamage=" + appliedExtraDamage.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) +
                " FinalDamage=" + damagedHp.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) +
                " TargetHealth=" + updatedHealth.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) + ".");
            return true;
        }

        private static ItemObject TryResolveAgentPrimaryCombatItem(
            Agent agent,
            MissionEquipment equipment,
            out WeaponComponentData primaryWeapon,
            out SkillObject relevantSkill)
        {
            primaryWeapon = null;
            relevantSkill = null;

            if (agent == null || equipment == null)
                return null;

            EquipmentIndex primaryWieldedItemIndex = agent.GetPrimaryWieldedItemIndex();
            if (primaryWieldedItemIndex != EquipmentIndex.None)
            {
                MissionWeapon wieldedMissionWeapon = equipment[primaryWieldedItemIndex];
                ItemObject wieldedItem = wieldedMissionWeapon.Item;
                if (wieldedItem != null)
                {
                    primaryWeapon = wieldedMissionWeapon.CurrentUsageItem ?? wieldedItem.PrimaryWeapon;
                    relevantSkill = wieldedItem.RelevantSkill;
                    return wieldedItem;
                }
            }

            for (EquipmentIndex index = EquipmentIndex.Weapon0; index <= EquipmentIndex.Weapon3; index++)
            {
                MissionWeapon missionWeapon = equipment[index];
                ItemObject item = missionWeapon.Item;
                if (item == null)
                    continue;

                WeaponComponentData usageItem = missionWeapon.CurrentUsageItem ?? item.PrimaryWeapon;
                if (usageItem == null || usageItem.IsAmmo || usageItem.IsShield)
                    continue;

                primaryWeapon = usageItem;
                relevantSkill = item.RelevantSkill;
                return item;
            }

            for (EquipmentIndex index = EquipmentIndex.Weapon0; index <= EquipmentIndex.Weapon3; index++)
            {
                MissionWeapon missionWeapon = equipment[index];
                ItemObject item = missionWeapon.Item;
                if (item == null)
                    continue;

                primaryWeapon = missionWeapon.CurrentUsageItem ?? item.PrimaryWeapon;
                relevantSkill = item.RelevantSkill;
                return item;
            }

            return null;
        }

        private static bool TryApplyLoadoutAttributeDrivenStats(
            Agent agent,
            MaterializedCombatProfileRuntimeState profile,
            AgentDrivenProperties agentDrivenProperties)
        {
            if (agent == null || profile == null || agentDrivenProperties == null)
                return false;

            int templateVigor = DeriveCharacterVigorAttribute(agent.Character);
            int templateControl = DeriveCharacterControlAttribute(agent.Character);

            int desiredVigor = profile.AttributeVigor > 0 ? profile.AttributeVigor : DeriveCombatAttributeFromSkills(profile.SkillOneHanded, profile.SkillTwoHanded, profile.SkillPolearm);
            int desiredControl = profile.AttributeControl > 0 ? profile.AttributeControl : DeriveCombatAttributeFromSkills(profile.SkillBow, profile.SkillCrossbow, profile.SkillThrowing);

            bool applied = false;
            if (AgentLoadoutContainsRelevantSkill(agent, "OneHanded", "TwoHanded", "Polearm"))
            {
                if (TryApplyVigorDrivenStats(agentDrivenProperties, templateVigor, desiredVigor))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "attribute-vigor", ref profile.CountedVigorAttributeAdjustment);
                }
            }

            if (AgentLoadoutContainsRelevantSkill(agent, "Bow", "Crossbow", "Throwing") &&
                !ShouldSuppressApproximateHeroRangedBallistics(profile, agent))
            {
                if (TryApplyControlDrivenStats(agentDrivenProperties, templateControl, desiredControl))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "attribute-control", ref profile.CountedControlAttributeAdjustment);
                }
            }

            return applied;
        }

        private static bool TryApplyPerkDrivenStats(
            Agent agent,
            MaterializedCombatProfileRuntimeState profile,
            AgentDrivenProperties agentDrivenProperties,
            WeaponComponentData primaryWeapon,
            SkillObject relevantSkill)
        {
            if (agent == null || profile == null || agentDrivenProperties == null || profile.PerkIds == null || profile.PerkIds.Count == 0)
                return false;

            bool applied = false;
            bool isMounted = agent.HasMount || agent.MountAgent != null;
            int adjustedRangedPerkCount = profile.PerkRangedCount;
            bool suppressApproximateHeroRangedBallistics =
                ShouldSuppressApproximateHeroRangedBallistics(profile, agent, primaryWeapon);
            bool lowLevelExactPersonalPerksActive =
                IsHeroProfileEligibleForExactPersonalPerks(profile) &&
                CoopCampaignDerivedAgentStatCalculateModel.IsActiveForMission(agent.Mission);

            if (TryApplyExactPersonalPerkDrivenStats(agent, profile, agentDrivenProperties, primaryWeapon, relevantSkill))
            {
                applied = true;
                CountMaterializedCombatProfileApply(profile, "perk-personal-exact", ref profile.CountedPerkExactPersonalAdjustment);

                if (IsHeroProfileEligibleForExactPersonalPerks(profile))
                {
                    adjustedRangedPerkCount = Math.Max(
                        0,
                        adjustedRangedPerkCount - CountExactPersonalRangedPerkCoverage(profile, relevantSkill, primaryWeapon, isMounted));
                }
            }

            if (!lowLevelExactPersonalPerksActive &&
                profile.PerkMeleeCount > 0 &&
                AgentLoadoutContainsRelevantSkill(agent, "OneHanded", "TwoHanded", "Polearm"))
            {
                if (TryApplyMeleePerkDrivenStats(agentDrivenProperties, profile.PerkMeleeCount))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "perk-melee", ref profile.CountedPerkMeleeAdjustment);
                }
            }

            if (adjustedRangedPerkCount > 0 &&
                ShouldApplyApproximateRangedPerkDrivenStats(profile) &&
                AgentLoadoutContainsRelevantSkill(agent, "Bow", "Crossbow", "Throwing"))
            {
                if (TryApplyRangedPerkDrivenStats(agentDrivenProperties, adjustedRangedPerkCount))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "perk-ranged", ref profile.CountedPerkRangedAdjustment);
                }
            }

            if (!lowLevelExactPersonalPerksActive &&
                profile.PerkAthleticsCount > 0 &&
                !agent.IsMount &&
                !(agent.HasMount || agent.MountAgent != null))
            {
                if (TryApplyAthleticsPerkDrivenStats(agentDrivenProperties, profile.PerkAthleticsCount))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "perk-athletics", ref profile.CountedPerkAthleticsAdjustment);
                }
            }

            if (!lowLevelExactPersonalPerksActive &&
                profile.PerkRidingCount > 0 &&
                (agent.HasMount || agent.MountAgent != null) &&
                !suppressApproximateHeroRangedBallistics)
            {
                if (TryApplyRidingPerkDrivenStats(agentDrivenProperties, profile.PerkRidingCount))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "perk-riding", ref profile.CountedPerkRidingAdjustment);
                }
            }

            return applied;
        }

        private static bool TryApplyExactPersonalPerkDrivenStats(
            Agent agent,
            MaterializedCombatProfileRuntimeState profile,
            AgentDrivenProperties agentDrivenProperties,
            WeaponComponentData primaryWeapon,
            SkillObject relevantSkill)
        {
            if (agent == null ||
                profile == null ||
                agentDrivenProperties == null ||
                profile.PerkIds == null ||
                profile.PerkIds.Count == 0 ||
                !IsHeroProfileEligibleForExactPersonalPerks(profile) ||
                !agent.IsHuman)
            {
                return false;
            }

            bool applied = false;
            bool lowLevelExactAgentStatsActive = CoopCampaignDerivedAgentStatCalculateModel.IsActiveForMission(agent.Mission);

            if (!lowLevelExactAgentStatsActive && HasPerkId(profile.PerkIds, "AthleticsFormFittingArmor"))
                applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ArmorEncumbrance, 1f, 0.85f);

            // Keep personal ranged driven perks disabled until they are bridged
            // against the native runtime weapon-state path. The first direct port
            // caused projectile drift and ammo/runtime divergence despite correct
            // snapshot transfer.
            if (IsExactPersonalRangedDrivenPerkSubsetEnabled())
            {
                applied |= TryApplyExactPersonalRangedPerkDrivenStats(
                    agent,
                    profile,
                    agentDrivenProperties,
                    relevantSkill,
                    primaryWeapon);
            }

            return applied;
        }

        private static bool TryApplyExactPersonalRangedPerkDrivenStats(
            Agent agent,
            MaterializedCombatProfileRuntimeState profile,
            AgentDrivenProperties agentDrivenProperties,
            SkillObject relevantSkill,
            WeaponComponentData primaryWeapon)
        {
            if (agent == null || profile == null || agentDrivenProperties == null)
                return false;

            string relevantSkillId = GetPrimaryCombatRelevantSkillId(relevantSkill, primaryWeapon);
            if (!IsExactPersonalRangedRelevantSkillId(relevantSkillId))
                return false;

            bool isMounted = agent.HasMount || agent.MountAgent != null;
            bool applied = false;

            if (HasPerkId(profile.PerkIds, "BowNockingPoint"))
                applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ReloadMovementPenaltyFactor, 1f, 0.5f);

            if (isMounted && HasPerkId(profile.PerkIds, "RidingSagittarius"))
            {
                applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstMobileAccuracyPenalty, 1f, 0.85f);
                applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstUnsteadyAccuracyPenalty, 1f, 0.85f);
            }

            if (string.Equals(relevantSkillId, "Bow", StringComparison.OrdinalIgnoreCase))
            {
                if (HasPerkId(profile.PerkIds, "BowBowControl"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstMobileAccuracyPenalty, 1f, 0.7f);
                if (HasPerkId(profile.PerkIds, "BowRapidFire"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ReloadSpeed, 1f, 1.25f);
                if (HasPerkId(profile.PerkIds, "BowQuickAdjustments"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponRotationalAccuracyPenaltyInRadians, 1f, 0.5f);
                if (HasPerkId(profile.PerkIds, "BowDiscipline"))
                {
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponUnsteadyBeginTime, 1f, 1.5f);
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponUnsteadyEndTime, 1f, 1.5f);
                }
                if (HasPerkId(profile.PerkIds, "BowQuickDraw"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ThrustOrRangedReadySpeedMultiplier, 1f, 1.25f);
                if (isMounted && HasPerkId(profile.PerkIds, "BowMountedArchery"))
                {
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstMobileAccuracyPenalty, 1f, 0.7f);
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstUnsteadyAccuracyPenalty, 1f, 0.7f);
                }
            }
            else if (string.Equals(relevantSkillId, "Crossbow", StringComparison.OrdinalIgnoreCase))
            {
                if (isMounted && HasPerkId(profile.PerkIds, "CrossbowSteady"))
                {
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstMobileAccuracyPenalty, 1f, 0.5f);
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponRotationalAccuracyPenaltyInRadians, 1f, 0.5f);
                }
                if (HasPerkId(profile.PerkIds, "CrossbowWindWinder"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ReloadSpeed, 1f, 1.25f);
                if (HasPerkId(profile.PerkIds, "CrossbowDonkeysSwiftness"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstMobileAccuracyPenalty, 1f, 0.7f);
                if (HasPerkId(profile.PerkIds, "CrossbowMarksmen"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ThrustOrRangedReadySpeedMultiplier, 1f, 1.25f);
            }
            else if (string.Equals(relevantSkillId, "Throwing", StringComparison.OrdinalIgnoreCase))
            {
                if (HasPerkId(profile.PerkIds, "ThrowingQuickDraw"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ReloadSpeed, 1f, 1.2f);
                if (HasPerkId(profile.PerkIds, "ThrowingPerfectTechnique"))
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.MissileSpeedMultiplier, 1f, 1.25f);
                if (isMounted && HasPerkId(profile.PerkIds, "ThrowingMountedSkirmisher"))
                {
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstMobileAccuracyPenalty, 1f, 0.8f);
                    applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.WeaponWorstUnsteadyAccuracyPenalty, 1f, 0.8f);
                }
            }

            return applied;
        }

        private static int CountExactPersonalRangedPerkCoverage(
            MaterializedCombatProfileRuntimeState profile,
            SkillObject relevantSkill,
            WeaponComponentData primaryWeapon,
            bool isMounted)
        {
            if (!IsExactPersonalRangedDrivenPerkSubsetEnabled())
                return 0;

            if (profile?.PerkIds == null || profile.PerkIds.Count == 0)
                return 0;

            string relevantSkillId = GetPrimaryCombatRelevantSkillId(relevantSkill, primaryWeapon);
            if (!IsExactPersonalRangedRelevantSkillId(relevantSkillId))
                return 0;

            int count = 0;

            if (HasPerkId(profile.PerkIds, "BowNockingPoint"))
                count++;

            if (string.Equals(relevantSkillId, "Bow", StringComparison.OrdinalIgnoreCase))
            {
                if (HasPerkId(profile.PerkIds, "BowBowControl"))
                    count++;
                if (HasPerkId(profile.PerkIds, "BowRapidFire"))
                    count++;
                if (HasPerkId(profile.PerkIds, "BowQuickAdjustments"))
                    count++;
                if (HasPerkId(profile.PerkIds, "BowDiscipline"))
                    count++;
                if (HasPerkId(profile.PerkIds, "BowQuickDraw"))
                    count++;
                if (isMounted && HasPerkId(profile.PerkIds, "BowMountedArchery"))
                    count++;
            }
            else if (string.Equals(relevantSkillId, "Crossbow", StringComparison.OrdinalIgnoreCase))
            {
                if (isMounted && HasPerkId(profile.PerkIds, "CrossbowSteady"))
                    count++;
                if (HasPerkId(profile.PerkIds, "CrossbowWindWinder"))
                    count++;
                if (HasPerkId(profile.PerkIds, "CrossbowDonkeysSwiftness"))
                    count++;
                if (HasPerkId(profile.PerkIds, "CrossbowMarksmen"))
                    count++;
            }
            else if (string.Equals(relevantSkillId, "Throwing", StringComparison.OrdinalIgnoreCase))
            {
                if (HasPerkId(profile.PerkIds, "ThrowingQuickDraw"))
                    count++;
                if (HasPerkId(profile.PerkIds, "ThrowingPerfectTechnique"))
                    count++;
                if (isMounted && HasPerkId(profile.PerkIds, "ThrowingMountedSkirmisher"))
                    count++;
            }

            return count;
        }

        private static bool IsExactPersonalRangedDrivenPerkSubsetEnabled()
        {
            return false;
        }

        private static bool ShouldApplyApproximateRangedPerkDrivenStats(MaterializedCombatProfileRuntimeState profile)
        {
            // The old count-based ranged approximation mutates generic inaccuracy and
            // missile properties without the native skill/weapon conditions. For hero
            // entries this produced visibly wrong bow ballistics. Keep it only for the
            // non-hero fallback path until ranged perks are ported exact from native.
            return !IsHeroProfileEligibleForExactPersonalPerks(profile);
        }

        private static bool ShouldSuppressApproximateHeroRangedBallistics(
            MaterializedCombatProfileRuntimeState profile,
            Agent agent,
            WeaponComponentData primaryWeapon = null)
        {
            if (!IsHeroProfileEligibleForExactPersonalPerks(profile) || agent == null)
                return false;

            SkillObject relevantSkill = primaryWeapon?.RelevantSkill;
            if (relevantSkill == DefaultSkills.Bow || relevantSkill == DefaultSkills.Crossbow || relevantSkill == DefaultSkills.Throwing)
                return true;

            return AgentLoadoutContainsRelevantSkill(agent, "Bow", "Crossbow", "Throwing");
        }

        private static string GetPrimaryCombatRelevantSkillId(SkillObject relevantSkill, WeaponComponentData primaryWeapon)
        {
            return relevantSkill?.StringId
                ?? primaryWeapon?.RelevantSkill?.StringId
                ?? string.Empty;
        }

        private static bool IsExactPersonalRangedRelevantSkillId(string relevantSkillId)
        {
            return string.Equals(relevantSkillId, "Bow", StringComparison.OrdinalIgnoreCase)
                || string.Equals(relevantSkillId, "Crossbow", StringComparison.OrdinalIgnoreCase)
                || string.Equals(relevantSkillId, "Throwing", StringComparison.OrdinalIgnoreCase);
        }

        private static bool TryApplyPartyModifierDrivenStats(
            Agent agent,
            MaterializedCombatProfileRuntimeState profile,
            AgentDrivenProperties agentDrivenProperties)
        {
            if (agent == null || profile == null || agentDrivenProperties == null)
                return false;

            bool applied = false;

            if (TryApplyPartyMoraleDrivenStats(agentDrivenProperties, profile))
            {
                applied = true;
                CountMaterializedCombatProfileApply(profile, "party-morale", ref profile.CountedPartyMoraleAdjustment);
            }

            if (TryApplyPartyTacticsDrivenStats(agent, agentDrivenProperties, profile))
            {
                applied = true;
                CountMaterializedCombatProfileApply(profile, "party-tactics", ref profile.CountedPartyTacticsAdjustment);
            }

            if (TryApplyPartyCaptainDrivenStats(agent, agentDrivenProperties, profile))
            {
                applied = true;
                CountMaterializedCombatProfileApply(profile, "party-captain", ref profile.CountedPartyCaptainAdjustment);
            }

            if (AgentLoadoutContainsRelevantSkill(agent, "Bow", "Crossbow", "Throwing"))
            {
                if (TryApplyPartyScoutDrivenStats(agentDrivenProperties, profile))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "party-scout", ref profile.CountedPartyScoutAdjustment);
                }
            }

            if (!agent.IsMount)
            {
                if (TryApplyPartyQuartermasterDrivenStats(agentDrivenProperties, profile))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "party-quartermaster", ref profile.CountedPartyQuartermasterAdjustment);
                }

                if (TryApplyPartyEngineerDrivenStats(agent, agentDrivenProperties, profile))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "party-engineer", ref profile.CountedPartyEngineerAdjustment);
                }

                if (TryApplyPartySurgeonDrivenStats(agentDrivenProperties, profile))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "party-surgeon", ref profile.CountedPartySurgeonAdjustment);
                }
            }

            return applied;
        }

        private static bool AgentLoadoutContainsRelevantSkill(Agent agent, params string[] relevantSkillIds)
        {
            if (agent == null || relevantSkillIds == null || relevantSkillIds.Length == 0)
                return false;

            MissionEquipment equipment = agent.Equipment;
            if (equipment == null)
                return false;

            for (EquipmentIndex index = EquipmentIndex.Weapon0; index <= EquipmentIndex.Weapon3; index++)
            {
                MissionWeapon missionWeapon = equipment[index];
                ItemObject item = missionWeapon.Item;
                if (item == null)
                    continue;

                WeaponComponentData usageItem = missionWeapon.CurrentUsageItem ?? item.PrimaryWeapon;
                if (MatchesRelevantSkillIdsByWeaponUsage(item, usageItem, relevantSkillIds))
                    return true;

                string skillId = item.RelevantSkill?.StringId;
                if (string.IsNullOrWhiteSpace(skillId))
                    continue;

                for (int i = 0; i < relevantSkillIds.Length; i++)
                {
                    if (string.Equals(skillId, relevantSkillIds[i], StringComparison.OrdinalIgnoreCase))
                        return true;
                }
            }

            return false;
        }

        private static bool MatchesRelevantSkillIdsByWeaponUsage(ItemObject item, WeaponComponentData usageItem, params string[] relevantSkillIds)
        {
            if (relevantSkillIds == null || relevantSkillIds.Length == 0)
                return false;

            bool wantsMelee = ContainsRelevantSkillId(relevantSkillIds, "OneHanded")
                || ContainsRelevantSkillId(relevantSkillIds, "TwoHanded")
                || ContainsRelevantSkillId(relevantSkillIds, "Polearm");
            bool wantsRanged = ContainsRelevantSkillId(relevantSkillIds, "Bow")
                || ContainsRelevantSkillId(relevantSkillIds, "Crossbow")
                || ContainsRelevantSkillId(relevantSkillIds, "Throwing");

            if (usageItem != null)
            {
                if (wantsMelee && (usageItem.IsOneHanded || usageItem.IsTwoHanded || usageItem.IsPolearm || usageItem.IsMeleeWeapon))
                    return true;

                if (wantsRanged && (usageItem.IsRangedWeapon
                    || usageItem.WeaponClass == WeaponClass.Javelin
                    || usageItem.WeaponClass == WeaponClass.ThrowingAxe
                    || usageItem.WeaponClass == WeaponClass.ThrowingKnife
                    || usageItem.WeaponClass == WeaponClass.Stone
                    || usageItem.WeaponClass == WeaponClass.SlingStone))
                    return true;
            }

            if (item == null)
                return false;

            switch (item.ItemType)
            {
                case ItemObject.ItemTypeEnum.OneHandedWeapon:
                case ItemObject.ItemTypeEnum.TwoHandedWeapon:
                case ItemObject.ItemTypeEnum.Polearm:
                    return wantsMelee;
                case ItemObject.ItemTypeEnum.Bow:
                case ItemObject.ItemTypeEnum.Crossbow:
                case ItemObject.ItemTypeEnum.Sling:
                case ItemObject.ItemTypeEnum.Thrown:
                    return wantsRanged;
                default:
                    return false;
            }
        }

        private static bool ContainsRelevantSkillId(string[] relevantSkillIds, string skillId)
        {
            if (relevantSkillIds == null || string.IsNullOrWhiteSpace(skillId))
                return false;

            for (int i = 0; i < relevantSkillIds.Length; i++)
            {
                if (string.Equals(relevantSkillIds[i], skillId, StringComparison.OrdinalIgnoreCase))
                    return true;
            }

            return false;
        }

        private static bool TryApplyEnduranceDrivenStats(
            Agent agent,
            MaterializedCombatProfileRuntimeState profile,
            AgentDrivenProperties agentDrivenProperties)
        {
            if (agent == null || profile == null || agentDrivenProperties == null || agent.IsMount)
                return false;

            int templateEndurance = DeriveCharacterEnduranceAttribute(agent.Character);
            int desiredEndurance = profile.AttributeEndurance > 0 ? profile.AttributeEndurance : DeriveCombatAttributeFromSkills(profile.SkillRiding, profile.SkillAthletics);
            if (!TryApplyEnduranceDrivenProperties(agentDrivenProperties, templateEndurance, desiredEndurance))
                return false;

            CountMaterializedCombatProfileApply(profile, "attribute-endurance", ref profile.CountedEnduranceAttributeAdjustment);
            return true;
        }

        private static bool TryApplyMountDrivenSkillCombatProfile(Agent mountAgent, AgentDrivenProperties agentDrivenProperties)
        {
            Agent riderAgent = mountAgent?.RiderAgent;
            if (mountAgent == null || riderAgent == null || !_materializedCombatProfilesByAgentIndex.TryGetValue(riderAgent.Index, out MaterializedCombatProfileRuntimeState profile))
                return false;

            int templateRiding = TryGetCharacterSkillValue(riderAgent.Character, DefaultSkills.Riding);
            int desiredRiding = profile.SkillRiding > 0 ? profile.SkillRiding : templateRiding;
            if (templateRiding <= 0 || desiredRiding <= 0)
                return false;

            bool applied = false;
            float mountSpeedBaseFactor = 1f + templateRiding * 0.0032f;
            float mountSpeedDesiredFactor = 1f + desiredRiding * 0.0032f;
            float mountManeuverBaseFactor = 1f + templateRiding * 0.0035f;
            float mountManeuverDesiredFactor = 1f + desiredRiding * 0.0035f;

            SetDrivenPropertyBaselineContext(profile, mountAgent, isMountContext: true);
            try
            {
                applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.MountSpeed, mountSpeedBaseFactor, mountSpeedDesiredFactor);
                applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.MountManeuver, mountManeuverBaseFactor, mountManeuverDesiredFactor);
                if (applied)
                    CountMaterializedCombatProfileApply(profile, "mount", ref profile.CountedMountStatAdjustment);

                if (TryApplyMountPerkDrivenStats(mountAgent, profile, agentDrivenProperties))
                {
                    applied = true;
                    CountMaterializedCombatProfileApply(profile, "perk-mount", ref profile.CountedPerkMountAdjustment);
                }

                return applied;
            }
            finally
            {
                ClearDrivenPropertyBaselineContext();
            }
        }

        private static bool TryApplyMountPerkDrivenStats(
            Agent mountAgent,
            MaterializedCombatProfileRuntimeState profile,
            AgentDrivenProperties agentDrivenProperties)
        {
            if (profile == null || agentDrivenProperties == null || profile.PerkRidingCount <= 0)
                return false;

            if (IsHeroProfileEligibleForExactPersonalPerks(profile) &&
                CoopCampaignDerivedAgentStatCalculateModel.IsActiveForMission(mountAgent?.Mission))
            {
                return false;
            }

            float factor = ComputePerkPositiveFactor(profile.PerkRidingCount, 0.005f, 0.08f);
            bool applied = false;
            applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.MountSpeed, 1f, factor);
            applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.MountManeuver, 1f, factor);
            return applied;
        }

        private static bool TryApplyPrimaryWeaponSkillDrivenStats(
            AgentDrivenProperties agentDrivenProperties,
            WeaponComponentData primaryWeapon,
            int templateRelevantSkill,
            int desiredRelevantSkill)
        {
            if (desiredRelevantSkill <= 0)
                return false;

            float baseFactor = 0.93f + 0.0007f * templateRelevantSkill;
            float desiredFactor = 0.93f + 0.0007f * desiredRelevantSkill;
            bool applied = false;
            applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.SwingSpeedMultiplier, baseFactor, desiredFactor);
            applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ThrustOrRangedReadySpeedMultiplier, baseFactor, desiredFactor);
            applied |= TryScaleDrivenProperty(agentDrivenProperties, DrivenProperty.ReloadSpeed, baseFactor, desiredFactor);
            return applied;
        }

